fn ppc_interrupt_callback_stack_pointer(interrupted_sp: u32) -> u32 {
    // Inside Macintosh: PowerPC System Software (1994), pp. 1-46–1-47:
    // an interrupt handler must skip the 224-byte Red Zone before using the
    // stack because an optimized leaf routine may keep live nonvolatile
    // registers there without allocating a frame.
    interrupted_sp
        .saturating_sub(PPC_INTERRUPT_RED_ZONE_SIZE)
        .saturating_sub(PPC_INITIAL_STACK_FRAME_SIZE)
        & !0xFu32
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PpcLoadConfig {
    pub stack_size: u32,
    pub screen_depth: u32,
}

impl PpcLoadConfig {
    pub fn from_cfrg_app_stack_size(app_stack_size: u32) -> Self {
        if app_stack_size == 0 {
            Self::default()
        } else {
            Self {
                stack_size: app_stack_size,
                ..Self::default()
            }
        }
    }
}

impl Default for PpcLoadConfig {
    fn default() -> Self {
        Self {
            stack_size: PPC_DEFAULT_STACK_SIZE,
            screen_depth: PPC_MAIN_PIXEL_DEPTH,
        }
    }
}

