fn ppc_clip_rect(
    cpu: &PpcCpu,
    allocator: Option<&mut PpcProcessAllocatorView<'_>>,
    memory: &mut PpcSectionMem,
    current_gworld: u32,
    heap_cursor: &mut u32,
    heap_limit: u32,
    last_mem_error: &mut i16,
    handles: &mut Vec<PpcHandleRecord>,
) {
    // Inside Macintosh: Imaging With QuickDraw (1994), p. 2-42: ClipRect
    // replaces the current port's clipping-region contents while retaining
    // the region handle itself.
    let Some((top, left, bottom, right)) = ppc_read_rect(memory, cpu.gpr[3]) else {
        *last_mem_error = PPC_PARAM_ERR;
        return;
    };
    let Some(clip_addr) = current_gworld.checked_add(PPC_CGRAF_PORT_CLIP_RGN_OFFSET) else {
        *last_mem_error = PPC_PARAM_ERR;
        return;
    };
    let mut clip_rgn = memory.read_u32_be(clip_addr).unwrap_or(0);
    if ppc_rgn_ptr(memory, clip_rgn).is_none() {
        clip_rgn = ppc_allocator_view_new_rgn(
            allocator,
            memory,
            heap_cursor,
            heap_limit,
            last_mem_error,
            handles,
        );
        if clip_rgn == 0 || memory.write_u32_be(clip_addr, clip_rgn).is_none() {
            *last_mem_error = PPC_PARAM_ERR;
            return;
        }
    }
    if ppc_write_rgn_bbox(memory, clip_rgn, top, left, bottom, right).is_none() {
        *last_mem_error = PPC_PARAM_ERR;
        return;
    }
    *last_mem_error = PPC_NO_ERR;
}

fn ppc_rgn_ptr(memory: &mut PpcSectionMem, rgn_handle: u32) -> Option<u32> {
    if rgn_handle == 0 {
        return None;
    }
    let ptr = memory.read_u32_be(rgn_handle)?;
    if ptr == 0 {
        None
    } else {
        Some(ptr)
    }
}

fn ppc_write_rgn_bbox(
    memory: &mut PpcSectionMem,
    rgn_handle: u32,
    top: i16,
    left: i16,
    bottom: i16,
    right: i16,
) -> Option<()> {
    let ptr = ppc_rgn_ptr(memory, rgn_handle)?;
    memory.write_u16_be(ptr, 10)?;
    ppc_write_rect(memory, ptr + 2, top, left, bottom, right)
}

fn ppc_read_rgn_bbox(memory: &mut PpcSectionMem, rgn_handle: u32) -> Option<(i16, i16, i16, i16)> {
    let ptr = ppc_rgn_ptr(memory, rgn_handle)?;
    ppc_read_rect(memory, ptr + 2)
}

fn ppc_set_empty_rgn(memory: &mut PpcSectionMem, rgn_handle: u32) -> Option<()> {
    ppc_write_rgn_bbox(memory, rgn_handle, 0, 0, 0, 0)
}

fn ppc_copy_rgn(
    allocator: Option<&mut PpcProcessAllocatorView<'_>>,
    memory: &mut PpcSectionMem,
    heap_cursor: &mut u32,
    heap_limit: u32,
    last_mem_error: &mut i16,
    handles: &mut Vec<PpcHandleRecord>,
    src_rgn: u32,
    dst_rgn: u32,
) -> i16 {
    if src_rgn == dst_rgn {
        return if ppc_rgn_ptr(memory, src_rgn).is_some() {
            PPC_NO_ERR
        } else {
            PPC_PARAM_ERR
        };
    }
    let Some(src_ptr) = ppc_rgn_ptr(memory, src_rgn) else {
        return PPC_PARAM_ERR;
    };
    let Some(size) = memory.read_u16_be(src_ptr).map(u32::from) else {
        return PPC_PARAM_ERR;
    };
    // Inside Macintosh: Imaging With QuickDraw (1994), pp. 3-90–3-91:
    // CopyRgn duplicates the complete mathematical region into an existing
    // destination so later changes to either region remain independent.
    if size < 10 || !ppc_memory_can_read_bytes(memory, src_ptr, size) {
        return PPC_PARAM_ERR;
    }
    let bytes = (0..size)
        .map(|offset| memory.read_u8(src_ptr + offset))
        .collect::<Option<Vec<_>>>();
    let Some(bytes) = bytes else {
        return PPC_PARAM_ERR;
    };
    if !handles.iter().any(|record| record.handle == dst_rgn) {
        let Some(dst_ptr) = ppc_rgn_ptr(memory, dst_rgn) else {
            return PPC_PARAM_ERR;
        };
        let Some(dst_size) = memory.read_u16_be(dst_ptr).map(u32::from) else {
            return PPC_PARAM_ERR;
        };
        if dst_size < size || !ppc_memory_can_write_bytes(memory, dst_ptr, size) {
            return PPC_PARAM_ERR;
        }
        return if memory.write_bytes(dst_ptr, &bytes).is_some() {
            PPC_NO_ERR
        } else {
            PPC_PARAM_ERR
        };
    }
    let result = ppc_allocator_view_resize_handle(
        allocator,
        memory,
        heap_cursor,
        heap_limit,
        last_mem_error,
        handles,
        dst_rgn,
        size,
    );
    if result != PPC_NO_ERR {
        return result;
    }
    let Some(dst_ptr) = ppc_rgn_ptr(memory, dst_rgn) else {
        return PPC_PARAM_ERR;
    };
    for (offset, byte) in bytes.into_iter().enumerate() {
        if memory.write_u8(dst_ptr + offset as u32, byte).is_none() {
            return PPC_PARAM_ERR;
        }
    }
    PPC_NO_ERR
}

#[derive(Clone, Copy)]
enum PpcRegionBooleanOp {
    Intersection,
    Union,
    Difference,
    Xor,
}

fn ppc_region_storage(memory: &mut PpcSectionMem, rgn_handle: u32) -> Option<Vec<u8>> {
    let ptr = ppc_rgn_ptr(memory, rgn_handle)?;
    let size = u32::from(memory.read_u16_be(ptr)?);
    if size < 10 || !ppc_memory_can_read_bytes(memory, ptr, size) {
        return None;
    }
    (0..size)
        .map(|offset| memory.read_u8(ptr + offset))
        .collect()
}

fn ppc_region_storage_bbox(storage: &[u8]) -> Option<(i16, i16, i16, i16)> {
    if storage.len() < 10 {
        return None;
    }
    let word = |offset: usize| i16::from_be_bytes([storage[offset], storage[offset + 1]]);
    let bbox = (word(2), word(4), word(6), word(8));
    (bbox.2 > bbox.0 && bbox.3 > bbox.1).then_some(bbox)
}

fn ppc_region_merge_endpoints(lhs: &[i16], rhs: &[i16]) -> Vec<i16> {
    let mut merged = Vec::with_capacity(lhs.len() + rhs.len());
    let mut lhs_index = 0usize;
    let mut rhs_index = 0usize;
    while lhs_index < lhs.len() || rhs_index < rhs.len() {
        match (lhs.get(lhs_index), rhs.get(rhs_index)) {
            (Some(&lhs_value), Some(&rhs_value)) if lhs_value < rhs_value => {
                merged.push(lhs_value);
                lhs_index += 1;
            }
            (Some(&lhs_value), Some(&rhs_value)) if rhs_value < lhs_value => {
                merged.push(rhs_value);
                rhs_index += 1;
            }
            (Some(_), Some(_)) => {
                lhs_index += 1;
                rhs_index += 1;
            }
            (Some(&lhs_value), None) => {
                merged.push(lhs_value);
                lhs_index += 1;
            }
            (None, Some(&rhs_value)) => {
                merged.push(rhs_value);
                rhs_index += 1;
            }
            (None, None) => break,
        }
    }
    merged
}

fn ppc_region_rows_for_band(storage: &[u8], top: i16, bottom: i16) -> Option<Vec<Vec<i16>>> {
    let height = (i32::from(bottom) - i32::from(top)).max(0) as usize;
    let mut rows = vec![Vec::new(); height];
    let Some((rgn_top, rgn_left, rgn_bottom, rgn_right)) = ppc_region_storage_bbox(storage) else {
        return Some(rows);
    };
    let overlap_top = top.max(rgn_top);
    let overlap_bottom = bottom.min(rgn_bottom);
    if overlap_bottom <= overlap_top {
        return Some(rows);
    }
    if storage.len() == 10 {
        for y in overlap_top..overlap_bottom {
            rows[(i32::from(y) - i32::from(top)) as usize] = vec![rgn_left, rgn_right];
        }
        return Some(rows);
    }

    const REGION_STOP: i16 = i16::MAX;
    let mut cursor = 10usize;
    let read_word = |storage: &[u8], cursor: &mut usize| {
        let bytes = storage.get(*cursor..cursor.checked_add(2)?)?;
        *cursor += 2;
        Some(i16::from_be_bytes([bytes[0], bytes[1]]))
    };
    let mut next_change_y = read_word(storage, &mut cursor)?;
    let mut active = Vec::new();
    for y32 in i32::from(rgn_top)..i32::from(overlap_bottom) {
        let y = y32 as i16;
        while next_change_y != REGION_STOP && next_change_y <= y {
            let mut delta = Vec::new();
            loop {
                let value = read_word(storage, &mut cursor)?;
                if value == REGION_STOP {
                    break;
                }
                delta.push(value);
            }
            active = ppc_region_merge_endpoints(&active, &delta);
            next_change_y = read_word(storage, &mut cursor)?;
        }
        if y >= overlap_top {
            rows[(i32::from(y) - i32::from(top)) as usize] = active.clone();
        }
    }
    Some(rows)
}

fn ppc_region_endpoints_to_intervals(endpoints: &[i16]) -> Vec<(i16, i16)> {
    endpoints
        .chunks_exact(2)
        .filter_map(|pair| (pair[0] < pair[1]).then_some((pair[0], pair[1])))
        .collect()
}

fn ppc_region_intervals_to_endpoints(mut intervals: Vec<(i16, i16)>) -> Vec<i16> {
    intervals.sort_unstable();
    let mut merged: Vec<(i16, i16)> = Vec::with_capacity(intervals.len());
    for (start, end) in intervals {
        if start >= end {
            continue;
        }
        if let Some((_, last_end)) = merged.last_mut() {
            if start <= *last_end {
                *last_end = (*last_end).max(end);
                continue;
            }
        }
        merged.push((start, end));
    }
    merged
        .into_iter()
        .flat_map(|(start, end)| [start, end])
        .collect()
}

fn ppc_region_intersect_rows(lhs: &[i16], rhs: &[i16]) -> Vec<i16> {
    let lhs = ppc_region_endpoints_to_intervals(lhs);
    let rhs = ppc_region_endpoints_to_intervals(rhs);
    let mut out = Vec::new();
    for &(lhs_start, lhs_end) in &lhs {
        for &(rhs_start, rhs_end) in &rhs {
            let start = lhs_start.max(rhs_start);
            let end = lhs_end.min(rhs_end);
            if start < end {
                out.push((start, end));
            }
        }
    }
    ppc_region_intervals_to_endpoints(out)
}

fn ppc_region_union_rows(lhs: &[i16], rhs: &[i16]) -> Vec<i16> {
    let mut intervals = ppc_region_endpoints_to_intervals(lhs);
    intervals.extend(ppc_region_endpoints_to_intervals(rhs));
    ppc_region_intervals_to_endpoints(intervals)
}

fn ppc_region_difference_rows(lhs: &[i16], rhs: &[i16]) -> Vec<i16> {
    let lhs = ppc_region_endpoints_to_intervals(lhs);
    let rhs = ppc_region_endpoints_to_intervals(rhs);
    let mut out = Vec::new();
    for (lhs_start, lhs_end) in lhs {
        let mut start = lhs_start;
        for &(rhs_start, rhs_end) in &rhs {
            if rhs_end <= start {
                continue;
            }
            if rhs_start >= lhs_end {
                break;
            }
            if rhs_start > start {
                out.push((start, rhs_start.min(lhs_end)));
            }
            start = start.max(rhs_end);
            if start >= lhs_end {
                break;
            }
        }
        if start < lhs_end {
            out.push((start, lhs_end));
        }
    }
    ppc_region_intervals_to_endpoints(out)
}

fn ppc_region_combine_rows(lhs: &[i16], rhs: &[i16], operation: PpcRegionBooleanOp) -> Vec<i16> {
    match operation {
        PpcRegionBooleanOp::Intersection => ppc_region_intersect_rows(lhs, rhs),
        PpcRegionBooleanOp::Union => ppc_region_union_rows(lhs, rhs),
        PpcRegionBooleanOp::Difference => ppc_region_difference_rows(lhs, rhs),
        PpcRegionBooleanOp::Xor => ppc_region_union_rows(
            &ppc_region_difference_rows(lhs, rhs),
            &ppc_region_difference_rows(rhs, lhs),
        ),
    }
}

fn ppc_region_storage_from_rows(top: i16, rows: &[Vec<i16>]) -> Option<Vec<u8>> {
    const REGION_STOP: i16 = i16::MAX;
    let mut bbox: Option<(i16, i16, i16, i16)> = None;
    for (row_index, row) in rows.iter().enumerate() {
        if row.is_empty() {
            continue;
        }
        let y = i32::from(top).checked_add(i32::try_from(row_index).ok()?)?;
        let y = i16::try_from(y).ok()?;
        let bottom = y.checked_add(1)?;
        let left = row[0];
        let right = *row.last()?;
        bbox = Some(match bbox {
            Some((current_top, current_left, current_bottom, current_right)) => (
                current_top,
                current_left.min(left),
                current_bottom.max(bottom),
                current_right.max(right),
            ),
            None => (y, left, bottom, right),
        });
    }
    let Some((bbox_top, left, bottom, right)) = bbox else {
        return Some(vec![0, 10, 0, 0, 0, 0, 0, 0, 0, 0]);
    };
    let first = &rows[(i32::from(bbox_top) - i32::from(top)) as usize];
    let rectangular = first == &[left, right]
        && (i32::from(bbox_top)..i32::from(bottom))
            .all(|y| rows[(y - i32::from(top)) as usize] == *first);

    let mut words = Vec::new();
    if !rectangular {
        let mut previous = Vec::new();
        for y32 in i32::from(bbox_top)..=i32::from(bottom) {
            let current = if y32 < i32::from(bottom) {
                rows[(y32 - i32::from(top)) as usize].clone()
            } else {
                Vec::new()
            };
            let delta = ppc_region_merge_endpoints(&previous, &current);
            if !delta.is_empty() {
                words.push(y32 as i16);
                words.extend(delta);
                words.push(REGION_STOP);
            }
            previous = current;
        }
        words.push(REGION_STOP);
    }
    let size = 10usize.checked_add(words.len().checked_mul(2)?)?;
    let size = u16::try_from(size).ok()?;
    let mut storage = Vec::with_capacity(usize::from(size));
    storage.extend_from_slice(&size.to_be_bytes());
    for value in [bbox_top, left, bottom, right] {
        storage.extend_from_slice(&value.to_be_bytes());
    }
    for word in words {
        storage.extend_from_slice(&word.to_be_bytes());
    }
    Some(storage)
}

fn ppc_write_region_storage(
    allocator: Option<&mut PpcProcessAllocatorView<'_>>,
    memory: &mut PpcSectionMem,
    heap_cursor: &mut u32,
    heap_limit: u32,
    last_mem_error: &mut i16,
    handles: &mut Vec<PpcHandleRecord>,
    rgn_handle: u32,
    storage: &[u8],
) -> i16 {
    let result = ppc_allocator_view_resize_handle(
        allocator,
        memory,
        heap_cursor,
        heap_limit,
        last_mem_error,
        handles,
        rgn_handle,
        u32::try_from(storage.len()).unwrap_or(u32::MAX),
    );
    if result != PPC_NO_ERR {
        return result;
    }
    let Some(ptr) = ppc_rgn_ptr(memory, rgn_handle) else {
        return PPC_PARAM_ERR;
    };
    for (offset, byte) in storage.iter().copied().enumerate() {
        if memory.write_u8(ptr + offset as u32, byte).is_none() {
            return PPC_PARAM_ERR;
        }
    }
    PPC_NO_ERR
}

fn ppc_region_boolean_op(
    allocator: Option<&mut PpcProcessAllocatorView<'_>>,
    memory: &mut PpcSectionMem,
    heap_cursor: &mut u32,
    heap_limit: u32,
    last_mem_error: &mut i16,
    handles: &mut Vec<PpcHandleRecord>,
    src_a: u32,
    src_b: u32,
    dst: u32,
    operation: PpcRegionBooleanOp,
) -> i16 {
    // Inside Macintosh: Imaging With QuickDraw (1994), pp. 3-93–3-96:
    // region Boolean operations preserve the complete mathematical shape,
    // allow a destination to alias either source, and write into an existing
    // destination handle.
    let Some(storage_a) = ppc_region_storage(memory, src_a) else {
        return PPC_PARAM_ERR;
    };
    let Some(storage_b) = ppc_region_storage(memory, src_b) else {
        return PPC_PARAM_ERR;
    };
    let bbox_a = ppc_region_storage_bbox(&storage_a);
    let bbox_b = ppc_region_storage_bbox(&storage_b);
    let band = match operation {
        PpcRegionBooleanOp::Intersection => match (bbox_a, bbox_b) {
            (Some(a), Some(b)) if a.2.min(b.2) > a.0.max(b.0) => Some((a.0.max(b.0), a.2.min(b.2))),
            _ => None,
        },
        PpcRegionBooleanOp::Difference => bbox_a.map(|a| (a.0, a.2)),
        PpcRegionBooleanOp::Union | PpcRegionBooleanOp::Xor => match (bbox_a, bbox_b) {
            (Some(a), Some(b)) => Some((a.0.min(b.0), a.2.max(b.2))),
            (Some(a), None) => Some((a.0, a.2)),
            (None, Some(b)) => Some((b.0, b.2)),
            (None, None) => None,
        },
    };
    let output = if let Some((top, bottom)) = band {
        let Some(rows_a) = ppc_region_rows_for_band(&storage_a, top, bottom) else {
            return PPC_PARAM_ERR;
        };
        let Some(rows_b) = ppc_region_rows_for_band(&storage_b, top, bottom) else {
            return PPC_PARAM_ERR;
        };
        let rows = rows_a
            .iter()
            .zip(&rows_b)
            .map(|(lhs, rhs)| ppc_region_combine_rows(lhs, rhs, operation))
            .collect::<Vec<_>>();
        let Some(output) = ppc_region_storage_from_rows(top, &rows) else {
            return PPC_MEM_FULL_ERR;
        };
        output
    } else {
        vec![0, 10, 0, 0, 0, 0, 0, 0, 0, 0]
    };
    ppc_write_region_storage(
        allocator,
        memory,
        heap_cursor,
        heap_limit,
        last_mem_error,
        handles,
        dst,
        &output,
    )
}

fn ppc_set_rect_rgn(
    memory: &mut PpcSectionMem,
    rgn_handle: u32,
    left: i16,
    top: i16,
    right: i16,
    bottom: i16,
) -> Option<()> {
    ppc_write_rgn_bbox(memory, rgn_handle, top, left, bottom, right)
}

fn ppc_rect_rgn(memory: &mut PpcSectionMem, rgn_handle: u32, rect_ptr: u32) -> Option<()> {
    let (top, left, bottom, right) = ppc_read_rect(memory, rect_ptr)?;
    ppc_write_rgn_bbox(memory, rgn_handle, top, left, bottom, right)
}

fn ppc_offset_rgn(memory: &mut PpcSectionMem, rgn_handle: u32, dh: i16, dv: i16) -> i16 {
    let Some(ptr) = ppc_rgn_ptr(memory, rgn_handle) else {
        return PPC_PARAM_ERR;
    };
    let Some(size) = memory.read_u16_be(ptr).map(u32::from) else {
        return PPC_PARAM_ERR;
    };
    if size < 10 || !ppc_memory_can_write_bytes(memory, ptr, size) {
        return PPC_PARAM_ERR;
    }
    let Some((top, left, bottom, right)) = ppc_read_rect(memory, ptr + 2) else {
        return PPC_PARAM_ERR;
    };
    if bottom <= top || right <= left {
        return PPC_NO_ERR;
    }
    if ppc_write_rect(
        memory,
        ptr + 2,
        top.wrapping_add(dv),
        left.wrapping_add(dh),
        bottom.wrapping_add(dv),
        right.wrapping_add(dh),
    )
    .is_none()
    {
        return PPC_PARAM_ERR;
    }
    if size == 10 {
        return PPC_NO_ERR;
    }

    // Imaging With QuickDraw (1994), p. 3-93: the nonrectangular region
    // payload alternates vertical change coordinates with horizontal boundary
    // coordinates; $7FFF terminates each row and then the complete region.
    let mut offset = 10u32;
    while offset + 2 <= size {
        let Some(y) = memory.read_u16_be(ptr + offset) else {
            return PPC_PARAM_ERR;
        };
        if y == 0x7fff {
            return PPC_NO_ERR;
        }
        if memory
            .write_u16_be(ptr + offset, (y as i16).wrapping_add(dv) as u16)
            .is_none()
        {
            return PPC_PARAM_ERR;
        }
        offset += 2;
        loop {
            if offset + 2 > size {
                return PPC_PARAM_ERR;
            }
            let Some(x) = memory.read_u16_be(ptr + offset) else {
                return PPC_PARAM_ERR;
            };
            if x == 0x7fff {
                offset += 2;
                break;
            }
            if memory
                .write_u16_be(ptr + offset, (x as i16).wrapping_add(dh) as u16)
                .is_none()
            {
                return PPC_PARAM_ERR;
            }
            offset += 2;
        }
    }
    PPC_PARAM_ERR
}

fn ppc_empty_rgn(memory: &mut PpcSectionMem, rgn_handle: u32) -> bool {
    let Some((top, left, bottom, right)) = ppc_read_rgn_bbox(memory, rgn_handle) else {
        return true;
    };
    bottom <= top || right <= left
}

fn ppc_point_in_region(memory: &mut PpcSectionMem, rgn_handle: u32, v: i16, h: i16) -> bool {
    let Some(storage) = ppc_region_storage(memory, rgn_handle) else {
        return false;
    };
    ppc_point_in_region_storage(&storage, v, h)
}

fn ppc_point_in_region_storage(storage: &[u8], v: i16, h: i16) -> bool {
    let Some((top, left, bottom, right)) = ppc_region_storage_bbox(&storage) else {
        return false;
    };
    if v < top || v >= bottom || h < left || h >= right {
        return false;
    }
    if storage.len() == 10 {
        return true;
    }
    ppc_region_rows_for_band(&storage, v, v.saturating_add(1)).is_some_and(|rows| {
        rows.first().is_some_and(|row| {
            row.chunks_exact(2)
                .any(|interval| h >= interval[0] && h < interval[1])
        })
    })
}

fn ppc_rect_in_region(memory: &mut PpcSectionMem, rect_ptr: u32, rgn_handle: u32) -> bool {
    let Some((rect_top, rect_left, rect_bottom, rect_right)) = ppc_read_rect(memory, rect_ptr)
    else {
        return false;
    };
    let Some(storage) = ppc_region_storage(memory, rgn_handle) else {
        return false;
    };
    let Some((rgn_top, rgn_left, rgn_bottom, rgn_right)) = ppc_region_storage_bbox(&storage) else {
        return false;
    };
    let top = rect_top.max(rgn_top);
    let bottom = rect_bottom.min(rgn_bottom);
    if top >= bottom || rect_left.max(rgn_left) >= rect_right.min(rgn_right) {
        return false;
    }
    ppc_region_rows_for_band(&storage, top, bottom).is_some_and(|rows| {
        rows.iter().any(|row| {
            row.chunks_exact(2)
                .any(|interval| rect_left < interval[1] && rect_right > interval[0])
        })
    })
}

fn ppc_open_polygon(memory: &mut PpcSectionMem, current_gworld: u32) -> Option<u32> {
    (current_gworld != 0)
        .then(|| memory.read_u32_be(current_gworld.wrapping_add(100)))
        .flatten()
        .filter(|handle| *handle != 0)
}

fn ppc_open_poly(
    process_memory_manager: &mut ProcessNativeMemoryManager,
    memory: &mut PpcSectionMem,
    heap_cursor: &mut u32,
    last_mem_error: &mut i16,
    handles: &mut Vec<PpcHandleRecord>,
    current_gworld: u32,
) -> u32 {
    if current_gworld == 0 || ppc_open_polygon(memory, current_gworld).is_some() {
        *last_mem_error = PPC_PARAM_ERR;
        return 0;
    }
    let handle = ppc_process_alloc_handle(
        process_memory_manager,
        memory,
        heap_cursor,
        last_mem_error,
        handles,
        10,
        true,
    );
    let Some(ptr) = memory.read_u32_be(handle).filter(|ptr| *ptr != 0) else {
        *last_mem_error = PPC_MEM_FULL_ERR;
        return 0;
    };
    if memory.write_u16_be(ptr, 10).is_none()
        || ppc_write_rect(memory, ptr + 2, 0, 0, 0, 0).is_none()
        || memory
            .write_u32_be(current_gworld.wrapping_add(100), handle)
            .is_none()
    {
        *last_mem_error = PPC_PARAM_ERR;
        return 0;
    }
    // Imaging With QuickDraw (1994), pp. 3-77--3-81: OpenPoly allocates a
    // PolyHandle, installs it in polySave, and records subsequent Move/Line
    // vertices until ClosePoly clears polySave.
    *last_mem_error = PPC_NO_ERR;
    handle
}

fn ppc_record_polygon_point(
    process_memory_manager: &mut ProcessNativeMemoryManager,
    memory: &mut PpcSectionMem,
    heap_cursor: &mut u32,
    last_mem_error: &mut i16,
    handles: &mut Vec<PpcHandleRecord>,
    handle: u32,
    h: i16,
    v: i16,
) -> i16 {
    let Some(ptr) = memory.read_u32_be(handle).filter(|ptr| *ptr != 0) else {
        return PPC_PARAM_ERR;
    };
    let Some(size) = memory.read_u16_be(ptr).map(u32::from) else {
        return PPC_PARAM_ERR;
    };
    if size < 10 || (size - 10) % 4 != 0 {
        return PPC_PARAM_ERR;
    }
    if size >= 14
        && memory.read_u16_be(ptr + size - 4) == Some(v as u16)
        && memory.read_u16_be(ptr + size - 2) == Some(h as u16)
    {
        return PPC_NO_ERR;
    }
    let Some(new_size) = size.checked_add(4) else {
        return PPC_MEM_FULL_ERR;
    };
    let result = process_memory_manager.set_native_handle_size(memory, handle, new_size);
    ppc_apply_process_native_resource_handle(
        process_memory_manager,
        memory,
        heap_cursor,
        last_mem_error,
        handles,
        handle,
    );
    if result != PPC_NO_ERR {
        return result;
    }
    let Some(ptr) = memory.read_u32_be(handle).filter(|ptr| *ptr != 0) else {
        return PPC_PARAM_ERR;
    };
    if memory.write_u16_be(ptr + size, v as u16).is_none()
        || memory.write_u16_be(ptr + size + 2, h as u16).is_none()
        || memory.write_u16_be(ptr, new_size as u16).is_none()
    {
        return PPC_PARAM_ERR;
    }
    let bounds = if size == 10 {
        (v, h, v.saturating_add(1), h.saturating_add(1))
    } else {
        let Some((top, left, bottom, right)) = ppc_read_rect(memory, ptr + 2) else {
            return PPC_PARAM_ERR;
        };
        (
            top.min(v),
            left.min(h),
            bottom.max(v.saturating_add(1)),
            right.max(h.saturating_add(1)),
        )
    };
    if ppc_write_rect(memory, ptr + 2, bounds.0, bounds.1, bounds.2, bounds.3).is_none() {
        return PPC_PARAM_ERR;
    }
    PPC_NO_ERR
}

fn ppc_polygon_points(memory: &mut PpcSectionMem, handle: u32) -> Option<Vec<(i16, i16)>> {
    let ptr = memory.read_u32_be(handle).filter(|ptr| *ptr != 0)?;
    let size = u32::from(memory.read_u16_be(ptr)?);
    if size < 10 || (size - 10) % 4 != 0 {
        return None;
    }
    (10..size)
        .step_by(4)
        .map(|offset| {
            Some((
                memory.read_u16_be(ptr + offset + 2)? as i16,
                memory.read_u16_be(ptr + offset)? as i16,
            ))
        })
        .collect()
}

fn ppc_paint_polygon(
    memory: &mut PpcSectionMem,
    gworlds: &[PpcGWorldRecord],
    current_gworld: u32,
    handle: u32,
    color: PpcRgbColor,
    explicit_index: Option<u8>,
) -> bool {
    let Some(points) = ppc_polygon_points(memory, handle).filter(|points| points.len() >= 3) else {
        return false;
    };
    let Some(ptr) = memory.read_u32_be(handle) else {
        return false;
    };
    let Some(bounds) = ppc_read_rect(memory, ptr + 2) else {
        return false;
    };
    let Some(surface) = ppc_live_quickdraw_surface(memory, gworlds, current_gworld) else {
        return false;
    };
    let front_buffer = surface.front_buffer;
    let Some(color_pixel) =
        ppc_quickdraw_surface_fore_pixel(memory, surface, color, explicit_index)
    else {
        return false;
    };
    let (top, left, bottom, right) = surface.local_rect(bounds);
    let points = points
        .into_iter()
        .map(|(h, v)| surface.local_point((i32::from(h), i32::from(v))))
        .collect::<Vec<_>>();
    let mut wrote = false;
    for y in top..bottom {
        for x in left..right {
            let mut crossings = 0u32;
            for index in 0..points.len() {
                let (x1, y1) = points[index];
                let (x2, y2) = points[(index + 1) % points.len()];
                let (x1, y1, x2, y2) = (f64::from(x1), f64::from(y1), f64::from(x2), f64::from(y2));
                let (y_min, y_max, x_at_min, x_at_max) = if y1 < y2 {
                    (y1, y2, x1, x2)
                } else {
                    (y2, y1, x2, x1)
                };
                if y1 != y2 && f64::from(y) >= y_min && f64::from(y) < y_max {
                    let intersection = x_at_min
                        + (f64::from(y) - y_min) * (x_at_max - x_at_min) / (y_max - y_min);
                    if intersection <= f64::from(x) {
                        crossings += 1;
                    }
                }
            }
            if crossings & 1 != 0 {
                wrote |= ppc_quickdraw_write_raw_pixel(memory, front_buffer, (x, y), color_pixel);
            }
        }
    }
    wrote
}

fn ppc_frame_polygon(
    memory: &mut PpcSectionMem,
    gworlds: &[PpcGWorldRecord],
    current_gworld: u32,
    handle: u32,
    color: PpcRgbColor,
    explicit_index: Option<u8>,
) -> bool {
    // Inside Macintosh: Imaging With QuickDraw, pp. 3-81–3-82: FramePoly
    // plays back the polygon's line-drawing commands with the current pen.
    let Some(points) = ppc_polygon_points(memory, handle).filter(|points| points.len() >= 2) else {
        return false;
    };
    let mut wrote = false;
    for i in 0..points.len() {
        let from = points[i];
        let to = points[(i + 1) % points.len()];
        wrote |= ppc_line_to(
            memory,
            gworlds,
            current_gworld,
            from,
            to,
            color,
            explicit_index,
        );
    }
    wrote
}

fn ppc_offset_rect(memory: &mut PpcSectionMem, rect_ptr: u32, dh: i16, dv: i16) -> Option<()> {
    let (top, left, bottom, right) = ppc_read_rect(memory, rect_ptr)?;
    ppc_write_rect(
        memory,
        rect_ptr,
        top.wrapping_add(dv),
        left.wrapping_add(dh),
        bottom.wrapping_add(dv),
        right.wrapping_add(dh),
    )
}

fn ppc_map_rect(memory: &mut PpcSectionMem, rect_ptr: u32, src_ptr: u32, dst_ptr: u32) {
    // Inside Macintosh Volume I (1985), p. I-197: MapRect maps all four
    // coordinates proportionally from srcRect's coordinate space into
    // dstRect's coordinate space.
    let (
        Some((top, left, bottom, right)),
        Some((src_top, src_left, src_bottom, src_right)),
        Some((dst_top, dst_left, dst_bottom, dst_right)),
    ) = (
        ppc_read_rect(memory, rect_ptr),
        ppc_read_rect(memory, src_ptr),
        ppc_read_rect(memory, dst_ptr),
    )
    else {
        return;
    };
    let src_width = i64::from(src_right) - i64::from(src_left);
    let src_height = i64::from(src_bottom) - i64::from(src_top);
    let dst_width = i64::from(dst_right) - i64::from(dst_left);
    let dst_height = i64::from(dst_bottom) - i64::from(dst_top);
    let map_h = |value: i16| {
        if src_width == 0 {
            value
        } else {
            (i64::from(dst_left) + (i64::from(value) - i64::from(src_left)) * dst_width / src_width)
                as i16
        }
    };
    let map_v = |value: i16| {
        if src_height == 0 {
            value
        } else {
            (i64::from(dst_top) + (i64::from(value) - i64::from(src_top)) * dst_height / src_height)
                as i16
        }
    };
    let _ = ppc_write_rect(
        memory,
        rect_ptr,
        map_v(top),
        map_h(left),
        map_v(bottom),
        map_h(right),
    );
}

fn ppc_fs_make_fsspec(
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    default_dir_id: u32,
) -> i16 {
    let requested_vref = cpu.gpr[3] as u16 as i16;
    let requested_dir_id = cpu.gpr[4];
    let name_ptr = cpu.gpr[5];
    let spec_ptr = cpu.gpr[6];
    if spec_ptr == 0 {
        return PPC_PARAM_ERR;
    }

    let effective_vref = ppc_resolve_volume_ref_num(requested_vref);
    let effective_dir_id =
        ppc_resolve_directory_id(requested_vref, requested_dir_id, default_dir_id);
    let name_bytes = if name_ptr == 0 {
        Vec::new()
    } else {
        let Some(bytes) = ppc_read_pstring_bytes(memory, name_ptr) else {
            return PPC_PARAM_ERR;
        };
        bytes
    };

    let mut output_dir_id = effective_dir_id;
    let mut output_name_bytes = name_bytes.clone();
    let result = if !name_bytes.is_empty()
        && effective_dir_id > 1
        && ppc_directory_path_for_id(vfs_directories, effective_dir_id).is_none()
    {
        PPC_DIR_NF_ERR
    } else if let Some(target_path) = ppc_resolved_fsspec_target_path(
        vfs_directories,
        vfs_files,
        vfs_resource_files,
        effective_dir_id,
        &name_bytes,
    ) {
        if !name_bytes.is_empty() {
            output_dir_id = ppc_parent_dir_id_for_path(vfs_directories, &target_path);
            output_name_bytes = ppc_vfs_basename_bytes(&target_path);
        }
        PPC_NO_ERR
    } else {
        PPC_FNF_ERR
    };
    if ppc_write_fsspec(
        memory,
        spec_ptr,
        effective_vref,
        output_dir_id,
        &output_name_bytes,
    )
    .is_none()
    {
        return PPC_PARAM_ERR;
    }
    if ppc_hle_trace_enabled() {
        eprintln!(
            "[PPC-TRACE] FSMakeFSSpec requested_vref={} requested_dir={} effective_vref={} effective_dir={} name=\"{}\" result={}",
            requested_vref,
            requested_dir_id,
            effective_vref,
            effective_dir_id,
            decode_mac_roman(&name_bytes),
            result
        );
    }
    result
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct PpcCatalogEntry {
    path: String,
    name: Vec<u8>,
    is_directory: bool,
}

fn ppc_pb_get_cat_info(
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_volumes: &[PpcVfsVolumeRecord],
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    vfs_resources: &[PpcVfsResourceRecord],
    default_dir_id: u32,
) -> i16 {
    let pb = cpu.gpr[3];
    if pb == 0 {
        return PPC_PARAM_ERR;
    }
    if !ppc_memory_can_write_bytes(memory, pb + 16, 2)
        || !ppc_memory_can_write_bytes(memory, pb + 22, 2)
    {
        return PPC_PARAM_ERR;
    }
    let Some(name_ptr) = memory.read_u32_be(pb + 18) else {
        return PPC_PARAM_ERR;
    };
    let Some(vref) = memory.read_u16_be(pb + 22).map(|value| value as i16) else {
        return PPC_PARAM_ERR;
    };
    let Some(fdir_index) = memory.read_u16_be(pb + 28).map(|value| value as i16) else {
        return PPC_PARAM_ERR;
    };
    let Some(requested_dir_id) = memory.read_u32_be(pb + 48) else {
        return PPC_PARAM_ERR;
    };
    let effective_dir_id = ppc_resolve_directory_id(vref, requested_dir_id, default_dir_id);
    let name_bytes = if name_ptr == 0 {
        Vec::new()
    } else {
        match ppc_read_pstring_bytes(memory, name_ptr) {
            Some(bytes) => bytes,
            None => return ppc_complete_pb(memory, pb, PPC_PARAM_ERR),
        }
    };
    let requested_name = decode_mac_roman(&name_bytes);
    let absolute_pathname = !requested_name.starts_with(':') && requested_name.contains(':');
    let pathname_volume = (!requested_name.starts_with(':'))
        .then(|| requested_name.split_once(':').map(|(volume, _)| volume))
        .flatten()
        .and_then(|name| {
            vfs_volumes
                .iter()
                .find(|volume| volume.name.eq_ignore_ascii_case(name))
        });
    let resolved_vref =
        pathname_volume.map_or_else(|| ppc_resolve_volume_ref_num(vref), |volume| volume.ref_num);
    if !absolute_pathname
        && effective_dir_id > 1
        && ppc_directory_path_for_id(vfs_directories, effective_dir_id).is_none()
    {
        return ppc_complete_pb(memory, pb, PPC_DIR_NF_ERR);
    }

    let Some(entry) = ppc_catalog_entry_for_lookup(
        vfs_directories,
        vfs_files,
        vfs_resource_files,
        effective_dir_id,
        &name_bytes,
        fdir_index,
    ) else {
        if ppc_hle_trace_enabled() {
            eprintln!(
                "[PPC-TRACE] PBGetCatInfo dir={} index={} name=\"{}\" -> {}",
                effective_dir_id,
                fdir_index,
                decode_mac_roman(&name_bytes),
                PPC_FNF_ERR
            );
        }
        return ppc_complete_pb(memory, pb, PPC_FNF_ERR);
    };

    let filled = if entry.is_directory {
        vfs_directories
            .iter()
            .find(|directory| directory.path.eq_ignore_ascii_case(&entry.path))
            .and_then(|directory| {
                ppc_fill_directory_catalog_info(
                    memory,
                    pb,
                    directory,
                    vfs_directories,
                    vfs_files,
                    vfs_resource_files,
                )
            })
    } else {
        ppc_fill_file_catalog_info(
            memory,
            pb,
            vfs_directories,
            vfs_files,
            vfs_resource_files,
            vfs_resources,
            &entry.path,
        )
    };
    if filled.is_none() {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    }
    if fdir_index >= 0 && name_ptr != 0 && !ppc_write_pstring_bytes(memory, name_ptr, &entry.name) {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    }
    if memory.write_u16_be(pb + 22, resolved_vref as u16).is_none() {
        return PPC_PARAM_ERR;
    }
    if ppc_hle_trace_enabled() {
        eprintln!(
            "[PPC-TRACE] PBGetCatInfo dir={} index={} name=\"{}\" -> 0 out=\"{}\"",
            effective_dir_id,
            fdir_index,
            decode_mac_roman(&name_bytes),
            decode_mac_roman(&entry.name)
        );
    }
    ppc_complete_pb(memory, pb, PPC_NO_ERR)
}

fn ppc_pb_set_cat_info(
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_directories: &mut [PpcVfsDirectory],
    vfs_files: &mut [PpcVfsFileRecord],
    vfs_resource_files: &mut [PpcVfsResourceFileRecord],
    default_dir_id: u32,
) -> i16 {
    let pb = cpu.gpr[3];
    if pb == 0 {
        return PPC_PARAM_ERR;
    }
    let Some(name_ptr) = memory.read_u32_be(pb + 18) else {
        return PPC_PARAM_ERR;
    };
    let Some(vref) = memory.read_u16_be(pb + 22).map(|value| value as i16) else {
        return PPC_PARAM_ERR;
    };
    let Some(fdir_index) = memory.read_u16_be(pb + 28).map(|value| value as i16) else {
        return PPC_PARAM_ERR;
    };
    let Some(requested_dir_id) = memory.read_u32_be(pb + 48) else {
        return PPC_PARAM_ERR;
    };
    let effective_dir_id = ppc_resolve_directory_id(vref, requested_dir_id, default_dir_id);
    let name_bytes = if name_ptr == 0 {
        Vec::new()
    } else {
        match ppc_read_pstring_bytes(memory, name_ptr) {
            Some(bytes) => bytes,
            None => return ppc_complete_pb(memory, pb, PPC_PARAM_ERR),
        }
    };
    if effective_dir_id > 1
        && ppc_directory_path_for_id(vfs_directories, effective_dir_id).is_none()
    {
        return ppc_complete_pb(memory, pb, PPC_DIR_NF_ERR);
    }
    let Some((file_type, creator, finder_flags)) = ppc_read_finfo(memory, pb + 32) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    let Some(entry) = ppc_catalog_entry_for_lookup(
        vfs_directories,
        vfs_files,
        vfs_resource_files,
        effective_dir_id,
        &name_bytes,
        fdir_index,
    ) else {
        return ppc_complete_pb(memory, pb, PPC_FNF_ERR);
    };
    if entry.is_directory {
        let Some(directory) = vfs_directories
            .iter_mut()
            .find(|directory| directory.path.eq_ignore_ascii_case(&entry.path))
        else {
            return ppc_complete_pb(memory, pb, PPC_FNF_ERR);
        };
        directory.file_type = file_type;
        directory.creator = creator;
        directory.finder_flags = finder_flags;
        directory.dirty = true;
    } else {
        let mut found = false;
        for file in vfs_files
            .iter_mut()
            .filter(|record| record.path.eq_ignore_ascii_case(&entry.path))
        {
            file.file_type = file_type;
            file.creator = creator;
            file.finder_flags = finder_flags;
            file.dirty = true;
            found = true;
        }
        for file in vfs_resource_files
            .iter_mut()
            .filter(|record| record.path.eq_ignore_ascii_case(&entry.path))
        {
            file.file_type = file_type;
            file.creator = creator;
            file.finder_flags = finder_flags;
            file.dirty = true;
            found = true;
        }
        if !found {
            return ppc_complete_pb(memory, pb, PPC_FNF_ERR);
        }
    }
    let resolved_vref = ppc_resolve_volume_ref_num(vref);
    if memory.write_u16_be(pb + 22, resolved_vref as u16).is_none() {
        return PPC_PARAM_ERR;
    }
    ppc_complete_pb(memory, pb, PPC_NO_ERR)
}

fn ppc_pb_get_finfo(
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    vfs_resources: &[PpcVfsResourceRecord],
    default_dir_id: u32,
    hfs: bool,
) -> i16 {
    let pb = cpu.gpr[3];
    if pb == 0 {
        return PPC_PARAM_ERR;
    }
    if !ppc_memory_can_write_bytes(memory, pb + 16, 2)
        || !ppc_memory_can_write_bytes(memory, pb + 22, 2)
    {
        return PPC_PARAM_ERR;
    }
    let Some(name_ptr) = memory.read_u32_be(pb + 18) else {
        return PPC_PARAM_ERR;
    };
    let Some(vref) = memory.read_u16_be(pb + 22).map(|value| value as i16) else {
        return PPC_PARAM_ERR;
    };
    let Some(fdir_index) = memory.read_u16_be(pb + 28).map(|value| value as i16) else {
        return PPC_PARAM_ERR;
    };
    let requested_dir_id = if hfs {
        let Some(dir_id) = memory.read_u32_be(pb + 48) else {
            return PPC_PARAM_ERR;
        };
        dir_id
    } else {
        0
    };
    let resolved_vref = ppc_resolve_volume_ref_num(vref);
    let effective_dir_id = ppc_resolve_directory_id(vref, requested_dir_id, default_dir_id);
    let name_bytes = if name_ptr == 0 {
        Vec::new()
    } else {
        match ppc_read_pstring_bytes(memory, name_ptr) {
            Some(bytes) => bytes,
            None => return ppc_complete_pb(memory, pb, PPC_PARAM_ERR),
        }
    };
    if effective_dir_id > 1
        && ppc_directory_path_for_id(vfs_directories, effective_dir_id).is_none()
    {
        return ppc_complete_pb(memory, pb, PPC_DIR_NF_ERR);
    }
    let Some(path) = ppc_pb_finfo_path_for_lookup(
        vfs_directories,
        vfs_files,
        vfs_resource_files,
        effective_dir_id,
        &name_bytes,
        fdir_index,
    ) else {
        return ppc_complete_pb(memory, pb, PPC_FNF_ERR);
    };
    if ppc_fill_file_finfo_pb(
        memory,
        pb,
        vfs_directories,
        vfs_files,
        vfs_resource_files,
        vfs_resources,
        &path,
        hfs,
    )
    .is_none()
    {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    }
    if name_ptr != 0 && !ppc_write_pstring_bytes(memory, name_ptr, &ppc_vfs_basename_bytes(&path)) {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    }
    if memory.write_u16_be(pb + 22, resolved_vref as u16).is_none() {
        return PPC_PARAM_ERR;
    }
    ppc_complete_pb(memory, pb, PPC_NO_ERR)
}

fn ppc_pb_set_finfo(
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &mut [PpcVfsFileRecord],
    vfs_resource_files: &mut [PpcVfsResourceFileRecord],
    default_dir_id: u32,
    hfs: bool,
) -> i16 {
    let pb = cpu.gpr[3];
    if pb == 0 {
        return PPC_PARAM_ERR;
    }
    if !ppc_memory_can_write_bytes(memory, pb + 16, 2)
        || !ppc_memory_can_write_bytes(memory, pb + 22, 2)
    {
        return PPC_PARAM_ERR;
    }
    let Some(name_ptr) = memory.read_u32_be(pb + 18) else {
        return PPC_PARAM_ERR;
    };
    let Some(vref) = memory.read_u16_be(pb + 22).map(|value| value as i16) else {
        return PPC_PARAM_ERR;
    };
    let Some(fdir_index) = memory.read_u16_be(pb + 28).map(|value| value as i16) else {
        return PPC_PARAM_ERR;
    };
    let requested_dir_id = if hfs {
        let Some(dir_id) = memory.read_u32_be(pb + 48) else {
            return PPC_PARAM_ERR;
        };
        dir_id
    } else {
        0
    };
    let resolved_vref = ppc_resolve_volume_ref_num(vref);
    let effective_dir_id = ppc_resolve_directory_id(vref, requested_dir_id, default_dir_id);
    let name_bytes = if name_ptr == 0 {
        Vec::new()
    } else {
        match ppc_read_pstring_bytes(memory, name_ptr) {
            Some(bytes) => bytes,
            None => return ppc_complete_pb(memory, pb, PPC_PARAM_ERR),
        }
    };
    if effective_dir_id > 1
        && ppc_directory_path_for_id(vfs_directories, effective_dir_id).is_none()
    {
        return ppc_complete_pb(memory, pb, PPC_DIR_NF_ERR);
    }
    let Some((file_type, creator, finder_flags)) = ppc_read_finfo(memory, pb + 32) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    let Some(path) = ppc_pb_finfo_path_for_lookup(
        vfs_directories,
        vfs_files,
        vfs_resource_files,
        effective_dir_id,
        &name_bytes,
        fdir_index,
    ) else {
        return ppc_complete_pb(memory, pb, PPC_FNF_ERR);
    };
    if !ppc_set_finfo_for_path(
        vfs_files,
        vfs_resource_files,
        &path,
        file_type,
        creator,
        finder_flags,
    ) {
        return ppc_complete_pb(memory, pb, PPC_FNF_ERR);
    }
    if memory.write_u16_be(pb + 22, resolved_vref as u16).is_none() {
        return PPC_PARAM_ERR;
    }
    ppc_complete_pb(memory, pb, PPC_NO_ERR)
}

fn ppc_pb_finfo_path_for_lookup(
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    dir_id: u32,
    name_bytes: &[u8],
    fdir_index: i16,
) -> Option<String> {
    if fdir_index > 0 {
        let entry = ppc_catalog_child_by_index(
            vfs_directories,
            vfs_files,
            vfs_resource_files,
            dir_id,
            fdir_index as usize,
        )?;
        return (!entry.is_directory).then_some(entry.path);
    }
    if name_bytes.is_empty() {
        return None;
    }
    let normalized_name = ppc_normalize_vfs_path(&decode_mac_roman(name_bytes));
    if normalized_name.is_empty() {
        return None;
    }
    if let Some(parent_path) = ppc_directory_path_for_id(vfs_directories, dir_id) {
        let candidate = ppc_join_vfs_path(parent_path, &normalized_name);
        if let Some(path) = ppc_vfs_file_or_resource_path(vfs_files, vfs_resource_files, &candidate)
        {
            return Some(path);
        }
    }
    if normalized_name.contains('/') {
        if let Some(path) =
            ppc_vfs_file_or_resource_path(vfs_files, vfs_resource_files, &normalized_name)
        {
            return Some(path);
        }
    }
    ppc_vfs_file_or_resource_path_by_basename(vfs_files, vfs_resource_files, &normalized_name)
}

fn ppc_vfs_file_or_resource_path(
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    path: &str,
) -> Option<String> {
    vfs_files
        .iter()
        .find(|file| file.path.eq_ignore_ascii_case(path))
        .map(|file| file.path.clone())
        .or_else(|| {
            vfs_resource_files
                .iter()
                .find(|file| file.path.eq_ignore_ascii_case(path))
                .map(|file| file.path.clone())
        })
}

fn ppc_vfs_file_or_resource_path_by_basename(
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    name: &str,
) -> Option<String> {
    let basename = name.rsplit('/').next().unwrap_or(name);
    let mut data_paths = vfs_files.iter().map(|file| &file.path).collect::<Vec<_>>();
    data_paths.sort_by_key(|path| path.to_ascii_lowercase());
    if let Some(path) = data_paths
        .into_iter()
        .find(|path| ppc_vfs_basename(path).eq_ignore_ascii_case(basename))
    {
        return Some(path.clone());
    }
    let mut resource_paths = vfs_resource_files
        .iter()
        .map(|file| &file.path)
        .collect::<Vec<_>>();
    resource_paths.sort_by_key(|path| path.to_ascii_lowercase());
    resource_paths
        .into_iter()
        .find(|path| ppc_vfs_basename(path).eq_ignore_ascii_case(basename))
        .cloned()
}

fn ppc_vfs_basename(path: &str) -> &str {
    path.rsplit('/')
        .next()
        .filter(|name| !name.is_empty())
        .unwrap_or(path)
}

fn ppc_fill_file_finfo_pb(
    memory: &mut PpcSectionMem,
    pb: u32,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    vfs_resources: &[PpcVfsResourceRecord],
    path: &str,
    include_parent_dir_id: bool,
) -> Option<()> {
    let data_len = vfs_files
        .iter()
        .find(|file| file.path.eq_ignore_ascii_case(path))
        .map_or(0, |file| u32::try_from(file.data.len()).unwrap_or(u32::MAX));
    let resource_len = ppc_resource_fork_len_for_path(vfs_resource_files, vfs_resources, path);
    let (file_type, creator, finder_flags) =
        ppc_finder_info_for_path(vfs_files, vfs_resource_files, path);
    memory.write_u8(pb + 30, 0)?;
    memory.write_u8(pb + 31, 0)?;
    ppc_write_finfo(memory, pb + 32, file_type, creator, finder_flags)?;
    memory.write_u32_be(pb + 48, ppc_synthetic_file_id(path))?;
    memory.write_u32_be(pb + 54, data_len)?;
    memory.write_u32_be(pb + 58, data_len)?;
    memory.write_u32_be(pb + 64, resource_len)?;
    memory.write_u32_be(pb + 68, resource_len)?;
    memory.write_u32_be(pb + 72, 0)?;
    memory.write_u32_be(pb + 76, 0)?;
    if include_parent_dir_id {
        memory.write_u32_be(pb + 100, ppc_parent_dir_id_for_path(vfs_directories, path))?;
    }
    Some(())
}

fn ppc_set_finfo_for_path(
    vfs_files: &mut [PpcVfsFileRecord],
    vfs_resource_files: &mut [PpcVfsResourceFileRecord],
    path: &str,
    file_type: u32,
    creator: u32,
    finder_flags: u16,
) -> bool {
    let mut found = false;
    for file in vfs_files
        .iter_mut()
        .filter(|record| record.path.eq_ignore_ascii_case(path))
    {
        file.file_type = file_type;
        file.creator = creator;
        file.finder_flags = finder_flags;
        file.dirty = true;
        found = true;
    }
    for file in vfs_resource_files
        .iter_mut()
        .filter(|record| record.path.eq_ignore_ascii_case(path))
    {
        file.file_type = file_type;
        file.creator = creator;
        file.finder_flags = finder_flags;
        file.dirty = true;
        found = true;
    }
    found
}

fn ppc_pbh_get_v_info(
    cpu: &PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_volumes: &[PpcVfsVolumeRecord],
) -> i16 {
    let pb = cpu.gpr[3];
    if pb == 0 || !ppc_memory_can_write_bytes(memory, pb, 122) {
        return PPC_PARAM_ERR;
    }
    let Some(name_ptr) = memory.read_u32_be(pb + 18) else {
        return PPC_PARAM_ERR;
    };
    let Some(vref_num) = memory.read_u16_be(pb + 22).map(|value| value as i16) else {
        return PPC_PARAM_ERR;
    };
    let Some(volume_index) = memory.read_u16_be(pb + 28).map(|value| value as i16) else {
        return PPC_PARAM_ERR;
    };
    let requested_name = if name_ptr == 0 {
        String::new()
    } else {
        ppc_read_pstring_bytes(memory, name_ptr)
            .map(|name| decode_mac_roman(&name))
            .unwrap_or_default()
    };
    let relative_pathname = requested_name.starts_with(':');
    let absolute_pathname = !relative_pathname && requested_name.contains(':');

    // Inside Macintosh: Files (1992), pp. 2-144--2-146: a positive
    // ioVolIndex enumerates the VCB queue, zero selects by name or reference,
    // and a negative index uses the standard name/reference search order.
    let boot_volume = || PpcVfsVolumeRecord {
        ref_num: PPC_BOOT_VOLUME_REF_NUM,
        name: crate::trap::TrapDispatcher::boot_volume_name().to_string(),
        root_dir_id: PPC_ROOT_DIR_ID,
        attributes: 0,
        file_count: 0,
        allocation_block_count: u16::MAX,
        allocation_block_size: 4096,
        clump_size: 4096,
        free_blocks: 0x8000,
        bitmap_start: 3,
        allocation_pointer: 4,
        allocation_start: 3,
        next_catalog_id: 1024,
        created_date: 0,
        modified_date: 0,
    };
    let volume_by_name = |name: &str| {
        let volume_name = name.split(':').next().unwrap_or(name);
        if volume_name.eq_ignore_ascii_case(crate::trap::TrapDispatcher::boot_volume_name()) {
            Some(boot_volume())
        } else {
            vfs_volumes
                .iter()
                .find(|volume| volume.name.eq_ignore_ascii_case(volume_name))
                .cloned()
        }
    };
    let volume_by_ref = |requested_ref: i16| {
        if requested_ref == PPC_BOOT_VOLUME_REF_NUM {
            Some(boot_volume())
        } else {
            vfs_volumes
                .iter()
                .find(|volume| volume.ref_num == requested_ref)
                .cloned()
        }
    };
    let selected = if volume_index == 0 {
        if vref_num != 0 {
            volume_by_ref(vref_num)
        } else if relative_pathname {
            Some(boot_volume())
        } else if !requested_name.is_empty() {
            volume_by_name(&requested_name)
        } else {
            Some(boot_volume())
        }
    } else if volume_index > 0 {
        if volume_index == 1 {
            Some(boot_volume())
        } else {
            vfs_volumes.get((volume_index - 2) as usize).cloned()
        }
    } else if absolute_pathname {
        volume_by_name(&requested_name)
    } else if vref_num != 0 {
        volume_by_ref(vref_num)
    } else if relative_pathname {
        Some(boot_volume())
    } else if !requested_name.is_empty() {
        volume_by_name(&requested_name)
    } else {
        Some(boot_volume())
    };
    let Some(volume) = selected else {
        if ppc_hle_trace_enabled() {
            eprintln!(
                "[PPC-TRACE] PBHGetVInfo index={volume_index} vref={vref_num} name={requested_name:?} -> nsvErr"
            );
        }
        return ppc_complete_pb(memory, pb, PPC_NSV_ERR);
    };

    let volume_name = encode_mac_roman_lossy(&volume.name);
    if name_ptr != 0 && !ppc_optional_pstring_output_can_write(memory, name_ptr, &volume_name) {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    }
    if name_ptr != 0 {
        let _ = ppc_write_pstring_bytes(memory, name_ptr, &volume_name);
    }

    if ppc_hle_trace_enabled() {
        eprintln!(
            "[PPC-TRACE] PBHGetVInfo index={volume_index} vref={vref_num} name={requested_name:?} -> {:?} ({})",
            volume.name, volume.ref_num
        );
    }

    // Inside Macintosh: Files (1992), p. 2-238: HVolumeParam layout.
    let writes = [
        memory.write_u16_be(pb + 22, volume.ref_num as u16),
        memory.write_u32_be(pb + 30, volume.created_date),
        memory.write_u32_be(pb + 34, volume.modified_date),
        memory.write_u16_be(pb + 38, volume.attributes),
        memory.write_u16_be(pb + 40, volume.file_count),
        memory.write_u16_be(pb + 42, volume.bitmap_start),
        memory.write_u16_be(pb + 44, volume.allocation_pointer),
        memory.write_u16_be(pb + 46, volume.allocation_block_count),
        memory.write_u32_be(pb + 48, volume.allocation_block_size),
        memory.write_u32_be(pb + 52, volume.clump_size),
        memory.write_u16_be(pb + 56, volume.allocation_start),
        memory.write_u32_be(pb + 58, volume.next_catalog_id),
        memory.write_u16_be(pb + 62, volume.free_blocks),
        memory.write_u16_be(pb + 64, 0x4244),
        memory.write_u16_be(pb + 66, 1),
        memory.write_u16_be(pb + 68, (-33i16) as u16),
        memory.write_u16_be(pb + 70, 0),
        memory.write_u32_be(pb + 72, 0),
        memory.write_u16_be(pb + 76, 0),
        memory.write_u32_be(pb + 78, 0),
        memory.write_u32_be(pb + 82, 0),
        memory.write_u32_be(pb + 86, 0),
        memory.write_u32_be(pb + 90, PPC_SYSTEM_FOLDER_DIR_ID),
    ];
    if writes.iter().any(Option::is_none) {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    }
    ppc_complete_pb(memory, pb, PPC_NO_ERR)
}

fn ppc_complete_pb(memory: &mut PpcSectionMem, pb: u32, err: i16) -> i16 {
    if memory.write_u16_be(pb + 16, err as u16).is_none() {
        PPC_PARAM_ERR
    } else {
        err
    }
}

#[allow(clippy::too_many_arguments)]
fn ppc_pb_get_fcb_info(
    cpu: &PpcCpu,
    memory: &mut PpcSectionMem,
    files: &[PpcFileRecord],
    resource_files: &[PpcResourceFileRecord],
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    vfs_resources: &[PpcVfsResourceRecord],
    launched_app_path: Option<&str>,
) -> i16 {
    // Inside Macintosh: Files (1992), pp. 2-237--2-238: FCBPBRec selects an
    // open fork by ioRefNum when ioFCBIndx is zero, or enumerates open FCBs
    // when ioFCBIndx is positive.
    let pb = cpu.gpr[3];
    if pb == 0 || !ppc_memory_can_write_bytes(memory, pb, 62) {
        return PPC_PARAM_ERR;
    }
    let Some(name_ptr) = memory.read_u32_be(pb + 18) else {
        return PPC_PARAM_ERR;
    };
    let Some(vref) = memory.read_u16_be(pb + 22).map(|value| value as i16) else {
        return PPC_PARAM_ERR;
    };
    let Some(requested_ref_num) = memory.read_u16_be(pb + 24).map(|value| value as i16) else {
        return PPC_PARAM_ERR;
    };
    let Some(fcb_index) = memory.read_u16_be(pb + 28).map(|value| value as i16) else {
        return PPC_PARAM_ERR;
    };
    if fcb_index < 0 || (name_ptr != 0 && !ppc_memory_can_write_bytes(memory, name_ptr, 32)) {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    }
    // Inside Macintosh: Files (1992), pp. 2-218--2-219: ioVRefNum limits
    // indexed FCB enumeration, but ioRefNum alone selects the open file when
    // ioFCBIndx is zero. Real applications consequently leave ioVRefNum
    // uninitialized for the latter form.
    if fcb_index > 0 && !matches!(vref, 0 | PPC_BOOT_VOLUME_REF_NUM) {
        return ppc_complete_pb(memory, pb, PPC_NSV_ERR);
    }

    let selected = if fcb_index == 0 {
        if requested_ref_num == 0 {
            launched_app_path.map(|path| (0, path.to_string(), true, 0))
        } else if let Some(file) = files.iter().find(|file| file.ref_num == requested_ref_num) {
            Some((file.ref_num, file.path.clone(), false, file.position))
        } else {
            resource_files
                .iter()
                .find(|file| file.ref_num == requested_ref_num)
                .map(|file| (file.ref_num, file.path.clone(), true, 0))
        }
    } else {
        let mut open_forks = Vec::with_capacity(
            files.len() + resource_files.len() + usize::from(launched_app_path.is_some()),
        );
        if let Some(path) = launched_app_path {
            open_forks.push((0, path.to_string(), true, 0));
        }
        open_forks.extend(
            files
                .iter()
                .map(|file| (file.ref_num, file.path.clone(), false, file.position)),
        );
        open_forks.extend(
            resource_files
                .iter()
                .map(|file| (file.ref_num, file.path.clone(), true, 0)),
        );
        open_forks.into_iter().nth(fcb_index as usize - 1)
    };
    let Some((ref_num, path, is_resource_fork, position)) = selected else {
        return ppc_complete_pb(memory, pb, PPC_FN_OPN_ERR);
    };

    let logical_eof = if is_resource_fork {
        ppc_resource_fork_len_for_path(vfs_resource_files, vfs_resources, &path)
    } else {
        vfs_files
            .iter()
            .find(|file| file.path.eq_ignore_ascii_case(&path))
            .map(|file| u32::try_from(file.data.len()).unwrap_or(u32::MAX))
            .unwrap_or(0)
    };
    let mut name = ppc_vfs_basename_bytes(&path);
    name.truncate(31);
    let flags = if is_resource_fork { 0x0200 } else { 0x0100 };
    let writes = [
        memory.write_u16_be(pb + 22, PPC_BOOT_VOLUME_REF_NUM as u16),
        memory.write_u16_be(pb + 24, ref_num as u16),
        memory.write_u16_be(pb + 30, 0),
        memory.write_u32_be(pb + 32, ppc_synthetic_file_id(&path)),
        memory.write_u16_be(pb + 36, flags),
        memory.write_u16_be(pb + 38, 0),
        memory.write_u32_be(pb + 40, logical_eof),
        memory.write_u32_be(pb + 44, logical_eof),
        memory.write_u32_be(pb + 48, position.min(logical_eof)),
        memory.write_u16_be(pb + 52, PPC_BOOT_VOLUME_REF_NUM as u16),
        memory.write_u32_be(pb + 54, 0),
        memory.write_u32_be(pb + 58, ppc_parent_dir_id_for_path(vfs_directories, &path)),
    ];
    if writes.iter().any(Option::is_none)
        || (name_ptr != 0 && !ppc_write_pstring_bytes(memory, name_ptr, &name))
    {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    }
    if ppc_hle_trace_enabled() {
        eprintln!(
            "[PPC-TRACE] PBGetFCBInfo ref={} index={} -> ref={} path=\"{}\" resource={} eof={} position={}",
            requested_ref_num, fcb_index, ref_num, path, is_resource_fork, logical_eof, position
        );
    }
    ppc_complete_pb(memory, pb, PPC_NO_ERR)
}

fn ppc_catalog_entry_for_lookup(
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    dir_id: u32,
    name_bytes: &[u8],
    fdir_index: i16,
) -> Option<PpcCatalogEntry> {
    if fdir_index > 0 {
        return ppc_catalog_child_by_index(
            vfs_directories,
            vfs_files,
            vfs_resource_files,
            dir_id,
            fdir_index as usize,
        );
    }
    if fdir_index < 0 {
        let directory = vfs_directories
            .iter()
            .find(|directory| directory.dir_id == dir_id)?;
        return Some(PpcCatalogEntry {
            path: directory.path.clone(),
            name: ppc_vfs_basename_bytes(&directory.path),
            is_directory: true,
        });
    }
    if name_bytes.is_empty() {
        let directory = vfs_directories
            .iter()
            .find(|directory| directory.dir_id == dir_id)?;
        return Some(PpcCatalogEntry {
            path: directory.path.clone(),
            name: ppc_vfs_basename_bytes(&directory.path),
            is_directory: true,
        });
    }

    let decoded_name = decode_mac_roman(name_bytes);
    let normalized_name = ppc_normalize_vfs_path(&decoded_name);
    if normalized_name.is_empty() {
        return None;
    }
    // Inside Macintosh: Files (1992), pp. 2-6--2-7: a pathname beginning
    // with a volume name is absolute, while a leading colon is relative.
    let absolute = !decoded_name.starts_with(':') && decoded_name.contains(':');
    let path = if absolute {
        normalized_name
    } else {
        let parent_path = ppc_directory_path_for_id(vfs_directories, dir_id)?;
        ppc_join_vfs_path(parent_path, &normalized_name)
    };
    if ppc_directory_id_for_path(vfs_directories, &path).is_some() {
        return Some(PpcCatalogEntry {
            name: ppc_vfs_basename_bytes(&path),
            path,
            is_directory: true,
        });
    }
    if ppc_vfs_file_index(vfs_files, &path).is_some()
        || ppc_vfs_resource_file_index(vfs_resource_files, &path).is_some()
    {
        return Some(PpcCatalogEntry {
            name: ppc_vfs_basename_bytes(&path),
            path,
            is_directory: false,
        });
    }
    None
}

fn ppc_catalog_child_by_index(
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    dir_id: u32,
    fdir_index: usize,
) -> Option<PpcCatalogEntry> {
    let parent_path = ppc_directory_path_for_id(vfs_directories, dir_id)?;
    let mut entries = Vec::new();
    for directory in vfs_directories
        .iter()
        .filter(|directory| directory.parent_dir_id == dir_id)
    {
        entries.push(PpcCatalogEntry {
            path: directory.path.clone(),
            name: ppc_vfs_basename_bytes(&directory.path),
            is_directory: true,
        });
    }
    for file in vfs_files {
        if let Some(name) = ppc_child_name_for_parent(parent_path, &file.path) {
            entries.push(PpcCatalogEntry {
                path: file.path.clone(),
                name: name.as_bytes().to_vec(),
                is_directory: false,
            });
        }
    }
    for fork in vfs_resource_files {
        if vfs_files
            .iter()
            .any(|file| file.path.eq_ignore_ascii_case(&fork.path))
        {
            continue;
        }
        if let Some(name) = ppc_child_name_for_parent(parent_path, &fork.path) {
            entries.push(PpcCatalogEntry {
                path: fork.path.clone(),
                name: name.as_bytes().to_vec(),
                is_directory: false,
            });
        }
    }
    entries.sort_by(|left, right| {
        let left_key = (
            left.name.to_ascii_lowercase(),
            u8::from(!left.is_directory),
            left.path.to_ascii_lowercase(),
        );
        let right_key = (
            right.name.to_ascii_lowercase(),
            u8::from(!right.is_directory),
            right.path.to_ascii_lowercase(),
        );
        left_key.cmp(&right_key)
    });
    entries.into_iter().nth(fdir_index.saturating_sub(1))
}

fn ppc_child_name_for_parent<'a>(parent_path: &str, path: &'a str) -> Option<&'a str> {
    if parent_path.is_empty() {
        return if !path.is_empty() && !path.contains('/') {
            Some(path)
        } else {
            None
        };
    }
    let remainder = path.strip_prefix(parent_path)?.strip_prefix('/')?;
    if remainder.is_empty() || remainder.contains('/') {
        None
    } else {
        Some(remainder)
    }
}

fn ppc_vfs_basename_bytes(path: &str) -> Vec<u8> {
    let basename = path
        .rsplit('/')
        .next()
        .filter(|name| !name.is_empty())
        .unwrap_or(path);
    encode_mac_roman_lossy(basename)
}

fn ppc_fill_file_catalog_info(
    memory: &mut PpcSectionMem,
    pb: u32,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    vfs_resources: &[PpcVfsResourceRecord],
    path: &str,
) -> Option<()> {
    let data_len = vfs_files
        .iter()
        .find(|file| file.path.eq_ignore_ascii_case(path))
        .map_or(0, |file| u32::try_from(file.data.len()).unwrap_or(u32::MAX));
    let resource_len = ppc_resource_fork_len_for_path(vfs_resource_files, vfs_resources, path);
    let (file_type, creator, finder_flags) =
        ppc_finder_info_for_path(vfs_files, vfs_resource_files, path);
    memory.write_u8(pb + 30, 0)?;
    memory.write_u8(pb + 31, 0)?;
    ppc_write_finfo(memory, pb + 32, file_type, creator, finder_flags)?;
    memory.write_u32_be(pb + 48, ppc_synthetic_file_id(path))?;
    memory.write_u32_be(pb + 54, data_len)?;
    memory.write_u32_be(pb + 58, data_len)?;
    memory.write_u32_be(pb + 64, resource_len)?;
    memory.write_u32_be(pb + 68, resource_len)?;
    memory.write_u32_be(pb + 72, 0)?;
    memory.write_u32_be(pb + 76, 0)?;
    memory.write_u32_be(pb + 100, ppc_parent_dir_id_for_path(vfs_directories, path))?;
    Some(())
}

fn ppc_resource_fork_len_for_path(
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    vfs_resources: &[PpcVfsResourceRecord],
    path: &str,
) -> u32 {
    let resource_file = vfs_resource_files
        .iter()
        .find(|fork| fork.path.eq_ignore_ascii_case(path));
    if let Some(raw_data) = resource_file.and_then(|fork| fork.raw_data.as_ref()) {
        return u32::try_from(raw_data.len()).unwrap_or(u32::MAX);
    }
    let entries = vfs_resources
        .iter()
        .filter(|resource| resource.path.eq_ignore_ascii_case(path))
        .map(|resource| {
            let (data, attrs) = match (&resource.raw_data, resource.raw_attrs) {
                (Some(raw_data), Some(raw_attrs)) => (raw_data.clone(), raw_attrs),
                _ => (resource.data.clone(), resource.attrs),
            };
            ResourceForkEntry {
                res_type: resource.res_type.to_be_bytes(),
                id: resource.res_id,
                name: resource.name.clone(),
                data,
                attrs: (attrs & 0x00ff) as u8,
            }
        })
        .collect::<Vec<_>>();
    if !entries.is_empty() {
        return serialize_resource_fork_with_attrs(
            &entries,
            resource_file.map_or(0, |fork| fork.map_attrs),
        )
        .map(|bytes| u32::try_from(bytes.len()).unwrap_or(u32::MAX))
        .unwrap_or(0);
    }
    resource_file.map_or(0, |fork| fork.resource_len)
}

fn ppc_fill_directory_catalog_info(
    memory: &mut PpcSectionMem,
    pb: u32,
    directory: &PpcVfsDirectory,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
) -> Option<()> {
    memory.write_u8(pb + 30, 0x10)?;
    memory.write_u8(pb + 31, 0)?;
    ppc_write_finfo(
        memory,
        pb + 32,
        directory.file_type,
        directory.creator,
        directory.finder_flags,
    )?;
    memory.write_u32_be(pb + 48, directory.dir_id)?;
    let mut entry_count = 0usize;
    while ppc_catalog_child_by_index(
        vfs_directories,
        vfs_files,
        vfs_resource_files,
        directory.dir_id,
        entry_count.saturating_add(1),
    )
    .is_some()
    {
        entry_count = entry_count.saturating_add(1);
    }
    memory.write_u16_be(pb + 52, entry_count.min(u16::MAX as usize) as u16)?;
    memory.write_u32_be(pb + 72, 0)?;
    memory.write_u32_be(pb + 76, 0)?;
    memory.write_u32_be(pb + 100, directory.parent_dir_id)?;
    Some(())
}

fn ppc_finder_info_for_path(
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    path: &str,
) -> (u32, u32, u16) {
    if let Some(file) = vfs_files
        .iter()
        .find(|file| file.path.eq_ignore_ascii_case(path))
    {
        return (file.file_type, file.creator, file.finder_flags);
    }
    if let Some(fork) = vfs_resource_files
        .iter()
        .find(|fork| fork.path.eq_ignore_ascii_case(path))
    {
        return (fork.file_type, fork.creator, fork.finder_flags);
    }
    (0, 0, 0)
}

fn ppc_synthetic_file_id(path: &str) -> u32 {
    let mut hash = 0x811c_9dc5u32;
    for byte in path.bytes().map(|byte| byte.to_ascii_lowercase()) {
        hash ^= u32::from(byte);
        hash = hash.wrapping_mul(0x0100_0193);
    }
    0x1000_0000 | (hash & 0x0fff_ffff)
}

fn ppc_parent_dir_id_for_path(vfs_directories: &[PpcVfsDirectory], path: &str) -> u32 {
    let parent_path = path.rsplit_once('/').map_or("", |(parent, _)| parent);
    ppc_directory_id_for_path(vfs_directories, parent_path).unwrap_or(PPC_ROOT_DIR_ID)
}

fn ppc_get_finfo(
    cpu: &PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    default_dir_id: u32,
) -> i16 {
    let file_name_ptr = cpu.gpr[3];
    let vref_num = cpu.gpr[4] as u16 as i16;
    let finfo_ptr = cpu.gpr[5];
    if !matches!(vref_num, 0 | PPC_BOOT_VOLUME_REF_NUM)
        || finfo_ptr == 0
        || !ppc_memory_can_write_bytes(memory, finfo_ptr, 16)
    {
        return PPC_PARAM_ERR;
    }
    let Some(name_bytes) = ppc_read_pstring_bytes(memory, file_name_ptr) else {
        return PPC_PARAM_ERR;
    };
    let path = ppc_resolved_fsspec_target_path(
        vfs_directories,
        vfs_files,
        vfs_resource_files,
        default_dir_id,
        &name_bytes,
    )
    .or_else(|| {
        ppc_resolved_fsspec_target_path(
            vfs_directories,
            vfs_files,
            vfs_resource_files,
            PPC_ROOT_DIR_ID,
            &name_bytes,
        )
    });
    let Some(path) = path else {
        let _ = ppc_write_finfo(memory, finfo_ptr, 0, 0, 0);
        return PPC_FNF_ERR;
    };
    let (file_type, creator, finder_flags) =
        ppc_finder_info_for_path(vfs_files, vfs_resource_files, &path);
    // Inside Macintosh, Volume II (1985), File Manager p. II-95: GetFInfo
    // takes a Str255 name and volume reference and returns the 16-byte FInfo.
    if ppc_write_finfo(memory, finfo_ptr, file_type, creator, finder_flags).is_none() {
        PPC_PARAM_ERR
    } else {
        PPC_NO_ERR
    }
}

fn ppc_h_finfo_path(
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    vref_num: i16,
    requested_dir_id: u32,
    file_name_ptr: u32,
    default_dir_id: u32,
) -> Result<String, i16> {
    if !matches!(vref_num, 0 | PPC_BOOT_VOLUME_REF_NUM) {
        return Err(PPC_NSV_ERR);
    }
    let name_bytes = ppc_read_pstring_bytes(memory, file_name_ptr).ok_or(PPC_PARAM_ERR)?;
    let name = ppc_normalize_vfs_path(&decode_mac_roman(&name_bytes));
    if name.is_empty() || name.contains('/') {
        return Err(PPC_BD_NAM_ERR);
    }
    let dir_id = ppc_resolve_directory_id(vref_num, requested_dir_id, default_dir_id);
    let parent = ppc_directory_path_for_id(vfs_directories, dir_id).ok_or(PPC_DIR_NF_ERR)?;
    let requested_path = ppc_join_vfs_path(parent, &name);
    ppc_vfs_file_or_resource_path(vfs_files, vfs_resource_files, &requested_path).ok_or(PPC_FNF_ERR)
}

fn ppc_h_get_finfo(
    cpu: &PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    default_dir_id: u32,
) -> i16 {
    let finfo_ptr = cpu.gpr[6];
    if finfo_ptr == 0 || !ppc_memory_can_write_bytes(memory, finfo_ptr, 16) {
        return PPC_PARAM_ERR;
    }
    let path = match ppc_h_finfo_path(
        memory,
        vfs_directories,
        vfs_files,
        vfs_resource_files,
        cpu.gpr[3] as u16 as i16,
        cpu.gpr[4],
        cpu.gpr[5],
        default_dir_id,
    ) {
        Ok(path) => path,
        Err(err) => return err,
    };
    let (file_type, creator, finder_flags) =
        ppc_finder_info_for_path(vfs_files, vfs_resource_files, &path);
    // Inside Macintosh: Files (1992), pp. 2-175--2-176: HGetFInfo uses the
    // explicit directory ID and returns the original 16-byte FInfo record.
    if ppc_write_finfo(memory, finfo_ptr, file_type, creator, finder_flags).is_some() {
        PPC_NO_ERR
    } else {
        PPC_PARAM_ERR
    }
}

fn ppc_h_set_finfo(
    cpu: &PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &mut [PpcVfsFileRecord],
    vfs_resource_files: &mut [PpcVfsResourceFileRecord],
    default_dir_id: u32,
) -> i16 {
    let finfo_ptr = cpu.gpr[6];
    let Some((file_type, creator, finder_flags)) = ppc_read_finfo(memory, finfo_ptr) else {
        return PPC_PARAM_ERR;
    };
    let path = match ppc_h_finfo_path(
        memory,
        vfs_directories,
        vfs_files,
        vfs_resource_files,
        cpu.gpr[3] as u16 as i16,
        cpu.gpr[4],
        cpu.gpr[5],
        default_dir_id,
    ) {
        Ok(path) => path,
        Err(err) => return err,
    };
    if ppc_set_finfo_for_path(
        vfs_files,
        vfs_resource_files,
        &path,
        file_type,
        creator,
        finder_flags,
    ) {
        PPC_NO_ERR
    } else {
        PPC_FNF_ERR
    }
}

const PPC_STANDARD_FILE_GET_DIALOG_WIDTH: i16 = 356;
const PPC_STANDARD_FILE_GET_DIALOG_HEIGHT: i16 = 178;
const PPC_STANDARD_FILE_GET_LIST_RECT: (i16, i16, i16, i16) = (35, 18, 163, 236);
const PPC_STANDARD_FILE_GET_SCROLL_RECT: (i16, i16, i16, i16) = (35, 235, 163, 251);
const PPC_STANDARD_FILE_GET_DESKTOP_RECT: (i16, i16, i16, i16) = (66, 258, 87, 338);
const PPC_STANDARD_FILE_GET_CANCEL_RECT: (i16, i16, i16, i16) = (110, 258, 131, 338);
const PPC_STANDARD_FILE_GET_OPEN_RECT: (i16, i16, i16, i16) = (138, 258, 159, 338);
const PPC_STANDARD_FILE_GET_ROW_HEIGHT: i16 = 14;
const PPC_STANDARD_FILE_PUT_DIALOG_WIDTH: i16 = 360;
const PPC_STANDARD_FILE_PUT_DIALOG_HEIGHT: i16 = 148;
const PPC_STANDARD_FILE_PUT_CANCEL_RECT: (i16, i16, i16, i16) = (103, 166, 125, 246);
const PPC_STANDARD_FILE_PUT_SAVE_RECT: (i16, i16, i16, i16) = (103, 258, 125, 338);
const PPC_STANDARD_FILE_PUT_NAME_RECT: (i16, i16, i16, i16) = (52, 24, 72, 330);

fn ppc_standard_file_reply_ptr(mode: PpcStandardFileMode, cpu: &PpcCpu) -> u32 {
    match mode {
        PpcStandardFileMode::GetModern => cpu.gpr[6],
        PpcStandardFileMode::GetLegacy => cpu.gpr[9],
        PpcStandardFileMode::PutModern => cpu.gpr[5],
        PpcStandardFileMode::PutLegacy => cpu.gpr[7],
    }
}

fn ppc_standard_file_call(mode: PpcStandardFileMode, cpu: &PpcCpu) -> PpcStandardFileCall {
    PpcStandardFileCall {
        mode,
        reply: ppc_standard_file_reply_ptr(mode, cpu),
        return_address: cpu.lr,
    }
}

fn ppc_standard_file_get_type_list(
    memory: &mut PpcSectionMem,
    num_types: i16,
    type_list_ptr: u32,
) -> Option<Option<Vec<u32>>> {
    // Inside Macintosh: Files (1992), pp. 3-50--3-51: -1 means all types,
    // zero means no selectable file types, and positive values name OSTypes.
    if num_types < -1 {
        return None;
    }
    if num_types == -1 {
        return Some(None);
    }
    if num_types == 0 {
        return Some(Some(Vec::new()));
    }
    if type_list_ptr == 0 {
        return None;
    }
    let count = usize::try_from(num_types).ok()?.min(64);
    let mut result = Vec::with_capacity(count);
    for index in 0..count {
        let offset = u32::try_from(index).ok()?.checked_mul(4)?;
        result.push(memory.read_u32_be(type_list_ptr.checked_add(offset)?)?);
    }
    Some(Some(result))
}

fn ppc_standard_file_get_entries(
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    dir_id: u32,
    file_types: Option<&[u32]>,
) -> Vec<PpcStandardFileEntry> {
    let Some(parent_path) = ppc_directory_path_for_id(vfs_directories, dir_id) else {
        return Vec::new();
    };
    let mut entries = Vec::new();
    for directory in vfs_directories
        .iter()
        .filter(|directory| directory.parent_dir_id == dir_id)
    {
        entries.push(PpcStandardFileEntry {
            name: encode_mac_roman_lossy(ppc_vfs_basename(&directory.path))
                .into_iter()
                .take(63)
                .collect(),
            path: directory.path.clone(),
            dir_id: directory.dir_id,
            file_type: 0,
            finder_flags: directory.finder_flags,
            is_directory: true,
        });
    }
    for file in vfs_files {
        let Some(name) = ppc_child_name_for_parent(parent_path, &file.path) else {
            continue;
        };
        if file_types.is_some_and(|types| !types.contains(&file.file_type)) {
            continue;
        }
        entries.push(PpcStandardFileEntry {
            name: encode_mac_roman_lossy(name).into_iter().take(63).collect(),
            path: file.path.clone(),
            dir_id,
            file_type: file.file_type,
            finder_flags: file.finder_flags,
            is_directory: false,
        });
    }
    for fork in vfs_resource_files {
        // A resource-only record is visible, but a second resource record for
        // a data-backed file must not duplicate the catalog row.
        if vfs_files
            .iter()
            .any(|file| file.path.eq_ignore_ascii_case(&fork.path))
        {
            continue;
        }
        let Some(name) = ppc_child_name_for_parent(parent_path, &fork.path) else {
            continue;
        };
        if file_types.is_some_and(|types| !types.contains(&fork.file_type)) {
            continue;
        }
        entries.push(PpcStandardFileEntry {
            name: encode_mac_roman_lossy(name).into_iter().take(63).collect(),
            path: fork.path.clone(),
            dir_id,
            file_type: fork.file_type,
            finder_flags: fork.finder_flags,
            is_directory: false,
        });
    }
    entries.sort_by(|left, right| {
        (
            String::from_utf8_lossy(&left.name).to_ascii_lowercase(),
            u8::from(!left.is_directory),
            left.path.to_ascii_lowercase(),
        )
            .cmp(&(
                String::from_utf8_lossy(&right.name).to_ascii_lowercase(),
                u8::from(!right.is_directory),
                right.path.to_ascii_lowercase(),
            ))
    });
    entries
}

fn ppc_standard_file_save_pixels(
    memory: &mut PpcSectionMem,
    front: PpcFrontBuffer,
    bounds: (i16, i16, i16, i16),
) -> Vec<(i32, i32, u16)> {
    let top = i32::from(bounds.0).max(0).min(front.height as i32);
    let left = i32::from(bounds.1).max(0).min(front.width as i32);
    let bottom = i32::from(bounds.2).max(0).min(front.height as i32);
    let right = i32::from(bounds.3).max(0).min(front.width as i32);
    let mut pixels = Vec::new();
    for y in top..bottom {
        for x in left..right {
            if let Some(pixel) = ppc_quickdraw_read_pixel(memory, front, (x, y)) {
                pixels.push((x, y, pixel));
            }
        }
    }
    pixels
}

fn ppc_standard_file_restore_pixels(
    memory: &mut PpcSectionMem,
    pixels: &[(i32, i32, u16)],
    front: PpcFrontBuffer,
) {
    for (x, y, value) in pixels.iter().copied() {
        let _ = ppc_quickdraw_write_raw_pixel(memory, front, (x, y), value);
    }
}

fn ppc_standard_file_point_in_rect(
    point: (i16, i16),
    rect: (i16, i16, i16, i16),
) -> bool {
    point.0 >= rect.0 && point.0 < rect.2 && point.1 >= rect.1 && point.1 < rect.3
}

fn ppc_standard_file_centered_bounds(
    front: PpcFrontBuffer,
    width: i16,
    height: i16,
    requested_origin: Option<(i16, i16)>,
) -> (i16, i16, i16, i16) {
    let (centered_top, centered_left) = (
        (front.height as i16).saturating_sub(height) / 2,
        (front.width as i16).saturating_sub(width) / 2,
    );
    let (requested_top, requested_left) = requested_origin.unwrap_or((centered_top, centered_left));
    let top = requested_top
        .max(0)
        .min((front.height as i16).saturating_sub(height).max(0));
    let left = requested_left
        .max(0)
        .min((front.width as i16).saturating_sub(width).max(0));
    (top, left, top.saturating_add(height), left.saturating_add(width))
}

fn ppc_standard_file_point_from_gpr(point: u32) -> (i16, i16) {
    ((point >> 16) as u16 as i16, point as u16 as i16)
}

fn ppc_standard_file_requested_origin(symbol_name: &str, cpu: &PpcCpu) -> Option<(i16, i16)> {
    let point = match symbol_name {
        "SFGetFile" | "SFPGetFile" | "SFPutFile" | "SFPPutFile" => cpu.gpr[3],
        "CustomGetFile" => cpu.gpr[8],
        "CustomPutFile" => cpu.gpr[7],
        _ => return None,
    };
    let origin = ppc_standard_file_point_from_gpr(point);
    if origin == (-1, -1) {
        None
    } else {
        Some(origin)
    }
}

fn ppc_standard_file_prompt(memory: &mut PpcSectionMem, prompt_ptr: u32) -> Vec<u8> {
    if prompt_ptr == 0 {
        return b"Save as:".to_vec();
    }
    let prompt = ppc_read_pstring_bytes(memory, prompt_ptr).unwrap_or_default();
    if prompt.is_empty() {
        b"Save as:".to_vec()
    } else {
        prompt
    }
}

const PPC_STANDARD_FILE_FILTER_PB_SIZE: u32 = 256;
const PPC_STANDARD_FILE_FILTER_NAME_OFFSET: u32 = 128;

fn ppc_standard_file_filter_pointer(symbol_name: &str, cpu: &PpcCpu) -> (u32, bool) {
    match symbol_name {
        "StandardGetFile" | "CustomGetFile" => (cpu.gpr[3], symbol_name == "CustomGetFile"),
        "SFGetFile" | "SFPGetFile" => (cpu.gpr[5], false),
        _ => (0, false),
    }
}

fn ppc_standard_file_write_filter_pb(
    memory: &mut PpcSectionMem,
    filter_pb: u32,
    entry: &PpcStandardFileEntry,
) -> bool {
    if !ppc_memory_can_write_bytes(memory, filter_pb, PPC_STANDARD_FILE_FILTER_PB_SIZE) {
        return false;
    }
    let name_ptr = filter_pb.saturating_add(PPC_STANDARD_FILE_FILTER_NAME_OFFSET);
    ppc_write_pstring_bytes(memory, name_ptr, &entry.name)
        && memory.write_u32_be(filter_pb + 18, name_ptr).is_some()
        && memory
            .write_u16_be(filter_pb + 22, PPC_BOOT_VOLUME_REF_NUM as u16)
            .is_some()
        && memory.write_u16_be(filter_pb + 28, 0).is_some()
        && memory.write_u32_be(filter_pb + 48, entry.dir_id).is_some()
        && ppc_write_finfo(memory, filter_pb + 32, entry.file_type, 0, entry.finder_flags).is_some()
}

fn ppc_standard_file_filter_next_action(
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    state: &mut PpcStandardFileFilteringState,
) -> Option<PpcImportAction> {
    while state
        .tracking
        .entries
        .get(state.next_entry)
        .is_some_and(|entry| entry.is_directory)
    {
        state.next_entry = state.next_entry.saturating_add(1);
    }
    let entry = state.tracking.entries.get(state.next_entry)?;
    if entry.is_directory {
        return None;
    }
    if !ppc_standard_file_write_filter_pb(memory, state.filter_pb, entry) {
        return None;
    }
    let arguments = if state.callback_with_data {
        vec![state.filter_pb, 0]
    } else {
        vec![state.filter_pb]
    };
    ppc_install_native_call_arguments(cpu, memory, &arguments)?;
    Some(PpcImportAction::CallNative {
        entry: state.callback.entry,
        rtoc: state.callback.rtoc,
        return_pc: PPC_GUEST_CALL_RETURN_PC,
        final_pc: state.import_pc,
        restore_rtoc: state.restore_rtoc,
        return_gpr3: PpcNativeReturnGpr3::Mask(0xff),
    })
}

fn ppc_standard_file_dispose_filter_pb(
    process_memory_manager: &mut ProcessNativeMemoryManager,
    memory: &mut PpcSectionMem,
    heap_cursor: &mut u32,
    last_mem_error: &mut i16,
    filter_pb: u32,
) {
    if filter_pb != 0 {
        let _ = process_memory_manager.dispose_native_ptr(filter_pb);
        ppc_apply_process_native_allocator(
            process_memory_manager,
            memory,
            heap_cursor,
            last_mem_error,
        );
    }
}

fn ppc_standard_file_draw_button(
    memory: &mut PpcSectionMem,
    front: PpcFrontBuffer,
    gworlds: &[PpcGWorldRecord],
    bounds: (i16, i16, i16, i16),
    rect: (i16, i16, i16, i16),
    label: &[u8],
) {
    let global = (
        bounds.0.saturating_add(rect.0),
        bounds.1.saturating_add(rect.1),
        bounds.0.saturating_add(rect.2),
        bounds.1.saturating_add(rect.3),
    );
    let _ = ppc_fill_front_rect(memory, front, global, PPC_RGB_WHITE);
    let _ = ppc_frame_front_rect(memory, front, global, PPC_RGB_BLACK, 1);
    ppc_draw_dialog_text(memory, gworlds, global, label, PPC_RGB_BLACK);
}

fn ppc_standard_file_draw_scrollbar(
    memory: &mut PpcSectionMem,
    front: PpcFrontBuffer,
    gworlds: &[PpcGWorldRecord],
    bounds: (i16, i16, i16, i16),
) {
    let rect = (
        bounds.0.saturating_add(PPC_STANDARD_FILE_GET_SCROLL_RECT.0),
        bounds.1.saturating_add(PPC_STANDARD_FILE_GET_SCROLL_RECT.1),
        bounds.0.saturating_add(PPC_STANDARD_FILE_GET_SCROLL_RECT.2),
        bounds.1.saturating_add(PPC_STANDARD_FILE_GET_SCROLL_RECT.3),
    );
    let _ = ppc_fill_front_rect(memory, front, rect, PPC_RGB_WHITE);
    let _ = ppc_frame_front_rect(memory, front, rect, PPC_RGB_BLACK, 1);
    let middle = rect.0.saturating_add((rect.2 - rect.0) / 2);
    let _ = ppc_fill_front_rect(
        memory,
        front,
        (middle, rect.1, middle.saturating_add(1), rect.3),
        PPC_RGB_BLACK,
    );
    ppc_draw_dialog_text(
        memory,
        gworlds,
        (rect.0, rect.1, middle, rect.3),
        b"^",
        PPC_RGB_BLACK,
    );
    ppc_draw_dialog_text(
        memory,
        gworlds,
        (middle, rect.1, rect.2, rect.3),
        b"v",
        PPC_RGB_BLACK,
    );
}

fn ppc_standard_file_draw_get_dialog(
    memory: &mut PpcSectionMem,
    gworlds: &[PpcGWorldRecord],
    tracking: &PpcStandardFileGetTrackingState,
) {
    let front = tracking.front_buffer;
    let bounds = tracking.bounds;
    let _ = ppc_fill_front_rect(memory, front, bounds, PPC_RGB_WHITE);
    let _ = ppc_frame_front_rect(memory, front, bounds, PPC_RGB_BLACK, 2);
    ppc_draw_dialog_text(
        memory,
        gworlds,
        (
            bounds.0.saturating_add(14),
            bounds.1.saturating_add(18),
            bounds.0.saturating_add(32),
            bounds.1.saturating_add(330),
        ),
        b"Open File",
        PPC_RGB_BLACK,
    );
    let list = (
        bounds.0.saturating_add(PPC_STANDARD_FILE_GET_LIST_RECT.0),
        bounds.1.saturating_add(PPC_STANDARD_FILE_GET_LIST_RECT.1),
        bounds.0.saturating_add(PPC_STANDARD_FILE_GET_LIST_RECT.2),
        bounds.1.saturating_add(PPC_STANDARD_FILE_GET_LIST_RECT.3),
    );
    let _ = ppc_fill_front_rect(memory, front, list, PPC_RGB_WHITE);
    let _ = ppc_frame_front_rect(memory, front, list, PPC_RGB_BLACK, 1);
    let visible_rows = 8usize;
    let first_visible = tracking.selected.saturating_sub(visible_rows - 1);
    for row in 0..visible_rows {
        let index = first_visible + row;
        let Some(entry) = tracking.entries.get(index) else {
            break;
        };
        let row_top = list.0.saturating_add(2).saturating_add(
            i16::try_from(row)
                .unwrap_or(i16::MAX)
                .saturating_mul(PPC_STANDARD_FILE_GET_ROW_HEIGHT),
        );
        let row_bottom = row_top
            .saturating_add(PPC_STANDARD_FILE_GET_ROW_HEIGHT)
            .min(list.2.saturating_sub(1));
        let selected = index == tracking.selected;
        let row_rect = (
            row_top,
            list.1.saturating_add(2),
            row_bottom,
            list.3.saturating_sub(2),
        );
        if selected {
            let _ = ppc_fill_front_rect(memory, front, row_rect, PPC_RGB_BLACK);
        }
        let mut text = entry.name.clone();
        if entry.is_directory {
            text.extend_from_slice(b" >");
        }
        ppc_draw_dialog_text(
            memory,
            gworlds,
            (
                row_top.saturating_add(1),
                list.1.saturating_add(5),
                row_bottom,
                list.3.saturating_sub(3),
            ),
            &text,
            if selected { PPC_RGB_WHITE } else { PPC_RGB_BLACK },
        );
    }
    let filter = tracking
        .file_types
        .as_ref()
        .and_then(|types| types.first().copied())
        .map(|value| value.to_be_bytes())
        .unwrap_or(*b"ALL ");
    let mut filter_label = b"Filter: ".to_vec();
    filter_label.extend_from_slice(&filter);
    ppc_draw_dialog_text(
        memory,
        gworlds,
        (
            bounds.0.saturating_add(14),
            bounds.1.saturating_add(190),
            bounds.0.saturating_add(34),
            bounds.1.saturating_add(330),
        ),
        &filter_label,
        PPC_RGB_BLACK,
    );
    ppc_standard_file_draw_scrollbar(memory, front, gworlds, bounds);
    ppc_standard_file_draw_button(
        memory,
        front,
        gworlds,
        bounds,
        PPC_STANDARD_FILE_GET_DESKTOP_RECT,
        b"Desktop",
    );
    ppc_standard_file_draw_button(
        memory,
        front,
        gworlds,
        bounds,
        PPC_STANDARD_FILE_GET_CANCEL_RECT,
        b"Cancel",
    );
    ppc_standard_file_draw_button(
        memory,
        front,
        gworlds,
        bounds,
        PPC_STANDARD_FILE_GET_OPEN_RECT,
        b"Open",
    );
}

fn ppc_standard_file_draw_put_dialog(
    memory: &mut PpcSectionMem,
    gworlds: &[PpcGWorldRecord],
    tracking: &PpcStandardFilePutTrackingState,
) {
    let front = tracking.front_buffer;
    let bounds = tracking.bounds;
    let _ = ppc_fill_front_rect(memory, front, bounds, PPC_RGB_WHITE);
    let _ = ppc_frame_front_rect(memory, front, bounds, PPC_RGB_BLACK, 2);
    ppc_draw_dialog_text(
        memory,
        gworlds,
        (
            bounds.0.saturating_add(14),
            bounds.1.saturating_add(18),
            bounds.0.saturating_add(32),
            bounds.1.saturating_add(330),
        ),
        b"Save File",
        PPC_RGB_BLACK,
    );
    ppc_draw_dialog_text(
        memory,
        gworlds,
        (
            bounds.0.saturating_add(32),
            bounds.1.saturating_add(18),
            bounds.0.saturating_add(50),
            bounds.1.saturating_add(330),
        ),
        &tracking.prompt,
        PPC_RGB_BLACK,
    );
    let name = (
        bounds.0.saturating_add(PPC_STANDARD_FILE_PUT_NAME_RECT.0),
        bounds.1.saturating_add(PPC_STANDARD_FILE_PUT_NAME_RECT.1),
        bounds.0.saturating_add(PPC_STANDARD_FILE_PUT_NAME_RECT.2),
        bounds.1.saturating_add(PPC_STANDARD_FILE_PUT_NAME_RECT.3),
    );
    let _ = ppc_fill_front_rect(memory, front, name, PPC_RGB_WHITE);
    let _ = ppc_frame_front_rect(memory, front, name, PPC_RGB_BLACK, 1);
    let selected = tracking.sel_start < tracking.sel_end;
    if selected {
        let _ = ppc_fill_front_rect(
            memory,
            front,
            (
                name.0,
                name.1.saturating_add(2),
                name.2,
                name.3.saturating_sub(2),
            ),
            PPC_RGB_BLACK,
        );
    }
    ppc_draw_dialog_text(
        memory,
        gworlds,
        (name.0.saturating_add(2), name.1, name.2, name.3),
        &tracking.name,
        if selected { PPC_RGB_WHITE } else { PPC_RGB_BLACK },
    );
    ppc_standard_file_draw_button(
        memory,
        front,
        gworlds,
        bounds,
        PPC_STANDARD_FILE_PUT_CANCEL_RECT,
        b"Cancel",
    );
    ppc_standard_file_draw_button(
        memory,
        front,
        gworlds,
        bounds,
        PPC_STANDARD_FILE_PUT_SAVE_RECT,
        b"Save",
    );
}

fn ppc_standard_file_write_cancel_reply(
    memory: &mut PpcSectionMem,
    mode: PpcStandardFileMode,
    reply: u32,
) {
    if reply == 0 {
        return;
    }
    // sfGood/good is the only defined result after cancellation; preserve
    // the caller-owned tail just as Standard File does on classic systems.
    let _ = memory.write_u8(reply, 0);
    let _ = mode;
}

fn ppc_standard_file_working_directory_ref(
    vref: i16,
    dir_id: u32,
    vfs_volumes: &[PpcVfsVolumeRecord],
    working_directories: &mut HashMap<i16, ProcessWorkingDirectory>,
    next_working_directory_ref_num: &mut i16,
) -> i16 {
    let root_dir_id = if vref == PPC_BOOT_VOLUME_REF_NUM {
        PPC_ROOT_DIR_ID
    } else {
        vfs_volumes
            .iter()
            .find(|volume| volume.ref_num == vref)
            .map(|volume| volume.root_dir_id)
            .unwrap_or(PPC_ROOT_DIR_ID)
    };
    if dir_id == root_dir_id {
        return vref;
    }
    if let Some(existing) = working_directories.values().find(|record| {
        record.volume_ref_num == vref && record.dir_id == dir_id && record.proc_id == 0
    }) {
        return existing.ref_num;
    }
    let mut ref_num = (*next_working_directory_ref_num).max(1);
    while ref_num == PPC_BOOT_VOLUME_REF_NUM || working_directories.contains_key(&ref_num) {
        ref_num = ref_num.saturating_add(1);
    }
    *next_working_directory_ref_num = ref_num.saturating_add(1);
    working_directories.insert(
        ref_num,
        ProcessWorkingDirectory {
            ref_num,
            volume_ref_num: vref,
            dir_id,
            proc_id: 0,
        },
    );
    ref_num
}

fn ppc_standard_file_write_get_reply(
    memory: &mut PpcSectionMem,
    mode: PpcStandardFileMode,
    reply: u32,
    entry: &PpcStandardFileEntry,
    legacy_wd_ref: i16,
) {
    if reply == 0 {
        return;
    }
    match mode {
        PpcStandardFileMode::GetModern => {
            if memory.write_u8(reply, 1).is_none() {
                return;
            }
            let _ = memory.write_u8(reply + 1, 0);
            let _ = memory.write_u32_be(reply + 2, entry.file_type);
            let _ = ppc_write_fsspec(
                memory,
                reply + 6,
                PPC_BOOT_VOLUME_REF_NUM,
                entry.dir_id,
                &entry.name,
            );
            let _ = memory.write_u16_be(reply + 76, 0);
            let _ = memory.write_u16_be(reply + 78, entry.finder_flags);
            let _ = memory.write_u8(reply + 80, 0);
            let _ = memory.write_u8(reply + 81, 0);
            let _ = memory.write_u32_be(reply + 82, 0);
            let _ = memory.write_u16_be(reply + 86, 0);
        }
        PpcStandardFileMode::GetLegacy => {
            if memory.write_u8(reply, 1).is_none() {
                return;
            }
            let _ = memory.write_u8(reply + 1, 0);
            let _ = memory.write_u32_be(reply + 2, entry.file_type);
            let _ = memory.write_u16_be(reply + 6, legacy_wd_ref as u16);
            let _ = memory.write_u16_be(reply + 8, 0);
            let _ = ppc_write_pstring_bytes(memory, reply + 10, &entry.name);
        }
        PpcStandardFileMode::PutModern | PpcStandardFileMode::PutLegacy => {}
    }
}

fn ppc_standard_file_write_put_reply(
    memory: &mut PpcSectionMem,
    mode: PpcStandardFileMode,
    reply: u32,
    vref: i16,
    dir_id: u32,
    name: &[u8],
    replacing: bool,
) {
    if reply == 0 {
        return;
    }
    match mode {
        PpcStandardFileMode::PutModern => {
            if memory.write_u8(reply, 1).is_none() {
                return;
            }
            let _ = memory.write_u8(reply + 1, u8::from(replacing));
            let _ = memory.write_u32_be(reply + 2, 0);
            let _ = ppc_write_fsspec(memory, reply + 6, vref, dir_id, name);
            let _ = memory.write_u16_be(reply + 76, 0);
            let _ = memory.write_u16_be(reply + 78, 0);
            let _ = memory.write_u8(reply + 80, 0);
            let _ = memory.write_u8(reply + 81, 0);
            let _ = memory.write_u32_be(reply + 82, 0);
            let _ = memory.write_u16_be(reply + 86, 0);
        }
        PpcStandardFileMode::PutLegacy => {
            if memory.write_u8(reply, 1).is_none() {
                return;
            }
            let _ = memory.write_u8(reply + 1, 0);
            let _ = memory.write_u32_be(reply + 2, 0);
            let _ = memory.write_u16_be(reply + 6, vref as u16);
            let _ = memory.write_u16_be(reply + 8, 0);
            let _ = ppc_write_pstring_bytes(memory, reply + 10, name);
        }
        PpcStandardFileMode::GetModern | PpcStandardFileMode::GetLegacy => {}
    }
}

fn ppc_standard_file_finish_get(
    memory: &mut PpcSectionMem,
    startup: &mut PpcToolboxStartupState,
    tracking: PpcStandardFileGetTrackingState,
    vfs_volumes: &[PpcVfsVolumeRecord],
    working_directories: &mut HashMap<i16, ProcessWorkingDirectory>,
    next_working_directory_ref_num: &mut i16,
    accepted: bool,
) -> PpcImportAction {
    ppc_standard_file_restore_pixels(memory, &tracking.saved_pixels, tracking.front_buffer);
    if accepted
        && tracking
            .entries
            .get(tracking.selected)
            .is_some_and(|entry| !entry.is_directory)
    {
        let legacy_wd_ref = if tracking.call.mode == PpcStandardFileMode::GetLegacy {
            ppc_standard_file_working_directory_ref(
                PPC_BOOT_VOLUME_REF_NUM,
                tracking.entries.get(tracking.selected).unwrap().dir_id,
                vfs_volumes,
                working_directories,
                next_working_directory_ref_num,
            )
        } else {
            PPC_BOOT_VOLUME_REF_NUM
        };
        ppc_standard_file_write_get_reply(
            memory,
            tracking.call.mode,
            tracking.call.reply,
            tracking.entries.get(tracking.selected).unwrap(),
            legacy_wd_ref,
        );
    } else {
        ppc_standard_file_write_cancel_reply(memory, tracking.call.mode, tracking.call.reply);
    }
    startup.standard_file_get_tracking = None;
    PpcImportAction::ReturnPreserve
}

fn ppc_standard_file_finish_put(
    memory: &mut PpcSectionMem,
    startup: &mut PpcToolboxStartupState,
    tracking: PpcStandardFilePutTrackingState,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    vfs_volumes: &[PpcVfsVolumeRecord],
    working_directories: &mut HashMap<i16, ProcessWorkingDirectory>,
    next_working_directory_ref_num: &mut i16,
    accepted: bool,
) -> PpcImportAction {
    ppc_standard_file_restore_pixels(memory, &tracking.saved_pixels, tracking.front_buffer);
    if accepted && !tracking.name.is_empty() {
        let replacing = ppc_fsspec_target_exists(
            vfs_directories,
            vfs_files,
            vfs_resource_files,
            tracking.dir_id,
            &tracking.name,
        );
        let vref = if tracking.call.mode == PpcStandardFileMode::PutLegacy {
            ppc_standard_file_working_directory_ref(
                tracking.vref,
                tracking.dir_id,
                vfs_volumes,
                working_directories,
                next_working_directory_ref_num,
            )
        } else {
            tracking.vref
        };
        ppc_standard_file_write_put_reply(
            memory,
            tracking.call.mode,
            tracking.call.reply,
            vref,
            tracking.dir_id,
            &tracking.name,
            replacing,
        );
    } else {
        ppc_standard_file_write_cancel_reply(memory, tracking.call.mode, tracking.call.reply);
    }
    startup.standard_file_put_tracking = None;
    PpcImportAction::ReturnPreserve
}

fn ppc_standard_file_backspace_name(tracking: &mut PpcStandardFilePutTrackingState) {
    let start = tracking.sel_start.min(tracking.name.len());
    let end = tracking.sel_end.min(tracking.name.len()).max(start);
    if start < end {
        tracking.name.drain(start..end);
        tracking.sel_start = start;
        tracking.sel_end = start;
    } else if start > 0 {
        tracking.name.remove(start - 1);
        tracking.sel_start = start - 1;
        tracking.sel_end = start - 1;
    } else {
        tracking.sel_start = 0;
        tracking.sel_end = 0;
    }
}

fn ppc_standard_file_insert_name_character(
    tracking: &mut PpcStandardFilePutTrackingState,
    character: u8,
) {
    let start = tracking.sel_start.min(tracking.name.len());
    let end = tracking.sel_end.min(tracking.name.len()).max(start);
    let retained_len = tracking.name.len().saturating_sub(end - start);
    if retained_len >= 63 {
        tracking.sel_start = start.min(63);
        tracking.sel_end = tracking.sel_start;
        return;
    }
    tracking.name.splice(start..end, [character]);
    tracking.name.truncate(63);
    tracking.sel_start = start.saturating_add(1).min(tracking.name.len());
    tracking.sel_end = tracking.sel_start;
}

fn ppc_standard_file_get_service(
    cpu: &PpcCpu,
    memory: &mut PpcSectionMem,
    startup: &mut PpcToolboxStartupState,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &ProcessVfsFileRecords,
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    vfs_volumes: &[PpcVfsVolumeRecord],
    working_directories: &mut HashMap<i16, ProcessWorkingDirectory>,
    next_working_directory_ref_num: &mut i16,
    event_queue: &mut EventQueue,
    gworlds: &[PpcGWorldRecord],
) -> PpcImportAction {
    let Some(mut tracking) = startup.standard_file_get_tracking.take() else {
        return PpcImportAction::ReturnPreserve;
    };
    if tracking.call.return_address != cpu.lr {
        return ppc_standard_file_finish_get(
            memory,
            startup,
            tracking,
            vfs_volumes,
            working_directories,
            next_working_directory_ref_num,
            false,
        );
    }
    let event = event_queue
        .iter()
        .position(|event| matches!(event.what, 1 | 3 | 5))
        .and_then(|index| event_queue.remove(index));
    let mut open = false;
    if let Some(event) = event {
        if event.what == 1 {
            let local = (
                event.where_v.saturating_sub(tracking.bounds.0),
                event.where_h.saturating_sub(tracking.bounds.1),
            );
            if ppc_standard_file_point_in_rect(local, PPC_STANDARD_FILE_GET_CANCEL_RECT) {
                return ppc_standard_file_finish_get(
                    memory,
                    startup,
                    tracking,
                    vfs_volumes,
                    working_directories,
                    next_working_directory_ref_num,
                    false,
                );
            }
            if ppc_standard_file_point_in_rect(local, PPC_STANDARD_FILE_GET_DESKTOP_RECT) {
                tracking.current_dir_id = PPC_ROOT_DIR_ID;
                tracking.entries = ppc_standard_file_get_entries(
                    vfs_directories,
                    vfs_files,
                    vfs_resource_files,
                    PPC_ROOT_DIR_ID,
                    tracking.file_types.as_deref(),
                );
                tracking.selected = 0;
            } else if ppc_standard_file_point_in_rect(local, PPC_STANDARD_FILE_GET_OPEN_RECT) {
                open = true;
            } else if ppc_standard_file_point_in_rect(local, PPC_STANDARD_FILE_GET_LIST_RECT)
                && !tracking.entries.is_empty()
            {
                let row = ((local.0 - PPC_STANDARD_FILE_GET_LIST_RECT.0 - 2)
                    / PPC_STANDARD_FILE_GET_ROW_HEIGHT)
                    .max(0) as usize;
                let first_visible = tracking.selected.saturating_sub(7);
                let index = first_visible.saturating_add(row);
                if index < tracking.entries.len() {
                    tracking.selected = index;
                }
            } else if ppc_standard_file_point_in_rect(local, PPC_STANDARD_FILE_GET_SCROLL_RECT)
                && !tracking.entries.is_empty()
            {
                let halfway = (PPC_STANDARD_FILE_GET_SCROLL_RECT.2
                    - PPC_STANDARD_FILE_GET_SCROLL_RECT.0)
                    / 2;
                tracking.selected = if local.0 < PPC_STANDARD_FILE_GET_SCROLL_RECT.0 + halfway {
                    tracking.selected.saturating_sub(1)
                } else {
                    (tracking.selected + 1).min(tracking.entries.len() - 1)
                };
            }
        } else {
            let character = event.message as u8;
            let key_code = (event.message >> 8) as u8;
            if character == b'\r'
                || character == 3
                || key_code == PPC_KEY_RETURN
                || key_code == PPC_KEY_NUMPAD_ENTER
            {
                open = true;
            } else if character == 0x1b || key_code == PPC_KEY_ESCAPE {
                return ppc_standard_file_finish_get(
                    memory,
                    startup,
                    tracking,
                    vfs_volumes,
                    working_directories,
                    next_working_directory_ref_num,
                    false,
                );
            } else if key_code == 0x7e || character == 0x1e {
                tracking.selected = tracking.selected.saturating_sub(1);
            } else if key_code == 0x7d || character == 0x1f {
                if !tracking.entries.is_empty() {
                    tracking.selected = (tracking.selected + 1).min(tracking.entries.len() - 1);
                }
            }
        }
    }
    if open {
        if let Some(entry) = tracking.entries.get(tracking.selected) {
            if entry.is_directory {
                tracking.current_dir_id = entry.dir_id;
                tracking.entries = ppc_standard_file_get_entries(
                    vfs_directories,
                    vfs_files,
                    vfs_resource_files,
                    entry.dir_id,
                    tracking.file_types.as_deref(),
                );
                tracking.selected = 0;
            } else {
                return ppc_standard_file_finish_get(
                    memory,
                    startup,
                    tracking,
                    vfs_volumes,
                    working_directories,
                    next_working_directory_ref_num,
                    true,
                );
            }
        }
    }
    ppc_standard_file_draw_get_dialog(memory, gworlds, &tracking);
    startup.standard_file_get_tracking = Some(tracking);
    PpcImportAction::Yield(u64::MAX)
}

fn ppc_standard_file_get_start(
    symbol_name: &str,
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    startup: &mut PpcToolboxStartupState,
    process_memory_manager: &mut ProcessNativeMemoryManager,
    heap_cursor: &mut u32,
    last_mem_error: &mut i16,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &ProcessVfsFileRecords,
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    vfs_volumes: &[PpcVfsVolumeRecord],
    working_directories: &mut HashMap<i16, ProcessWorkingDirectory>,
    next_working_directory_ref_num: &mut i16,
    default_dir_id: u32,
    event_queue: &mut EventQueue,
    gworlds: &[PpcGWorldRecord],
    mode: PpcStandardFileMode,
    requested_origin: Option<(i16, i16)>,
) -> PpcImportAction {
    if let Some(mut filtering) = startup.standard_file_get_filtering.take() {
        if filtering.import_pc == cpu.pc && cpu.lr == cpu.pc {
            let candidate_index = filtering.next_entry;
            let accepted = cpu.gpr[3] & 0xff != 0;
            if accepted {
                filtering.next_entry = filtering.next_entry.saturating_add(1);
            } else if candidate_index < filtering.tracking.entries.len()
                && !filtering.tracking.entries[candidate_index].is_directory
            {
                filtering.tracking.entries.remove(candidate_index);
            }
            if let Some(action) = ppc_standard_file_filter_next_action(
                cpu,
                memory,
                &mut filtering,
            ) {
                startup.standard_file_get_filtering = Some(filtering);
                return action;
            }
            ppc_standard_file_dispose_filter_pb(
                process_memory_manager,
                memory,
                heap_cursor,
                last_mem_error,
                filtering.filter_pb,
            );
            let tracking = filtering.tracking;
            ppc_standard_file_draw_get_dialog(memory, gworlds, &tracking);
            startup.standard_file_get_tracking = Some(tracking);
            return PpcImportAction::Yield(u64::MAX);
        }
        ppc_standard_file_dispose_filter_pb(
            process_memory_manager,
            memory,
            heap_cursor,
            last_mem_error,
            filtering.filter_pb,
        );
        ppc_standard_file_restore_pixels(
            memory,
            &filtering.tracking.saved_pixels,
            filtering.tracking.front_buffer,
        );
        ppc_standard_file_write_cancel_reply(
            memory,
            filtering.tracking.call.mode,
            filtering.tracking.call.reply,
        );
        return PpcImportAction::ReturnPreserve;
    }
    if startup.standard_file_get_tracking.is_some() {
        return ppc_standard_file_get_service(
            cpu,
            memory,
            startup,
            vfs_directories,
            vfs_files,
            vfs_resource_files,
            vfs_volumes,
            working_directories,
            next_working_directory_ref_num,
            event_queue,
            gworlds,
        );
    }
    let (num_types, type_list) = match mode {
        PpcStandardFileMode::GetModern => (cpu.gpr[4] as u16 as i16, cpu.gpr[5]),
        PpcStandardFileMode::GetLegacy => (cpu.gpr[6] as u16 as i16, cpu.gpr[7]),
        PpcStandardFileMode::PutModern | PpcStandardFileMode::PutLegacy => {
            return PpcImportAction::ReturnPreserve
        }
    };
    let reply = ppc_standard_file_reply_ptr(mode, cpu);
    let Some(file_types) = ppc_standard_file_get_type_list(memory, num_types, type_list) else {
        ppc_standard_file_write_cancel_reply(memory, mode, reply);
        return PpcImportAction::ReturnPreserve;
    };
    let current_dir_id = ppc_directory_path_for_id(vfs_directories, default_dir_id)
        .map(|_| default_dir_id)
        .unwrap_or(PPC_ROOT_DIR_ID);
    let entries = ppc_standard_file_get_entries(
        vfs_directories,
        vfs_files,
        vfs_resource_files,
        current_dir_id,
        file_types.as_deref(),
    );
    let Some(front_buffer) = ppc_front_buffer_for_gworld(gworlds, PPC_MAIN_GWORLD) else {
        ppc_standard_file_write_cancel_reply(memory, mode, reply);
        return PpcImportAction::ReturnPreserve;
    };
    let bounds = ppc_standard_file_centered_bounds(
        front_buffer,
        PPC_STANDARD_FILE_GET_DIALOG_WIDTH,
        PPC_STANDARD_FILE_GET_DIALOG_HEIGHT,
        requested_origin,
    );
    let mut tracking = PpcStandardFileGetTrackingState {
        call: ppc_standard_file_call(mode, cpu),
        entries,
        current_dir_id,
        file_types,
        selected: 0,
        bounds,
        front_buffer,
        saved_pixels: ppc_standard_file_save_pixels(memory, front_buffer, bounds),
    };
    let (filter_ptr, callback_with_data) = ppc_standard_file_filter_pointer(symbol_name, cpu);
    if filter_ptr != 0 {
        if let Some(callback) = ppc_resolve_callback_target(memory, filter_ptr, cpu.gpr[2], None)
            .filter(|callback| memory.read_u32_be(callback.entry).is_some())
        {
            let filter_pb = process_memory_manager.new_native_ptr(
                memory,
                PPC_STANDARD_FILE_FILTER_PB_SIZE,
                true,
            );
            ppc_apply_process_native_allocator(
                process_memory_manager,
                memory,
                heap_cursor,
                last_mem_error,
            );
            if filter_pb != 0 {
                let mut filtering = PpcStandardFileFilteringState {
                    import_pc: cpu.pc,
                    restore_rtoc: cpu.gpr[2],
                    callback,
                    callback_with_data,
                    tracking,
                    next_entry: 0,
                    filter_pb,
                };
                if let Some(action) =
                    ppc_standard_file_filter_next_action(cpu, memory, &mut filtering)
                {
                    startup.standard_file_get_filtering = Some(filtering);
                    return action;
                }
                ppc_standard_file_dispose_filter_pb(
                    process_memory_manager,
                    memory,
                    heap_cursor,
                    last_mem_error,
                    filter_pb,
                );
                tracking = filtering.tracking;
            }
        }
    }
    ppc_standard_file_draw_get_dialog(memory, gworlds, &tracking);
    startup.standard_file_get_tracking = Some(tracking);
    PpcImportAction::Yield(u64::MAX)
}

fn ppc_standard_file_put_start(
    cpu: &PpcCpu,
    memory: &mut PpcSectionMem,
    startup: &mut PpcToolboxStartupState,
    default_dir_id: u32,
    gworlds: &[PpcGWorldRecord],
    mode: PpcStandardFileMode,
    prompt_ptr: u32,
    requested_origin: Option<(i16, i16)>,
) -> PpcImportAction {
    let name_ptr = match mode {
        PpcStandardFileMode::PutModern => cpu.gpr[4],
        PpcStandardFileMode::PutLegacy => cpu.gpr[5],
        PpcStandardFileMode::GetModern | PpcStandardFileMode::GetLegacy => {
            return PpcImportAction::ReturnPreserve
        }
    };
    let mut name = if name_ptr != 0 {
        ppc_read_pstring_bytes(memory, name_ptr).unwrap_or_default()
    } else {
        Vec::new()
    };
    if name.is_empty() {
        name.extend_from_slice(b"Untitled");
    }
    name.truncate(63);
    let reply = ppc_standard_file_reply_ptr(mode, cpu);
    let Some(front_buffer) = ppc_front_buffer_for_gworld(gworlds, PPC_MAIN_GWORLD) else {
        ppc_standard_file_write_cancel_reply(memory, mode, reply);
        return PpcImportAction::ReturnPreserve;
    };
    let bounds = ppc_standard_file_centered_bounds(
        front_buffer,
        PPC_STANDARD_FILE_PUT_DIALOG_WIDTH,
        PPC_STANDARD_FILE_PUT_DIALOG_HEIGHT,
        requested_origin,
    );
    let tracking = PpcStandardFilePutTrackingState {
        call: ppc_standard_file_call(mode, cpu),
        vref: PPC_BOOT_VOLUME_REF_NUM,
        dir_id: default_dir_id,
        prompt: ppc_standard_file_prompt(memory, prompt_ptr),
        name: name.clone(),
        sel_start: 0,
        sel_end: name.len(),
        bounds,
        front_buffer,
        saved_pixels: ppc_standard_file_save_pixels(memory, front_buffer, bounds),
    };
    ppc_standard_file_draw_put_dialog(memory, gworlds, &tracking);
    startup.standard_file_put_tracking = Some(tracking);
    PpcImportAction::Yield(u64::MAX)
}

#[allow(clippy::too_many_arguments)]
fn ppc_dispatch_standard_file(
    symbol_name: &str,
    mode: PpcStandardFileMode,
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    startup: &mut PpcToolboxStartupState,
    process_memory_manager: &mut ProcessNativeMemoryManager,
    heap_cursor: &mut u32,
    last_mem_error: &mut i16,
    gworlds: &[PpcGWorldRecord],
    vfs_directories: &mut Vec<PpcVfsDirectory>,
    vfs_files: &ProcessVfsFileRecords,
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    vfs_volumes: &[PpcVfsVolumeRecord],
    default_dir_id: u32,
    working_directories: &mut HashMap<i16, ProcessWorkingDirectory>,
    next_working_directory_ref_num: &mut i16,
    event_queue: &mut EventQueue,
) -> PpcImportAction {
    let requested_origin = ppc_standard_file_requested_origin(symbol_name, cpu);
    match mode {
        PpcStandardFileMode::GetModern | PpcStandardFileMode::GetLegacy => {
            ppc_standard_file_get_start(
                symbol_name,
                cpu,
                memory,
                startup,
                process_memory_manager,
                heap_cursor,
                last_mem_error,
                vfs_directories,
                vfs_files,
                vfs_resource_files,
                vfs_volumes,
                working_directories,
                next_working_directory_ref_num,
                default_dir_id,
                event_queue,
                gworlds,
                mode,
                requested_origin,
            )
        }
        PpcStandardFileMode::PutModern | PpcStandardFileMode::PutLegacy => {
            if let Some(mut tracking) = startup.standard_file_put_tracking.take() {
                if tracking.call.return_address != cpu.lr {
                    return ppc_standard_file_finish_put(
                        memory,
                        startup,
                        tracking,
                        vfs_directories,
                        vfs_files,
                        vfs_resource_files,
                        vfs_volumes,
                        working_directories,
                        next_working_directory_ref_num,
                        false,
                    );
                }
                let event = event_queue
                    .iter()
                    .position(|event| matches!(event.what, 1 | 3 | 5))
                    .and_then(|index| event_queue.remove(index));
                let mut accept = false;
                if let Some(event) = event {
                    if event.what == 1 {
                        let local = (
                            event.where_v.saturating_sub(tracking.bounds.0),
                            event.where_h.saturating_sub(tracking.bounds.1),
                        );
                        if ppc_standard_file_point_in_rect(local, PPC_STANDARD_FILE_PUT_CANCEL_RECT)
                        {
                            return ppc_standard_file_finish_put(
                                memory,
                                startup,
                                tracking,
                                vfs_directories,
                                vfs_files,
                                vfs_resource_files,
                                vfs_volumes,
                                working_directories,
                                next_working_directory_ref_num,
                                false,
                            );
                        }
                        accept = ppc_standard_file_point_in_rect(
                            local,
                            PPC_STANDARD_FILE_PUT_SAVE_RECT,
                        );
                    } else {
                        let character = event.message as u8;
                        let key_code = (event.message >> 8) as u8;
                        if character == b'\r'
                            || character == 3
                            || key_code == PPC_KEY_RETURN
                            || key_code == PPC_KEY_NUMPAD_ENTER
                        {
                            accept = true;
                        } else if character == 0x1b || key_code == PPC_KEY_ESCAPE {
                            return ppc_standard_file_finish_put(
                                memory,
                                startup,
                                tracking,
                                vfs_directories,
                                vfs_files,
                                vfs_resource_files,
                                vfs_volumes,
                                working_directories,
                                next_working_directory_ref_num,
                                false,
                            );
                        } else if character.eq_ignore_ascii_case(&b'a')
                            && event.modifiers & 0x0100 != 0
                        {
                            tracking.sel_start = 0;
                            tracking.sel_end = tracking.name.len();
                        } else if character == 0x08 || key_code == 0x33 {
                            ppc_standard_file_backspace_name(&mut tracking);
                        } else if event.modifiers & 0x0100 == 0
                            && (0x20..=0x7e).contains(&character)
                            && !matches!(character, b'/' | b':')
                            && tracking.sel_start <= tracking.sel_end
                            && tracking.sel_end <= tracking.name.len()
                        {
                            ppc_standard_file_insert_name_character(&mut tracking, character);
                        }
                    }
                }
                if accept {
                    return ppc_standard_file_finish_put(
                        memory,
                        startup,
                        tracking,
                        vfs_directories,
                        vfs_files,
                        vfs_resource_files,
                        vfs_volumes,
                        working_directories,
                        next_working_directory_ref_num,
                        true,
                    );
                }
                ppc_standard_file_draw_put_dialog(memory, gworlds, &tracking);
                startup.standard_file_put_tracking = Some(tracking);
                PpcImportAction::Yield(u64::MAX)
            } else {
                let prompt_ptr = match symbol_name {
                    "StandardPutFile" | "CustomPutFile" => cpu.gpr[3],
                    "SFPutFile" | "SFPPutFile" => cpu.gpr[4],
                    _ => 0,
                };
                ppc_standard_file_put_start(
                    cpu,
                    memory,
                    startup,
                    default_dir_id,
                    gworlds,
                    mode,
                    prompt_ptr,
                    requested_origin,
                )
            }
        }
    }
}

fn ppc_fsp_get_finfo(
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
) -> i16 {
    let spec_ptr = cpu.gpr[3];
    let finfo_ptr = cpu.gpr[4];
    if finfo_ptr == 0 {
        return PPC_PARAM_ERR;
    }
    let path = match ppc_path_for_fsspec(memory, vfs_directories, spec_ptr) {
        Ok(path) => path,
        Err(err) => return err,
    };
    if let Some(directory) = vfs_directories
        .iter()
        .find(|directory| directory.path.eq_ignore_ascii_case(&path))
    {
        return if ppc_write_finfo(
            memory,
            finfo_ptr,
            directory.file_type,
            directory.creator,
            directory.finder_flags,
        )
        .is_some()
        {
            PPC_NO_ERR
        } else {
            PPC_PARAM_ERR
        };
    }
    if let Some(file) = vfs_files
        .iter()
        .find(|record| record.path.eq_ignore_ascii_case(&path))
    {
        return if ppc_write_finfo(
            memory,
            finfo_ptr,
            file.file_type,
            file.creator,
            file.finder_flags,
        )
        .is_some()
        {
            PPC_NO_ERR
        } else {
            PPC_PARAM_ERR
        };
    }
    if let Some(file) = vfs_resource_files
        .iter()
        .find(|record| record.path.eq_ignore_ascii_case(&path))
    {
        return if ppc_write_finfo(
            memory,
            finfo_ptr,
            file.file_type,
            file.creator,
            file.finder_flags,
        )
        .is_some()
        {
            PPC_NO_ERR
        } else {
            PPC_PARAM_ERR
        };
    }
    let _ = ppc_write_finfo(memory, finfo_ptr, 0, 0, 0);
    PPC_FNF_ERR
}

fn ppc_fsp_set_finfo(
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_directories: &mut [PpcVfsDirectory],
    vfs_files: &mut [PpcVfsFileRecord],
    vfs_resource_files: &mut [PpcVfsResourceFileRecord],
) -> i16 {
    let spec_ptr = cpu.gpr[3];
    let finfo_ptr = cpu.gpr[4];
    if finfo_ptr == 0 {
        return PPC_PARAM_ERR;
    }
    let path = match ppc_path_for_fsspec(memory, vfs_directories, spec_ptr) {
        Ok(path) => path,
        Err(err) => return err,
    };
    let Some((file_type, creator, finder_flags)) = ppc_read_finfo(memory, finfo_ptr) else {
        return PPC_PARAM_ERR;
    };
    let mut found = false;
    for file in vfs_files
        .iter_mut()
        .filter(|record| record.path.eq_ignore_ascii_case(&path))
    {
        file.file_type = file_type;
        file.creator = creator;
        file.finder_flags = finder_flags;
        file.dirty = true;
        found = true;
    }
    for file in vfs_resource_files
        .iter_mut()
        .filter(|record| record.path.eq_ignore_ascii_case(&path))
    {
        file.file_type = file_type;
        file.creator = creator;
        file.finder_flags = finder_flags;
        file.dirty = true;
        found = true;
    }
    if found {
        PPC_NO_ERR
    } else if let Some(directory) = vfs_directories
        .iter_mut()
        .find(|directory| directory.path.eq_ignore_ascii_case(&path))
    {
        directory.file_type = file_type;
        directory.creator = creator;
        directory.finder_flags = finder_flags;
        directory.dirty = true;
        PPC_NO_ERR
    } else {
        PPC_FNF_ERR
    }
}

fn ppc_write_finfo(
    memory: &mut PpcSectionMem,
    finfo_ptr: u32,
    file_type: u32,
    creator: u32,
    finder_flags: u16,
) -> Option<()> {
    memory.write_u32_be(finfo_ptr, file_type)?;
    memory.write_u32_be(finfo_ptr + 4, creator)?;
    memory.write_u16_be(finfo_ptr + 8, finder_flags)?;
    memory.write_u32_be(finfo_ptr + 10, 0)?;
    memory.write_u16_be(finfo_ptr + 14, 0)?;
    Some(())
}

fn ppc_read_finfo(memory: &mut PpcSectionMem, finfo_ptr: u32) -> Option<(u32, u32, u16)> {
    Some((
        memory.read_u32_be(finfo_ptr)?,
        memory.read_u32_be(finfo_ptr + 4)?,
        memory.read_u16_be(finfo_ptr + 8)?,
    ))
}

fn ppc_write_fsspec(
    memory: &mut PpcSectionMem,
    spec_ptr: u32,
    vref: i16,
    dir_id: u32,
    name_bytes: &[u8],
) -> Option<()> {
    memory.write_u16_be(spec_ptr, vref as u16)?;
    memory.write_u32_be(spec_ptr + 2, dir_id)?;
    let len = name_bytes.len().min(63);
    memory.write_u8(spec_ptr + 6, len as u8)?;
    for (offset, byte) in name_bytes.iter().take(len).enumerate() {
        memory.write_u8(spec_ptr + 7 + offset as u32, *byte)?;
    }
    Some(())
}

fn ppc_fsspec_target_exists(
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    dir_id: u32,
    name_bytes: &[u8],
) -> bool {
    ppc_resolved_fsspec_target_path(
        vfs_directories,
        vfs_files,
        vfs_resource_files,
        dir_id,
        name_bytes,
    )
    .is_some()
}

fn ppc_resolved_fsspec_target_path(
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    dir_id: u32,
    name_bytes: &[u8],
) -> Option<String> {
    if name_bytes.is_empty() {
        return ppc_directory_path_for_id(vfs_directories, dir_id).map(str::to_string);
    }
    let Some(parent_path) = ppc_directory_path_for_id(vfs_directories, dir_id) else {
        return None;
    };
    let name = decode_mac_roman(name_bytes);
    let normalized_name = ppc_normalize_vfs_path(&name);
    if normalized_name.is_empty() {
        return None;
    }
    let path = ppc_join_vfs_path(parent_path, &normalized_name);
    if let Some(path) = ppc_vfs_target_path(vfs_directories, vfs_files, vfs_resource_files, &path) {
        return Some(path);
    }
    if normalized_name.contains('/') {
        if let Some(path) = ppc_vfs_target_path(
            vfs_directories,
            vfs_files,
            vfs_resource_files,
            &normalized_name,
        ) {
            return Some(path);
        }
    }
    if dir_id != PPC_ROOT_DIR_ID {
        return None;
    }
    ppc_vfs_target_path_by_suffix_or_unique_basename(
        vfs_directories,
        vfs_files,
        vfs_resource_files,
        &normalized_name,
    )
}

fn ppc_path_for_fsspec(
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    spec_ptr: u32,
) -> Result<String, i16> {
    if spec_ptr == 0 {
        return Err(PPC_PARAM_ERR);
    }
    let Some(dir_id) = memory.read_u32_be(spec_ptr + 2) else {
        return Err(PPC_PARAM_ERR);
    };
    let Some(name_bytes) = ppc_read_pstring_bytes(memory, spec_ptr + 6) else {
        return Err(PPC_PARAM_ERR);
    };
    let Some(parent_path) = ppc_directory_path_for_id(vfs_directories, dir_id) else {
        return Err(PPC_DIR_NF_ERR);
    };
    let name = decode_mac_roman(&name_bytes);
    let normalized_name = ppc_normalize_vfs_path(&name);
    if normalized_name.is_empty() {
        return Err(PPC_PARAM_ERR);
    }
    Ok(ppc_join_vfs_path(parent_path, &normalized_name))
}

fn ppc_existing_path_for_fsspec(
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    spec_ptr: u32,
) -> Result<String, i16> {
    if spec_ptr == 0 {
        return Err(PPC_PARAM_ERR);
    }
    let Some(dir_id) = memory.read_u32_be(spec_ptr + 2) else {
        return Err(PPC_PARAM_ERR);
    };
    let Some(name_bytes) = ppc_read_pstring_bytes(memory, spec_ptr + 6) else {
        return Err(PPC_PARAM_ERR);
    };
    if name_bytes.is_empty() {
        return ppc_directory_path_for_id(vfs_directories, dir_id)
            .map(str::to_string)
            .ok_or(PPC_DIR_NF_ERR);
    }
    let name = decode_mac_roman(&name_bytes);
    let normalized_name = ppc_normalize_vfs_path(&name);
    if normalized_name.is_empty() {
        return Err(PPC_PARAM_ERR);
    }
    let mut fallback_path = None;
    if let Some(parent_path) = ppc_directory_path_for_id(vfs_directories, dir_id) {
        let path = ppc_join_vfs_path(parent_path, &normalized_name);
        if ppc_directory_id_for_path(vfs_directories, &path).is_some() {
            return Ok(path);
        }
        if let Some(path) = ppc_vfs_file_or_resource_path(vfs_files, vfs_resource_files, &path) {
            return Ok(path);
        }
        fallback_path = Some(path);
    }
    if let Some(path) = ppc_vfs_file_or_resource_path_by_suffix_or_unique_basename(
        vfs_files,
        vfs_resource_files,
        &normalized_name,
    ) {
        return Ok(path);
    }
    fallback_path.ok_or(PPC_DIR_NF_ERR)
}

fn ppc_existing_data_path_for_fsspec(
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &[PpcVfsFileRecord],
    spec_ptr: u32,
) -> Result<String, i16> {
    if spec_ptr == 0 {
        return Err(PPC_PARAM_ERR);
    }
    let Some(dir_id) = memory.read_u32_be(spec_ptr + 2) else {
        return Err(PPC_PARAM_ERR);
    };
    let Some(name_bytes) = ppc_read_pstring_bytes(memory, spec_ptr + 6) else {
        return Err(PPC_PARAM_ERR);
    };
    if name_bytes.is_empty() {
        return Err(PPC_PARAM_ERR);
    }
    let name = decode_mac_roman(&name_bytes);
    let normalized_name = ppc_normalize_vfs_path(&name);
    if normalized_name.is_empty() {
        return Err(PPC_PARAM_ERR);
    }
    if let Some(parent_path) = ppc_directory_path_for_id(vfs_directories, dir_id) {
        let path = ppc_join_vfs_path(parent_path, &normalized_name);
        if let Some(index) = ppc_vfs_file_index(vfs_files, &path) {
            if vfs_files[index].data.is_empty() {
                if let Some(non_empty_path) =
                    ppc_unique_non_empty_vfs_file_path_by_basename(vfs_files, &normalized_name)
                {
                    return Ok(non_empty_path);
                }
            }
            return Ok(vfs_files[index].path.clone());
        }
        if dir_id == PPC_ROOT_DIR_ID {
            if let Some(path) = ppc_vfs_file_path_by_suffix_or_unique_basename(vfs_files, &path) {
                return Ok(path);
            }
        }
    }
    if dir_id == PPC_ROOT_DIR_ID {
        if let Some(path) =
            ppc_vfs_file_path_by_suffix_or_unique_basename(vfs_files, &normalized_name)
        {
            return Ok(path);
        }
    }
    Err(PPC_FNF_ERR)
}

fn ppc_unique_non_empty_vfs_file_path_by_basename(
    vfs_files: &[PpcVfsFileRecord],
    path: &str,
) -> Option<String> {
    let basename = ppc_vfs_basename(path);
    let matches = vfs_files
        .iter()
        .filter(|file| !file.data.is_empty())
        .filter(|file| ppc_vfs_basename(&file.path).eq_ignore_ascii_case(basename))
        .map(|file| file.path.as_str())
        .collect::<Vec<_>>();
    ppc_unique_case_insensitive_path(matches)
}

fn ppc_vfs_target_path(
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    path: &str,
) -> Option<String> {
    if let Some(directory) = vfs_directories
        .iter()
        .find(|directory| directory.path.eq_ignore_ascii_case(path))
    {
        return Some(directory.path.clone());
    }
    ppc_vfs_file_or_resource_path(vfs_files, vfs_resource_files, path)
}

fn ppc_vfs_target_path_by_suffix_or_unique_basename(
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    path: &str,
) -> Option<String> {
    let normalized_path = ppc_normalize_vfs_path(path);
    if normalized_path.is_empty() {
        return None;
    }
    let suffix = format!("/{}", normalized_path.to_ascii_lowercase());
    let all_paths = vfs_directories
        .iter()
        .map(|directory| directory.path.as_str())
        .chain(vfs_files.iter().map(|file| file.path.as_str()))
        .chain(vfs_resource_files.iter().map(|file| file.path.as_str()))
        .collect::<Vec<_>>();
    let suffix_matches = all_paths
        .iter()
        .copied()
        .filter(|candidate| candidate.to_ascii_lowercase().ends_with(&suffix))
        .collect::<Vec<_>>();
    if let Some(path) = ppc_unique_case_insensitive_path(suffix_matches) {
        return Some(path);
    }

    let basename = ppc_vfs_basename(&normalized_path);
    let basename_matches = all_paths
        .iter()
        .copied()
        .filter(|candidate| ppc_vfs_basename(candidate).eq_ignore_ascii_case(basename))
        .collect::<Vec<_>>();
    ppc_unique_case_insensitive_path(basename_matches)
}

