fn ppc_vfs_file_or_resource_path_by_nearest_basename(
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    path: &str,
    context_path: Option<&str>,
) -> Option<String> {
    let context_path = context_path?;
    let normalized_path = ppc_normalize_vfs_path(path);
    let basename = ppc_vfs_basename(&normalized_path);
    if basename.is_empty() {
        return None;
    }
    let mut matches = vfs_files
        .iter()
        .map(|file| file.path.as_str())
        .chain(vfs_resource_files.iter().map(|file| file.path.as_str()))
        .filter(|candidate| ppc_vfs_basename(candidate).eq_ignore_ascii_case(basename))
        .collect::<Vec<_>>();
    matches.sort_by_key(|candidate| candidate.to_ascii_lowercase());
    matches.dedup_by(|left, right| left.eq_ignore_ascii_case(right));

    let common_prefix_len = |candidate: &str| {
        candidate
            .split('/')
            .zip(context_path.split('/'))
            .take_while(|(left, right)| left.eq_ignore_ascii_case(right))
            .count()
    };
    let best_prefix_len = matches
        .iter()
        .map(|candidate| common_prefix_len(candidate))
        .max()?;
    if best_prefix_len == 0 {
        return None;
    }
    let mut best = matches
        .into_iter()
        .filter(|candidate| common_prefix_len(candidate) == best_prefix_len);
    let selected = best.next()?;
    best.next().is_none().then(|| selected.to_string())
}

fn ppc_vfs_file_or_resource_path_by_suffix(
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    path: &str,
) -> Option<String> {
    let normalized_path = ppc_normalize_vfs_path(path);
    if normalized_path.is_empty() {
        return None;
    }
    let suffix = format!("/{}", normalized_path.to_ascii_lowercase());
    let all_paths = vfs_files
        .iter()
        .map(|file| file.path.as_str())
        .chain(vfs_resource_files.iter().map(|file| file.path.as_str()))
        .collect::<Vec<_>>();
    let suffix_matches = all_paths
        .iter()
        .copied()
        .filter(|candidate| candidate.to_ascii_lowercase().ends_with(&suffix))
        .collect::<Vec<_>>();
    ppc_unique_case_insensitive_path(suffix_matches)
}

fn ppc_vfs_file_or_resource_path_by_parent_basename(
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    path: &str,
) -> Option<String> {
    let normalized_path = ppc_normalize_vfs_path(path);
    let (parent, basename) = normalized_path.rsplit_once('/')?;
    let parent_basename = ppc_vfs_basename(parent);
    if parent_basename.is_empty() || basename.is_empty() {
        return None;
    }
    let all_paths = vfs_files
        .iter()
        .map(|file| file.path.as_str())
        .chain(vfs_resource_files.iter().map(|file| file.path.as_str()))
        .collect::<Vec<_>>();
    let matches = all_paths
        .iter()
        .copied()
        .filter(|candidate| {
            let Some((candidate_parent, candidate_basename)) = candidate.rsplit_once('/') else {
                return false;
            };
            candidate_basename.eq_ignore_ascii_case(basename)
                && ppc_vfs_basename(candidate_parent).eq_ignore_ascii_case(parent_basename)
        })
        .collect::<Vec<_>>();
    ppc_unique_case_insensitive_path(matches)
}

fn ppc_unique_case_insensitive_path(mut paths: Vec<&str>) -> Option<String> {
    paths.sort_by_key(|path| path.to_ascii_lowercase());
    let mut unique = Vec::new();
    for path in paths {
        if !unique
            .iter()
            .any(|candidate: &&str| candidate.eq_ignore_ascii_case(path))
        {
            unique.push(path);
        }
    }
    (unique.len() == 1).then(|| unique[0].to_string())
}

fn ppc_vfs_file_index(vfs_files: &[PpcVfsFileRecord], path: &str) -> Option<usize> {
    vfs_files
        .iter()
        .position(|record| record.path.eq_ignore_ascii_case(path))
}

fn ppc_vfs_file_mut<'a>(
    vfs_files: &'a mut [PpcVfsFileRecord],
    path: &str,
) -> Option<&'a mut PpcVfsFileRecord> {
    vfs_files
        .iter_mut()
        .find(|record| record.path.eq_ignore_ascii_case(path))
}

fn ppc_vfs_resource_file_index(
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    path: &str,
) -> Option<usize> {
    if let Some(index) = vfs_resource_files
        .iter()
        .position(|record| record.path.eq_ignore_ascii_case(path))
    {
        return Some(index);
    }
    if !path.contains('/') {
        let basename = ppc_vfs_basename(path);
        return vfs_resource_files
            .iter()
            .position(|record| ppc_vfs_basename(&record.path).eq_ignore_ascii_case(basename));
    }
    None
}

fn ppc_mark_resource_file_contents_dirty(
    vfs_resource_files: &mut [PpcVfsResourceFileRecord],
    path: &str,
) {
    if path.is_empty() {
        return;
    }
    if let Some(record) = vfs_resource_files
        .iter_mut()
        .find(|record| record.path.eq_ignore_ascii_case(path))
    {
        record.raw_data = None;
        record.dirty = true;
    }
}

fn ppc_resource_file_path(resource_files: &[PpcResourceFileRecord], ref_num: i16) -> String {
    resource_files
        .iter()
        .find(|record| record.ref_num == ref_num)
        .map(|record| record.path.clone())
        .unwrap_or_default()
}

fn ppc_rebind_resources_for_path(
    vfs_resources: &mut [PpcVfsResourceRecord],
    path: &str,
    ref_num: i16,
) {
    for resource in vfs_resources
        .iter_mut()
        .filter(|resource| resource.path.eq_ignore_ascii_case(path))
    {
        resource.ref_num = ref_num;
    }
}

fn ppc_register_vfs_resource_fonts(resources: &[PpcVfsResourceRecord]) {
    let fond_type = u32::from_be_bytes(*b"FOND");
    let font_type = u32::from_be_bytes(*b"FONT");
    let nfnt_type = u32::from_be_bytes(*b"NFNT");
    let sfnt_type = u32::from_be_bytes(*b"sfnt");

    for font in resources.iter().filter(|resource| {
        resource.res_type == font_type
            || resource.res_type == nfnt_type
            || resource.res_type == sfnt_type
    }) {
        let associations = resources
            .iter()
            .filter(|resource| {
                resource.path.eq_ignore_ascii_case(&font.path) && resource.res_type == fond_type
            })
            .filter_map(|fond| {
                crate::quickdraw::fonts::parse_fond_associations(fond.res_id, &fond.data)
            })
            .flatten()
            .filter(|association| association.font_resource_id == font.res_id)
            .collect::<Vec<_>>();

        if associations.is_empty() {
            if font.res_type == font_type {
                let _ =
                    crate::quickdraw::fonts::register_resource_font_strike(font.res_id, &font.data);
            }
            continue;
        }

        for association in associations {
            if association.style & 0x00ff != 0 {
                continue;
            }
            let registered = if font.res_type == sfnt_type {
                crate::quickdraw::fonts::register_resource_outline_font(
                    association.family_id,
                    &font.data,
                )
            } else {
                crate::quickdraw::fonts::register_resource_font_strike_for_family(
                    association.family_id,
                    association.size,
                    &font.data,
                )
            };
            if registered && std::env::var_os("SYSTEMLESS_TRACE_FONT_TRAPS").is_some() {
                eprintln!(
                    "[FONT] PPC FOND {} maps {}pt style ${:04X} to bitmap resource {}",
                    association.family_id,
                    association.size,
                    association.style,
                    association.font_resource_id,
                );
            }
        }
    }
}

fn ppc_vfs_font_id_for_name(resources: &[PpcVfsResourceRecord], name: &str) -> Option<i16> {
    let fond_type = u32::from_be_bytes(*b"FOND");
    resources
        .iter()
        .filter(|resource| resource.res_type == fond_type)
        .find(|resource| {
            decode_mac_roman(&resource.name)
                .trim()
                .eq_ignore_ascii_case(name.trim())
        })
        .map(|resource| resource.res_id)
}

fn ppc_vfs_font_name_for_id(resources: &[PpcVfsResourceRecord], font_id: i16) -> Option<String> {
    let fond_type = u32::from_be_bytes(*b"FOND");
    resources
        .iter()
        .find(|resource| resource.res_type == fond_type && resource.res_id == font_id)
        .map(|resource| decode_mac_roman(&resource.name))
}

fn ppc_materialize_resource_records_for_path(
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    vfs_resources: &mut Vec<PpcVfsResourceRecord>,
    path: &str,
) {
    let Some(raw_data) = vfs_resource_files
        .iter()
        .find(|file| file.path.eq_ignore_ascii_case(path))
        .and_then(|file| file.raw_data.as_ref())
    else {
        return;
    };
    let Some(fork) = ResourceFork::parse(raw_data) else {
        return;
    };
    let mut sorted_resources = fork.resources().values().collect::<Vec<_>>();
    sorted_resources.sort_by_key(|resource| (resource.res_type, resource.id));
    for resource in sorted_resources {
        let res_type = u32::from_be_bytes(resource.res_type);
        if vfs_resources.iter().any(|existing| {
            existing.path.eq_ignore_ascii_case(path)
                && existing.res_type == res_type
                && existing.res_id == resource.id
        }) {
            continue;
        }
        vfs_resources.push(PpcVfsResourceRecord {
            ref_num: 0,
            path: path.to_string(),
            res_type,
            res_id: resource.id,
            name: resource.name_bytes.clone().unwrap_or_default(),
            data: resource.data.clone(),
            raw_data: resource.raw_data.clone(),
            raw_attrs: resource.raw_attrs.map(u16::from),
            attrs: u16::from(resource.attrs),
            handle: 0,
        });
    }
}

fn ppc_materialize_quilt_resources_for_existing_path(
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    vfs_resources: &mut Vec<PpcVfsResourceRecord>,
    path: &str,
) {
    let Some((_, mut resources)) =
        ppc_quilt_named_resource_records(vfs_files, vfs_resource_files, path)
    else {
        return;
    };
    resources.sort_by_key(|resource| (resource.res_type, resource.res_id));
    for mut resource in resources {
        if vfs_resources.iter().any(|existing| {
            existing.path.eq_ignore_ascii_case(path)
                && existing.res_type == resource.res_type
                && existing.res_id == resource.res_id
        }) {
            continue;
        }
        resource.path = path.to_string();
        vfs_resources.push(resource);
    }
}

fn ppc_materialize_unique_named_resource_file(
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &mut ProcessVfsResourceFileRecords,
    vfs_resources: &mut Vec<PpcVfsResourceRecord>,
    path: &str,
) -> bool {
    if ppc_vfs_resource_file_index(vfs_resource_files, path).is_some() {
        return true;
    }
    let basename = ppc_vfs_basename(path);
    let mut matches = Vec::new();
    for file in vfs_resource_files.iter() {
        let Some(raw_data) = file.raw_data.as_ref() else {
            continue;
        };
        let Some(fork) = ResourceFork::parse(raw_data) else {
            continue;
        };
        for resource in fork.resources().values() {
            let Some(name_bytes) = resource.name_bytes.as_ref() else {
                continue;
            };
            let name = decode_mac_roman(name_bytes);
            if ppc_vfs_basename(&ppc_normalize_vfs_path(&name)).eq_ignore_ascii_case(basename) {
                matches.push((file.clone(), resource.clone()));
            }
        }
    }
    let quilt_records = ppc_quilt_named_resource_records(vfs_files, vfs_resource_files, path);
    let prefer_quilt_records = basename.to_ascii_lowercase().ends_with(".picr")
        && quilt_records.as_ref().is_some_and(|(_, resources)| {
            let img_type = u32::from_be_bytes(*b"#Img");
            let pict_type = u32::from_be_bytes(*b"PICT");
            resources
                .iter()
                .any(|resource| resource.res_type == img_type || resource.res_type == pict_type)
        });
    let (source_file, mut resources) = if matches.is_empty() {
        match quilt_records {
            Some(records) => records,
            None => return false,
        }
    } else if prefer_quilt_records {
        match quilt_records {
            Some(records) => records,
            None => return false,
        }
    } else {
        let source_path = &matches[0].0.path;
        if matches
            .iter()
            .any(|(source_file, _)| !source_file.path.eq_ignore_ascii_case(source_path))
        {
            match quilt_records {
                Some(records) => records,
                None => return false,
            }
        } else {
            let source_file = matches[0].0.clone();
            let resources = matches
                .into_iter()
                .map(|(_, resource)| PpcVfsResourceRecord {
                    ref_num: 0,
                    path: path.to_string(),
                    res_type: u32::from_be_bytes(resource.res_type),
                    res_id: resource.id,
                    name: resource.name_bytes.unwrap_or_default(),
                    data: resource.data,
                    raw_data: resource.raw_data,
                    raw_attrs: resource.raw_attrs.map(u16::from),
                    attrs: u16::from(resource.attrs),
                    handle: 0,
                })
                .collect::<Vec<_>>();
            (source_file, resources)
        }
    };
    ppc_synthesize_quilt_img_resource_if_missing(path, &mut resources);
    let resource_len = resources
        .iter()
        .map(|resource| resource.data.len())
        .sum::<usize>();
    vfs_resource_files.push(PpcVfsResourceFileRecord {
        path: path.to_string(),
        creator: source_file.creator,
        file_type: source_file.file_type,
        finder_flags: source_file.finder_flags,
        resource_len: u32::try_from(resource_len).unwrap_or(u32::MAX),
        raw_data: None,
        map_attrs: source_file.map_attrs,
        dirty: false,
    });
    resources.sort_by_key(|resource| (resource.res_type, resource.res_id));
    for mut resource in resources {
        resource.path = path.to_string();
        vfs_resources.push(resource);
    }
    true
}

fn ppc_synthesize_quilt_img_resource_if_missing(
    path: &str,
    resources: &mut Vec<PpcVfsResourceRecord>,
) {
    let img_type = u32::from_be_bytes(*b"#Img");
    if resources
        .iter()
        .any(|resource| resource.res_type == img_type)
    {
        return;
    }
    let pict_type = u32::from_be_bytes(*b"PICT");
    let frame_count = resources
        .iter()
        .filter(|resource| resource.res_type == pict_type)
        .count();
    if frame_count == 0 {
        return;
    }
    let mut data = vec![0u8; 18];
    data[0..2].copy_from_slice(&1u16.to_be_bytes());
    data[2..4].copy_from_slice(&1u16.to_be_bytes());
    data[4..6].copy_from_slice(&1u16.to_be_bytes());
    data[6..8].copy_from_slice(&(u16::try_from(frame_count).unwrap_or(u16::MAX)).to_be_bytes());
    data[8..10].copy_from_slice(&1u16.to_be_bytes());
    data[10..12].copy_from_slice(&1u16.to_be_bytes());

    resources.push(PpcVfsResourceRecord {
        ref_num: 0,
        path: path.to_string(),
        res_type: img_type,
        res_id: 1000,
        name: ppc_vfs_basename(path).as_bytes().to_vec(),
        data,
        raw_data: None,
        raw_attrs: None,
        attrs: 0,
        handle: 0,
    });
}

fn ppc_quilt_named_resource_records(
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    target_path: &str,
) -> Option<(PpcVfsResourceFileRecord, Vec<PpcVfsResourceRecord>)> {
    let target_basename = ppc_vfs_basename(target_path);
    let versionless_target_basename = target_basename
        .trim_end_matches(|character: char| character.is_ascii_digit())
        .trim_end();
    let mut matches = Vec::new();
    let mut best_name_rank = 0u8;
    for resource_file in vfs_resource_files {
        let Some(raw_data) = resource_file.raw_data.as_ref() else {
            continue;
        };
        let Some(fork) = ResourceFork::parse(raw_data) else {
            continue;
        };
        let Some(data_file) = vfs_files
            .iter()
            .find(|file| file.path.eq_ignore_ascii_case(&resource_file.path))
        else {
            continue;
        };
        for resource in fork.resources().values() {
            if resource.res_type != *b"qDir" {
                continue;
            }
            for record in resource.data.chunks_exact(60) {
                let name_len = u16::from_be_bytes([record[26], record[27]]) as usize;
                if name_len == 0 || name_len > 32 {
                    continue;
                }
                let name_bytes = &record[28..28 + name_len];
                let name = decode_mac_roman(name_bytes);
                let normalized_name = ppc_normalize_vfs_path(&name);
                let record_basename = ppc_vfs_basename(&normalized_name);
                let name_rank = if record_basename.eq_ignore_ascii_case(target_basename) {
                    2
                } else if versionless_target_basename.len() < target_basename.len()
                    && record_basename.eq_ignore_ascii_case(versionless_target_basename)
                {
                    1
                } else {
                    0
                };
                if name_rank == 0 || name_rank < best_name_rank {
                    continue;
                }
                if name_rank > best_name_rank {
                    matches.clear();
                    best_name_rank = name_rank;
                }
                let data_len =
                    u32::from_be_bytes([record[8], record[9], record[10], record[11]]) as usize;
                let data_offset =
                    u32::from_be_bytes([record[12], record[13], record[14], record[15]]) as usize;
                let Some(end) = data_offset.checked_add(data_len) else {
                    continue;
                };
                let Some(data) = data_file.data.get(data_offset..end) else {
                    continue;
                };
                matches.push((
                    resource_file.clone(),
                    PpcVfsResourceRecord {
                        ref_num: 0,
                        path: String::new(),
                        res_type: u32::from_be_bytes([record[0], record[1], record[2], record[3]]),
                        res_id: u32::from_be_bytes([record[4], record[5], record[6], record[7]])
                            as u16 as i16,
                        name: name_bytes.to_vec(),
                        data: data.to_vec(),
                        raw_data: None,
                        raw_attrs: None,
                        attrs: 0,
                        handle: 0,
                    },
                ));
            }
        }
    }
    if matches.is_empty() {
        return None;
    }
    let mut source_paths = matches
        .iter()
        .map(|(source_file, _)| source_file.path.clone())
        .collect::<Vec<_>>();
    source_paths.sort_by_key(|path| {
        let common_prefix = path
            .split('/')
            .zip(target_path.split('/'))
            .take_while(|(left, right)| left.eq_ignore_ascii_case(right))
            .count();
        let depth = path
            .split('/')
            .filter(|component| !component.is_empty())
            .count();
        std::cmp::Reverse((common_prefix, depth))
    });
    source_paths.dedup_by(|left, right| left.eq_ignore_ascii_case(right));
    let source_path = source_paths.first()?;
    matches.retain(|(source_file, _)| source_file.path.eq_ignore_ascii_case(source_path));

    let source_file = matches.first()?.0.clone();
    let mut resources = matches
        .into_iter()
        .map(|(_, resource)| resource)
        .collect::<Vec<_>>();
    ppc_add_quilt_anam_picture_resources(vfs_files, &source_file, &mut resources);
    ppc_expand_compact_quilt_frames(&mut resources);
    ppc_wrap_quilt_raw_pict_frames(&mut resources);
    Some((source_file, resources))
}

fn ppc_add_quilt_anam_picture_resources(
    vfs_files: &[PpcVfsFileRecord],
    source_file: &PpcVfsResourceFileRecord,
    resources: &mut Vec<PpcVfsResourceRecord>,
) {
    ppc_apply_quilt_animation_resource_names(resources);
    let pict_type = u32::from_be_bytes(*b"PICT");
    let img_type = u32::from_be_bytes(*b"#Img");
    if resources
        .iter()
        .any(|resource| resource.res_type == pict_type || resource.res_type == img_type)
    {
        return;
    }
    let anam_type = u32::from_be_bytes(*b"ANAM");
    let Some(picture_name) = resources
        .iter()
        .find(|resource| resource.res_type == anam_type)
        .and_then(|resource| {
            let len = resource
                .data
                .iter()
                .position(|byte| *byte == 0)
                .unwrap_or(resource.data.len());
            let name = decode_mac_roman(&resource.data[..len]);
            let normalized = ppc_normalize_vfs_path(&name);
            normalized
                .to_ascii_lowercase()
                .ends_with(".picr")
                .then_some(normalized)
        })
    else {
        return;
    };
    let picture_basename = ppc_vfs_basename(&picture_name);
    let Some(raw_data) = source_file.raw_data.as_ref() else {
        return;
    };
    let Some(fork) = ResourceFork::parse(raw_data) else {
        return;
    };
    let Some(data_file) = vfs_files
        .iter()
        .find(|file| file.path.eq_ignore_ascii_case(&source_file.path))
    else {
        return;
    };
    let existing = resources
        .iter()
        .map(|resource| (resource.res_type, resource.res_id))
        .collect::<Vec<_>>();
    for resource in fork.resources().values() {
        if resource.res_type != *b"qDir" {
            continue;
        }
        for record in resource.data.chunks_exact(60) {
            let name_len = u16::from_be_bytes([record[26], record[27]]) as usize;
            if name_len == 0 || name_len > 32 {
                continue;
            }
            let name_bytes = &record[28..28 + name_len];
            let name = decode_mac_roman(name_bytes);
            if !ppc_vfs_basename(&ppc_normalize_vfs_path(&name))
                .eq_ignore_ascii_case(picture_basename)
            {
                continue;
            }
            let res_type = u32::from_be_bytes([record[0], record[1], record[2], record[3]]);
            let res_id =
                u32::from_be_bytes([record[4], record[5], record[6], record[7]]) as u16 as i16;
            if existing.iter().any(|(existing_type, existing_id)| {
                *existing_type == res_type && *existing_id == res_id
            }) {
                continue;
            }
            let data_len =
                u32::from_be_bytes([record[8], record[9], record[10], record[11]]) as usize;
            let data_offset =
                u32::from_be_bytes([record[12], record[13], record[14], record[15]]) as usize;
            let Some(end) = data_offset.checked_add(data_len) else {
                continue;
            };
            let Some(data) = data_file.data.get(data_offset..end) else {
                continue;
            };
            resources.push(PpcVfsResourceRecord {
                ref_num: 0,
                path: String::new(),
                res_type,
                res_id,
                name: name_bytes.to_vec(),
                data: data.to_vec(),
                raw_data: None,
                raw_attrs: None,
                attrs: 0,
                handle: 0,
            });
        }
    }
}

fn ppc_apply_quilt_animation_resource_names(resources: &mut [PpcVfsResourceRecord]) {
    let animation_list_type = u32::from_be_bytes(*b"Alst");
    let animation_name_type = u32::from_be_bytes(*b"ANAM");
    let names = resources
        .iter()
        .filter(|resource| resource.res_type == animation_name_type)
        .filter_map(|resource| {
            let len = resource
                .data
                .iter()
                .position(|byte| *byte == 0)
                .unwrap_or(resource.data.len());
            let name = resource.data.get(..len)?;
            decode_mac_roman(name)
                .to_ascii_lowercase()
                .ends_with(".picr")
                .then(|| (resource.res_id, name.to_vec()))
        })
        .collect::<Vec<_>>();
    for resource in resources
        .iter_mut()
        .filter(|resource| resource.res_type == animation_list_type)
    {
        if let Some((_, name)) = names.iter().find(|(id, _)| *id == resource.res_id) {
            resource.name.clone_from(name);
        }
    }
}

fn ppc_expand_compact_quilt_frames(resources: &mut Vec<PpcVfsResourceRecord>) {
    let img_type = u32::from_be_bytes(*b"#Img");
    let frms_type = u32::from_be_bytes(*b"frms");
    let pict_type = u32::from_be_bytes(*b"PICT");
    let Some(img) = resources
        .iter()
        .find(|resource| resource.res_type == img_type && resource.data.len() >= 8)
    else {
        return;
    };
    let frms_indices = resources
        .iter()
        .enumerate()
        .filter(|(_, resource)| resource.res_type == frms_type)
        .map(|(index, _)| index)
        .collect::<Vec<_>>();
    let pict_indices = resources
        .iter()
        .enumerate()
        .filter(|(_, resource)| resource.res_type == pict_type)
        .map(|(index, _)| index)
        .collect::<Vec<_>>();
    if frms_indices.len() != 1 || pict_indices.len() != 1 {
        return;
    }
    let frms = resources[frms_indices[0]].clone();
    let pict = resources[pict_indices[0]].clone();
    let header_frame_count = u16::from_be_bytes([img.data[6], img.data[7]]) as usize;
    let inferred_frame_count = frms.data.len() / 8;
    let frame_count = if header_frame_count > 1
        && frms.data.len() == header_frame_count * 8
        && pict.data.len() % header_frame_count == 0
    {
        header_frame_count
    } else if inferred_frame_count > 1 && frms.data.len() == inferred_frame_count * 8 {
        inferred_frame_count
    } else {
        return;
    };
    if pict.data.len() % frame_count != 0 {
        return;
    }
    let frame_pict_len = pict.data.len() / frame_count;
    let mut expanded = resources
        .iter()
        .filter(|resource| resource.res_type != frms_type && resource.res_type != pict_type)
        .cloned()
        .collect::<Vec<_>>();
    for frame_index in 0..frame_count {
        let Some(res_id) = 1000i16.checked_add(frame_index as i16) else {
            return;
        };
        let frame_offset = frame_index * 8;
        let pict_offset = frame_index * frame_pict_len;
        let mut frame_resource = frms.clone();
        frame_resource.res_id = res_id;
        frame_resource.data = frms.data[frame_offset..frame_offset + 8].to_vec();
        frame_resource.handle = 0;
        expanded.push(frame_resource);

        let mut pict_resource = pict.clone();
        pict_resource.res_id = res_id;
        pict_resource.data = pict.data[pict_offset..pict_offset + frame_pict_len].to_vec();
        pict_resource.handle = 0;
        expanded.push(pict_resource);
    }
    *resources = expanded;
}

fn ppc_wrap_quilt_raw_pict_frames(resources: &mut [PpcVfsResourceRecord]) {
    let frms_type = u32::from_be_bytes(*b"frms");
    let pict_type = u32::from_be_bytes(*b"PICT");
    let frame_rects = resources
        .iter()
        .filter(|resource| resource.res_type == frms_type && resource.data.len() == 8)
        .map(|resource| (resource.res_id, resource.data.clone()))
        .collect::<Vec<_>>();
    if frame_rects.is_empty() {
        return;
    }
    for resource in resources.iter_mut() {
        if resource.res_type != pict_type {
            continue;
        }
        let Some((_, rect)) = frame_rects
            .iter()
            .find(|(res_id, _)| *res_id == resource.res_id)
        else {
            continue;
        };
        let top = i16::from_be_bytes([rect[0], rect[1]]);
        let bottom = i16::from_be_bytes([rect[4], rect[5]]);
        let height = i32::from(bottom) - i32::from(top);
        if height <= 0 || resource.data.len() % height as usize != 0 {
            continue;
        }
        let Some(pict_size) = resource.data.len().checked_add(24) else {
            continue;
        };
        let pict_size = u16::try_from(pict_size).unwrap_or(u16::MAX);
        let mut wrapped = Vec::with_capacity(usize::from(pict_size));
        wrapped.extend_from_slice(&pict_size.to_be_bytes());
        wrapped.extend_from_slice(rect);
        wrapped.extend_from_slice(&[0; 14]);
        wrapped.extend_from_slice(&resource.data);
        resource.data = wrapped;
        resource.handle = 0;
    }
}

fn ppc_file_permission_allows_writing(permission: u8) -> bool {
    // Inside Macintosh: Files (1992), pp. 2-7--2-8: fsCurPerm grants
    // read/write when available, and fsWrPerm is synonymous with fsRdWrPerm.
    matches!(permission, 0 | 2 | 3 | 4)
}

fn ppc_fsp_open_df(
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &mut Vec<PpcVfsFileRecord>,
    files: &mut Vec<PpcFileRecord>,
    writable_refnums: &mut HashSet<u16>,
    next_file_ref_num: &mut i16,
) -> i16 {
    let spec_ptr = cpu.gpr[3];
    let permission = cpu.gpr[4] as u8;
    let ref_num_out_ptr = cpu.gpr[5];
    if ref_num_out_ptr == 0 || !ppc_memory_can_write_bytes(memory, ref_num_out_ptr, 2) {
        return PPC_PARAM_ERR;
    }
    let path = match ppc_existing_data_path_for_fsspec(memory, vfs_directories, vfs_files, spec_ptr)
    {
        Ok(path) => path,
        Err(err) => return err,
    };
    let ref_num = *next_file_ref_num;
    let Some(next_ref_num) = next_file_ref_num.checked_add(1) else {
        return PPC_PARAM_ERR;
    };
    let Some(existing_index) = ppc_vfs_file_index(vfs_files, &path) else {
        return PPC_FNF_ERR;
    };
    let opened_data_len = vfs_files[existing_index].data.len();
    if ppc_hle_trace_enabled() {
        eprintln!(
            "[PPC-TRACE] FSpOpenDF path=\"{}\" permission={} data_len={} result={}",
            path, permission, opened_data_len, PPC_NO_ERR
        );
    }
    let _ = memory.write_u16_be(ref_num_out_ptr, ref_num as u16);
    files.push(PpcFileRecord {
        ref_num,
        path,
        position: 0,
    });
    if ppc_file_permission_allows_writing(permission) {
        writable_refnums.insert(ref_num as u16);
    }
    *next_file_ref_num = next_ref_num;
    PPC_NO_ERR
}

fn ppc_h_open(
    cpu: &PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &[PpcVfsFileRecord],
    files: &mut Vec<PpcFileRecord>,
    writable_refnums: &mut HashSet<u16>,
    next_file_ref_num: &mut i16,
    default_dir_id: u32,
) -> i16 {
    // Inside Macintosh: Files (1992), 2-181: HOpen takes vRefNum, dirID,
    // fileName, permission, and a returned file reference number.
    let vref = cpu.gpr[3] as u16 as i16;
    let dir_id = cpu.gpr[4];
    ppc_open_data_fork_by_name(
        memory,
        vfs_directories,
        vfs_files,
        files,
        writable_refnums,
        next_file_ref_num,
        default_dir_id,
        vref,
        dir_id,
        cpu.gpr[5],
        cpu.gpr[6] as u8,
        cpu.gpr[7],
    )
}

fn ppc_fs_open(
    cpu: &PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &[PpcVfsFileRecord],
    files: &mut Vec<PpcFileRecord>,
    writable_refnums: &mut HashSet<u16>,
    next_file_ref_num: &mut i16,
    default_dir_id: u32,
) -> i16 {
    // Inside Macintosh: Files (1992), 2-179: FSOpen resolves its file name
    // relative to the current volume/directory and returns a refnum.
    ppc_open_data_fork_by_name(
        memory,
        vfs_directories,
        vfs_files,
        files,
        writable_refnums,
        next_file_ref_num,
        default_dir_id,
        0,
        0,
        cpu.gpr[3],
        cpu.gpr[4] as u8,
        cpu.gpr[5],
    )
}

#[allow(clippy::too_many_arguments)]
fn ppc_open_data_fork_by_name(
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &[PpcVfsFileRecord],
    files: &mut Vec<PpcFileRecord>,
    writable_refnums: &mut HashSet<u16>,
    next_file_ref_num: &mut i16,
    default_dir_id: u32,
    vref: i16,
    dir_id: u32,
    name_ptr: u32,
    permission: u8,
    ref_num_out_ptr: u32,
) -> i16 {
    if !matches!(vref, 0 | PPC_BOOT_VOLUME_REF_NUM)
        || ref_num_out_ptr == 0
        || !ppc_memory_can_write_bytes(memory, ref_num_out_ptr, 2)
    {
        return PPC_PARAM_ERR;
    }
    let Some(name_bytes) = ppc_read_pstring_bytes(memory, name_ptr) else {
        return PPC_PARAM_ERR;
    };
    let name = ppc_normalize_vfs_path(&decode_mac_roman(&name_bytes));
    if name.is_empty() {
        return PPC_PARAM_ERR;
    }
    let effective_dir_id = ppc_resolve_directory_id(vref, dir_id, default_dir_id);
    let Some(parent_path) = ppc_directory_path_for_id(vfs_directories, effective_dir_id) else {
        return PPC_DIR_NF_ERR;
    };
    let requested_path = ppc_join_vfs_path(parent_path, &name);
    let path = ppc_vfs_file_index(vfs_files, &requested_path)
        .map(|index| vfs_files[index].path.clone())
        .or_else(|| ppc_vfs_file_path_by_suffix_or_unique_basename(vfs_files, &name));
    let Some(path) = path else {
        return PPC_FNF_ERR;
    };
    let ref_num = *next_file_ref_num;
    let Some(next_ref_num) = next_file_ref_num.checked_add(1) else {
        return PPC_PARAM_ERR;
    };
    if memory
        .write_u16_be(ref_num_out_ptr, ref_num as u16)
        .is_none()
    {
        return PPC_PARAM_ERR;
    }
    files.push(PpcFileRecord {
        ref_num,
        path,
        position: 0,
    });
    if ppc_file_permission_allows_writing(permission) {
        writable_refnums.insert(ref_num as u16);
    }
    *next_file_ref_num = next_ref_num;
    PPC_NO_ERR
}

fn ppc_pbh_open_df(
    cpu: &PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &mut [PpcVfsFileRecord],
    files: &mut Vec<PpcFileRecord>,
    writable_refnums: &mut HashSet<u16>,
    next_file_ref_num: &mut i16,
) -> i16 {
    let pb = cpu.gpr[3];
    if pb == 0 || !ppc_memory_can_write_bytes(memory, pb, 52) {
        return PPC_PARAM_ERR;
    }
    let Some(name_ptr) = memory.read_u32_be(pb + 18) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    let Some(name_bytes) = ppc_read_pstring_bytes(memory, name_ptr) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    let Some(dir_id) = memory.read_u32_be(pb + 48) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    let Some(permission) = memory.read_u8(pb + 27) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    let name = ppc_normalize_vfs_path(&decode_mac_roman(&name_bytes));
    if name.is_empty() {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    }
    let exact_path = ppc_directory_path_for_id(vfs_directories, dir_id)
        .map(|parent| ppc_join_vfs_path(parent, &name));
    let path = exact_path
        .as_deref()
        .and_then(|path| {
            ppc_vfs_file_index(vfs_files, path).map(|index| vfs_files[index].path.clone())
        })
        .or_else(|| ppc_vfs_file_path_by_suffix_or_unique_basename(vfs_files, &name));
    let Some(path) = path else {
        return ppc_complete_pb(memory, pb, PPC_FNF_ERR);
    };
    let ref_num = *next_file_ref_num;
    let Some(next_ref_num) = next_file_ref_num.checked_add(1) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };

    // Inside Macintosh: Files (1992), 2-183 through 2-184: PBHOpenDF uses
    // ioNamePtr/ioVRefNum/ioDirID to open a data fork and returns the access
    // path's file reference number in ioRefNum at offset 24.
    if memory.write_u16_be(pb + 24, ref_num as u16).is_none() {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    }
    files.push(PpcFileRecord {
        ref_num,
        path,
        position: 0,
    });
    if ppc_file_permission_allows_writing(permission) {
        writable_refnums.insert(ref_num as u16);
    }
    *next_file_ref_num = next_ref_num;
    ppc_complete_pb(memory, pb, PPC_NO_ERR)
}

fn ppc_fs_close(
    cpu: &mut PpcCpu,
    files: &mut Vec<PpcFileRecord>,
    writable_refnums: &mut HashSet<u16>,
) -> i16 {
    let ref_num = ppc_ref_num_from_gpr(cpu.gpr[3]);
    files.retain(|file| file.ref_num != ref_num);
    writable_refnums.remove(&(ref_num as u16));
    PPC_NO_ERR
}

fn ppc_pb_close(
    cpu: &PpcCpu,
    memory: &mut PpcSectionMem,
    files: &mut Vec<PpcFileRecord>,
    writable_refnums: &mut HashSet<u16>,
) -> i16 {
    let pb = cpu.gpr[3];
    let Some(ref_num) = memory.read_u16_be(pb + 24).map(|value| value as i16) else {
        return PPC_PARAM_ERR;
    };
    if !files.iter().any(|file| file.ref_num == ref_num) {
        return ppc_complete_pb(memory, pb, PPC_RF_NUM_ERR);
    }
    files.retain(|file| file.ref_num != ref_num);
    writable_refnums.remove(&(ref_num as u16));
    ppc_complete_pb(memory, pb, PPC_NO_ERR)
}

fn ppc_pb_flush_file(cpu: &PpcCpu, memory: &mut PpcSectionMem, files: &[PpcFileRecord]) -> i16 {
    let pb = cpu.gpr[3];
    let Some(ref_num) = memory.read_u16_be(pb + 24).map(|value| value as i16) else {
        return PPC_PARAM_ERR;
    };
    // VFS writes are committed to their in-memory fork immediately, so the
    // synchronous flush only validates the open file and completes ioResult.
    let result = if files.iter().any(|file| file.ref_num == ref_num) {
        PPC_NO_ERR
    } else {
        PPC_RF_NUM_ERR
    };
    ppc_complete_pb(memory, pb, result)
}

fn ppc_pb_position(mode: u16, offset: i32, mark: u32, eof: usize) -> Option<usize> {
    let base = match mode & 0x000f {
        0 => i64::from(mark),
        1 => 0,
        2 => i64::try_from(eof).ok()?,
        3 => i64::from(mark),
        _ => return None,
    };
    let delta = if mode & 0x000f == 0 {
        0
    } else {
        i64::from(offset)
    };
    usize::try_from(base.checked_add(delta)?).ok()
}

fn ppc_pb_read(
    cpu: &PpcCpu,
    memory: &mut PpcSectionMem,
    files: &mut [PpcFileRecord],
    vfs_files: &[PpcVfsFileRecord],
) -> i16 {
    let pb = cpu.gpr[3];
    if pb == 0 || !ppc_memory_can_write_bytes(memory, pb, 50) {
        return PPC_PARAM_ERR;
    }
    let Some(ref_num) = memory.read_u16_be(pb + 24).map(|value| value as i16) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    let Some(buffer_ptr) = memory.read_u32_be(pb + 32) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    let Some(requested_count) = memory.read_u32_be(pb + 36) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    let Some(position_mode) = memory.read_u16_be(pb + 44) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    let Some(position_offset) = memory.read_u32_be(pb + 46).map(|value| value as i32) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    let Some(file_index) = files.iter().position(|file| file.ref_num == ref_num) else {
        return ppc_complete_pb(memory, pb, PPC_RF_NUM_ERR);
    };
    let Some(vfs_file) = vfs_files
        .iter()
        .find(|record| record.path.eq_ignore_ascii_case(&files[file_index].path))
    else {
        return ppc_complete_pb(memory, pb, PPC_FNF_ERR);
    };
    let Some(start) = ppc_pb_position(
        position_mode,
        position_offset,
        files[file_index].position,
        vfs_file.data.len(),
    ) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    if start > vfs_file.data.len() {
        return ppc_complete_pb(memory, pb, PPC_POS_ERR);
    }
    let requested_len = usize::try_from(requested_count).unwrap_or(usize::MAX);
    let read_len = requested_len.min(vfs_file.data.len().saturating_sub(start));
    if read_len != 0
        && (buffer_ptr == 0 || !ppc_memory_can_write_bytes(memory, buffer_ptr, read_len as u32))
    {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    }
    for (offset, byte) in vfs_file.data[start..start + read_len]
        .iter()
        .copied()
        .enumerate()
    {
        if memory.write_u8(buffer_ptr + offset as u32, byte).is_none() {
            return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
        }
    }
    let new_position = start.saturating_add(read_len).min(u32::MAX as usize) as u32;
    files[file_index].position = new_position;
    let _ = memory.write_u32_be(pb + 40, read_len as u32);
    let _ = memory.write_u32_be(pb + 46, new_position);
    let result = if read_len < requested_len {
        PPC_EOF_ERR
    } else {
        PPC_NO_ERR
    };
    ppc_complete_pb(memory, pb, result)
}

fn ppc_pb_write(
    cpu: &PpcCpu,
    memory: &mut PpcSectionMem,
    files: &mut [PpcFileRecord],
    writable_refnums: &HashSet<u16>,
    vfs_files: &mut [PpcVfsFileRecord],
) -> i16 {
    let pb = cpu.gpr[3];
    if pb == 0 || !ppc_memory_can_write_bytes(memory, pb, 50) {
        return PPC_PARAM_ERR;
    }
    let Some(ref_num) = memory.read_u16_be(pb + 24).map(|value| value as i16) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    let Some(buffer_ptr) = memory.read_u32_be(pb + 32) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    let Some(requested_count) = memory.read_u32_be(pb + 36) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    let Some(position_mode) = memory.read_u16_be(pb + 44) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    let Some(position_offset) = memory.read_u32_be(pb + 46).map(|value| value as i32) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    if requested_count != 0
        && (buffer_ptr == 0 || !ppc_memory_can_read_bytes(memory, buffer_ptr, requested_count))
    {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    }
    let Some(file_index) = files.iter().position(|file| file.ref_num == ref_num) else {
        return ppc_complete_pb(memory, pb, PPC_RF_NUM_ERR);
    };
    if !writable_refnums.contains(&(ref_num as u16)) {
        return ppc_complete_pb(memory, pb, PPC_WR_PERM_ERR);
    }
    let Some(vfs_file_index) = vfs_files
        .iter()
        .position(|record| record.path.eq_ignore_ascii_case(&files[file_index].path))
    else {
        return ppc_complete_pb(memory, pb, PPC_FNF_ERR);
    };
    let Some(start) = ppc_pb_position(
        position_mode,
        position_offset,
        files[file_index].position,
        vfs_files[vfs_file_index].data.len(),
    ) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    let Ok(write_len) = usize::try_from(requested_count) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    let Some(end) = start.checked_add(write_len) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    vfs_files[vfs_file_index].data.resize(end, 0);
    for offset in 0..write_len {
        let Some(byte) = memory.read_u8(buffer_ptr + offset as u32) else {
            return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
        };
        vfs_files[vfs_file_index].data[start + offset] = byte;
    }
    vfs_files[vfs_file_index].dirty = true;
    let new_position = end.min(u32::MAX as usize) as u32;
    files[file_index].position = new_position;
    let _ = memory.write_u32_be(pb + 40, requested_count);
    let _ = memory.write_u32_be(pb + 46, new_position);
    ppc_complete_pb(memory, pb, PPC_NO_ERR)
}

fn ppc_pb_get_eof(
    cpu: &PpcCpu,
    memory: &mut PpcSectionMem,
    files: &[PpcFileRecord],
    vfs_files: &[PpcVfsFileRecord],
) -> i16 {
    let pb = cpu.gpr[3];
    let Some(ref_num) = memory.read_u16_be(pb + 24).map(|value| value as i16) else {
        return PPC_PARAM_ERR;
    };
    let Some(file) = files.iter().find(|file| file.ref_num == ref_num) else {
        return ppc_complete_pb(memory, pb, PPC_RF_NUM_ERR);
    };
    let Some(vfs_file) = vfs_files
        .iter()
        .find(|record| record.path.eq_ignore_ascii_case(&file.path))
    else {
        return ppc_complete_pb(memory, pb, PPC_FNF_ERR);
    };
    let eof = u32::try_from(vfs_file.data.len()).unwrap_or(u32::MAX);
    if memory.write_u32_be(pb + 28, eof).is_none() {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    }
    ppc_complete_pb(memory, pb, PPC_NO_ERR)
}

fn ppc_pb_set_eof(
    cpu: &PpcCpu,
    memory: &mut PpcSectionMem,
    files: &mut [PpcFileRecord],
    writable_refnums: &HashSet<u16>,
    vfs_files: &mut [PpcVfsFileRecord],
) -> i16 {
    let pb = cpu.gpr[3];
    let Some(ref_num) = memory.read_u16_be(pb + 24).map(|value| value as i16) else {
        return PPC_PARAM_ERR;
    };
    let Some(new_eof) = memory.read_u32_be(pb + 28) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    let Some(file_index) = files.iter().position(|file| file.ref_num == ref_num) else {
        return ppc_complete_pb(memory, pb, PPC_RF_NUM_ERR);
    };
    if !writable_refnums.contains(&(ref_num as u16)) {
        return ppc_complete_pb(memory, pb, PPC_WR_PERM_ERR);
    }
    let Some(vfs_file) = vfs_files
        .iter_mut()
        .find(|record| record.path.eq_ignore_ascii_case(&files[file_index].path))
    else {
        return ppc_complete_pb(memory, pb, PPC_FNF_ERR);
    };
    let Ok(new_len) = usize::try_from(new_eof) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    vfs_file.data.resize(new_len, 0);
    vfs_file.dirty = true;
    files[file_index].position = files[file_index].position.min(new_eof);
    ppc_complete_pb(memory, pb, PPC_NO_ERR)
}

fn ppc_pb_set_fpos(
    cpu: &PpcCpu,
    memory: &mut PpcSectionMem,
    files: &mut [PpcFileRecord],
    vfs_files: &[PpcVfsFileRecord],
) -> i16 {
    let pb = cpu.gpr[3];
    let Some(ref_num) = memory.read_u16_be(pb + 24).map(|value| value as i16) else {
        return PPC_PARAM_ERR;
    };
    let Some(position_mode) = memory.read_u16_be(pb + 44) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    let Some(position_offset) = memory.read_u32_be(pb + 46).map(|value| value as i32) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    let Some(file_index) = files.iter().position(|file| file.ref_num == ref_num) else {
        return ppc_complete_pb(memory, pb, PPC_RF_NUM_ERR);
    };
    let Some(eof) = vfs_files
        .iter()
        .find(|record| record.path.eq_ignore_ascii_case(&files[file_index].path))
        .map(|record| record.data.len())
    else {
        return ppc_complete_pb(memory, pb, PPC_FNF_ERR);
    };
    let Some(position) = ppc_pb_position(
        position_mode,
        position_offset,
        files[file_index].position,
        eof,
    ) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    let Ok(position) = u32::try_from(position) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    files[file_index].position = position;
    let _ = memory.write_u32_be(pb + 46, position);
    ppc_complete_pb(memory, pb, PPC_NO_ERR)
}

// Inside Macintosh: Files (1992), 2-92 through 2-103 and the I/O parameter
// layout on 2-237 define PBRead/PBWrite/PBSetFPos/PBGetEOF/PBSetEOF/PBClose,
// including ioActCount, mark updates, and eofErr on a short read.

fn ppc_fsp_create_res_file(
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &mut ProcessVfsFileRecords,
    vfs_resource_files: &mut ProcessVfsResourceFileRecords,
    last_resource_error: &mut i16,
) {
    let spec_ptr = cpu.gpr[3];
    let creator = cpu.gpr[4];
    let file_type = cpu.gpr[5];
    let path = match ppc_path_for_fsspec(memory, vfs_directories, spec_ptr) {
        Ok(path) => path,
        Err(err) => {
            *last_resource_error = err;
            return;
        }
    };
    if ppc_vfs_resource_file_index(vfs_resource_files, &path).is_some() {
        *last_resource_error = PPC_DUP_FN_ERR;
        return;
    }
    if ppc_vfs_file_index(vfs_files, &path).is_none() {
        vfs_files.push(PpcVfsFileRecord {
            path: path.clone(),
            data: Vec::new().into(),
            creator,
            file_type,
            finder_flags: 0,
            dirty: true,
        });
    }
    vfs_resource_files.push(PpcVfsResourceFileRecord {
        path,
        creator,
        file_type,
        finder_flags: 0,
        resource_len: 0,
        raw_data: None,
        map_attrs: 0,
        dirty: true,
    });
    *last_resource_error = PPC_NO_ERR;
}

fn ppc_h_create_res_file(
    cpu: &PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &mut ProcessVfsFileRecords,
    vfs_resource_files: &mut ProcessVfsResourceFileRecords,
    default_dir_id: u32,
    last_resource_error: &mut i16,
) {
    let vref = cpu.gpr[3] as u16 as i16;
    if !matches!(vref, 0 | PPC_BOOT_VOLUME_REF_NUM) {
        *last_resource_error = PPC_NSV_ERR;
        return;
    }
    let Some(name_bytes) = ppc_read_pstring_bytes(memory, cpu.gpr[5]) else {
        *last_resource_error = PPC_PARAM_ERR;
        return;
    };
    let name = ppc_normalize_vfs_path(&decode_mac_roman(&name_bytes));
    if name.is_empty() {
        *last_resource_error = PPC_BD_NAM_ERR;
        return;
    }
    let dir_id = ppc_resolve_directory_id(vref, cpu.gpr[4], default_dir_id);
    let Some(parent_path) = ppc_directory_path_for_id(vfs_directories, dir_id) else {
        *last_resource_error = PPC_DIR_NF_ERR;
        return;
    };
    let path = ppc_join_vfs_path(parent_path, &name);
    if ppc_vfs_resource_file_index(vfs_resource_files, &path).is_some() {
        *last_resource_error = PPC_DUP_FN_ERR;
        return;
    }
    let (creator, file_type, finder_flags) =
        if let Some(index) = ppc_vfs_file_index(vfs_files, &path) {
            let file = &vfs_files[index];
            (file.creator, file.file_type, file.finder_flags)
        } else {
            vfs_files.push(PpcVfsFileRecord {
                path: path.clone(),
                data: Vec::new().into(),
                creator: 0,
                file_type: 0,
                finder_flags: 0,
                dirty: true,
            });
            (0, 0, 0)
        };
    // More Macintosh Toolbox (1993), pp. 1-56--1-57: HCreateResFile uses
    // vRefNum/dirID/name, creates a missing zero-length data fork, and leaves
    // the new empty resource fork closed until HOpenResFile is called.
    vfs_resource_files.push(PpcVfsResourceFileRecord {
        path,
        creator,
        file_type,
        finder_flags,
        resource_len: 0,
        raw_data: None,
        map_attrs: 0,
        dirty: true,
    });
    *last_resource_error = PPC_NO_ERR;
}

fn ppc_fsp_open_res_file(
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &mut ProcessVfsFileRecords,
    vfs_resource_files: &mut ProcessVfsResourceFileRecords,
    resource_files: &mut Vec<PpcResourceFileRecord>,
    vfs_resources: &mut Vec<PpcVfsResourceRecord>,
    next_file_ref_num: &mut i16,
    current_resource_refnum: &mut i16,
    last_resource_error: &mut i16,
) -> i16 {
    let spec_ptr = cpu.gpr[3];
    let _permission = cpu.gpr[4] as u8;
    let path = match ppc_path_for_fsspec(memory, vfs_directories, spec_ptr) {
        Ok(path) => path,
        Err(err) => {
            *last_resource_error = err;
            return -1;
        }
    };
    let resolved_path = if let Some(index) = ppc_vfs_resource_file_index(vfs_resource_files, &path)
    {
        vfs_resource_files[index].path.clone()
    } else {
        path
    };
    let path = resolved_path;
    let data_file_exists = vfs_files
        .iter()
        .any(|file| file.path.eq_ignore_ascii_case(&path));
    if ppc_vfs_resource_file_index(vfs_resource_files, &path).is_none() {
        *last_resource_error = if data_file_exists {
            PPC_RES_F_NOT_FOUND_ERR
        } else {
            PPC_FNF_ERR
        };
        if ppc_hle_trace_enabled() {
            eprintln!(
                "[PPC-TRACE] FSpOpenResFile path=\"{}\" permission={} -> {}",
                path, _permission, *last_resource_error
            );
        }
        return -1;
    }
    ppc_materialize_resource_records_for_path(vfs_resource_files, vfs_resources, &path);
    ppc_materialize_quilt_resources_for_existing_path(
        vfs_files,
        vfs_resource_files,
        vfs_resources,
        &path,
    );
    if let Some(existing) = resource_files
        .iter()
        .find(|record| record.path.eq_ignore_ascii_case(&path))
    {
        ppc_set_current_resource_refnum(memory, current_resource_refnum, existing.ref_num);
        ppc_rebind_resources_for_path(vfs_resources, &path, existing.ref_num);
        *last_resource_error = PPC_NO_ERR;
        if ppc_hle_trace_enabled() {
            eprintln!(
                "[PPC-TRACE] FSpOpenResFile path=\"{}\" permission={} -> ref={} existing",
                path, _permission, existing.ref_num
            );
        }
        return existing.ref_num;
    }
    let ref_num = *next_file_ref_num;
    let Some(next_ref_num) = next_file_ref_num.checked_add(1) else {
        *last_resource_error = PPC_PARAM_ERR;
        return -1;
    };
    resource_files.push(PpcResourceFileRecord {
        ref_num,
        path: path.clone(),
    });
    ppc_rebind_resources_for_path(vfs_resources, &path, ref_num);
    *next_file_ref_num = next_ref_num;
    ppc_set_current_resource_refnum(memory, current_resource_refnum, ref_num);
    *last_resource_error = PPC_NO_ERR;
    if ppc_hle_trace_enabled() {
        let matching_resources = vfs_resources
            .iter()
            .filter(|resource| resource.path.eq_ignore_ascii_case(&path))
            .collect::<Vec<_>>();
        eprintln!(
            "[PPC-TRACE] FSpOpenResFile path=\"{}\" permission={} -> ref={} resources={}",
            path,
            _permission,
            ref_num,
            matching_resources.len()
        );
        for resource in matching_resources {
            eprintln!(
                "[PPC-TRACE]   resource '{}' id={} size={} attrs=${:02X} raw_size={}",
                ppc_res_type_text(resource.res_type),
                resource.res_id,
                resource.data.len(),
                resource.attrs,
                resource.raw_data.as_ref().map_or(0, Vec::len)
            );
        }
    }
    ref_num
}

fn ppc_open_res_file(
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_files: &mut ProcessVfsFileRecords,
    vfs_resource_files: &mut ProcessVfsResourceFileRecords,
    resource_files: &mut Vec<PpcResourceFileRecord>,
    vfs_resources: &mut Vec<PpcVfsResourceRecord>,
    next_file_ref_num: &mut i16,
    current_resource_refnum: &mut i16,
    last_resource_error: &mut i16,
    launched_app_path: Option<&str>,
) -> i16 {
    let name_ptr = cpu.gpr[3];
    let Some(name_bytes) = ppc_read_pstring_bytes(memory, name_ptr) else {
        *last_resource_error = PPC_PARAM_ERR;
        return -1;
    };
    let normalized_name = ppc_normalize_vfs_path(&decode_mac_roman(&name_bytes));
    if normalized_name.is_empty() {
        *last_resource_error = PPC_PARAM_ERR;
        return -1;
    }
    let path = if normalized_name.contains('/') {
        ppc_vfs_file_or_resource_path_by_suffix(vfs_files, vfs_resource_files, &normalized_name)
            .or_else(|| {
                ppc_vfs_file_or_resource_path_by_parent_basename(
                    vfs_files,
                    vfs_resource_files,
                    &normalized_name,
                )
            })
            .unwrap_or(normalized_name)
    } else {
        ppc_vfs_file_or_resource_path_by_suffix_or_unique_basename(
            vfs_files,
            vfs_resource_files,
            &normalized_name,
        )
        .or_else(|| {
            ppc_vfs_file_or_resource_path_by_nearest_basename(
                vfs_files,
                vfs_resource_files,
                &normalized_name,
                launched_app_path,
            )
        })
        .unwrap_or(normalized_name)
    };
    ppc_open_resource_path(
        memory,
        vfs_files,
        vfs_resource_files,
        resource_files,
        vfs_resources,
        next_file_ref_num,
        current_resource_refnum,
        last_resource_error,
        path,
        true,
        "OpenResFile",
    )
}

#[allow(clippy::too_many_arguments)]
fn ppc_h_open_res_file(
    cpu: &PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &mut ProcessVfsFileRecords,
    vfs_resource_files: &mut ProcessVfsResourceFileRecords,
    resource_files: &mut Vec<PpcResourceFileRecord>,
    vfs_resources: &mut Vec<PpcVfsResourceRecord>,
    next_file_ref_num: &mut i16,
    current_resource_refnum: &mut i16,
    last_resource_error: &mut i16,
    default_dir_id: u32,
) -> i16 {
    // Inside Macintosh: More Macintosh Toolbox (1993), pp. 1-62--1-64:
    // HOpenResFile identifies the resource fork by volume, directory ID, and
    // Pascal file name, returning -1 with the error available via ResError.
    let vref = cpu.gpr[3] as u16 as i16;
    if !matches!(vref, 0 | PPC_BOOT_VOLUME_REF_NUM) {
        *last_resource_error = PPC_NSV_ERR;
        return -1;
    }
    let Some(name_bytes) = ppc_read_pstring_bytes(memory, cpu.gpr[5]) else {
        *last_resource_error = PPC_PARAM_ERR;
        return -1;
    };
    let name = ppc_normalize_vfs_path(&decode_mac_roman(&name_bytes));
    if name.is_empty() {
        *last_resource_error = PPC_PARAM_ERR;
        return -1;
    }
    let dir_id = ppc_resolve_directory_id(vref, cpu.gpr[4], default_dir_id);
    let Some(parent_path) = ppc_directory_path_for_id(vfs_directories, dir_id) else {
        *last_resource_error = PPC_DIR_NF_ERR;
        return -1;
    };
    let requested_path = ppc_join_vfs_path(parent_path, &name);
    let path = ppc_vfs_file_or_resource_path(vfs_files, vfs_resource_files, &requested_path)
        .unwrap_or(requested_path);
    ppc_open_resource_path(
        memory,
        vfs_files,
        vfs_resource_files,
        resource_files,
        vfs_resources,
        next_file_ref_num,
        current_resource_refnum,
        last_resource_error,
        path,
        false,
        "HOpenResFile",
    )
}

#[allow(clippy::too_many_arguments)]
fn ppc_open_resource_path(
    memory: &mut PpcSectionMem,
    vfs_files: &mut ProcessVfsFileRecords,
    vfs_resource_files: &mut ProcessVfsResourceFileRecords,
    resource_files: &mut Vec<PpcResourceFileRecord>,
    vfs_resources: &mut Vec<PpcVfsResourceRecord>,
    next_file_ref_num: &mut i16,
    current_resource_refnum: &mut i16,
    last_resource_error: &mut i16,
    path: String,
    make_existing_current: bool,
    trace_name: &str,
) -> i16 {
    let resolved_path = if let Some(index) = ppc_vfs_resource_file_index(vfs_resource_files, &path)
    {
        vfs_resource_files[index].path.clone()
    } else {
        path
    };
    let path = resolved_path;
    let data_file_exists = vfs_files
        .iter()
        .any(|file| file.path.eq_ignore_ascii_case(&path));
    if ppc_vfs_resource_file_index(vfs_resource_files, &path).is_none() {
        if !data_file_exists
            && ppc_materialize_unique_named_resource_file(
                vfs_files,
                vfs_resource_files,
                vfs_resources,
                &path,
            )
        {
            if ppc_hle_trace_enabled() {
                eprintln!(
                    "[PPC-TRACE] {} path=\"{}\" materialized named resource",
                    trace_name, path
                );
            }
        } else {
            *last_resource_error = if data_file_exists {
                PPC_RES_F_NOT_FOUND_ERR
            } else {
                PPC_FNF_ERR
            };
            if ppc_hle_trace_enabled() {
                eprintln!(
                    "[PPC-TRACE] {} path=\"{}\" -> {}",
                    trace_name, path, *last_resource_error
                );
            }
            return -1;
        }
    }
    ppc_materialize_resource_records_for_path(vfs_resource_files, vfs_resources, &path);
    ppc_materialize_quilt_resources_for_existing_path(
        vfs_files,
        vfs_resource_files,
        vfs_resources,
        &path,
    );
    if let Some(existing) = resource_files
        .iter()
        .find(|record| record.path.eq_ignore_ascii_case(&path))
    {
        if make_existing_current {
            ppc_set_current_resource_refnum(memory, current_resource_refnum, existing.ref_num);
        }
        ppc_rebind_resources_for_path(vfs_resources, &path, existing.ref_num);
        *last_resource_error = PPC_NO_ERR;
        if ppc_hle_trace_enabled() {
            eprintln!(
                "[PPC-TRACE] {} path=\"{}\" -> ref={} existing",
                trace_name, path, existing.ref_num
            );
        }
        return existing.ref_num;
    }
    let ref_num = *next_file_ref_num;
    let Some(next_ref_num) = next_file_ref_num.checked_add(1) else {
        *last_resource_error = PPC_PARAM_ERR;
        return -1;
    };
    resource_files.push(PpcResourceFileRecord {
        ref_num,
        path: path.clone(),
    });
    ppc_rebind_resources_for_path(vfs_resources, &path, ref_num);
    *next_file_ref_num = next_ref_num;
    ppc_set_current_resource_refnum(memory, current_resource_refnum, ref_num);
    *last_resource_error = PPC_NO_ERR;
    if ppc_hle_trace_enabled() {
        let resource_count = vfs_resources
            .iter()
            .filter(|resource| resource.path.eq_ignore_ascii_case(&path))
            .count();
        eprintln!(
            "[PPC-TRACE] {} path=\"{}\" -> ref={} resources={}",
            trace_name, path, ref_num, resource_count
        );
    }
    ref_num
}

fn ppc_close_res_file(
    cpu: &mut PpcCpu,
    process_memory_manager: &mut ProcessNativeMemoryManager,
    memory: &mut PpcSectionMem,
    heap_cursor: &mut u32,
    heap_limit: u32,
    last_mem_error: &mut i16,
    handles: &mut Vec<PpcHandleRecord>,
    resource_files: &mut Vec<PpcResourceFileRecord>,
    vfs_resource_files: &mut [PpcVfsResourceFileRecord],
    vfs_resources: &mut [PpcVfsResourceRecord],
    current_resource_refnum: &mut i16,
    last_resource_error: &mut i16,
) {
    let ref_num = cpu.gpr[3] as u16 as i16;
    ppc_update_res_file(
        cpu,
        memory,
        handles,
        resource_files,
        vfs_resource_files,
        vfs_resources,
        *current_resource_refnum,
        last_resource_error,
    );
    if *last_resource_error != PPC_NO_ERR {
        return;
    }
    // Inside Macintosh, Volume I (1985), p. I-115: CloseResFile updates the
    // file, then calls ReleaseResource for every resource in that file.
    // Detached resources have no associated record handle and remain owned by
    // the application.
    let resource_handles: Vec<u32> = vfs_resources
        .iter()
        .filter(|resource| resource.ref_num == ref_num && resource.handle != 0)
        .map(|resource| resource.handle)
        .collect();
    for handle in resource_handles {
        let _ = ppc_dispose_process_native_handle(
            process_memory_manager,
            memory,
            heap_cursor,
            heap_limit,
            last_mem_error,
            handles,
            handle,
        );
    }
    resource_files.retain(|file| file.ref_num != ref_num);
    for resource in vfs_resources
        .iter_mut()
        .filter(|resource| resource.ref_num == ref_num)
    {
        resource.handle = 0;
        resource.ref_num = PPC_CLOSED_RESOURCE_REF_NUM;
    }
    if ref_num == *current_resource_refnum {
        let replacement = resource_files
            .last()
            .map(|file| file.ref_num)
            .unwrap_or_default();
        ppc_set_current_resource_refnum(memory, current_resource_refnum, replacement);
    }
    *last_resource_error = PPC_NO_ERR;
}

fn ppc_get_eof(
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    files: &[PpcFileRecord],
    vfs_files: &[PpcVfsFileRecord],
) -> i16 {
    let ref_num = ppc_ref_num_from_gpr(cpu.gpr[3]);
    let eof_out_ptr = cpu.gpr[4];
    let Some(file) = files.iter().find(|file| file.ref_num == ref_num) else {
        return PPC_RF_NUM_ERR;
    };
    let eof = vfs_files
        .iter()
        .find(|record| record.path.eq_ignore_ascii_case(&file.path))
        .map(|record| u32::try_from(record.data.len()).unwrap_or(u32::MAX))
        .unwrap_or(0);
    if eof_out_ptr == 0 || !ppc_memory_can_write_bytes(memory, eof_out_ptr, 4) {
        PPC_PARAM_ERR
    } else {
        let _ = memory.write_u32_be(eof_out_ptr, eof);
        PPC_NO_ERR
    }
}

fn ppc_alloc_contig(
    cpu: &PpcCpu,
    memory: &mut PpcSectionMem,
    files: &[PpcFileRecord],
    writable_refnums: &HashSet<u16>,
) -> i16 {
    // Files (1992), pp. 2-119--2-120: AllocContig reserves physical file
    // blocks without changing logical EOF. The virtual filesystem has no
    // physical allocation map, so a valid open fork can satisfy the request.
    let ref_num = ppc_ref_num_from_gpr(cpu.gpr[3]);
    let count_ptr = cpu.gpr[4];
    if !files.iter().any(|file| file.ref_num == ref_num) {
        return PPC_RF_NUM_ERR;
    }
    if !writable_refnums.contains(&(ref_num as u16)) {
        return PPC_WR_PERM_ERR;
    }
    if count_ptr == 0 || !ppc_memory_can_write_bytes(memory, count_ptr, 4) {
        return PPC_PARAM_ERR;
    }
    PPC_NO_ERR
}

fn ppc_set_eof(
    cpu: &mut PpcCpu,
    files: &mut [PpcFileRecord],
    writable_refnums: &HashSet<u16>,
    vfs_files: &mut [PpcVfsFileRecord],
) -> i16 {
    let ref_num = ppc_ref_num_from_gpr(cpu.gpr[3]);
    let new_eof = cpu.gpr[4];
    let Some(path) = files
        .iter()
        .find(|file| file.ref_num == ref_num)
        .map(|file| file.path.clone())
    else {
        return PPC_RF_NUM_ERR;
    };
    if !writable_refnums.contains(&(ref_num as u16)) {
        return PPC_WR_PERM_ERR;
    }
    let Some(vfs_file) = vfs_files
        .iter_mut()
        .find(|record| record.path.eq_ignore_ascii_case(&path))
    else {
        return PPC_FNF_ERR;
    };
    let Ok(new_len) = usize::try_from(new_eof) else {
        return PPC_PARAM_ERR;
    };
    vfs_file.data.resize(new_len, 0);
    vfs_file.dirty = true;
    for file in files
        .iter_mut()
        .filter(|file| file.path.eq_ignore_ascii_case(&path))
    {
        if file.position > new_eof {
            file.position = new_eof;
        }
    }
    PPC_NO_ERR
}

fn ppc_get_fpos(cpu: &mut PpcCpu, memory: &mut PpcSectionMem, files: &[PpcFileRecord]) -> i16 {
    let ref_num = ppc_ref_num_from_gpr(cpu.gpr[3]);
    let pos_out_ptr = cpu.gpr[4];
    let Some(file) = files.iter().find(|file| file.ref_num == ref_num) else {
        return PPC_RF_NUM_ERR;
    };
    if pos_out_ptr == 0 || !ppc_memory_can_write_bytes(memory, pos_out_ptr, 4) {
        PPC_PARAM_ERR
    } else {
        let _ = memory.write_u32_be(pos_out_ptr, file.position);
        PPC_NO_ERR
    }
}

fn ppc_set_fpos(
    cpu: &mut PpcCpu,
    files: &mut [PpcFileRecord],
    vfs_files: &[PpcVfsFileRecord],
) -> i16 {
    let ref_num = ppc_ref_num_from_gpr(cpu.gpr[3]);
    let pos_mode = cpu.gpr[4] as u16;
    let pos_offset = cpu.gpr[5] as i32 as i64;
    let Some(file) = files.iter_mut().find(|file| file.ref_num == ref_num) else {
        return PPC_RF_NUM_ERR;
    };
    let eof = vfs_files
        .iter()
        .find(|record| record.path.eq_ignore_ascii_case(&file.path))
        .map_or(0i64, |record| {
            i64::try_from(record.data.len()).unwrap_or(i64::MAX)
        });
    let current = i64::from(file.position);
    let new_pos = match pos_mode {
        0 => current,
        1 => pos_offset,
        2 => eof.saturating_add(pos_offset),
        3 => current.saturating_add(pos_offset),
        _ => return PPC_PARAM_ERR,
    };
    let Ok(new_pos) = u32::try_from(new_pos) else {
        return PPC_PARAM_ERR;
    };
    file.position = new_pos;
    PPC_NO_ERR
}

fn ppc_fs_read(
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    files: &mut [PpcFileRecord],
    vfs_files: &[PpcVfsFileRecord],
) -> i16 {
    let ref_num = ppc_ref_num_from_gpr(cpu.gpr[3]);
    let count_ptr = cpu.gpr[4];
    let buffer_ptr = cpu.gpr[5];
    if count_ptr == 0 || !ppc_memory_can_write_bytes(memory, count_ptr, 4) {
        return PPC_PARAM_ERR;
    }
    let Some(requested_count) = memory.read_u32_be(count_ptr) else {
        return PPC_PARAM_ERR;
    };
    let Some(file) = files.iter_mut().find(|file| file.ref_num == ref_num) else {
        return PPC_PARAM_ERR;
    };
    if requested_count > 0 && buffer_ptr == 0 {
        return PPC_PARAM_ERR;
    }
    let Some(vfs_file) = vfs_files
        .iter()
        .find(|record| record.path.eq_ignore_ascii_case(&file.path))
    else {
        return PPC_FNF_ERR;
    };
    let start = usize::try_from(file.position)
        .unwrap_or(usize::MAX)
        .min(vfs_file.data.len());
    let requested_len = usize::try_from(requested_count).unwrap_or(usize::MAX);
    let available = vfs_file.data.len().saturating_sub(start);
    let read_len = requested_len.min(available);
    if read_len > 0
        && !ppc_memory_can_write_bytes(
            memory,
            buffer_ptr,
            u32::try_from(read_len).unwrap_or(u32::MAX),
        )
    {
        return PPC_PARAM_ERR;
    }
    for (offset, byte) in vfs_file.data[start..start + read_len]
        .iter()
        .copied()
        .enumerate()
    {
        let Ok(offset) = u32::try_from(offset) else {
            return PPC_PARAM_ERR;
        };
        if memory.write_u8(buffer_ptr + offset, byte).is_none() {
            return PPC_PARAM_ERR;
        };
    }
    let read_count = u32::try_from(read_len).unwrap_or(u32::MAX);
    file.position = file.position.saturating_add(read_count);
    let _ = memory.write_u32_be(count_ptr, read_count);
    if read_count < requested_count {
        PPC_EOF_ERR
    } else {
        PPC_NO_ERR
    }
}

fn ppc_fs_write(
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    files: &mut [PpcFileRecord],
    writable_refnums: &HashSet<u16>,
    vfs_files: &mut Vec<PpcVfsFileRecord>,
) -> i16 {
    let ref_num = ppc_ref_num_from_gpr(cpu.gpr[3]);
    let count_ptr = cpu.gpr[4];
    let buffer_ptr = cpu.gpr[5];
    if count_ptr == 0 || !ppc_memory_can_write_bytes(memory, count_ptr, 4) {
        return PPC_PARAM_ERR;
    }
    let Some(requested_count) = memory.read_u32_be(count_ptr) else {
        return PPC_PARAM_ERR;
    };
    let Some(file) = files.iter_mut().find(|file| file.ref_num == ref_num) else {
        return PPC_RF_NUM_ERR;
    };
    if requested_count > 0 && buffer_ptr == 0 {
        return PPC_PARAM_ERR;
    }
    if requested_count > 0 && !ppc_memory_can_read_bytes(memory, buffer_ptr, requested_count) {
        return PPC_PARAM_ERR;
    }
    if !writable_refnums.contains(&(ref_num as u16)) {
        return PPC_WR_PERM_ERR;
    }
    let Some(vfs_file) = ppc_vfs_file_mut(vfs_files, &file.path) else {
        return PPC_FNF_ERR;
    };
    let Ok(start) = usize::try_from(file.position) else {
        return PPC_PARAM_ERR;
    };
    let Ok(requested_len) = usize::try_from(requested_count) else {
        return PPC_PARAM_ERR;
    };
    let Some(end) = start.checked_add(requested_len) else {
        return PPC_PARAM_ERR;
    };
    if start > vfs_file.data.len() {
        vfs_file.data.resize(start, 0);
    }
    if end > vfs_file.data.len() {
        vfs_file.data.resize(end, 0);
    }
    let bytes = ppc_memory_read_bytes(memory, buffer_ptr, requested_count).unwrap_or_default();
    vfs_file.dirty = true;
    vfs_file.data[start..end].copy_from_slice(&bytes);
    file.position = file.position.saturating_add(requested_count);
    let _ = memory.write_u32_be(count_ptr, requested_count);
    PPC_NO_ERR
}

fn ppc_fsp_create(
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &mut ProcessVfsFileRecords,
) -> i16 {
    let spec_ptr = cpu.gpr[3];
    let creator = cpu.gpr[4];
    let file_type = cpu.gpr[5];
    let path = match ppc_path_for_fsspec(memory, vfs_directories, spec_ptr) {
        Ok(path) => path,
        Err(err) => return err,
    };
    if ppc_vfs_file_index(vfs_files, &path).is_some() {
        return PPC_DUP_FN_ERR;
    }
    vfs_files.push(PpcVfsFileRecord {
        path,
        data: Vec::new().into(),
        creator,
        file_type,
        finder_flags: 0,
        dirty: true,
    });
    PPC_NO_ERR
}

fn ppc_h_create(
    cpu: &PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &mut ProcessVfsFileRecords,
    default_dir_id: u32,
) -> i16 {
    // Inside Macintosh: Files (1992), 2-169: HCreate identifies the parent
    // with a volume reference and directory ID, then supplies creator/type.
    ppc_create_data_fork_by_name(
        memory,
        vfs_directories,
        vfs_files,
        default_dir_id,
        cpu.gpr[3] as u16 as i16,
        cpu.gpr[4],
        cpu.gpr[5],
        cpu.gpr[6],
        cpu.gpr[7],
    )
}

fn ppc_pbh_create(
    binding: &PpcImportBinding,
    cpu: &PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &mut ProcessVfsFileRecords,
    default_dir_id: u32,
) -> i16 {
    let pb = cpu.gpr[3];
    if pb == 0 || !ppc_memory_can_write_bytes(memory, pb, 24) {
        return PPC_PARAM_ERR;
    }
    let Some(name_ptr) = memory.read_u32_be(pb + 18) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    let Some(vref) = memory.read_u16_be(pb + 22).map(|value| value as i16) else {
        return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
    };
    let hierarchical = binding.symbol_name.starts_with("PBHCreate");
    let dir_id = if hierarchical {
        let Some(dir_id) = memory.read_u32_be(pb + 48) else {
            return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
        };
        dir_id
    } else {
        0
    };
    // Inside Macintosh: Files (1992), 2-186 through 2-187: PBHCreate
    // creates closed, empty data and resource forks in ioDirID.
    let result = ppc_create_data_fork_by_name(
        memory,
        vfs_directories,
        vfs_files,
        default_dir_id,
        vref,
        dir_id,
        name_ptr,
        0,
        0,
    );
    ppc_complete_pb(memory, pb, result)
}

fn ppc_create(
    cpu: &PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &mut ProcessVfsFileRecords,
    default_dir_id: u32,
) -> i16 {
    // The non-hierarchical Create call resolves against the current directory.
    ppc_create_data_fork_by_name(
        memory,
        vfs_directories,
        vfs_files,
        default_dir_id,
        cpu.gpr[4] as u16 as i16,
        0,
        cpu.gpr[3],
        cpu.gpr[5],
        cpu.gpr[6],
    )
}

#[allow(clippy::too_many_arguments)]
fn ppc_create_data_fork_by_name(
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &mut ProcessVfsFileRecords,
    default_dir_id: u32,
    vref: i16,
    dir_id: u32,
    name_ptr: u32,
    creator: u32,
    file_type: u32,
) -> i16 {
    if !matches!(vref, 0 | PPC_BOOT_VOLUME_REF_NUM) {
        return PPC_NSV_ERR;
    }
    let Some(name_bytes) = ppc_read_pstring_bytes(memory, name_ptr) else {
        return PPC_PARAM_ERR;
    };
    let name = ppc_normalize_vfs_path(&decode_mac_roman(&name_bytes));
    if name.is_empty() {
        return PPC_PARAM_ERR;
    }
    let effective_dir_id = ppc_resolve_directory_id(vref, dir_id, default_dir_id);
    let Some(parent_path) = ppc_directory_path_for_id(vfs_directories, effective_dir_id) else {
        return PPC_DIR_NF_ERR;
    };
    let path = ppc_join_vfs_path(parent_path, &name);
    if ppc_vfs_file_index(vfs_files, &path).is_some() {
        return PPC_DUP_FN_ERR;
    }
    vfs_files.push(PpcVfsFileRecord {
        path,
        data: Vec::new().into(),
        creator,
        file_type,
        finder_flags: 0,
        dirty: true,
    });
    PPC_NO_ERR
}

fn ppc_fsp_delete(
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &mut ProcessVfsFileRecords,
    deleted_vfs_file_paths: &mut Vec<String>,
    files: &mut Vec<PpcFileRecord>,
    vfs_resource_files: &mut ProcessVfsResourceFileRecords,
    resource_files: &mut Vec<PpcResourceFileRecord>,
    vfs_resources: &mut Vec<PpcVfsResourceRecord>,
) -> i16 {
    let spec_ptr = cpu.gpr[3];
    let path = match ppc_path_for_fsspec(memory, vfs_directories, spec_ptr) {
        Ok(path) => path,
        Err(err) => return err,
    };
    ppc_delete_vfs_path(
        &path,
        vfs_files,
        deleted_vfs_file_paths,
        files,
        vfs_resource_files,
        resource_files,
        vfs_resources,
    )
}

#[allow(clippy::too_many_arguments)]
fn ppc_delete_by_name(
    binding: &PpcImportBinding,
    cpu: &PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &mut ProcessVfsFileRecords,
    deleted_vfs_file_paths: &mut Vec<String>,
    files: &mut Vec<PpcFileRecord>,
    vfs_resource_files: &mut ProcessVfsResourceFileRecords,
    resource_files: &mut Vec<PpcResourceFileRecord>,
    vfs_resources: &mut Vec<PpcVfsResourceRecord>,
    default_dir_id: u32,
) -> i16 {
    let is_parameter_block = matches!(
        binding.dispatcher_target,
        PpcImportDispatcherTarget::PBDelete
    );
    let (vref, dir_id, name_ptr, pb) = if is_parameter_block {
        let pb = cpu.gpr[3];
        if pb == 0 || !ppc_memory_can_write_bytes(memory, pb, 24) {
            return PPC_PARAM_ERR;
        }
        let Some(name_ptr) = memory.read_u32_be(pb + 18) else {
            return PPC_PARAM_ERR;
        };
        let Some(vref) = memory.read_u16_be(pb + 22).map(|value| value as i16) else {
            return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
        };
        let hierarchical = binding.symbol_name.starts_with("PBHDelete");
        let dir_id = if hierarchical {
            let Some(dir_id) = memory.read_u32_be(pb + 48) else {
                return ppc_complete_pb(memory, pb, PPC_PARAM_ERR);
            };
            dir_id
        } else {
            0
        };
        (vref, dir_id, name_ptr, Some(pb))
    } else if matches!(
        binding.dispatcher_target,
        PpcImportDispatcherTarget::HDelete
    ) {
        (cpu.gpr[3] as u16 as i16, cpu.gpr[4], cpu.gpr[5], None)
    } else {
        (cpu.gpr[4] as u16 as i16, 0, cpu.gpr[3], None)
    };

    // Inside Macintosh: Files (1992), 2-102 and 2-189: PBDelete/PBHDelete
    // identify both forks by name; HDelete's high-level ABI is on 2-173.
    let result = if !matches!(vref, 0 | PPC_BOOT_VOLUME_REF_NUM) {
        PPC_NSV_ERR
    } else if let Some(name_bytes) = ppc_read_pstring_bytes(memory, name_ptr) {
        let name = ppc_normalize_vfs_path(&decode_mac_roman(&name_bytes));
        if name.is_empty() {
            PPC_PARAM_ERR
        } else {
            let effective_dir_id = ppc_resolve_directory_id(vref, dir_id, default_dir_id);
            if let Some(parent_path) = ppc_directory_path_for_id(vfs_directories, effective_dir_id)
            {
                let requested_path = ppc_join_vfs_path(parent_path, &name);
                let path =
                    ppc_vfs_file_or_resource_path(vfs_files, vfs_resource_files, &requested_path)
                        .or_else(|| {
                            ppc_vfs_file_or_resource_path_by_basename(
                                vfs_files,
                                vfs_resource_files,
                                &name,
                            )
                        });
                if let Some(path) = path {
                    ppc_delete_vfs_path(
                        &path,
                        vfs_files,
                        deleted_vfs_file_paths,
                        files,
                        vfs_resource_files,
                        resource_files,
                        vfs_resources,
                    )
                } else {
                    PPC_FNF_ERR
                }
            } else {
                PPC_DIR_NF_ERR
            }
        }
    } else {
        PPC_PARAM_ERR
    };
    pb.map_or(result, |pb| ppc_complete_pb(memory, pb, result))
}

fn ppc_delete_vfs_path(
    path: &str,
    vfs_files: &mut ProcessVfsFileRecords,
    deleted_vfs_file_paths: &mut Vec<String>,
    files: &mut Vec<PpcFileRecord>,
    vfs_resource_files: &mut ProcessVfsResourceFileRecords,
    resource_files: &mut Vec<PpcResourceFileRecord>,
    vfs_resources: &mut Vec<PpcVfsResourceRecord>,
) -> i16 {
    let existed = vfs_files
        .iter()
        .any(|file| file.path.eq_ignore_ascii_case(path))
        || vfs_resource_files
            .iter()
            .any(|file| file.path.eq_ignore_ascii_case(path))
        || vfs_resources
            .iter()
            .any(|resource| resource.path.eq_ignore_ascii_case(path));
    if !existed {
        return PPC_FNF_ERR;
    }
    vfs_files.retain(|file| !file.path.eq_ignore_ascii_case(path));
    if !deleted_vfs_file_paths
        .iter()
        .any(|deleted| deleted.eq_ignore_ascii_case(&path))
    {
        deleted_vfs_file_paths.push(path.to_string());
    }
    files.retain(|file| !file.path.eq_ignore_ascii_case(&path));
    vfs_resource_files.retain(|file| !file.path.eq_ignore_ascii_case(&path));
    resource_files.retain(|file| !file.path.eq_ignore_ascii_case(&path));
    vfs_resources.retain(|resource| !resource.path.eq_ignore_ascii_case(&path));
    PPC_NO_ERR
}

fn ppc_ref_num_from_gpr(value: u32) -> i16 {
    value as u16 as i16
}

fn ppc_block_move(cpu: &mut PpcCpu, memory: &mut PpcSectionMem) {
    let source_ptr = cpu.gpr[3];
    let dest_ptr = cpu.gpr[4];
    let byte_count = cpu.gpr[5] as usize;
    let mut bytes = vec![0; byte_count];
    let _ = memory
        .read_bytes_into(source_ptr, &mut bytes)
        .and_then(|()| memory.write_bytes(dest_ptr, &bytes));
}

#[cfg(test)]
fn ppc_hand_to_hand(
    cpu: &PpcCpu,
    memory: &mut PpcSectionMem,
    heap_cursor: &mut u32,
    heap_limit: u32,
    handles: &mut Vec<PpcHandleRecord>,
    free_handle_blocks: &mut Vec<PpcHandleRecord>,
) -> i16 {
    let handle_variable = cpu.gpr[3];
    if handle_variable == 0 || !ppc_memory_can_write_bytes(memory, handle_variable, 4) {
        return PPC_PARAM_ERR;
    }
    let Some(source_handle) = memory.read_u32_be(handle_variable) else {
        return PPC_PARAM_ERR;
    };
    let Some(source) = handles
        .iter()
        .find(|record| record.handle == source_handle)
        .copied()
        .or_else(|| ppc_system_handle_record(memory, source_handle))
    else {
        return PPC_NIL_HANDLE_ERR;
    };
    let Some(bytes) = ppc_memory_read_bytes(memory, source.ptr, source.size) else {
        return PPC_PARAM_ERR;
    };
    let copy = ppc_alloc_recyclable_handle_with_bytes(
        memory,
        heap_cursor,
        heap_limit,
        handles,
        free_handle_blocks,
        &bytes,
    );
    if copy == 0 {
        return PPC_MEM_FULL_ERR;
    }
    // Inside Macintosh: Memory (1992), pp. 2-62--2-63: HandToHand replaces
    // the caller's Handle variable with an unlocked, unpurgeable data copy.
    if memory.write_u32_be(handle_variable, copy).is_none() {
        return PPC_PARAM_ERR;
    }
    if ppc_hle_trace_enabled() {
        eprintln!(
            "[PPC-TRACE] HandToHand variable=${handle_variable:08X} source=${source_handle:08X} size={} -> ${copy:08X}",
            source.size
        );
    }
    PPC_NO_ERR
}

fn ppc_system_handle_record(memory: &mut PpcSectionMem, handle: u32) -> Option<PpcHandleRecord> {
    // Inside Macintosh: Imaging With QuickDraw (1994), pp. 4-47 and 4-83:
    // a GDevice's indexed PixMap owns its ColorTable through a Handle. The
    // main device is Toolbox-owned rather than application-heap-owned, but
    // Memory Manager routines such as HandToHand must still accept it.
    let size = match handle {
        PPC_MAIN_CTABLE_HANDLE => PPC_MAIN_CTABLE_SIZE,
        _ => return None,
    };
    let ptr = memory.read_u32_be(handle)?;
    ppc_memory_read_bytes(memory, ptr, size)?;
    Some(PpcHandleRecord {
        handle,
        ptr,
        size,
        capacity: size,
    })
}

fn initial_ppc_vfs_directories() -> Vec<PpcVfsDirectory> {
    vec![
        PpcVfsDirectory {
            dir_id: PPC_ROOT_DIR_ID,
            parent_dir_id: 1,
            path: String::new(),
            creator: PPC_DIRECTORY_CREATOR,
            file_type: PPC_DIRECTORY_FILE_TYPE,
            finder_flags: 0,
            dirty: false,
        },
        PpcVfsDirectory {
            dir_id: PPC_SYSTEM_FOLDER_DIR_ID,
            parent_dir_id: PPC_ROOT_DIR_ID,
            path: "System Folder".to_string(),
            creator: PPC_DIRECTORY_CREATOR,
            file_type: PPC_DIRECTORY_FILE_TYPE,
            finder_flags: 0,
            dirty: false,
        },
        PpcVfsDirectory {
            dir_id: PPC_PREFERENCES_DIR_ID,
            parent_dir_id: PPC_SYSTEM_FOLDER_DIR_ID,
            path: "System Folder/Preferences".to_string(),
            creator: PPC_DIRECTORY_CREATOR,
            file_type: PPC_DIRECTORY_FILE_TYPE,
            finder_flags: 0,
            dirty: false,
        },
    ]
}

fn ppc_dir_create(
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_directories: &mut Vec<PpcVfsDirectory>,
    next_vfs_dir_id: &mut u32,
    default_dir_id: u32,
) -> i16 {
    let vref = cpu.gpr[3] as u16 as i16;
    let parent_dir_id = ppc_resolve_directory_id(vref, cpu.gpr[4], default_dir_id);
    let directory_name_ptr = cpu.gpr[5];
    let created_dir_id_ptr = cpu.gpr[6];
    if directory_name_ptr == 0 || created_dir_id_ptr == 0 {
        return PPC_PARAM_ERR;
    }
    let Some(directory_name) = ppc_read_pstring(memory, directory_name_ptr) else {
        return PPC_PARAM_ERR;
    };
    let normalized_name = ppc_normalize_vfs_path(&directory_name);
    if normalized_name.is_empty() {
        return PPC_PARAM_ERR;
    }
    let Some(parent_path) = ppc_directory_path_for_id(vfs_directories, parent_dir_id) else {
        return PPC_FNF_ERR;
    };
    let path = ppc_join_vfs_path(parent_path, &normalized_name);
    if let Some(existing) = ppc_directory_id_for_path(vfs_directories, &path) {
        let _ = memory.write_u32_be(created_dir_id_ptr, existing);
        return PPC_DUP_FN_ERR;
    }

    let dir_id = *next_vfs_dir_id;
    let Some(next_dir_id) = next_vfs_dir_id.checked_add(1) else {
        return PPC_PARAM_ERR;
    };
    if memory.write_u32_be(created_dir_id_ptr, dir_id).is_none() {
        return PPC_PARAM_ERR;
    }
    *next_vfs_dir_id = next_dir_id;
    vfs_directories.push(PpcVfsDirectory {
        dir_id,
        parent_dir_id,
        path,
        creator: PPC_DIRECTORY_CREATOR,
        file_type: PPC_DIRECTORY_FILE_TYPE,
        finder_flags: 0,
        dirty: true,
    });
    PPC_NO_ERR
}

fn ppc_fsp_dir_create(
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_directories: &mut Vec<PpcVfsDirectory>,
    next_vfs_dir_id: &mut u32,
    default_dir_id: u32,
) -> i16 {
    let spec_ptr = cpu.gpr[3];
    let created_dir_id_ptr = cpu.gpr[5];
    if spec_ptr == 0 || created_dir_id_ptr == 0 {
        return PPC_PARAM_ERR;
    }
    let Some((vref, requested_dir_id, directory_name)) = ppc_read_fsspec_parts(memory, spec_ptr)
    else {
        return PPC_PARAM_ERR;
    };
    if directory_name.is_empty() {
        return PPC_PARAM_ERR;
    }
    let parent_dir_id = ppc_resolve_directory_id(vref, requested_dir_id, default_dir_id);
    let normalized_name = ppc_normalize_vfs_path(&decode_mac_roman(&directory_name));
    if normalized_name.is_empty() {
        return PPC_PARAM_ERR;
    }
    let Some(parent_path) = ppc_directory_path_for_id(vfs_directories, parent_dir_id) else {
        return PPC_FNF_ERR;
    };
    let path = ppc_join_vfs_path(parent_path, &normalized_name);
    if let Some(existing) = ppc_directory_id_for_path(vfs_directories, &path) {
        let _ = memory.write_u32_be(created_dir_id_ptr, existing);
        return PPC_DUP_FN_ERR;
    }

    let dir_id = *next_vfs_dir_id;
    let Some(next_dir_id) = next_vfs_dir_id.checked_add(1) else {
        return PPC_PARAM_ERR;
    };
    if memory.write_u32_be(created_dir_id_ptr, dir_id).is_none() {
        return PPC_PARAM_ERR;
    }
    *next_vfs_dir_id = next_dir_id;
    vfs_directories.push(PpcVfsDirectory {
        dir_id,
        parent_dir_id,
        path,
        creator: PPC_DIRECTORY_CREATOR,
        file_type: PPC_DIRECTORY_FILE_TYPE,
        finder_flags: 0,
        dirty: true,
    });
    PPC_NO_ERR
}

fn ppc_find_folder_dir_id(folder_type: u32) -> u32 {
    if folder_type == u32::from_be_bytes(*b"pref") {
        PPC_PREFERENCES_DIR_ID
    } else {
        PPC_ROOT_DIR_ID
    }
}

fn ppc_new_alias(
    cpu: &mut PpcCpu,
    process_memory_manager: &mut ProcessNativeMemoryManager,
    memory: &mut PpcSectionMem,
    heap_cursor: &mut u32,
    last_mem_error: &mut i16,
    handles: &mut Vec<PpcHandleRecord>,
    aliases: &mut Vec<PpcAliasRecord>,
) -> i16 {
    let _from_file_ptr = cpu.gpr[3];
    let target_ptr = cpu.gpr[4];
    let alias_out_ptr = cpu.gpr[5];
    if target_ptr == 0 || alias_out_ptr == 0 {
        *last_mem_error = PPC_NO_ERR;
        return PPC_PARAM_ERR;
    }
    if !ppc_memory_can_write_bytes(memory, alias_out_ptr, 4) {
        *last_mem_error = PPC_NO_ERR;
        return PPC_PARAM_ERR;
    };
    let Some((target_vref, target_dir_id, target_name)) = ppc_read_fsspec_parts(memory, target_ptr)
    else {
        *last_mem_error = PPC_NO_ERR;
        return PPC_PARAM_ERR;
    };
    let Some(alias_data) = ppc_alias_record_bytes(target_vref, target_dir_id, &target_name) else {
        *last_mem_error = PPC_NO_ERR;
        return PPC_PARAM_ERR;
    };

    let handle = ppc_process_alloc_handle_with_bytes(
        process_memory_manager,
        memory,
        heap_cursor,
        last_mem_error,
        handles,
        &alias_data,
    );
    if handle == 0 {
        *last_mem_error = PPC_MEM_FULL_ERR;
        return PPC_MEM_FULL_ERR;
    }
    if memory.write_u32_be(alias_out_ptr, handle).is_none() {
        *last_mem_error = PPC_NO_ERR;
        return PPC_PARAM_ERR;
    }
    aliases.push(PpcAliasRecord {
        handle,
        target_vref: target_vref as i16,
        target_dir_id,
        target_name,
    });
    *last_mem_error = PPC_NO_ERR;
    PPC_NO_ERR
}

fn ppc_write_fsspec_parts(
    memory: &mut PpcSectionMem,
    spec_ptr: u32,
    vref: i16,
    dir_id: u32,
    name: &[u8],
) -> bool {
    if spec_ptr == 0 || name.len() > PPC_FSSPEC_MAX_NAME_LEN {
        return false;
    }
    ppc_write_fsspec(memory, spec_ptr, vref, dir_id, name).is_some()
}

fn ppc_read_fsspec_parts(memory: &mut PpcSectionMem, spec_ptr: u32) -> Option<(i16, u32, Vec<u8>)> {
    if spec_ptr == 0 {
        return None;
    }
    let vref = memory.read_u16_be(spec_ptr)? as i16;
    let dir_id = memory.read_u32_be(spec_ptr + 2)?;
    let name_len = usize::from(memory.read_u8(spec_ptr + 6)?);
    if name_len > PPC_FSSPEC_MAX_NAME_LEN {
        return None;
    }
    let mut name = Vec::with_capacity(name_len);
    for offset in 0..name_len {
        name.push(memory.read_u8(spec_ptr.checked_add(7 + offset as u32)?)?);
    }
    Some((vref, dir_id, name))
}

fn ppc_alias_record_bytes(vref: i16, dir_id: u32, name: &[u8]) -> Option<Vec<u8>> {
    if name.len() > PPC_FSSPEC_MAX_NAME_LEN {
        return None;
    }
    let mut bytes = vec![0; PPC_CLASSIC_ALIAS_RECORD_SIZE];
    bytes[4..6].copy_from_slice(&(PPC_CLASSIC_ALIAS_RECORD_SIZE as u16).to_be_bytes());
    bytes[6..8].copy_from_slice(&PPC_CLASSIC_ALIAS_RECORD_VERSION.to_be_bytes());
    ppc_write_alias_pstring(
        &mut bytes,
        PPC_CLASSIC_ALIAS_VOLUME_NAME_OFFSET,
        27,
        b"Systemless",
    )?;
    ppc_write_alias_pstring(&mut bytes, PPC_CLASSIC_ALIAS_FILE_NAME_OFFSET, 63, name)?;
    bytes[PPC_CLASSIC_ALIAS_DIR_ID_OFFSET..PPC_CLASSIC_ALIAS_DIR_ID_OFFSET + 4]
        .copy_from_slice(&dir_id.to_be_bytes());

    let mystery_words = PPC_CLASSIC_ALIAS_MYSTERY_WORDS_OFFSET;
    bytes[mystery_words..mystery_words + 2].copy_from_slice(&0xffffu16.to_be_bytes());
    bytes[mystery_words + 2..mystery_words + 4].copy_from_slice(&0xffffu16.to_be_bytes());
    bytes[mystery_words + 6..mystery_words + 8].copy_from_slice(&17u16.to_be_bytes());

    let tail = PPC_CLASSIC_ALIAS_RECORD_HEADER_SIZE;
    bytes[tail..tail + 2].copy_from_slice(&PPC_CLASSIC_ALIAS_TAIL_TAG.to_be_bytes());
    bytes[tail + 2..tail + 4]
        .copy_from_slice(&(PPC_CLASSIC_ALIAS_TAIL_PAYLOAD_SIZE as u16).to_be_bytes());
    ppc_fill_classic_alias_tail_payload(
        &mut bytes[tail + 4..tail + 4 + PPC_CLASSIC_ALIAS_TAIL_PAYLOAD_SIZE],
    );
    let end = tail + 4 + PPC_CLASSIC_ALIAS_TAIL_PAYLOAD_SIZE;
    bytes[end..end + 2].copy_from_slice(&PPC_CLASSIC_ALIAS_END_TAG.to_be_bytes());

    // Classic AliasRecords are volume/name based. The in-memory side table
    // preserves the exact vRefNum for handles created during this run; decoded
    // archive-style records resolve to the boot volume.
    let _ = vref;
    Some(bytes)
}

#[cfg(test)]
fn ppc_legacy_alias_record_bytes(vref: i16, dir_id: u32, name: &[u8]) -> Option<Vec<u8>> {
    if name.len() > PPC_FSSPEC_MAX_NAME_LEN {
        return None;
    }
    let mut bytes = vec![0; PPC_ALIAS_RECORD_SIZE];
    bytes[0..4].copy_from_slice(&PPC_ALIAS_RECORD_MAGIC.to_be_bytes());
    bytes[4..6].copy_from_slice(&(PPC_ALIAS_RECORD_SIZE as u16).to_be_bytes());
    bytes[6..8].copy_from_slice(&PPC_ALIAS_RECORD_VERSION.to_be_bytes());
    bytes[8..10].copy_from_slice(&(PPC_ALIAS_RECORD_FSSPEC_OFFSET as u16).to_be_bytes());
    bytes[10..12].copy_from_slice(&(PPC_FSSPEC_SIZE as u16).to_be_bytes());

    let fsspec = PPC_ALIAS_RECORD_FSSPEC_OFFSET;
    bytes[fsspec..fsspec + 2].copy_from_slice(&(vref as u16).to_be_bytes());
    bytes[fsspec + 2..fsspec + 6].copy_from_slice(&dir_id.to_be_bytes());
    bytes[fsspec + 6] = name.len() as u8;
    bytes[fsspec + 7..fsspec + 7 + name.len()].copy_from_slice(name);
    Some(bytes)
}

fn ppc_write_alias_pstring(
    bytes: &mut [u8],
    offset: usize,
    max_len: usize,
    value: &[u8],
) -> Option<()> {
    if value.len() > max_len || offset.checked_add(1 + max_len)? > bytes.len() {
        return None;
    }
    bytes[offset] = value.len() as u8;
    bytes[offset + 1..offset + 1 + value.len()].copy_from_slice(value);
    Some(())
}

fn ppc_fill_classic_alias_tail_payload(payload: &mut [u8]) {
    let words = [
        (0usize, 0x00a8u16),
        (1, 0x6166),
        (2, 0x706d),
        (5, 0x0003),
        (6, 0x0018),
        (7, 0x0039),
        (8, 0x0059),
        (9, 0x0075),
        (10, 0x0095),
        (11, 0x009e),
    ];
    for (index, value) in words {
        let offset = index * 2;
        if offset + 2 <= payload.len() {
            payload[offset..offset + 2].copy_from_slice(&value.to_be_bytes());
        }
    }
    let zone_offset = 24usize;
    if zone_offset + 2 <= payload.len() {
        payload[zone_offset] = 1;
        payload[zone_offset + 1] = b'*';
    }
}

fn ppc_alias_record_from_handle(
    memory: &mut PpcSectionMem,
    handles: &[PpcHandleRecord],
    alias_handle: u32,
    vfs_directories: Option<&[PpcVfsDirectory]>,
) -> Option<PpcAliasRecord> {
    let handle_record = handles
        .iter()
        .find(|record| record.handle == alias_handle)?;
    let handle_size = usize::try_from(handle_record.size).ok()?;
    let data_ptr = memory.read_u32_be(alias_handle)?;
    ppc_legacy_alias_record_from_data(memory, alias_handle, data_ptr, handle_size).or_else(|| {
        ppc_classic_alias_record_from_data(
            memory,
            alias_handle,
            data_ptr,
            handle_size,
            vfs_directories,
        )
    })
}

fn ppc_legacy_alias_record_from_data(
    memory: &mut PpcSectionMem,
    alias_handle: u32,
    data_ptr: u32,
    handle_size: usize,
) -> Option<PpcAliasRecord> {
    let magic = memory.read_u32_be(data_ptr)?;
    if magic != PPC_ALIAS_RECORD_MAGIC {
        return None;
    }
    let record_size = usize::from(memory.read_u16_be(data_ptr + 4)?);
    let version = memory.read_u16_be(data_ptr + 6)?;
    let fsspec_offset = usize::from(memory.read_u16_be(data_ptr + 8)?);
    let fsspec_size = usize::from(memory.read_u16_be(data_ptr + 10)?);
    if version != PPC_ALIAS_RECORD_VERSION
        || record_size > handle_size
        || fsspec_size != PPC_FSSPEC_SIZE
        || fsspec_offset.checked_add(PPC_FSSPEC_SIZE)? > record_size
    {
        return None;
    }
    let fsspec_ptr = data_ptr.checked_add(u32::try_from(fsspec_offset).ok()?)?;
    let (target_vref, target_dir_id, target_name) = ppc_read_fsspec_parts(memory, fsspec_ptr)?;
    Some(PpcAliasRecord {
        handle: alias_handle,
        target_vref,
        target_dir_id,
        target_name,
    })
}

fn ppc_classic_alias_record_from_data(
    memory: &mut PpcSectionMem,
    alias_handle: u32,
    data_ptr: u32,
    handle_size: usize,
    vfs_directories: Option<&[PpcVfsDirectory]>,
) -> Option<PpcAliasRecord> {
    if handle_size < PPC_CLASSIC_ALIAS_RECORD_HEADER_SIZE {
        return None;
    }
    let record_size = usize::from(memory.read_u16_be(data_ptr + 4)?);
    let version = memory.read_u16_be(data_ptr + 6)?;
    if version != PPC_CLASSIC_ALIAS_RECORD_VERSION
        || record_size < PPC_CLASSIC_ALIAS_RECORD_HEADER_SIZE
        || record_size > handle_size
    {
        return None;
    }

    let mut target_dir_id = memory
        .read_u32_be(data_ptr.checked_add(u32::try_from(PPC_CLASSIC_ALIAS_DIR_ID_OFFSET).ok()?)?)?;
    let mut target_name = ppc_read_fixed_pstring_bytes(
        memory,
        data_ptr.checked_add(u32::try_from(PPC_CLASSIC_ALIAS_FILE_NAME_OFFSET).ok()?)?,
        PPC_FSSPEC_MAX_NAME_LEN,
    )?;

    if target_dir_id == u32::MAX || target_name.is_empty() {
        if let Some((full_path_dir_id, full_path_name)) =
            ppc_classic_alias_full_path_target(memory, data_ptr, record_size, vfs_directories)
        {
            target_dir_id = full_path_dir_id;
            target_name = full_path_name;
        }
    }
    if target_dir_id == u32::MAX || target_name.len() > PPC_FSSPEC_MAX_NAME_LEN {
        return None;
    }

    Some(PpcAliasRecord {
        handle: alias_handle,
        target_vref: PPC_BOOT_VOLUME_REF_NUM,
        target_dir_id,
        target_name,
    })
}

fn ppc_alias_record_from_bytes(
    bytes: &[u8],
    vfs_directories: Option<&[PpcVfsDirectory]>,
) -> Option<PpcAliasRecord> {
    ppc_legacy_alias_record_from_bytes(bytes)
        .or_else(|| ppc_classic_alias_record_from_bytes(bytes, vfs_directories))
}

fn ppc_legacy_alias_record_from_bytes(bytes: &[u8]) -> Option<PpcAliasRecord> {
    let magic = ppc_slice_u32_be(bytes, 0)?;
    if magic != PPC_ALIAS_RECORD_MAGIC {
        return None;
    }
    let record_size = usize::from(ppc_slice_u16_be(bytes, 4)?);
    let version = ppc_slice_u16_be(bytes, 6)?;
    let fsspec_offset = usize::from(ppc_slice_u16_be(bytes, 8)?);
    let fsspec_size = usize::from(ppc_slice_u16_be(bytes, 10)?);
    if version != PPC_ALIAS_RECORD_VERSION
        || record_size > bytes.len()
        || fsspec_size != PPC_FSSPEC_SIZE
        || fsspec_offset.checked_add(PPC_FSSPEC_SIZE)? > record_size
    {
        return None;
    }
    let target_vref = ppc_slice_u16_be(bytes, fsspec_offset)? as i16;
    let target_dir_id = ppc_slice_u32_be(bytes, fsspec_offset + 2)?;
    let target_name =
        ppc_slice_fixed_pstring_bytes(bytes, fsspec_offset + 6, PPC_FSSPEC_MAX_NAME_LEN)?;
    Some(PpcAliasRecord {
        handle: 0,
        target_vref,
        target_dir_id,
        target_name,
    })
}

fn ppc_classic_alias_record_from_bytes(
    bytes: &[u8],
    vfs_directories: Option<&[PpcVfsDirectory]>,
) -> Option<PpcAliasRecord> {
    if bytes.len() < PPC_CLASSIC_ALIAS_RECORD_HEADER_SIZE {
        return None;
    }
    let record_size = usize::from(ppc_slice_u16_be(bytes, 4)?);
    let version = ppc_slice_u16_be(bytes, 6)?;
    if version != PPC_CLASSIC_ALIAS_RECORD_VERSION
        || record_size < PPC_CLASSIC_ALIAS_RECORD_HEADER_SIZE
        || record_size > bytes.len()
    {
        return None;
    }
    let mut target_dir_id = ppc_slice_u32_be(bytes, PPC_CLASSIC_ALIAS_DIR_ID_OFFSET)?;
    let mut target_name = ppc_slice_fixed_pstring_bytes(
        bytes,
        PPC_CLASSIC_ALIAS_FILE_NAME_OFFSET,
        PPC_FSSPEC_MAX_NAME_LEN,
    )?;
    if target_dir_id == u32::MAX || target_name.is_empty() {
        if let Some((full_path_dir_id, full_path_name)) =
            ppc_classic_alias_full_path_target_from_bytes(bytes, record_size, vfs_directories)
        {
            target_dir_id = full_path_dir_id;
            target_name = full_path_name;
        }
    }
    if target_dir_id == u32::MAX || target_name.len() > PPC_FSSPEC_MAX_NAME_LEN {
        return None;
    }
    Some(PpcAliasRecord {
        handle: 0,
        target_vref: PPC_BOOT_VOLUME_REF_NUM,
        target_dir_id,
        target_name,
    })
}

fn ppc_classic_alias_full_path_target_from_bytes(
    bytes: &[u8],
    record_size: usize,
    vfs_directories: Option<&[PpcVfsDirectory]>,
) -> Option<(u32, Vec<u8>)> {
    let mut offset = PPC_CLASSIC_ALIAS_RECORD_HEADER_SIZE;
    while offset.checked_add(4)? <= record_size {
        let tag = ppc_slice_u16_be(bytes, offset)?;
        if tag == PPC_CLASSIC_ALIAS_END_TAG {
            return None;
        }
        let len = usize::from(ppc_slice_u16_be(bytes, offset + 2)?);
        let payload_offset = offset.checked_add(4)?;
        let payload_end = payload_offset.checked_add(len)?;
        if payload_end > record_size {
            return None;
        }
        if tag == PPC_CLASSIC_ALIAS_FULL_PATH_TAG {
            return ppc_classic_alias_target_from_full_path(
                bytes.get(payload_offset..payload_end)?,
                vfs_directories,
            );
        }
        offset = payload_offset.checked_add((len + 1) & !1)?;
    }
    None
}

fn ppc_slice_u16_be(bytes: &[u8], offset: usize) -> Option<u16> {
    Some(u16::from_be_bytes(
        bytes.get(offset..offset.checked_add(2)?)?.try_into().ok()?,
    ))
}

fn ppc_slice_u32_be(bytes: &[u8], offset: usize) -> Option<u32> {
    Some(u32::from_be_bytes(
        bytes.get(offset..offset.checked_add(4)?)?.try_into().ok()?,
    ))
}

fn ppc_slice_fixed_pstring_bytes(bytes: &[u8], offset: usize, max_len: usize) -> Option<Vec<u8>> {
    let len = usize::from(*bytes.get(offset)?);
    if len > max_len {
        return None;
    }
    Some(
        bytes
            .get(offset + 1..offset.checked_add(1 + len)?)?
            .to_vec(),
    )
}

fn ppc_classic_alias_full_path_target(
    memory: &mut PpcSectionMem,
    data_ptr: u32,
    record_size: usize,
    vfs_directories: Option<&[PpcVfsDirectory]>,
) -> Option<(u32, Vec<u8>)> {
    let mut offset = PPC_CLASSIC_ALIAS_RECORD_HEADER_SIZE;
    while offset.checked_add(4)? <= record_size {
        let tag = memory.read_u16_be(data_ptr.checked_add(u32::try_from(offset).ok()?)?)?;
        if tag == PPC_CLASSIC_ALIAS_END_TAG {
            return None;
        }
        let len = usize::from(
            memory
                .read_u16_be(data_ptr.checked_add(u32::try_from(offset.checked_add(2)?).ok()?)?)?,
        );
        let payload_offset = offset.checked_add(4)?;
        let payload_end = payload_offset.checked_add(len)?;
        if payload_end > record_size {
            return None;
        }
        if tag == PPC_CLASSIC_ALIAS_FULL_PATH_TAG {
            let payload_ptr = data_ptr.checked_add(u32::try_from(payload_offset).ok()?)?;
            let mut path = Vec::with_capacity(len);
            for path_offset in 0..len {
                path.push(memory.read_u8(payload_ptr.checked_add(path_offset as u32)?)?);
            }
            return ppc_classic_alias_target_from_full_path(&path, vfs_directories);
        }
        offset = payload_offset.checked_add((len + 1) & !1)?;
    }
    None
}

fn ppc_classic_alias_target_from_full_path(
    path: &[u8],
    vfs_directories: Option<&[PpcVfsDirectory]>,
) -> Option<(u32, Vec<u8>)> {
    let parts = path
        .split(|byte| *byte == b':')
        .filter(|part| !part.is_empty())
        .collect::<Vec<_>>();
    if parts.len() < 2 {
        return None;
    }
    let target_name = parts.last()?.to_vec();
    if target_name.len() > PPC_FSSPEC_MAX_NAME_LEN {
        return None;
    }
    let parent_parts = &parts[1..parts.len().saturating_sub(1)];
    let parent_path = parent_parts
        .iter()
        .map(|part| decode_mac_roman(part))
        .collect::<Vec<_>>()
        .join("/");
    let normalized_parent_path = ppc_normalize_vfs_path(&parent_path);
    if let Some(vfs_directories) = vfs_directories {
        if let Some(dir_id) = ppc_directory_id_for_path(vfs_directories, &normalized_parent_path) {
            return Some((dir_id, target_name));
        }
    }
    let dir_id = if normalized_parent_path.is_empty() {
        PPC_ROOT_DIR_ID
    } else if normalized_parent_path.eq_ignore_ascii_case("System Folder") {
        PPC_SYSTEM_FOLDER_DIR_ID
    } else if normalized_parent_path.eq_ignore_ascii_case("System Folder/Preferences") {
        PPC_PREFERENCES_DIR_ID
    } else {
        return None;
    };
    Some((dir_id, target_name))
}

fn ppc_read_fixed_pstring_bytes(
    memory: &mut PpcSectionMem,
    addr: u32,
    max_len: usize,
) -> Option<Vec<u8>> {
    let len = usize::from(memory.read_u8(addr)?);
    if len > max_len {
        return None;
    }
    let mut bytes = Vec::with_capacity(len);
    for offset in 0..len {
        bytes.push(memory.read_u8(addr.checked_add(1 + offset as u32)?)?);
    }
    Some(bytes)
}

fn ppc_resolve_alias(
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    handles: &[PpcHandleRecord],
    aliases: &[PpcAliasRecord],
) -> i16 {
    let _from_file_ptr = cpu.gpr[3];
    let alias_handle = cpu.gpr[4];
    let target_ptr = cpu.gpr[5];
    let was_changed_ptr = cpu.gpr[6];
    if alias_handle == 0 || target_ptr == 0 || was_changed_ptr == 0 {
        return PPC_PARAM_ERR;
    }
    if !ppc_memory_can_write_bytes(memory, target_ptr, PPC_FSSPEC_SIZE as u32)
        || !ppc_memory_can_write_bytes(memory, was_changed_ptr, 1)
    {
        return PPC_PARAM_ERR;
    };
    let alias = aliases
        .iter()
        .find(|record| record.handle == alias_handle)
        .cloned()
        .or_else(|| {
            ppc_alias_record_from_handle(memory, handles, alias_handle, Some(vfs_directories))
        });
    let Some(alias) = alias else {
        return PPC_PARAM_ERR;
    };
    if !ppc_write_fsspec_parts(
        memory,
        target_ptr,
        alias.target_vref,
        alias.target_dir_id,
        &alias.target_name,
    ) || memory.write_u8(was_changed_ptr, 0).is_none()
    {
        return PPC_PARAM_ERR;
    }
    PPC_NO_ERR
}

fn ppc_update_alias(
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    last_mem_error: &mut i16,
    vfs_directories: &[PpcVfsDirectory],
    handles: &mut [PpcHandleRecord],
    aliases: &mut Vec<PpcAliasRecord>,
) -> i16 {
    let _from_file_ptr = cpu.gpr[3];
    let target_ptr = cpu.gpr[4];
    let alias_handle = cpu.gpr[5];
    let was_changed_ptr = cpu.gpr[6];
    if target_ptr == 0 || alias_handle == 0 || was_changed_ptr == 0 {
        *last_mem_error = PPC_NO_ERR;
        return PPC_PARAM_ERR;
    }
    if !ppc_memory_can_write_bytes(memory, was_changed_ptr, 1) {
        *last_mem_error = PPC_NO_ERR;
        return PPC_PARAM_ERR;
    }
    let Some((target_vref, target_dir_id, target_name)) = ppc_read_fsspec_parts(memory, target_ptr)
    else {
        *last_mem_error = PPC_NO_ERR;
        return PPC_PARAM_ERR;
    };
    let Some(alias_data) = ppc_alias_record_bytes(target_vref, target_dir_id, &target_name) else {
        *last_mem_error = PPC_NO_ERR;
        return PPC_PARAM_ERR;
    };
    let Some(handle_index) = handles
        .iter()
        .position(|record| record.handle == alias_handle)
    else {
        *last_mem_error = PPC_NO_ERR;
        return PPC_PARAM_ERR;
    };
    let existing_alias = aliases
        .iter()
        .find(|record| record.handle == alias_handle)
        .cloned()
        .or_else(|| {
            ppc_alias_record_from_handle(memory, handles, alias_handle, Some(vfs_directories))
        });
    let Some(existing_alias) = existing_alias else {
        *last_mem_error = PPC_NO_ERR;
        return PPC_PARAM_ERR;
    };
    let changed = existing_alias.target_vref != target_vref
        || existing_alias.target_dir_id != target_dir_id
        || existing_alias.target_name != target_name;
    if !changed {
        if memory.write_u8(was_changed_ptr, 0).is_none() {
            *last_mem_error = PPC_NO_ERR;
            return PPC_PARAM_ERR;
        }
        *last_mem_error = PPC_NO_ERR;
        return PPC_NO_ERR;
    }

    let handle_size = usize::try_from(handles[handle_index].size).unwrap_or(usize::MAX);
    if alias_data.len() > handle_size {
        *last_mem_error = PPC_MEM_FULL_ERR;
        return PPC_MEM_FULL_ERR;
    }
    let Some(data_ptr) = memory.read_u32_be(alias_handle) else {
        *last_mem_error = PPC_NO_ERR;
        return PPC_PARAM_ERR;
    };
    let alias_data_len = u32::try_from(alias_data.len()).unwrap_or(u32::MAX);
    if !ppc_memory_can_write_bytes(memory, data_ptr, alias_data_len) {
        *last_mem_error = PPC_NO_ERR;
        return PPC_PARAM_ERR;
    }
    for (offset, byte) in alias_data.iter().copied().enumerate() {
        if memory.write_u8(data_ptr + offset as u32, byte).is_none() {
            *last_mem_error = PPC_NO_ERR;
            return PPC_PARAM_ERR;
        }
    }
    handles[handle_index].size = alias_data_len;
    if let Some(record) = aliases
        .iter_mut()
        .find(|record| record.handle == alias_handle)
    {
        record.target_vref = target_vref;
        record.target_dir_id = target_dir_id;
        record.target_name = target_name;
    } else {
        aliases.push(PpcAliasRecord {
            handle: alias_handle,
            target_vref,
            target_dir_id,
            target_name,
        });
    }
    if memory.write_u8(was_changed_ptr, 1).is_none() {
        *last_mem_error = PPC_NO_ERR;
        return PPC_PARAM_ERR;
    }
    *last_mem_error = PPC_NO_ERR;
    PPC_NO_ERR
}

fn ppc_resolve_alias_file(
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    vfs_directories: &[PpcVfsDirectory],
    vfs_files: &[PpcVfsFileRecord],
    vfs_resource_files: &[PpcVfsResourceFileRecord],
    vfs_resources: &[PpcVfsResourceRecord],
) -> i16 {
    let spec_ptr = cpu.gpr[3];
    let _resolve_alias_chains = cpu.gpr[4] != 0;
    let target_is_folder_ptr = cpu.gpr[5];
    let was_aliased_ptr = cpu.gpr[6];
    if target_is_folder_ptr == 0 || was_aliased_ptr == 0 {
        return PPC_PARAM_ERR;
    }
    let path = match ppc_path_for_fsspec(memory, vfs_directories, spec_ptr) {
        Ok(path) => path,
        Err(err) => return err,
    };
    let target_is_folder = ppc_directory_id_for_path(vfs_directories, &path).is_some();
    let known_file = target_is_folder
        || ppc_vfs_file_index(vfs_files, &path).is_some()
        || ppc_vfs_resource_file_index(vfs_resource_files, &path).is_some();
    if !known_file {
        return PPC_FNF_ERR;
    }
    if !ppc_memory_can_write_bytes(memory, target_is_folder_ptr, 1)
        || !ppc_memory_can_write_bytes(memory, was_aliased_ptr, 1)
    {
        return PPC_PARAM_ERR;
    }
    if let Some(alias) = ppc_alias_record_for_path(vfs_directories, vfs_resources, &path) {
        if !ppc_memory_can_write_bytes(memory, spec_ptr, PPC_FSSPEC_SIZE as u32) {
            return PPC_PARAM_ERR;
        }
        let target_exists = ppc_fsspec_target_exists(
            vfs_directories,
            vfs_files,
            vfs_resource_files,
            alias.target_dir_id,
            &alias.target_name,
        );
        let target_is_folder =
            ppc_fsspec_target_is_folder(vfs_directories, alias.target_dir_id, &alias.target_name);
        if !ppc_write_fsspec_parts(
            memory,
            spec_ptr,
            alias.target_vref,
            alias.target_dir_id,
            &alias.target_name,
        ) || memory
            .write_u8(target_is_folder_ptr, u8::from(target_is_folder))
            .is_none()
            || memory.write_u8(was_aliased_ptr, 1).is_none()
        {
            return PPC_PARAM_ERR;
        }
        return if target_exists {
            PPC_NO_ERR
        } else {
            PPC_FNF_ERR
        };
    }
    if memory
        .write_u8(target_is_folder_ptr, u8::from(target_is_folder))
        .is_none()
        || memory.write_u8(was_aliased_ptr, 0).is_none()
    {
        return PPC_PARAM_ERR;
    }
    PPC_NO_ERR
}

fn ppc_alias_record_for_path(
    vfs_directories: &[PpcVfsDirectory],
    vfs_resources: &[PpcVfsResourceRecord],
    path: &str,
) -> Option<PpcAliasRecord> {
    vfs_resources
        .iter()
        .filter(|resource| {
            resource.path.eq_ignore_ascii_case(path) && resource.res_type == PPC_ALIAS_RECORD_MAGIC
        })
        .min_by_key(|resource| (u8::from(resource.res_id != 0), resource.res_id))
        .and_then(|resource| ppc_alias_record_from_bytes(&resource.data, Some(vfs_directories)))
}

fn ppc_fsspec_target_is_folder(
    vfs_directories: &[PpcVfsDirectory],
    dir_id: u32,
    name_bytes: &[u8],
) -> bool {
    if name_bytes.is_empty() {
        return ppc_directory_path_for_id(vfs_directories, dir_id).is_some();
    }
    let Some(parent_path) = ppc_directory_path_for_id(vfs_directories, dir_id) else {
        return false;
    };
    let normalized_name = ppc_normalize_vfs_path(&decode_mac_roman(name_bytes));
    if normalized_name.is_empty() {
        return false;
    }
    let path = ppc_join_vfs_path(parent_path, &normalized_name);
    ppc_directory_id_for_path(vfs_directories, &path).is_some()
}

fn ppc_resolve_directory_id(vref: i16, dir_id: u32, default_dir_id: u32) -> u32 {
    if dir_id <= 1 {
        if dir_id == 0 && vref == 0 {
            return default_dir_id;
        }
        if dir_id == 0 {
            return PPC_ROOT_DIR_ID;
        }
        return dir_id;
    }
    dir_id
}

fn ppc_resolve_volume_ref_num(vref: i16) -> i16 {
    if vref == 0 {
        PPC_BOOT_VOLUME_REF_NUM
    } else {
        vref
    }
}

fn ppc_read_pstring(memory: &mut PpcSectionMem, addr: u32) -> Option<String> {
    Some(decode_mac_roman(&ppc_read_pstring_bytes(memory, addr)?))
}

fn ppc_equal_string(cpu: &PpcCpu, memory: &mut PpcSectionMem) -> u32 {
    let a_ptr = cpu.gpr[3];
    let b_ptr = cpu.gpr[4];
    let case_sensitive = (cpu.gpr[5] & 0xff) != 0;
    let _diac_sensitive = (cpu.gpr[6] & 0xff) != 0;
    let Some(a_bytes) = ppc_read_pstring_bytes(memory, a_ptr) else {
        return 0;
    };
    let Some(b_bytes) = ppc_read_pstring_bytes(memory, b_ptr) else {
        return 0;
    };
    let equal = if case_sensitive {
        a_bytes == b_bytes
    } else {
        a_bytes.eq_ignore_ascii_case(&b_bytes)
    };

    if ppc_hle_trace_enabled() {
        eprintln!(
            "[PPC-TRACE] EqualString a={:?} b={:?} case_sensitive={} -> {}",
            decode_mac_roman(&a_bytes),
            decode_mac_roman(&b_bytes),
            case_sensitive,
            equal
        );
    }

    u32::from(equal)
}

fn ppc_read_pstring_bytes(memory: &mut PpcSectionMem, addr: u32) -> Option<Vec<u8>> {
    let len = memory.read_u8(addr)? as usize;
    let mut bytes = Vec::with_capacity(len);
    for offset in 0..len {
        bytes.push(memory.read_u8(addr.checked_add(1 + offset as u32)?)?);
    }
    Some(bytes)
}

fn ppc_normalize_vfs_path(name: &str) -> String {
    name.replace(':', "/")
        .split('/')
        .filter(|part| !part.is_empty() && *part != ".")
        .collect::<Vec<_>>()
        .join("/")
}

fn ppc_join_vfs_path(parent_path: &str, child_name: &str) -> String {
    if parent_path.is_empty() {
        child_name.to_string()
    } else {
        format!("{parent_path}/{child_name}")
    }
}

fn ppc_directory_path_for_id(vfs_directories: &[PpcVfsDirectory], dir_id: u32) -> Option<&str> {
    vfs_directories
        .iter()
        .find(|directory| directory.dir_id == dir_id)
        .map(|directory| directory.path.as_str())
}

fn ppc_directory_id_for_path(vfs_directories: &[PpcVfsDirectory], path: &str) -> Option<u32> {
    vfs_directories
        .iter()
        .find(|directory| directory.path.eq_ignore_ascii_case(path))
        .map(|directory| directory.dir_id)
}

fn ppc_heap_alloc(
    memory: &mut PpcSectionMem,
    heap_cursor: &mut u32,
    heap_limit: u32,
    size: u32,
    clear: bool,
) -> u32 {
    let Some(aligned) = ppc_allocation_size(size) else {
        return 0;
    };
    let Some((ptr, next)) = ppc_heap_allocation_bounds(memory, *heap_cursor, heap_limit, aligned)
    else {
        return 0;
    };
    if ppc_memory_can_read_bytes(memory, ptr, aligned) {
        if clear {
            for offset in 0..aligned {
                let _ = memory.write_u8(ptr + offset, 0);
            }
        }
    } else {
        memory.add_region(ptr, vec![0u8; aligned as usize]);
    }
    *heap_cursor = next;
    ppc_update_zone_free_bytes(memory, next, heap_limit);
    ptr
}

fn ppc_process_heap_alloc(
    memory_manager: &mut ProcessNativeMemoryManager,
    memory: &mut PpcSectionMem,
    heap_cursor: &mut u32,
    size: u32,
    clear: bool,
) -> u32 {
    let ptr = memory_manager.reserve_native_bytes(memory, size, clear);
    if let Some(heap) = memory_manager.native_heap_state() {
        *heap_cursor = heap.heap_cursor;
        let allocation_limit = memory_manager.native_allocation_limit(heap.heap_limit);
        ppc_update_zone_free_bytes(memory, heap.heap_cursor, allocation_limit);
    }
    ptr
}

#[allow(clippy::too_many_arguments)]
fn ppc_process_alloc_handle_with_bytes(
    memory_manager: &mut ProcessNativeMemoryManager,
    memory: &mut PpcSectionMem,
    heap_cursor: &mut u32,
    last_mem_error: &mut i16,
    handles: &mut Vec<PpcHandleRecord>,
    bytes: &[u8],
) -> u32 {
    let handle = memory_manager.copy_bytes_to_new_native_handle(memory, bytes);
    ppc_apply_process_native_resource_handle(
        memory_manager,
        memory,
        heap_cursor,
        last_mem_error,
        handles,
        handle,
    );
    handle
}

#[allow(clippy::too_many_arguments)]
fn ppc_process_alloc_handle(
    memory_manager: &mut ProcessNativeMemoryManager,
    memory: &mut PpcSectionMem,
    heap_cursor: &mut u32,
    last_mem_error: &mut i16,
    handles: &mut Vec<PpcHandleRecord>,
    size: u32,
    clear: bool,
) -> u32 {
    let handle = memory_manager.new_native_handle(memory, size, clear);
    ppc_apply_process_native_resource_handle(
        memory_manager,
        memory,
        heap_cursor,
        last_mem_error,
        handles,
        handle,
    );
    handle
}

struct PpcProcessAllocatorView<'a> {
    memory_manager: &'a mut ProcessNativeMemoryManager,
}

impl PpcProcessAllocatorView<'_> {
    fn reserve_bytes(
        &mut self,
        memory: &mut PpcSectionMem,
        heap_cursor: &mut u32,
        size: u32,
        clear: bool,
    ) -> u32 {
        ppc_process_heap_alloc(self.memory_manager, memory, heap_cursor, size, clear)
    }

    fn allocate_handle(
        &mut self,
        memory: &mut PpcSectionMem,
        heap_cursor: &mut u32,
        last_mem_error: &mut i16,
        handles: &mut Vec<PpcHandleRecord>,
        size: u32,
        clear: bool,
    ) -> u32 {
        ppc_process_alloc_handle(
            self.memory_manager,
            memory,
            heap_cursor,
            last_mem_error,
            handles,
            size,
            clear,
        )
    }

    fn allocate_handle_with_bytes(
        &mut self,
        memory: &mut PpcSectionMem,
        heap_cursor: &mut u32,
        last_mem_error: &mut i16,
        handles: &mut Vec<PpcHandleRecord>,
        bytes: &[u8],
    ) -> u32 {
        ppc_process_alloc_handle_with_bytes(
            self.memory_manager,
            memory,
            heap_cursor,
            last_mem_error,
            handles,
            bytes,
        )
    }

    fn resize_handle(
        &mut self,
        memory: &mut PpcSectionMem,
        heap_cursor: &mut u32,
        last_mem_error: &mut i16,
        handles: &mut Vec<PpcHandleRecord>,
        handle: u32,
        size: u32,
    ) -> i16 {
        let result = self
            .memory_manager
            .set_native_handle_size(memory, handle, size);
        ppc_apply_process_native_resource_handle(
            self.memory_manager,
            memory,
            heap_cursor,
            last_mem_error,
            handles,
            handle,
        );
        result
    }

    fn dispose_handle(
        &mut self,
        memory: &mut PpcSectionMem,
        heap_cursor: &mut u32,
        heap_limit: u32,
        last_mem_error: &mut i16,
        handles: &mut Vec<PpcHandleRecord>,
        handle: u32,
    ) -> bool {
        ppc_dispose_process_native_handle(
            self.memory_manager,
            memory,
            heap_cursor,
            heap_limit,
            last_mem_error,
            handles,
            handle,
        )
    }
}

fn ppc_allocator_view_reserve_bytes(
    allocator: Option<&mut PpcProcessAllocatorView<'_>>,
    memory: &mut PpcSectionMem,
    heap_cursor: &mut u32,
    heap_limit: u32,
    size: u32,
    clear: bool,
) -> u32 {
    if let Some(allocator) = allocator {
        allocator.reserve_bytes(memory, heap_cursor, size, clear)
    } else {
        ppc_heap_alloc(memory, heap_cursor, heap_limit, size, clear)
    }
}

#[allow(clippy::too_many_arguments)]
fn ppc_allocator_view_allocate_handle(
    allocator: Option<&mut PpcProcessAllocatorView<'_>>,
    memory: &mut PpcSectionMem,
    heap_cursor: &mut u32,
    heap_limit: u32,
    last_mem_error: &mut i16,
    handles: &mut Vec<PpcHandleRecord>,
    size: u32,
    clear: bool,
) -> u32 {
    if let Some(allocator) = allocator {
        allocator.allocate_handle(memory, heap_cursor, last_mem_error, handles, size, clear)
    } else {
        ppc_alloc_handle(memory, heap_cursor, heap_limit, handles, size, clear)
    }
}

#[allow(clippy::too_many_arguments)]
fn ppc_allocator_view_allocate_handle_with_bytes(
    allocator: Option<&mut PpcProcessAllocatorView<'_>>,
    memory: &mut PpcSectionMem,
    heap_cursor: &mut u32,
    heap_limit: u32,
    last_mem_error: &mut i16,
    handles: &mut Vec<PpcHandleRecord>,
    bytes: &[u8],
) -> u32 {
    if let Some(allocator) = allocator {
        allocator.allocate_handle_with_bytes(memory, heap_cursor, last_mem_error, handles, bytes)
    } else {
        ppc_alloc_handle_with_bytes(memory, heap_cursor, heap_limit, handles, bytes)
    }
}

#[allow(clippy::too_many_arguments)]
fn ppc_allocator_view_resize_handle(
    allocator: Option<&mut PpcProcessAllocatorView<'_>>,
    memory: &mut PpcSectionMem,
    heap_cursor: &mut u32,
    heap_limit: u32,
    last_mem_error: &mut i16,
    handles: &mut Vec<PpcHandleRecord>,
    handle: u32,
    size: u32,
) -> i16 {
    if let Some(allocator) = allocator {
        allocator.resize_handle(memory, heap_cursor, last_mem_error, handles, handle, size)
    } else {
        ppc_set_handle_size(memory, heap_cursor, heap_limit, handles, handle, size)
    }
}

#[allow(clippy::too_many_arguments)]
fn ppc_allocator_view_dispose_handle(
    allocator: Option<&mut PpcProcessAllocatorView<'_>>,
    memory: &mut PpcSectionMem,
    heap_cursor: &mut u32,
    heap_limit: u32,
    last_mem_error: &mut i16,
    handles: &mut Vec<PpcHandleRecord>,
    legacy_handle_states: Option<&mut Vec<PpcHandleStateRecord>>,
    handle: u32,
) -> bool {
    if let Some(allocator) = allocator {
        allocator.dispose_handle(
            memory,
            heap_cursor,
            heap_limit,
            last_mem_error,
            handles,
            handle,
        )
    } else {
        ppc_dispose_tracked_handle(
            handle,
            memory,
            handles,
            legacy_handle_states.expect("legacy handle disposal requires handle state"),
        )
    }
}

fn ppc_heap_allocation_bounds(
    memory: &PpcSectionMem,
    heap_cursor: u32,
    heap_limit: u32,
    aligned_size: u32,
) -> Option<(u32, u32)> {
    // The native bump heap shares one guest address space with runner-owned
    // system code. Treat both its staged exclusion and live read-only mapping
    // as a reserved hole so a successful Memory Manager call never returns
    // storage whose writes the Trap Manager topology must reject.
    ppc_aligned_heap_allocation_bounds(
        memory,
        heap_cursor,
        heap_limit,
        aligned_size,
        PPC_HEAP_ALIGNMENT,
    )
}

fn ppc_aligned_heap_allocation_bounds(
    memory: &PpcSectionMem,
    heap_cursor: u32,
    heap_limit: u32,
    size: u32,
    alignment: u32,
) -> Option<(u32, u32)> {
    let mut ptr = align_up(heap_cursor, alignment).ok()?;
    loop {
        let next = ptr.checked_add(size)?;
        if next >= heap_limit {
            return None;
        }
        let Some(reserved_end) = memory.readonly_allocation_overlap_end(ptr, size) else {
            return Some((ptr, next));
        };
        ptr = align_up(reserved_end, alignment).ok()?;
    }
}

fn ppc_seed_zone_header(
    memory: &mut PpcSectionMem,
    zone: u32,
    heap_base: u32,
    heap_limit: u32,
    more_masters: u16,
) {
    // Inside Macintosh: Memory (1992), pp. 2-19--2-21, specifies the classic
    // Zone record through heapData. Universal Interfaces MacMemory.h refines
    // the former maxNRel field at byte 30 into heapType: k32BitHeap is bit 0
    // and kNewStyleHeap (the PowerPC Modern Memory Manager) is bit 1.
    let free_bytes = ppc_heap_free_capacity(memory, heap_base, heap_limit).0;
    let _ = memory.write_u32_be(zone, heap_limit); // bkLim
    let _ = memory.write_u32_be(zone + 4, 0); // purgePtr
    let _ = memory.write_u32_be(zone + 8, 0); // hFstFree
    let _ = memory.write_u32_be(zone + 12, free_bytes); // zcbFree
    let _ = memory.write_u32_be(zone + 16, 0); // gzProc
    let _ = memory.write_u16_be(zone + 20, more_masters); // moreMast
    let _ = memory.write_u16_be(zone + 22, 0); // flags
    let _ = memory.write_u16_be(zone + 24, 0); // cntRel
    let _ = memory.write_u16_be(zone + 26, 0); // maxRel
    let _ = memory.write_u16_be(zone + 28, 0); // cntNRel
    let _ = memory.write_u8(
        zone + PPC_ZONE_HEAP_TYPE_OFFSET,
        PPC_ZONE_32_BIT_HEAP | PPC_ZONE_NEW_STYLE_HEAP,
    );
    let _ = memory.write_u8(zone + PPC_ZONE_HEAP_TYPE_OFFSET + 1, 0);
    let _ = memory.write_u16_be(zone + 32, 0); // cntEmpty
    let _ = memory.write_u16_be(zone + 34, 0); // cntHandles
    let _ = memory.write_u32_be(zone + 36, free_bytes); // minCBFree
    let _ = memory.write_u32_be(zone + 40, 0); // purgeProc
    let _ = memory.write_u32_be(zone + 44, 0); // sparePtr
    let _ = memory.write_u32_be(zone + 48, heap_base); // allocPtr
    let _ = memory.write_u16_be(zone + 52, 0); // heapData
}

fn ppc_update_zone_free_bytes(memory: &mut PpcSectionMem, heap_cursor: u32, heap_limit: u32) {
    let free_bytes = ppc_heap_free_capacity(memory, heap_cursor, heap_limit).0;
    let _ = memory.write_u32_be(PPC_APPLICATION_ZONE + 12, free_bytes);
    let _ = memory.write_u32_be(PPC_SYSTEM_ZONE + 12, free_bytes);
}

#[allow(clippy::too_many_arguments)]
fn ppc_allocator_view_replace_handle_bytes(
    allocator: Option<&mut PpcProcessAllocatorView<'_>>,
    memory: &mut PpcSectionMem,
    heap_cursor: &mut u32,
    heap_limit: u32,
    last_mem_error: &mut i16,
    handles: &mut Vec<PpcHandleRecord>,
    handle: u32,
    bytes: &[u8],
) -> i16 {
    let Ok(size) = u32::try_from(bytes.len()) else {
        return PPC_MEM_FULL_ERR;
    };
    let result = ppc_allocator_view_resize_handle(
        allocator,
        memory,
        heap_cursor,
        heap_limit,
        last_mem_error,
        handles,
        handle,
        size,
    );
    if result != PPC_NO_ERR {
        return result;
    }
    let Some(ptr) = memory.read_u32_be(handle).filter(|ptr| *ptr != 0) else {
        return PPC_NIL_HANDLE_ERR;
    };
    if memory.write_bytes(ptr, bytes).is_none() {
        return PPC_PARAM_ERR;
    }
    PPC_NO_ERR
}

#[cfg(test)]
fn ppc_alloc_ptr(
    memory: &mut PpcSectionMem,
    heap_cursor: &mut u32,
    heap_limit: u32,
    ptrs: &mut Vec<PpcPtrRecord>,
    free_ptr_blocks: &mut Vec<PpcPtrRecord>,
    size: u32,
    clear: bool,
) -> u32 {
    let required = match ppc_allocation_size(size) {
        Some(required) => required,
        None => return 0,
    };
    let reusable_index = free_ptr_blocks
        .iter()
        .enumerate()
        .filter_map(|(index, record)| {
            let capacity = ppc_allocation_size(record.size)?;
            (capacity >= required).then_some((index, capacity))
        })
        .min_by_key(|(_, capacity)| *capacity)
        .map(|(index, _)| index);
    let ptr = if let Some(index) = reusable_index {
        free_ptr_blocks.swap_remove(index).ptr
    } else {
        ppc_heap_alloc(memory, heap_cursor, heap_limit, size, false)
    };
    if ptr == 0 {
        return 0;
    }
    if clear {
        for offset in 0..required {
            if memory.write_u8(ptr + offset, 0).is_none() {
                return 0;
            }
        }
    }
    // Inside Macintosh: Memory (1992), pp. 2-42 and 2-44: DisposePtr
    // returns a nonrelocatable block to the application heap for later use.
    ptrs.push(PpcPtrRecord { ptr, size });
    ptr
}

#[allow(clippy::too_many_arguments)]
fn ppc_dispatch_legacy_memory_utility(
    binding: &PpcImportBinding,
    cpu: &mut PpcCpu,
    process_memory_manager: &ProcessNativeMemoryManager,
    memory: &mut PpcSectionMem,
    heap_cursor: &mut u32,
    heap_limit: u32,
    last_mem_error: &mut i16,
    handles: &[PpcHandleRecord],
) -> Option<PpcImportAction> {
    let free_ptr_blocks = process_memory_manager.native_free_ptr_blocks();
    // Inside Macintosh: Operating System Utilities (1994), pp. 3-28--3-29,
    // and Memory (1992), pp. 2-42--2-83, define these routines independently
    // of any application. Keeping their implementations in one dispatcher is
    // only an ABI grouping; behavior is selected solely by the imported API.
    match binding.symbol_name.as_str() {
        "BitNot" => Some(PpcImportAction::Return(!cpu.gpr[3])),
        "BitSet" | "BitClr" => {
            let bit_number = cpu.gpr[4];
            let byte_addr = cpu.gpr[3].checked_add(bit_number / 8)?;
            let mask = 0x80u8 >> (bit_number & 7);
            let old = memory.read_u8(byte_addr)?;
            let value = if binding.symbol_name == "BitSet" {
                old | mask
            } else {
                old & !mask
            };
            memory.write_u8(byte_addr, value)?;
            Some(PpcImportAction::ReturnPreserve)
        }
        "Fix2X" => {
            let fixed = cpu.gpr[3] as i32;
            cpu.fpr[1] = (f64::from(fixed) / 65_536.0).to_bits();
            Some(PpcImportAction::ReturnPreserve)
        }
        "GetMyZone" => Some(PpcImportAction::Return(PPC_APPLICATION_ZONE)),
        "HandleZone" => {
            let handle = cpu.gpr[3];
            let valid = handle == 0 || handles.iter().any(|record| record.handle == handle);
            *last_mem_error = if valid { PPC_NO_ERR } else { -111 };
            Some(PpcImportAction::Return(if valid {
                PPC_APPLICATION_ZONE
            } else {
                0
            }))
        }
        "LockMemory" | "UnlockMemory" => {
            // The native heap is resident host memory, so a valid mapped range
            // is already immovable for the lifetime requested by the caller.
            let start = cpu.gpr[3];
            let len = cpu.gpr[4];
            let mapped = len == 0
                || (start != 0
                    && memory.read_u8(start).is_some()
                    && start
                        .checked_add(len - 1)
                        .and_then(|end| memory.read_u8(end))
                        .is_some());
            let result = if mapped { PPC_NO_ERR } else { PPC_PARAM_ERR };
            Some(PpcImportAction::Return(ppc_i16_result(result)))
        }
        "MaxBlock" => Some(PpcImportAction::Return(ppc_largest_free_ptr_block(
            memory,
            *heap_cursor,
            heap_limit,
            free_ptr_blocks,
        ))),
        "PurgeSpace" => {
            let total = ppc_heap_free_capacity(memory, *heap_cursor, heap_limit)
                .0
                .saturating_add(
                    free_ptr_blocks
                        .iter()
                        .filter(|block| ppc_free_ptr_block_fits_limit(block, heap_limit))
                        .fold(0u32, |sum, block| sum.saturating_add(block.size)),
                );
            let contiguous =
                ppc_largest_free_ptr_block(memory, *heap_cursor, heap_limit, free_ptr_blocks);
            if cpu.gpr[3] != 0 {
                memory.write_u32_be(cpu.gpr[3], total)?;
            }
            if cpu.gpr[4] != 0 {
                memory.write_u32_be(cpu.gpr[4], contiguous)?;
            }
            Some(PpcImportAction::ReturnPreserve)
        }
        "SetGrowZone" => {
            memory.write_u32_be(PPC_APPLICATION_ZONE + 16, cpu.gpr[3])?;
            Some(PpcImportAction::ReturnPreserve)
        }
        "StackSpace" => Some(PpcImportAction::Return(
            cpu.gpr[1].saturating_sub(
                process_memory_manager.application_heap_limit(heap_limit),
            ),
        )),
        "TempFreeMem" => Some(PpcImportAction::Return(
            ppc_heap_free_capacity(memory, *heap_cursor, heap_limit).0,
        )),
        _ => None,
    }
}

fn ppc_largest_free_ptr_block(
    memory: &PpcSectionMem,
    heap_cursor: u32,
    heap_limit: u32,
    free_ptr_blocks: &[PpcPtrRecord],
) -> u32 {
    free_ptr_blocks
        .iter()
        .filter(|record| ppc_free_ptr_block_fits_limit(record, heap_limit))
        .map(|record| record.size)
        .max()
        .unwrap_or(0)
        .max(ppc_heap_free_capacity(memory, heap_cursor, heap_limit).1)
}

fn ppc_free_ptr_block_fits_limit(record: &ProcessPtrRecord, heap_limit: u32) -> bool {
    ppc_allocation_size(record.size)
        .and_then(|capacity| record.ptr.checked_add(capacity))
        .is_some_and(|end| end <= heap_limit)
}

fn ppc_memory_can_write_bytes(memory: &mut PpcSectionMem, addr: u32, len: u32) -> bool {
    memory.preflight_writable_range(addr, len)
}

fn ppc_init_zone_header(
    memory: &mut PpcSectionMem,
    start: u32,
    limit: u32,
    more_masters_raw: u16,
    grow_zone: u32,
) {
    const ZONE_HEADER_SIZE: u32 = 52;

    let Some(header_end) = start.checked_add(ZONE_HEADER_SIZE) else {
        return;
    };
    if limit < header_end || !ppc_memory_can_write_bytes(memory, start, ZONE_HEADER_SIZE) {
        return;
    }

    let more_masters = i16::from_be_bytes(more_masters_raw.to_be_bytes()).max(0) as u32;
    let free_bytes = limit
        .saturating_sub(start)
        .saturating_sub(72 + (4 * more_masters));
    let first_master_ptr = if more_masters == 0 {
        0
    } else {
        start.wrapping_add(60)
    };

    let _ = memory.write_u32_be(start, limit); // bkLim
    let _ = memory.write_u32_be(start + 4, 0); // purgePtr
    let _ = memory.write_u32_be(start + 8, first_master_ptr); // hFstFree
    let _ = memory.write_u32_be(start + 12, free_bytes); // zcbFree
    let _ = memory.write_u32_be(start + 16, grow_zone); // gzProc
    let _ = memory.write_u16_be(start + 20, more_masters_raw); // moreMast
    let _ = memory.write_u16_be(start + 22, 0); // flags
    let _ = memory.write_u16_be(start + 24, 0); // cntRel
    let _ = memory.write_u16_be(start + 26, 0); // maxRel
    let _ = memory.write_u16_be(start + 28, 0); // cntNRel
    let _ = memory.write_u16_be(start + 30, 0); // maxNRel
    let _ = memory.write_u16_be(start + 32, 0); // cntEmpty
    let _ = memory.write_u16_be(start + 34, 0); // cntHandles
    let _ = memory.write_u32_be(start + 36, free_bytes); // minCBFree
    let _ = memory.write_u32_be(start + 40, 0); // purgeProc
    let _ = memory.write_u32_be(start + 44, 0); // sparePtr
    let _ = memory.write_u32_be(start + 48, start + ZONE_HEADER_SIZE); // allocPtr
    let _ = memory.write_u32_be(PPC_THE_ZONE_ADDR, start);
}

fn dispatch_getkeys_import(
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    input: PpcInputSnapshot,
    idle_poll_counts: Option<&mut HashMap<u32, u32>>,
) -> PpcImportAction {
    let key_map_ptr = cpu.gpr[3];
    if key_map_ptr != 0 {
        let _ = memory.write_bytes(key_map_ptr, &input.key_map[..PPC_KEY_MAP_SIZE as usize]);
    }
    let Some(idle_poll_counts) = idle_poll_counts else {
        return PpcImportAction::ReturnPreserve;
    };
    if input.key_map.iter().any(|byte| *byte != 0) || cpu.lr == 0 {
        idle_poll_counts.clear();
        return PpcImportAction::ReturnPreserve;
    }
    let count = idle_poll_counts.entry(cpu.lr).or_default();
    *count = count.saturating_add(1);
    if *count > PPC_GETKEYS_IDLE_POLL_FAST_FORWARD_THRESHOLD {
        PpcImportAction::ReturnPreserveWithExtraCycles(PPC_GETKEYS_IDLE_POLL_EXTRA_CYCLES)
    } else {
        PpcImportAction::ReturnPreserve
    }
}

fn dispatch_button_import(
    cpu: &PpcCpu,
    input: PpcInputSnapshot,
    idle_poll_counts: Option<&mut HashMap<u32, u32>>,
) -> PpcImportAction {
    let result = u32::from(input.mouse_button);
    let Some(idle_poll_counts) = idle_poll_counts else {
        return PpcImportAction::Return(result);
    };
    if input.mouse_button || cpu.lr == 0 {
        idle_poll_counts.clear();
        return PpcImportAction::Return(result);
    }
    let count = idle_poll_counts.entry(cpu.lr).or_default();
    *count = count.saturating_add(1);
    if *count > PPC_BUTTON_IDLE_POLL_FAST_FORWARD_THRESHOLD {
        PpcImportAction::ReturnWithExtraCycles(result, PPC_BUTTON_IDLE_POLL_EXTRA_CYCLES)
    } else {
        PpcImportAction::Return(result)
    }
}

fn dispatch_still_down_import(
    cpu: &PpcCpu,
    input: PpcInputSnapshot,
    event_queue: &VecDeque<PpcQueuedEvent>,
    idle_poll_counts: Option<&mut HashMap<u32, u32>>,
) -> PpcImportAction {
    let has_pending_mouse_event = event_queue.iter().any(|event| matches!(event.what, 1 | 2));
    let result = u32::from(input.mouse_button && !has_pending_mouse_event);
    let Some(idle_poll_counts) = idle_poll_counts else {
        return PpcImportAction::Return(result);
    };
    if result != 0 || cpu.lr == 0 {
        idle_poll_counts.clear();
        return PpcImportAction::Return(result);
    }
    let count = idle_poll_counts.entry(cpu.lr).or_default();
    *count = count.saturating_add(1);
    if *count > PPC_BUTTON_IDLE_POLL_FAST_FORWARD_THRESHOLD {
        PpcImportAction::ReturnWithExtraCycles(result, PPC_BUTTON_IDLE_POLL_EXTRA_CYCLES)
    } else {
        PpcImportAction::Return(result)
    }
}

fn dispatch_microseconds_import(
    cpu: &PpcCpu,
    memory: &mut PpcSectionMem,
    microseconds: u64,
    idle_poll_counts: Option<&mut HashMap<u32, u32>>,
) -> PpcImportAction {
    // Microseconds
    // Returns the number of microseconds elapsed since system startup.
    // PROCEDURE Microseconds (VAR microTickCount: UnsignedWide);
    // Inside Macintosh: Operating System Utilities (1994), p. 4-49.
    ppc_write_microseconds_value(cpu, memory, microseconds);
    let Some(idle_poll_counts) = idle_poll_counts else {
        return PpcImportAction::ReturnPreserve;
    };
    if cpu.lr == 0 {
        idle_poll_counts.clear();
        return PpcImportAction::ReturnPreserve;
    }
    let count = idle_poll_counts.entry(cpu.lr).or_default();
    *count = count.saturating_add(1);
    if *count > PPC_MICROSECONDS_IDLE_POLL_FAST_FORWARD_THRESHOLD {
        // A repeated caller within one execution slice is polling elapsed
        // time rather than sampling an application event. Charge equivalent
        // guest cycles so the clock remains monotonic without interpreting
        // thousands of iterations of the wait loop.
        PpcImportAction::ReturnPreserveWithExtraCycles(PPC_MICROSECONDS_IDLE_POLL_EXTRA_CYCLES)
    } else {
        PpcImportAction::ReturnPreserve
    }
}

fn ppc_memory_can_read_bytes(memory: &mut PpcSectionMem, addr: u32, len: u32) -> bool {
    for offset in 0..len {
        let Some(byte_addr) = addr.checked_add(offset) else {
            return false;
        };
        if memory.read_u8(byte_addr).is_none() {
            return false;
        }
    }
    true
}

fn ppc_memory_read_bytes(memory: &mut PpcSectionMem, addr: u32, len: u32) -> Option<Vec<u8>> {
    let mut bytes = Vec::with_capacity(usize::try_from(len).ok()?);
    for offset in 0..len {
        bytes.push(memory.read_u8(addr.checked_add(offset)?)?);
    }
    Some(bytes)
}

fn ppc_optional_output_can_write(memory: &mut PpcSectionMem, addr: u32, len: u32) -> bool {
    addr == 0 || ppc_memory_can_write_bytes(memory, addr, len)
}

fn ppc_optional_pstring_output_can_write(
    memory: &mut PpcSectionMem,
    addr: u32,
    bytes: &[u8],
) -> bool {
    let len = bytes.len().min(255) as u32;
    addr == 0 || ppc_memory_can_write_bytes(memory, addr, len + 1)
}

fn ppc_heap_can_alloc_sequence(
    memory: &PpcSectionMem,
    heap_cursor: u32,
    heap_limit: u32,
    sizes: &[u32],
) -> bool {
    let mut simulated_cursor = heap_cursor;
    for size in sizes {
        let Some(aligned_size) = ppc_allocation_size(*size) else {
            return false;
        };
        let Some((_, next)) =
            ppc_heap_allocation_bounds(memory, simulated_cursor, heap_limit, aligned_size)
        else {
            return false;
        };
        simulated_cursor = next;
    }
    true
}

fn ppc_heap_can_alloc_repeated(
    memory: &PpcSectionMem,
    heap_cursor: u32,
    heap_limit: u32,
    size: u32,
    count: u32,
) -> bool {
    let Some(aligned_size) = ppc_allocation_size(size) else {
        return false;
    };
    let mut simulated_cursor = heap_cursor;
    for _ in 0..count {
        let Some((_, next)) =
            ppc_heap_allocation_bounds(memory, simulated_cursor, heap_limit, aligned_size)
        else {
            return false;
        };
        simulated_cursor = next;
    }
    true
}

#[cfg(test)]
fn ppc_heap_allocation_sequence_size(sizes: &[u32]) -> Option<u32> {
    sizes.iter().try_fold(0u32, |total_size, size| {
        total_size.checked_add(ppc_allocation_size(*size)?)
    })
}

fn ppc_allocation_size(size: u32) -> Option<u32> {
    // The native Power Mac Memory Manager returns NewPtr/NewHandle storage on
    // 16-byte boundaries. Native renderers depend on this stronger guarantee:
    // for example, packed mask blitters derive their starting bit from the low
    // address bits of a PixMap's pixel storage.
    Some(size.checked_add(PPC_HEAP_ALIGNMENT - 1)? & !(PPC_HEAP_ALIGNMENT - 1))
        .map(|size| size.max(PPC_HEAP_ALIGNMENT))
}

fn ppc_heap_free_capacity(memory: &PpcSectionMem, heap_cursor: u32, heap_limit: u32) -> (u32, u32) {
    memory.readonly_allocation_available_bytes(heap_cursor, heap_limit)
}

fn ppc_i16_result(value: i16) -> u32 {
    i32::from(value) as u32
}

fn ppc_run_result_cycles(result: PpcRunResult) -> u64 {
    match result {
        PpcRunResult::CycleLimit { cycles }
        | PpcRunResult::Halted { cycles, .. }
        | PpcRunResult::Unimplemented { cycles, .. }
        | PpcRunResult::MemoryFault { cycles, .. }
        | PpcRunResult::Exception { cycles, .. }
        | PpcRunResult::FetchFault { cycles, .. } => cycles,
    }
}

fn ppc_run_result_with_cycles(result: PpcRunResult, cycles: u64) -> PpcRunResult {
    match result {
        PpcRunResult::CycleLimit { .. } => PpcRunResult::CycleLimit { cycles },
        PpcRunResult::Halted { pc, .. } => PpcRunResult::Halted { pc, cycles },
        PpcRunResult::Unimplemented { pc, error, .. } => {
            PpcRunResult::Unimplemented { pc, error, cycles }
        }
        PpcRunResult::MemoryFault {
            pc,
            addr,
            was_write,
            ..
        } => PpcRunResult::MemoryFault {
            pc,
            addr,
            was_write,
            cycles,
        },
        PpcRunResult::Exception { pc, exception, .. } => PpcRunResult::Exception {
            pc,
            exception,
            cycles,
        },
        PpcRunResult::FetchFault { pc, .. } => PpcRunResult::FetchFault { pc, cycles },
    }
}

fn ppc_native_exception_kind(exception: PpcException) -> Option<u32> {
    match exception {
        PpcException::IllegalInstruction { .. } => Some(PPC_ILLEGAL_INSTRUCTION_EXCEPTION),
        PpcException::ProgramTrap { .. } => Some(PPC_TRAP_EXCEPTION),
        _ => None,
    }
}

fn ppc_native_exception_cause_kind(cause: PpcNativeExceptionCause) -> Option<u32> {
    match cause {
        PpcNativeExceptionCause::Processor(exception) => ppc_native_exception_kind(exception),
        PpcNativeExceptionCause::UnmappedMemory { .. } => Some(PPC_UNMAPPED_MEMORY_EXCEPTION),
    }
}

fn ppc_native_exception_result(context: PpcNativeExceptionContext, cycles: u64) -> PpcRunResult {
    match context.cause {
        PpcNativeExceptionCause::Processor(exception) => PpcRunResult::Exception {
            pc: context.pc,
            exception,
            cycles,
        },
        PpcNativeExceptionCause::UnmappedMemory { address, was_write } => {
            PpcRunResult::MemoryFault {
                pc: context.pc,
                addr: address,
                was_write,
                cycles,
            }
        }
    }
}

fn ppc_write_exception_wide(memory: &mut PpcSectionMem, addr: u32, value: u32) -> Option<()> {
    memory.write_u32_be(addr, 0)?;
    memory.write_u32_be(addr.checked_add(4)?, value)?;
    Some(())
}

fn ppc_read_exception_wide(memory: &mut PpcSectionMem, addr: u32) -> Option<u32> {
    memory.read_u32_be(addr.checked_add(4)?)
}

fn ppc_begin_native_exception(
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    stack_base: u32,
    handler: u32,
    pc: u32,
    cause: PpcNativeExceptionCause,
) -> Option<PpcNativeExceptionContext> {
    let kind = ppc_native_exception_cause_kind(cause)?;
    // InstallExceptionHandler accepts an ExceptionHandlerTPP: a native
    // transition vector containing the entry point and TOC, not a UPP.
    // Inside Macintosh: PowerPC System Software (1994), p. 4-17
    let entry = memory.read_u32_be(handler)?;
    let rtoc = memory.read_u32_be(handler.checked_add(4)?)?;
    if entry == 0 {
        return None;
    }

    let records_size = PPC_EXCEPTION_INFORMATION_SIZE
        .checked_add(PPC_EXCEPTION_MACHINE_INFORMATION_SIZE)?
        .checked_add(PPC_EXCEPTION_REGISTER_INFORMATION_SIZE)?
        .checked_add(PPC_EXCEPTION_FPU_INFORMATION_SIZE)?
        .checked_add(PPC_EXCEPTION_VECTOR_INFORMATION_SIZE)?
        .checked_add(match cause {
            PpcNativeExceptionCause::UnmappedMemory { .. } => PPC_EXCEPTION_MEMORY_INFORMATION_SIZE,
            PpcNativeExceptionCause::Processor(_) => 0,
        })?;
    let frame_and_records = PPC_INITIAL_STACK_FRAME_SIZE.checked_add(records_size)?;
    let callback_sp = cpu.gpr[1]
        .checked_sub(PPC_INTERRUPT_RED_ZONE_SIZE)?
        .checked_sub(frame_and_records)?
        & !0xFu32;
    if callback_sp < stack_base
        || !ppc_memory_can_write_bytes(memory, callback_sp, frame_and_records)
    {
        return None;
    }

    let information = callback_sp.checked_add(PPC_INITIAL_STACK_FRAME_SIZE)?;
    let machine_state = information.checked_add(PPC_EXCEPTION_INFORMATION_SIZE)?;
    let register_image = machine_state.checked_add(PPC_EXCEPTION_MACHINE_INFORMATION_SIZE)?;
    let fpu_image = register_image.checked_add(PPC_EXCEPTION_REGISTER_INFORMATION_SIZE)?;
    let vector_image = fpu_image.checked_add(PPC_EXCEPTION_FPU_INFORMATION_SIZE)?;
    let memory_information = match cause {
        PpcNativeExceptionCause::UnmappedMemory { .. } => {
            Some(vector_image.checked_add(PPC_EXCEPTION_VECTOR_INFORMATION_SIZE)?)
        }
        PpcNativeExceptionCause::Processor(_) => None,
    };
    if !ppc_zero_guest_bytes(memory, callback_sp, frame_and_records) {
        return None;
    }

    // Universal Interfaces 3.4, MachineExceptions.h defines these PowerPC
    // records with 680x0 field alignment. The handler may edit any saved
    // register image; a noErr return restores those edited values.
    memory.write_u32_be(information, kind)?;
    memory.write_u32_be(information + 4, machine_state)?;
    memory.write_u32_be(information + 8, register_image)?;
    memory.write_u32_be(information + 12, fpu_image)?;
    memory.write_u32_be(information + 16, memory_information.unwrap_or(0))?;
    memory.write_u32_be(information + 20, vector_image)?;

    if let (
        PpcNativeExceptionCause::UnmappedMemory { address, was_write },
        Some(memory_information),
    ) = (cause, memory_information)
    {
        // MemoryExceptionInformation describes the affected area, logical
        // address, status, and reference kind. This HLE has one application
        // address space, identified by its nonzero stack-area base.
        // Inside Macintosh: PowerPC System Software (1994), pp. 4-11, 4-15
        memory.write_u32_be(memory_information, stack_base)?;
        memory.write_u32_be(memory_information + 4, address)?;
        memory.write_u32_be(memory_information + 8, PPC_UNMAPPED_MEMORY_ERROR)?;
        memory.write_u32_be(
            memory_information + 12,
            if was_write {
                PPC_WRITE_REFERENCE
            } else {
                PPC_READ_REFERENCE
            },
        )?;
    }

    ppc_write_exception_wide(memory, machine_state, cpu.ctr)?;
    ppc_write_exception_wide(memory, machine_state + 8, cpu.lr)?;
    ppc_write_exception_wide(memory, machine_state + 16, pc)?;
    memory.write_u32_be(machine_state + 24, cpu.cr)?;
    memory.write_u32_be(machine_state + 28, cpu.xer)?;
    memory.write_u32_be(machine_state + 32, cpu.msr)?;
    memory.write_u32_be(machine_state + 40, kind)?;
    for (index, value) in cpu.gpr.iter().copied().enumerate() {
        ppc_write_exception_wide(
            memory,
            register_image.checked_add(u32::try_from(index).ok()?.checked_mul(8)?)?,
            value,
        )?;
    }
    for (index, value) in cpu.fpr.iter().copied().enumerate() {
        memory.write_u64_be(
            fpu_image.checked_add(u32::try_from(index).ok()?.checked_mul(8)?)?,
            value,
        )?;
    }
    memory.write_u32_be(fpu_image + 256, cpu.fpscr)?;

    memory.write_u32_be(callback_sp + PPC_LINKAGE_BACK_CHAIN_OFFSET, cpu.gpr[1])?;
    memory.write_u32_be(callback_sp + PPC_LINKAGE_SAVED_CR_OFFSET, cpu.cr)?;
    memory.write_u32_be(callback_sp + PPC_LINKAGE_SAVED_LR_OFFSET, cpu.lr)?;
    memory.write_u32_be(callback_sp + PPC_LINKAGE_SAVED_RTOC_OFFSET, cpu.gpr[2])?;

    cpu.pc = entry;
    cpu.lr = PPC_HALT_PC;
    cpu.gpr[1] = callback_sp;
    cpu.gpr[2] = rtoc;
    ppc_install_native_call_arguments(cpu, memory, &[information])?;

    Some(PpcNativeExceptionContext {
        cause,
        pc,
        information,
        machine_state,
        register_image,
        fpu_image,
        vector_image,
        memory_information,
    })
}

fn ppc_restore_native_exception(
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    context: PpcNativeExceptionContext,
) -> Option<()> {
    let frame_is_valid = memory.read_u32_be(context.information + 4)? == context.machine_state
        && memory.read_u32_be(context.information + 8)? == context.register_image
        && memory.read_u32_be(context.information + 12)? == context.fpu_image
        && memory.read_u32_be(context.information + 16)? == context.memory_information.unwrap_or(0)
        && memory.read_u32_be(context.information + 20)? == context.vector_image;
    cpu.ctr = ppc_read_exception_wide(memory, context.machine_state)?;
    cpu.lr = ppc_read_exception_wide(memory, context.machine_state + 8)?;
    cpu.pc = ppc_read_exception_wide(memory, context.machine_state + 16)?;
    cpu.cr = memory.read_u32_be(context.machine_state + 24)?;
    cpu.xer = memory.read_u32_be(context.machine_state + 28)?;
    cpu.msr = memory.read_u32_be(context.machine_state + 32)?;
    for index in 0..cpu.gpr.len() {
        cpu.gpr[index] = ppc_read_exception_wide(
            memory,
            context
                .register_image
                .checked_add(u32::try_from(index).ok()?.checked_mul(8)?)?,
        )?;
    }
    for index in 0..cpu.fpr.len() {
        cpu.fpr[index] = memory.read_u64_be(
            context
                .fpu_image
                .checked_add(u32::try_from(index).ok()?.checked_mul(8)?)?,
        )?;
    }
    cpu.fpscr = memory.read_u32_be(context.fpu_image + 256)?;
    frame_is_valid.then_some(())
}

fn ppc_resolve_callback_target(
    memory: &mut PpcSectionMem,
    proc_ptr: u32,
    default_rtoc: u32,
    selector: Option<u32>,
) -> Option<PpcCallbackTarget> {
    let procedure = resolve_guest_procedure(
        memory,
        proc_ptr,
        default_rtoc,
        selector,
        GuestIsa::PowerPc,
        GuestIsa::PowerPc,
    )?;
    (procedure.isa == GuestIsa::PowerPc).then_some(PpcCallbackTarget {
        entry: procedure.entry,
        rtoc: procedure.rtoc,
        proc_info: procedure.proc_info,
        routine_flags: procedure.routine_flags,
    })
}

fn import_addresses(
    bindings: &[PpcImportBinding],
    import_count: usize,
) -> Result<Vec<u32>, PpcLoadError> {
    let mut addrs = vec![0; import_count];
    let symbol_index_base = bindings.first().map_or(0, |binding| binding.symbol_index);
    for binding in bindings {
        let local_index = binding
            .symbol_index
            .checked_sub(symbol_index_base)
            .and_then(|index| usize::try_from(index).ok())
            .ok_or(PpcLoadError::AddressOverflow)?;
        let slot = addrs
            .get_mut(local_index)
            .ok_or(PpcLoadError::AddressOverflow)?;
        *slot = binding.address;
    }
    Ok(addrs)
}

fn import_address_for(index: u32, class: u8) -> Result<u32, PpcLoadError> {
    match class {
        2 => PPC_IMPORT_TVECTOR_BASE
            .checked_add(index.checked_mul(8).ok_or(PpcLoadError::AddressOverflow)?)
            .ok_or(PpcLoadError::AddressOverflow),
        0 | 4 => import_trap_pc(index),
        _ => Ok(0),
    }
}

fn import_data_address_for(library_name: &str, symbol_name: &str) -> Option<u32> {
    match (library_name, symbol_name) {
        ("StdCLib", "_IntEnv") => Some(PPC_IMPORT_DATA_BASE),
        ("StdCLib", "__C_phase") => Some(PPC_IMPORT_DATA_BASE + 0x400),
        ("StdCLib", "__target_for_exit") => Some(PPC_IMPORT_DATA_BASE + 0x404),
        ("StdCLib", "_exit_status") => Some(PPC_IMPORT_DATA_BASE + 0x408),
        ("StdCLib", "_iob") => Some(PPC_STDIO_IOB_ADDR),
        ("StdCLib", "__p_CType") => Some(PPC_IMPORT_CTYPE_POINTER),
        ("StdCLib", "_DBL_EPSILON") => Some(PPC_IMPORT_STD_DBL_EPSILON),
        ("StdCLib", "_DBL_MAX") => Some(PPC_IMPORT_STD_DBL_MAX),
        ("StdCLib", "_DBL_MIN") => Some(PPC_IMPORT_STD_DBL_MIN),
        ("StdCLib", "_FLT_EPSILON") => Some(PPC_IMPORT_STD_FLT_EPSILON),
        ("StdCLib", "_FLT_MAX") => Some(PPC_IMPORT_STD_FLT_MAX),
        ("StdCLib", "_FLT_MIN") => Some(PPC_IMPORT_STD_FLT_MIN),
        ("StdCLib", "errno") => Some(PPC_IMPORT_STD_ERRNO),
        ("StdCLib", "MacOSErr") => Some(PPC_IMPORT_STD_MAC_OS_ERR),
        // PowerPC Numerics exposes `pi` as an addressable MathLib export.
        // Some CFM clients label the import as a transition-vector symbol but
        // dereference it directly as a double, so bind the known export to
        // stable data storage regardless of the PEF class tag.
        ("MathLib", "pi") => Some(PPC_IMPORT_MATH_PI),
        ("MathLib", "_FE_DFL_ENV") => Some(PPC_IMPORT_MATH_FE_DFL_ENV),
        _ => None,
    }
}

fn ppc_seed_import_data(memory: &mut PpcSectionMem) {
    // The Metrowerks runtime imports these as true CFM data symbols, not
    // callable entry points. Give them stable writable storage and point the
    // ctype indirection at a complete 256-entry classification table.
    let _ = memory.write_u32_be(PPC_IMPORT_CTYPE_POINTER, PPC_IMPORT_CTYPE_TABLE);
    let _ = memory.write_u64_be(PPC_IMPORT_MATH_PI, std::f64::consts::PI.to_bits());
    // Inside Macintosh: PowerPC Numerics (1994), Chapter 8 and Appendix C:
    // PowerPC fenv_t is a 32-bit word, with zero selecting round-to-nearest
    // and leaving every floating-point exception flag clear.
    let _ = memory.write_u32_be(PPC_IMPORT_MATH_FE_DFL_ENV, 0);
    // Universal Interfaces 3.4 float.h exposes these values by dereferencing
    // imported StdCLib objects. Seed their exact IEEE single- and
    // double-precision representations in big-endian guest memory.
    let _ = memory.write_u64_be(PPC_IMPORT_STD_DBL_EPSILON, f64::EPSILON.to_bits());
    let _ = memory.write_u64_be(PPC_IMPORT_STD_DBL_MAX, f64::MAX.to_bits());
    let _ = memory.write_u64_be(PPC_IMPORT_STD_DBL_MIN, f64::MIN_POSITIVE.to_bits());
    let _ = memory.write_u32_be(PPC_IMPORT_STD_FLT_EPSILON, f32::EPSILON.to_bits());
    let _ = memory.write_u32_be(PPC_IMPORT_STD_FLT_MAX, f32::MAX.to_bits());
    let _ = memory.write_u32_be(PPC_IMPORT_STD_FLT_MIN, f32::MIN_POSITIVE.to_bits());
    // Universal Interfaces 3.4 errno.h declares StdCLib's writable `errno`
    // as an int and `MacOSErr` as a short. Both begin clear at process launch.
    let _ = memory.write_u32_be(PPC_IMPORT_STD_ERRNO, 0);
    let _ = memory.write_u16_be(PPC_IMPORT_STD_MAC_OS_ERR, 0);
    let _ = memory.write_bytes(
        PPC_STDIO_IOB_ADDR,
        &vec![0; (3 * PPC_STDIO_FILE_SIZE) as usize],
    );
    for byte in 0u16..=255 {
        let _ = memory.write_u8(
            PPC_IMPORT_CTYPE_TABLE + u32::from(byte),
            ppc_ctype_entry(byte as u8),
        );
    }
}

pub(crate) fn ppc_initial_stdio_streams() -> HashMap<u32, PpcStdioStreamRecord> {
    (0..3u32)
        .map(|index| {
            (
                PPC_STDIO_IOB_ADDR + index * PPC_STDIO_FILE_SIZE,
                PpcStdioStreamRecord {
                    ref_num: None,
                    path: None,
                    position: 0,
                    standard: true,
                    readable: index == 0,
                    writable: index != 0,
                    append: false,
                    closed: false,
                    eof: false,
                    error: false,
                },
            )
        })
        .collect()
}

fn import_trap_pc(index: u32) -> Result<u32, PpcLoadError> {
    PPC_IMPORT_TRAP_BASE
        .checked_add(index.checked_mul(4).ok_or(PpcLoadError::AddressOverflow)?)
        .ok_or(PpcLoadError::AddressOverflow)
}

fn import_tvector_bytes(count: usize) -> Vec<u8> {
    let mut bytes = Vec::with_capacity(count * 8);
    for index in 0..count {
        let trap_pc = PPC_IMPORT_TRAP_BASE + (index as u32) * 4;
        bytes.extend_from_slice(&trap_pc.to_be_bytes());
        bytes.extend_from_slice(&0u32.to_be_bytes());
    }
    bytes
}

fn import_trap_bytes(count: usize) -> Vec<u8> {
    let mut bytes = Vec::with_capacity(count * 4);
    for _ in 0..count {
        bytes.extend_from_slice(&BLR.to_be_bytes());
    }
    bytes
}

fn ppc_application_init_return_trampoline(main_entry: u32, main_rtoc: u32) -> Vec<u8> {
    // r3 is the initializer's OSErr. A failed initializer terminates launch;
    // success restores the main routine's TOC and branches to its entry point.
    // The generated code is ordinary PowerPC ABI glue, not an HLE import.
    let words = [
        0x2c03_0000, // cmpwi r3, 0
        0x4082_0020, // bne failure
        0x3c40_0000 | (main_rtoc >> 16),
        0x6042_0000 | (main_rtoc & 0xffff),
        0x3d80_0000 | (main_entry >> 16),
        0x618c_0000 | (main_entry & 0xffff),
        0x7d89_03a6, // mtctr r12
        0x4e80_0420, // bctr
        0x3980_0000, // failure: li r12, 0
        0x7d89_03a6, // mtctr r12
        0x4e80_0420, // bctr
    ];
    words
        .into_iter()
        .flat_map(u32::to_be_bytes)
        .collect::<Vec<_>>()
}

fn alignment_bytes(power: u8) -> Result<u32, PpcLoadError> {
    if power >= 31 {
        return Err(PpcLoadError::AddressOverflow);
    }
    Ok(1u32 << power)
}

fn align_up(value: u32, align: u32) -> Result<u32, PpcLoadError> {
    if align <= 1 {
        return Ok(value);
    }
    let mask = align - 1;
    value
        .checked_add(mask)
        .map(|v| v & !mask)
        .ok_or(PpcLoadError::AddressOverflow)
}

fn normalize_stack_size(requested: u32) -> Result<u32, PpcLoadError> {
    let requested = if requested == 0 {
        PPC_DEFAULT_STACK_SIZE
    } else {
        requested
    };
    let requested = requested.max(PPC_INITIAL_STACK_FRAME_SIZE);
    let aligned =
        align_up(requested, 16).map_err(|_| PpcLoadError::StackSizeOutOfRange { requested })?;
    if aligned > PPC_MAX_STACK_SIZE {
        return Err(PpcLoadError::StackSizeOutOfRange { requested });
    }
    Ok(aligned)
}

fn read_u32(data: &[u8], offset: usize) -> Option<u32> {
    Some(u32::from_be_bytes(
        data.get(offset..offset + 4)?.try_into().ok()?,
    ))
}

