        let pef = synthetic_pef_with_library_import(b"QuickDraw\xaa 3D", b"Q3Vector3D_Normalize");
        let mut loaded = load_pef_application(&pef).unwrap();
        let vector_ptr = PPC_DATA_BASE + 0x1000;
