        let input = PPC_HEAP_BASE + 0x100;
        let output = PPC_HEAP_BASE + 0x108;
        let bits = (-1.5f64).to_bits();
        loaded.memory.write_u32_be(input, (bits >> 32) as u32);
        loaded.memory.write_u32_be(input + 4, bits as u32);
