        ppc_write_pstring_bytes(&mut loaded.memory, scratch + 8, b"Document");
        loaded.cpu.gpr[3] = 0;
        loaded.cpu.gpr[4] = scratch;
        loaded.cpu.gpr[5] = scratch + 8;
        loaded.cpu.gpr[6] = 0;
        loaded.cpu.gpr[7] = 0;
