            ppc_memory_read_bytes(&mut loaded.memory, front.base_addr, framebuffer_len).unwrap();
        loaded
            .memory
            .write_u16_be(PPC_THE_MENU_ADDR, 0x1357)
            .unwrap();
        loaded.cpu.gpr[3] = menu_handle;
        loaded.cpu.gpr[4] = 100;
        loaded.cpu.gpr[5] = 50;
        loaded.cpu.gpr[6] = 1;
