    #[test]
    fn hle_import_runner_creates_and_disposes_native_styled_textedit_records() {
        let pef = synthetic_pef_with_import(b"TEStyleNew");
        let mut loaded = load_pef_application(&pef).unwrap();
        let rects = PPC_DATA_BASE + 0x1000;
        loaded.memory.add_region(rects, vec![0; 16]);
        for (offset, value) in [10u16, 20, 110, 220].into_iter().enumerate() {
            loaded
                .memory
                .write_u16_be(rects + offset as u32 * 2, value)
                .unwrap();
        }
        for (offset, value) in [12u16, 22, 108, 218].into_iter().enumerate() {
            loaded
                .memory
                .write_u16_be(rects + 8 + offset as u32 * 2, value)
                .unwrap();
        }
        loaded.cpu.gpr[3] = rects;
        loaded.cpu.gpr[4] = rects + 8;

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.handled_import_count, 1);
        assert_eq!(probe.unsupported_import_index, None);
        let te_handle = loaded.cpu.gpr[3];
        let te_ptr = loaded.memory.read_u32_be(te_handle).unwrap();
        assert_ne!(te_handle, 0);
        assert_eq!(
            ppc_te_read_rect(&mut loaded.memory, te_ptr + PPC_TE_DEST_RECT_OFFSET),
            Some([10, 20, 110, 220])
        );
        assert_eq!(
            ppc_te_read_rect(&mut loaded.memory, te_ptr + PPC_TE_VIEW_RECT_OFFSET),
            Some([12, 22, 108, 218])
        );
        assert_eq!(
            loaded
                .memory
                .read_u16_be(te_ptr + PPC_TE_LINE_HEIGHT_OFFSET),
            Some(0xffff)
        );
        assert_eq!(
            loaded
                .memory
                .read_u16_be(te_ptr + PPC_TE_FONT_ASCENT_OFFSET),
            Some(0xffff)
        );
        assert_eq!(
            loaded.memory.read_u16_be(te_ptr + PPC_TE_TX_SIZE_OFFSET),
            Some(0xffff)
        );
        let text_handle = loaded
            .memory
            .read_u32_be(te_ptr + PPC_TE_HTEXT_OFFSET)
            .unwrap();
        let style_handle = loaded
            .memory
            .read_u32_be(te_ptr + PPC_TE_TX_FONT_OFFSET)
            .unwrap();
        assert_ne!(text_handle, 0);
        assert_ne!(style_handle, 0);
        assert_eq!(test_handle_records!(loaded).len(), 7);

        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::TEGetText;
        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.cpu.gpr[3] = te_handle;
        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.handled_import_count, 1);
        assert_eq!(loaded.cpu.gpr[3], text_handle);

        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::TEDispose;
        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.cpu.gpr[3] = te_handle;
        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.handled_import_count, 1);
        assert_eq!(loaded.memory.read_u32_be(te_handle), Some(0));
        assert!(test_handle_records!(loaded).is_empty());
    }

    #[test]
    fn native_styled_textedit_styles_runs_and_reports_real_measurements() {
        let pef = synthetic_pef_with_import(b"TEStyleNew");
        let mut loaded = load_pef_application(&pef).unwrap();
        let rects = PPC_DATA_BASE + 0x1000;
        let text_ptr = PPC_DATA_BASE + 0x1020;
        let style_ptr = PPC_DATA_BASE + 0x1040;
        let mode_ptr = PPC_DATA_BASE + 0x1060;
        let result_style_ptr = PPC_DATA_BASE + 0x1064;
        let locations_ptr = PPC_DATA_BASE + 0x1080;
        let name_ptr = PPC_DATA_BASE + 0x10a0;
        loaded
            .memory
            .add_region(PPC_DATA_BASE + 0x1000, vec![0; 0x100]);
        ppc_write_rect(&mut loaded.memory, rects, 10, 20, 80, 220).unwrap();
        ppc_write_rect(&mut loaded.memory, rects + 8, 10, 20, 80, 220).unwrap();
        loaded.cpu.gpr[3] = rects;
        loaded.cpu.gpr[4] = rects + 8;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::TEStyleNew);
        let te_handle = loaded.cpu.gpr[3];
        let constructor_te_ptr = loaded.memory.read_u32_be(te_handle).unwrap();
        let style_handle = loaded
            .memory
            .read_u32_be(constructor_te_ptr + PPC_TE_TX_FONT_OFFSET)
            .unwrap();

        loaded.memory.write_bytes(text_ptr, b"Styled").unwrap();
        loaded.cpu.gpr[3] = text_ptr;
        loaded.cpu.gpr[4] = 6;
        loaded.cpu.gpr[5] = te_handle;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::TESetText);

        let write_style =
            |memory: &mut PpcSectionMem, font: i16, face: u8, size: i16, color: PpcRgbColor| {
                memory.write_u16_be(style_ptr, font as u16).unwrap();
                memory.write_u8(style_ptr + 2, face).unwrap();
                memory.write_u16_be(style_ptr + 4, size as u16).unwrap();
                memory.write_u16_be(style_ptr + 6, color.red).unwrap();
                memory.write_u16_be(style_ptr + 8, color.green).unwrap();
                memory.write_u16_be(style_ptr + 10, color.blue).unwrap();
            };
        write_style(
            &mut loaded.memory,
            3,
            0x01,
            14,
            PpcRgbColor {
                red: 0xffff,
                green: 0,
                blue: 0,
            },
        );
        loaded.cpu.gpr[3] = 0;
        loaded.cpu.gpr[4] = 3;
        loaded.cpu.gpr[5] = te_handle;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::TESetSelect);
        loaded.cpu.gpr[3] = 0x000f;
        loaded.cpu.gpr[4] = style_ptr;
        loaded.cpu.gpr[5] = 0;
        loaded.cpu.gpr[6] = te_handle;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::TESetStyle);

        write_style(
            &mut loaded.memory,
            4,
            0x02,
            10,
            PpcRgbColor {
                red: 0,
                green: 0,
                blue: 0xffff,
            },
        );
        loaded.cpu.gpr[3] = 3;
        loaded.cpu.gpr[4] = 6;
        loaded.cpu.gpr[5] = te_handle;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::TESetSelect);
        loaded.cpu.gpr[3] = 0x000f;
        loaded.cpu.gpr[4] = style_ptr;
        loaded.cpu.gpr[5] = 0;
        loaded.cpu.gpr[6] = te_handle;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::TESetStyle);

        let runs = ppc_te_style_runs(
            &mut loaded.memory,
            &test_handle_records!(loaded),
            te_handle,
            6,
        );
        assert_eq!(
            runs.iter().map(|run| run.start).collect::<Vec<_>>(),
            vec![0, 3]
        );
        assert_eq!(runs[0].style.font, 3);
        assert_eq!(runs[0].style.face, 0x01);
        assert_eq!(runs[0].style.size, 14);
        assert_eq!(runs[0].style.color.red, 0xffff);
        assert_eq!(runs[1].style.font, 4);
        assert_eq!(runs[1].style.face, 0x02);
        assert_eq!(runs[1].style.size, 10);
        assert_eq!(runs[1].style.color.blue, 0xffff);

        loaded.cpu.gpr[3] = te_handle;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::TECalText);
        let te_ptr = loaded.memory.read_u32_be(te_handle).unwrap();
        let n_lines = usize::from(
            loaded
                .memory
                .read_u16_be(te_ptr + PPC_TE_N_LINES_OFFSET)
                .unwrap(),
        );
        assert!(n_lines > 0);
        assert_eq!(
            loaded
                .memory
                .read_u16_be(te_ptr + PPC_TE_LINE_STARTS_OFFSET + n_lines as u32 * 2),
            Some(6)
        );
        assert_eq!(
            loaded.memory.read_u16_be(
                te_ptr + PPC_TE_LINE_STARTS_OFFSET + n_lines.saturating_add(1) as u32 * 2,
            ),
            Some(0)
        );
        let style_record_ptr = loaded.memory.read_u32_be(style_handle).unwrap();
        let n_runs = usize::from(
            loaded
                .memory
                .read_u16_be(style_record_ptr + PPC_TE_STYLE_N_RUNS_OFFSET)
                .unwrap(),
        );
        assert_eq!(
            loaded.memory.read_u16_be(
                style_record_ptr + PPC_TE_STYLE_RUNS_OFFSET + n_runs as u32 * 4,
            ),
            Some(7)
        );
        let lh_handle = loaded
            .memory
            .read_u32_be(style_record_ptr + PPC_TE_STYLE_LH_TABLE_OFFSET)
            .unwrap();
        let handle_records = test_handle_records!(loaded);
        let lh_record = handle_records
            .iter()
            .find(|record| record.handle == lh_handle)
            .unwrap();
        assert!(lh_record.size >= (n_lines.saturating_add(1) * 4) as u32);
        let lh_ptr = loaded.memory.read_u32_be(lh_handle).unwrap();
        assert!(loaded.memory.read_u16_be(lh_ptr + n_lines as u32 * 4).unwrap() > 0);

        // Text 1993, p. 2-102: a mixed face selection reports the bits
        // common to every face, so bold plus bold-italic reports bold.
        write_style(
            &mut loaded.memory,
            4,
            0x03,
            10,
            PpcRgbColor {
                red: 0,
                green: 0,
                blue: 0xffff,
            },
        );
        loaded.cpu.gpr[3] = 3;
        loaded.cpu.gpr[4] = 6;
        loaded.cpu.gpr[5] = te_handle;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::TESetSelect);
        loaded.cpu.gpr[3] = 0x0002;
        loaded.cpu.gpr[4] = style_ptr;
        loaded.cpu.gpr[5] = 0;
        loaded.cpu.gpr[6] = te_handle;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::TESetStyle);
        loaded.cpu.gpr[3] = 0;
        loaded.cpu.gpr[4] = 6;
        loaded.cpu.gpr[5] = te_handle;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::TESetSelect);
        loaded.memory.write_u16_be(mode_ptr, 0x0002).unwrap();
        loaded.cpu.gpr[3] = mode_ptr;
        loaded.cpu.gpr[4] = result_style_ptr;
        loaded.cpu.gpr[5] = te_handle;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::TEContinuousStyle);
        assert_eq!(loaded.cpu.gpr[3], 1);
        assert_eq!(loaded.memory.read_u16_be(mode_ptr), Some(0x0002));
        assert_eq!(loaded.memory.read_u8(result_style_ptr + 2), Some(0x01));

        // TESetStyle at an insertion point updates the null scrap used by
        // later TEInsert/TEStyleInsert calls instead of changing no runs.
        write_style(
            &mut loaded.memory,
            4,
            0x04,
            11,
            PpcRgbColor {
                red: 0,
                green: 0xffff,
                blue: 0,
            },
        );
        loaded.cpu.gpr[3] = 3;
        loaded.cpu.gpr[4] = 3;
        loaded.cpu.gpr[5] = te_handle;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::TESetSelect);
        loaded.cpu.gpr[3] = 0x000f;
        loaded.cpu.gpr[4] = style_ptr;
        loaded.cpu.gpr[5] = 0;
        loaded.cpu.gpr[6] = te_handle;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::TESetStyle);
        let style_record_ptr = loaded.memory.read_u32_be(style_handle).unwrap();
        let null_style_handle = loaded
            .memory
            .read_u32_be(style_record_ptr + PPC_TE_STYLE_NULL_STYLE_OFFSET)
            .unwrap();
        let null_style_ptr = loaded.memory.read_u32_be(null_style_handle).unwrap();
        let null_scrap_handle = loaded
            .memory
            .read_u32_be(null_style_ptr + PPC_TE_NULL_STYLE_SCRAP_OFFSET)
            .unwrap();
        let null_scrap_ptr = loaded.memory.read_u32_be(null_scrap_handle).unwrap();
        let null_element = null_scrap_ptr + PPC_TE_SCRAP_STYLE_TAB_OFFSET;
        assert_eq!(
            loaded
                .memory
                .read_u16_be(null_scrap_ptr + PPC_TE_SCRAP_N_STYLES_OFFSET),
            Some(1)
        );
        assert_eq!(
            loaded
                .memory
                .read_u16_be(null_element + PPC_TE_SCRAP_STYLE_FONT_OFFSET),
            Some(4)
        );
        assert_eq!(
            loaded
                .memory
                .read_u8(null_element + PPC_TE_SCRAP_STYLE_FACE_OFFSET),
            Some(0x04)
        );
        assert_eq!(
            loaded
                .memory
                .read_u16_be(null_element + PPC_TE_SCRAP_STYLE_SIZE_OFFSET),
            Some(11)
        );
        assert_eq!(
            loaded
                .memory
                .read_u16_be(null_element + PPC_TE_SCRAP_STYLE_COLOR_OFFSET + 2),
            Some(0xffff)
        );
        loaded.memory.write_u16_be(mode_ptr, 0x000f).unwrap();
        loaded.cpu.gpr[3] = mode_ptr;
        loaded.cpu.gpr[4] = result_style_ptr;
        loaded.cpu.gpr[5] = te_handle;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::TEContinuousStyle);
        assert_eq!(loaded.cpu.gpr[3], 1);
        assert_eq!(loaded.memory.read_u16_be(mode_ptr), Some(0x000f));
        assert_eq!(loaded.memory.read_u8(result_style_ptr + 2), Some(0x04));
        assert_eq!(loaded.memory.read_u16_be(result_style_ptr + 4), Some(11));

        loaded.memory.write_u16_be(mode_ptr, 0x000f).unwrap();
        loaded.cpu.gpr[3] = 0;
        loaded.cpu.gpr[4] = 6;
        loaded.cpu.gpr[5] = te_handle;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::TESetSelect);
        loaded.cpu.gpr[3] = mode_ptr;
        loaded.cpu.gpr[4] = result_style_ptr;
        loaded.cpu.gpr[5] = te_handle;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::TEContinuousStyle);
        assert_eq!(loaded.cpu.gpr[3], 0);
        assert_eq!(loaded.memory.read_u16_be(mode_ptr), Some(0x0002));

        loaded.memory.write_u16_be(mode_ptr, 0x000f).unwrap();
        loaded.cpu.gpr[3] = 0;
        loaded.cpu.gpr[4] = 3;
        loaded.cpu.gpr[5] = te_handle;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::TESetSelect);
        loaded.cpu.gpr[3] = mode_ptr;
        loaded.cpu.gpr[4] = result_style_ptr;
        loaded.cpu.gpr[5] = te_handle;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::TEContinuousStyle);
        assert_eq!(loaded.cpu.gpr[3], 1);
        assert_eq!(loaded.memory.read_u16_be(mode_ptr), Some(0x000f));
        assert_eq!(loaded.memory.read_u16_be(result_style_ptr + 4), Some(14));

        loaded.cpu.gpr[3] = 3;
        loaded.cpu.gpr[4] = 10;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::TextSize);
        loaded.cpu.gpr[3] = 6;
        loaded.cpu.gpr[4] = text_ptr;
        loaded.cpu.gpr[5] = locations_ptr;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::MeasureText);
        let measure_width = loaded.memory.read_u16_be(locations_ptr + 12).unwrap();
        assert!(measure_width > 0);
        loaded.cpu.gpr[3] = text_ptr;
        loaded.cpu.gpr[4] = 0;
        loaded.cpu.gpr[5] = 6;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::TextWidth);
        let text_width = loaded.cpu.gpr[3];
        assert!(text_width > 0);
        assert!((text_width as i32 - measure_width as i32).abs() <= 6);

        write_ppc_pstring(&mut loaded.memory, name_ptr, b"Geneva");
        loaded.cpu.gpr[3] = name_ptr;
        loaded.cpu.gpr[4] = result_style_ptr;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::GetFNum);
        assert_eq!(loaded.memory.read_u16_be(result_style_ptr), Some(3));
        loaded.cpu.gpr[3] = 3;
        loaded.cpu.gpr[4] = 9;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::RealFont);
        assert_eq!(loaded.cpu.gpr[3], 1);
        loaded.cpu.gpr[3] = 0;
        loaded.cpu.gpr[4] = 12;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::RealFont);
        assert_eq!(loaded.cpu.gpr[3], 1);
        loaded.cpu.gpr[3] = 1;
        loaded.cpu.gpr[4] = 12;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::RealFont);
        assert_eq!(loaded.cpu.gpr[3], 0);
    }

    #[test]
    fn native_textedit_key_and_click_update_the_public_edit_record() {
        let pef = synthetic_pef_with_import(b"TEKey");
        let mut loaded = load_pef_application(&pef).unwrap();
        let rects = PPC_DATA_BASE + 0x1000;
        loaded.memory.add_region(rects, vec![0; 16]);
        ppc_write_rect(&mut loaded.memory, rects, 10, 20, 80, 220).unwrap();
        ppc_write_rect(&mut loaded.memory, rects + 8, 10, 20, 80, 220).unwrap();
        let mut last_mem_error = PPC_NO_ERR;
        let te_handle = ppc_te_initialize_record(
            None,
            &mut loaded.memory,
            test_heap_cursor!(loaded),
            test_heap_limit!(loaded),
            &mut last_mem_error,
            test_handles!(loaded),
            rects,
            rects + 8,
            PPC_MAIN_GWORLD,
            1,
            PPC_QD_TEXT_MODE_SRC_OR,
            12,
            PpcRgbColor {
                red: 0,
                green: 0,
                blue: 0,
            },
            false,
        );
        assert_eq!(
            ppc_te_set_text(
                None,
                &mut loaded.memory,
                test_heap_cursor!(loaded),
                test_heap_limit!(loaded),
                &mut last_mem_error,
                test_handles!(loaded),
                te_handle,
                b"abc",
            ),
            PPC_NO_ERR
        );

        loaded.cpu.gpr[3] = 0x08;
        loaded.cpu.gpr[4] = te_handle;
        let probe = loaded.run_with_hle_imports(64);
        assert_eq!(probe.unsupported_import_index, None);
        assert_eq!(
            ppc_te_text_bytes(&mut loaded.memory, &test_handle_records!(loaded), te_handle),
            Some(b"ab".to_vec())
        );

        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.cpu.gpr[3] = u32::from(b'Z');
        loaded.run_with_hle_imports(64);
        assert_eq!(
            ppc_te_text_bytes(&mut loaded.memory, &test_handle_records!(loaded), te_handle),
            Some(b"abZ".to_vec())
        );

        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.cpu.gpr[3] = 0x1c;
        loaded.run_with_hle_imports(64);
        let te_ptr = loaded.memory.read_u32_be(te_handle).unwrap();
        assert_eq!(
            loaded.memory.read_u16_be(te_ptr + PPC_TE_SEL_START_OFFSET),
            Some(2)
        );
        assert_eq!(
            loaded.memory.read_u16_be(te_ptr + PPC_TE_SEL_END_OFFSET),
            Some(2)
        );

        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.cpu.gpr[3] = 0x1d;
        loaded.run_with_hle_imports(64);
        assert_eq!(
            loaded.memory.read_u16_be(te_ptr + PPC_TE_SEL_START_OFFSET),
            Some(3)
        );
        assert_eq!(
            ppc_te_text_bytes(&mut loaded.memory, &test_handle_records!(loaded), te_handle),
            Some(b"abZ".to_vec())
        );

        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::TEClick;
        loaded.tick_count = 100;
        loaded.cpu.gpr[3] = (12u32 << 16) | 20;
        loaded.cpu.gpr[4] = 0;
        loaded.cpu.gpr[5] = te_handle;
        loaded.run_with_hle_imports(64);
        assert_eq!(
            loaded.memory.read_u16_be(te_ptr + PPC_TE_SEL_START_OFFSET),
            Some(0)
        );
        assert_eq!(
            loaded.memory.read_u16_be(te_ptr + PPC_TE_SEL_END_OFFSET),
            Some(0)
        );
        let click_time = loaded
            .memory
            .read_u32_be(te_ptr + PPC_TE_CLICK_TIME_OFFSET)
            .unwrap();
        assert!((100..=164).contains(&click_time));
    }

    #[test]
    fn native_textedit_line_starts_follow_shared_word_boundaries() {
        // Inside Macintosh: Text (1993), pp. 5-24--5-27: prefer a word
        // boundary over splitting the next word at the overflowing glyph.
        let pef = synthetic_pef_with_import(b"TECalText");
        let mut loaded = load_pef_application(&pef).unwrap();
        let rects = PPC_DATA_BASE + 0x1000;
        loaded.memory.add_region(rects, vec![0; 16]);
        let font = PPC_QD_TEXT_FONT_DEFAULT;
        let size = PPC_QD_TEXT_SIZE_SYSTEM;
        let first_line_width = ppc_text_bytes_advance_for_font(b"one two", font, size);
        ppc_write_rect(&mut loaded.memory, rects, 10, 20, 80, 20 + first_line_width).unwrap();
        ppc_write_rect(
            &mut loaded.memory,
            rects + 8,
            10,
            20,
            80,
            20 + first_line_width,
        )
        .unwrap();
        let mut last_mem_error = PPC_NO_ERR;
        let te_handle = ppc_te_initialize_record(
            None,
            &mut loaded.memory,
            test_heap_cursor!(loaded),
            test_heap_limit!(loaded),
            &mut last_mem_error,
            test_handles!(loaded),
            rects,
            rects + 8,
            PPC_MAIN_GWORLD,
            1,
            PPC_QD_TEXT_MODE_SRC_OR,
            size,
            PPC_RGB_BLACK,
            false,
        );

        assert_eq!(
            ppc_te_set_text(
                None,
                &mut loaded.memory,
                test_heap_cursor!(loaded),
                test_heap_limit!(loaded),
                &mut last_mem_error,
                test_handles!(loaded),
                te_handle,
                b"one two three",
            ),
            PPC_NO_ERR
        );
        let te_ptr = loaded.memory.read_u32_be(te_handle).unwrap();
        assert_eq!(
            loaded.memory.read_u16_be(te_ptr + PPC_TE_N_LINES_OFFSET),
            Some(2)
        );
        assert_eq!(
            loaded
                .memory
                .read_u16_be(te_ptr + PPC_TE_LINE_STARTS_OFFSET),
            Some(0)
        );
        assert_eq!(
            loaded
                .memory
                .read_u16_be(te_ptr + PPC_TE_LINE_STARTS_OFFSET + 2),
            Some(8)
        );
    }

    #[test]
    fn textedit_and_te_text_box_use_explicit_foreground_index() {
        let pef = synthetic_pef_with_import(b"TETextBox");
        let mut loaded = load_pef_application(&pef).unwrap();
        let scratch = PPC_DATA_BASE + 0x1000;
        let text = scratch;
        let text_box_rect = scratch + 0x20;
        let te_rects = scratch + 0x40;
        loaded.memory.add_region(scratch, vec![0; 0x60]);
        loaded.memory.write_u8(text, b'0').unwrap();
        ppc_write_rect(&mut loaded.memory, text_box_rect, 10, 10, 40, 100).unwrap();
        loaded.quickdraw_fore_indices.insert(PPC_MAIN_GWORLD, 103);
        loaded.cpu.gpr[3] = text;
        loaded.cpu.gpr[4] = 1;
        loaded.cpu.gpr[5] = text_box_rect;
        loaded.cpu.gpr[6] = 0;

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.unsupported_import_index, None);
        let front = ppc_front_buffer_for_gworld(&loaded.gworlds, PPC_MAIN_GWORLD).unwrap();
        assert!((10..40).any(|y| {
            (10..100)
                .any(|x| ppc_quickdraw_read_pixel(&mut loaded.memory, front, (x, y)) == Some(103))
        }));

        ppc_write_rect(&mut loaded.memory, te_rects, 60, 10, 100, 100).unwrap();
        ppc_write_rect(&mut loaded.memory, te_rects + 8, 60, 10, 100, 100).unwrap();
        let mut last_mem_error = PPC_NO_ERR;
        let te_handle = ppc_te_initialize_record(
            None,
            &mut loaded.memory,
            test_heap_cursor!(loaded),
            test_heap_limit!(loaded),
            &mut last_mem_error,
            test_handles!(loaded),
            te_rects,
            te_rects + 8,
            PPC_MAIN_GWORLD,
            0,
            PPC_QD_TEXT_MODE_SRC_OR,
            12,
            loaded.quickdraw_fore_color,
            false,
        );
        assert_eq!(
            ppc_te_set_text(
                None,
                &mut loaded.memory,
                test_heap_cursor!(loaded),
                test_heap_limit!(loaded),
                &mut last_mem_error,
                test_handles!(loaded),
                te_handle,
                b"0",
            ),
            PPC_NO_ERR
        );
        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::TEUpdate;
        loaded.cpu.gpr[3] = te_rects;
        loaded.cpu.gpr[4] = te_handle;

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.unsupported_import_index, None);
        assert!((60..100).any(|y| {
            (10..100)
                .any(|x| ppc_quickdraw_read_pixel(&mut loaded.memory, front, (x, y)) == Some(103))
        }));
    }

    #[test]
    fn native_textedit_and_scrap_manager_share_the_text_flavor() {
        let pef = synthetic_pef_with_import(b"TECopy");
        let mut loaded = load_pef_application(&pef).unwrap();
        let rects = PPC_DATA_BASE + 0x1000;
        let offset_ptr = rects + 0x20;
        loaded.memory.add_region(rects, vec![0; 0x40]);
        ppc_write_rect(&mut loaded.memory, rects, 0, 0, 80, 220).unwrap();
        ppc_write_rect(&mut loaded.memory, rects + 8, 0, 0, 80, 220).unwrap();
        let mut last_mem_error = PPC_NO_ERR;
        let te_handle = ppc_te_initialize_record(
            None,
            &mut loaded.memory,
            test_heap_cursor!(loaded),
            test_heap_limit!(loaded),
            &mut last_mem_error,
            test_handles!(loaded),
            rects,
            rects + 8,
            PPC_MAIN_GWORLD,
            0,
            PPC_QD_TEXT_MODE_SRC_OR,
            12,
            PPC_RGB_BLACK,
            false,
        );
        ppc_te_set_text(
            None,
            &mut loaded.memory,
            test_heap_cursor!(loaded),
            test_heap_limit!(loaded),
            &mut last_mem_error,
            test_handles!(loaded),
            te_handle,
            b"Pilot Name",
        );
        let te_ptr = loaded.memory.read_u32_be(te_handle).unwrap();
        loaded
            .memory
            .write_u16_be(te_ptr + PPC_TE_SEL_START_OFFSET, 0)
            .unwrap();
        loaded
            .memory
            .write_u16_be(te_ptr + PPC_TE_SEL_END_OFFSET, 5)
            .unwrap();
        loaded.cpu.gpr[3] = te_handle;
        loaded.run_with_hle_imports(64);
        assert_eq!(
            ppc_te_scrap_bytes(&mut loaded.memory),
            b"Pilot"
        );

        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::ZeroScrap;
        loaded.run_with_hle_imports(64);
        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::TETransferScrap {
            from_desktop: false,
        };
        loaded.run_with_hle_imports(64);

        let destination = ppc_alloc_handle(
            &mut loaded.memory,
            test_heap_cursor!(loaded),
            test_heap_limit!(loaded),
            test_handles!(loaded),
            0,
            true,
        );
        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::GetScrap;
        loaded.cpu.gpr[3] = destination;
        loaded.cpu.gpr[4] = u32::from_be_bytes(*b"TEXT");
        loaded.cpu.gpr[5] = offset_ptr;
        let probe = loaded.run_with_hle_imports(64);
        assert_eq!(probe.unsupported_import_index, None);
        assert_eq!(loaded.cpu.gpr[3], 5);
        assert_eq!(loaded.memory.read_u32_be(offset_ptr), Some(0));
        assert_eq!(
            ppc_handle_bytes(
                &mut loaded.memory,
                &test_handle_records!(loaded),
                destination
            ),
            Some(b"Pilot".to_vec())
        );
    }

    #[test]
    fn native_list_manager_stores_cells_rows_selection_and_geometry_in_public_records() {
        assert_eq!(
            dispatcher_target_for_import("InterfaceLib", "LScroll"),
            PpcImportDispatcherTarget::LScroll
        );
        assert_eq!(
            dispatcher_target_for_import("InterfaceLib", "LSize"),
            PpcImportDispatcherTarget::LSize
        );
        assert_eq!(
            dispatcher_target_for_import("InterfaceLib", "LSetDrawingMode"),
            PpcImportDispatcherTarget::LSetDrawingMode
        );
        let pef = synthetic_pef_with_import(b"LNew");
        let mut loaded = load_pef_application(&pef).unwrap();
        let scratch = PPC_DATA_BASE + 0x1000;
        let view_ptr = scratch;
        let bounds_ptr = scratch + 8;
        let text_ptr = scratch + 20;
        let output_ptr = scratch + 32;
        let length_ptr = scratch + 48;
        let cell_ptr = scratch + 52;
        loaded.memory.add_region(scratch, vec![0; 64]);
        ppc_write_rect(&mut loaded.memory, view_ptr, 10, 20, 90, 220).unwrap();
        ppc_write_rect(&mut loaded.memory, bounds_ptr, 0, 0, 2, 2).unwrap();
        loaded.memory.write_bytes(text_ptr, b"Pilot").unwrap();
        loaded.cpu.gpr[3] = view_ptr;
        loaded.cpu.gpr[4] = bounds_ptr;
        loaded.cpu.gpr[5] = (20u32 << 16) | 100;
        loaded.cpu.gpr[6] = 0;
        loaded.cpu.gpr[7] = PPC_MAIN_GWORLD;
        loaded.cpu.gpr[8] = 0;
        loaded.cpu.gpr[9] = 0;
        loaded.cpu.gpr[10] = 0;
        loaded
            .memory
            .write_u32_be(
                ppc_parameter_area_slot_addr(loaded.cpu.gpr[1], PPC_NATIVE_PARAMETER_GPR_COUNT)
                    .unwrap(),
                1,
            )
            .unwrap();
        let probe = loaded.run_with_hle_imports(128);
        assert_eq!(probe.unsupported_import_index, None);
        let list = loaded.cpu.gpr[3];
        let list_ptr = loaded.memory.read_u32_be(list).unwrap();
        assert_ne!(list, 0);
        assert_eq!(
            ppc_read_rect(&mut loaded.memory, list_ptr + PPC_LIST_DATA_BOUNDS_OFFSET),
            Some((0, 0, 2, 2))
        );
        assert_eq!(
            ppc_read_rect(&mut loaded.memory, list_ptr + PPC_LIST_VISIBLE_OFFSET),
            Some((0, 0, 2, 2))
        );
        assert_eq!(
            loaded
                .memory
                .read_u16_be(list_ptr + PPC_LIST_MAX_INDEX_OFFSET),
            Some(8)
        );
        assert_eq!(
            loaded
                .list_manager
                .get(&list)
                .map(|record| record.cell_size),
            Some((20, 100))
        );
        let vertical_scroll = loaded
            .memory
            .read_u32_be(list_ptr + PPC_LIST_VSCROLL_OFFSET)
            .unwrap();
        assert_ne!(vertical_scroll, 0);
        assert_eq!(
            loaded
                .memory
                .read_u32_be(list_ptr + PPC_LIST_HSCROLL_OFFSET),
            Some(0)
        );
        let vertical_scroll_ptr = ppc_control_ptr(&mut loaded.memory, vertical_scroll).unwrap();
        assert_eq!(
            ppc_read_rect(
                &mut loaded.memory,
                vertical_scroll_ptr + PPC_CONTROL_RECT_OFFSET,
            ),
            Some((9, 220, 91, 236))
        );
        assert_eq!(
            loaded
                .memory
                .read_u8(vertical_scroll_ptr + PPC_CONTROL_VISIBLE_OFFSET),
            Some(0)
        );
        loaded.cpu.gpr[3] = 1;
        loaded.cpu.gpr[4] = list;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::LSetDrawingMode);
        assert!(loaded.list_manager[&list].draw_enabled);
        assert_eq!(
            loaded
                .memory
                .read_u8(vertical_scroll_ptr + PPC_CONTROL_VISIBLE_OFFSET),
            Some(0xff)
        );

        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::LSetCell;
        loaded.cpu.gpr[3] = text_ptr;
        loaded.cpu.gpr[4] = 5;
        loaded.cpu.gpr[5] = (1u32 << 16) | 1;
        loaded.cpu.gpr[6] = list;
        loaded.run_with_hle_imports(128);

        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::LGetCell;
        loaded.memory.write_u16_be(length_ptr, 16).unwrap();
        loaded.cpu.gpr[3] = output_ptr;
        loaded.cpu.gpr[4] = length_ptr;
        loaded.cpu.gpr[5] = (1u32 << 16) | 1;
        loaded.cpu.gpr[6] = list;
        loaded.run_with_hle_imports(128);
        assert_eq!(loaded.memory.read_u16_be(length_ptr), Some(5));
        assert_eq!(
            ppc_memory_read_bytes(&mut loaded.memory, output_ptr, 5),
            Some(b"Pilot".to_vec())
        );

        loaded.memory.write_bytes(output_ptr, b"XXXXX").unwrap();
        loaded.memory.write_u16_be(length_ptr, 3).unwrap();
        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.run_with_hle_imports(128);
        assert_eq!(loaded.memory.read_u16_be(length_ptr), Some(3));
        assert_eq!(
            ppc_memory_read_bytes(&mut loaded.memory, output_ptr, 5),
            Some(b"XXXXX".to_vec())
        );

        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::LSetSelect;
        loaded.cpu.gpr[3] = 1;
        loaded.cpu.gpr[4] = (1u32 << 16) | 1;
        loaded.cpu.gpr[5] = list;
        loaded.run_with_hle_imports(128);
        loaded.memory.write_u16_be(cell_ptr, 0).unwrap();
        loaded.memory.write_u16_be(cell_ptr + 2, 0).unwrap();
        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::LGetSelect;
        loaded.cpu.gpr[3] = 1;
        loaded.cpu.gpr[4] = cell_ptr;
        loaded.cpu.gpr[5] = list;
        loaded.run_with_hle_imports(128);
        assert_eq!(loaded.cpu.gpr[3], 1);
        assert_eq!(loaded.memory.read_u16_be(cell_ptr), Some(1));
        assert_eq!(loaded.memory.read_u16_be(cell_ptr + 2), Some(1));

        let selected_before_rejected_clicks = loaded.list_manager[&list].selected.clone();
        loaded.cpu.gpr[3] = (9u32 << 16) | 20;
        loaded.cpu.gpr[4] = 0;
        loaded.cpu.gpr[5] = list;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::LClick);
        assert_eq!(
            loaded.list_manager[&list].selected, selected_before_rejected_clicks,
            "LClick must ignore points outside rView",
        );

        loaded.cpu.gpr[3] = 0;
        loaded.cpu.gpr[4] = list;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::LActivate);
        assert_eq!(
            loaded
                .memory
                .read_u8(vertical_scroll_ptr + PPC_CONTROL_HILITE_OFFSET),
            Some(0xff)
        );
        loaded.cpu.gpr[3] = (10u32 << 16) | 20;
        loaded.cpu.gpr[4] = 0;
        loaded.cpu.gpr[5] = list;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::LClick);
        assert_eq!(
            loaded.list_manager[&list].selected, selected_before_rejected_clicks,
            "LClick must ignore inactive lists",
        );
        loaded.cpu.gpr[3] = 1;
        loaded.cpu.gpr[4] = list;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::LActivate);
        assert_eq!(
            loaded
                .memory
                .read_u8(vertical_scroll_ptr + PPC_CONTROL_HILITE_OFFSET),
            Some(0)
        );

        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::LAddRow;
        loaded.cpu.gpr[3] = 3;
        loaded.cpu.gpr[4] = 2;
        loaded.cpu.gpr[5] = list;
        loaded.run_with_hle_imports(128);
        let list_ptr = loaded.memory.read_u32_be(list).unwrap();
        assert_eq!(
            ppc_read_rect(&mut loaded.memory, list_ptr + PPC_LIST_DATA_BOUNDS_OFFSET),
            Some((0, 0, 5, 2))
        );
        assert_eq!(
            loaded.list_manager.get(&list).map(|record| record.visible),
            Some((0, 0, 4, 2))
        );
        assert_eq!(
            ppc_read_rect(&mut loaded.memory, list_ptr + PPC_LIST_VISIBLE_OFFSET),
            Some((0, 0, 4, 2))
        );

        loaded.cpu.gpr[3] = 0;
        loaded.cpu.gpr[4] = 1;
        loaded.cpu.gpr[5] = list;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::LScroll);
        let list_ptr = loaded.memory.read_u32_be(list).unwrap();
        assert_eq!(
            loaded.list_manager.get(&list).map(|record| record.visible),
            Some((1, 0, 5, 2))
        );
        assert_eq!(
            ppc_read_rect(&mut loaded.memory, list_ptr + PPC_LIST_VISIBLE_OFFSET),
            Some((1, 0, 5, 2))
        );
        assert_eq!(
            loaded
                .memory
                .read_u16_be(vertical_scroll_ptr + PPC_CONTROL_VALUE_OFFSET),
            Some(1)
        );

        loaded.cpu.gpr[3] = 100;
        loaded.cpu.gpr[4] = 40;
        loaded.cpu.gpr[5] = list;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::LSize);
        let list_ptr = loaded.memory.read_u32_be(list).unwrap();
        assert_eq!(
            loaded
                .list_manager
                .get(&list)
                .map(|record| record.view_rect),
            Some((10, 20, 50, 120))
        );
        assert_eq!(
            loaded.list_manager.get(&list).map(|record| record.visible),
            Some((1, 0, 3, 1))
        );
        assert_eq!(
            ppc_read_rect(&mut loaded.memory, list_ptr + PPC_LIST_VIEW_OFFSET),
            Some((10, 20, 50, 120))
        );
        assert_eq!(
            ppc_read_rect(&mut loaded.memory, list_ptr + PPC_LIST_VISIBLE_OFFSET),
            Some((1, 0, 3, 1))
        );
        assert_eq!(
            ppc_read_rect(
                &mut loaded.memory,
                vertical_scroll_ptr + PPC_CONTROL_RECT_OFFSET,
            ),
            Some((9, 120, 51, 136))
        );
        assert_eq!(
            loaded
                .memory
                .read_u16_be(vertical_scroll_ptr + PPC_CONTROL_MAX_OFFSET),
            Some(3)
        );

        loaded.cpu.gpr[3] = list;
        run_test_import(&mut loaded, PpcImportDispatcherTarget::LDispose);
        assert_eq!(loaded.memory.read_u32_be(vertical_scroll), Some(0));
        assert!(!loaded
            .controls
            .iter()
            .any(|record| record.handle == vertical_scroll));
    }

    #[test]
    fn native_list_manager_draws_cell_backgrounds_in_port_coordinates() {
        let pef = synthetic_pef_with_import(b"LNew");
        let mut loaded = load_pef_application(&pef).unwrap();
        let scratch = PPC_DATA_BASE + 0x2200;
        let view_ptr = scratch;
        let bounds_ptr = scratch + 8;
        loaded.memory.add_region(scratch, vec![0; 24]);
        ppc_write_rect(&mut loaded.memory, view_ptr, 10, 20, 50, 120).unwrap();
        ppc_write_rect(&mut loaded.memory, bounds_ptr, 0, 0, 3, 1).unwrap();
        loaded.cpu.gpr[3] = view_ptr;
        loaded.cpu.gpr[4] = bounds_ptr;
        loaded.cpu.gpr[5] = (20u32 << 16) | 100;
        loaded.cpu.gpr[6] = 0;
        loaded.cpu.gpr[7] = PPC_MAIN_GWORLD;
        loaded.cpu.gpr[8] = 0;
        loaded.cpu.gpr[9] = 0;
        loaded.cpu.gpr[10] = 0;
        loaded
            .memory
            .write_u32_be(
                ppc_parameter_area_slot_addr(loaded.cpu.gpr[1], PPC_NATIVE_PARAMETER_GPR_COUNT)
                    .unwrap(),
                0,
            )
            .unwrap();
        let probe = loaded.run_with_hle_imports(128);
        assert_eq!(probe.unsupported_import_index, None);
        let list = loaded.cpu.gpr[3];
        let record = loaded.list_manager.get_mut(&list).unwrap();
        record.selected.insert((0, 0));

        // NewCWindow gives an on-screen window a negative PixMap origin so
        // its local port coordinates map to its global screen position.
        ppc_set_port_origin(&mut loaded.memory, PPC_MAIN_GWORLD, -150, -40).unwrap();
        let surface =
            ppc_live_quickdraw_surface(&mut loaded.memory, &loaded.gworlds, PPC_MAIN_GWORLD)
                .unwrap();
        assert_eq!((surface.top, surface.left), (-40, -150));
        let front = surface.front_buffer;
        let black =
            ppc_physical_screen_color_pixel(front, PPC_RGB_BLACK, &loaded.screen_clut).unwrap();
        let white =
            ppc_physical_screen_color_pixel(front, PPC_RGB_WHITE, &loaded.screen_clut).unwrap();
        assert!(ppc_fill_front_rect(
            &mut loaded.memory,
            front,
            (0, 0, front.height as i16, front.width as i16),
            PPC_RGB_WHITE,
        ));
        let record = loaded.list_manager.get(&list).unwrap().clone();
        ppc_list_draw(&mut loaded.memory, &loaded.gworlds, &record);

        // Row 0, column 0 is local (10,20)-(30,120), which maps to
        // screen (50,170)-(70,270) for this window origin.
        assert_eq!(
            ppc_quickdraw_read_pixel(&mut loaded.memory, front, (260, 65)),
            Some(black),
            "selected list background must follow the port origin"
        );
        assert_eq!(
            ppc_quickdraw_read_pixel(&mut loaded.memory, front, (110, 25)),
            Some(white),
            "selected list background must not remain at port-local screen coordinates"
        );
    }

    #[test]
    fn attached_list_manager_mutations_and_lifetime_cross_isa_immediately() {
        let mut native = load_pef_application(&synthetic_pef_with_import(b"LNew")).unwrap();
        let (mut classic, _classic_cpu, _classic_bus) = setup_with_port();
        let mut context = ProcessContext::default();
        classic.attach_process_context(&mut context);
        native.attach_process_context(&mut context);

        let scratch = PPC_DATA_BASE + 0x1800;
        let view_ptr = scratch;
        let bounds_ptr = scratch + 8;
        let classic_text_ptr = scratch + 20;
        let native_text_ptr = scratch + 32;
        let output_ptr = scratch + 48;
        let length_ptr = scratch + 64;
        native.memory.add_region(scratch, vec![0; 80]);
        ppc_write_rect(&mut native.memory, view_ptr, 10, 20, 50, 220).unwrap();
        ppc_write_rect(&mut native.memory, bounds_ptr, 0, 0, 2, 2).unwrap();
        native
            .memory
            .write_bytes(classic_text_ptr, b"Classic")
            .unwrap();
        native
            .memory
            .write_bytes(native_text_ptr, b"Native")
            .unwrap();

        native.cpu.gpr[3] = view_ptr;
        native.cpu.gpr[4] = bounds_ptr;
        native.cpu.gpr[5] = (20u32 << 16) | 100;
        native.cpu.gpr[6] = 0;
        native.cpu.gpr[7] = PPC_MAIN_GWORLD;
        native.cpu.gpr[8] = 0;
        native.cpu.gpr[9] = 0;
        native.cpu.gpr[10] = 0;
        native
            .memory
            .write_u32_be(
                ppc_parameter_area_slot_addr(native.cpu.gpr[1], PPC_NATIVE_PARAMETER_GPR_COUNT)
                    .unwrap(),
                0,
            )
            .unwrap();
        native.run_with_hle_imports(128);
        let first_list = native.cpu.gpr[3];
        assert!(classic.list_states.contains_key(&first_list));
        assert_eq!(
            native
                .list_manager
                .get(&first_list)
                .map(|record| record.cell_size),
            Some((20, 100))
        );

        let classic_state = classic.list_states.get_mut(&first_list).unwrap();
        classic_state.cells.insert((1, 1), b"Classic".to_vec());
        classic_state.selected.insert((1, 1));
        classic_state.draw_enabled = true;

        native.memory.write_u16_be(length_ptr, 16).unwrap();
        native.cpu.gpr[3] = output_ptr;
        native.cpu.gpr[4] = length_ptr;
        native.cpu.gpr[5] = (1u32 << 16) | 1;
        native.cpu.gpr[6] = first_list;
        run_test_import(&mut native, PpcImportDispatcherTarget::LGetCell);
        assert_eq!(native.memory.read_u16_be(length_ptr), Some(7));
        assert_eq!(
            ppc_memory_read_bytes(&mut native.memory, output_ptr, 7),
            Some(b"Classic".to_vec())
        );

        native.cpu.gpr[3] = native_text_ptr;
        native.cpu.gpr[4] = 6;
        native.cpu.gpr[5] = 0;
        native.cpu.gpr[6] = first_list;
        run_test_import(&mut native, PpcImportDispatcherTarget::LSetCell);
        assert_eq!(
            classic
                .list_states
                .get(&first_list)
                .and_then(|record| record.cells.get(&(0, 0)))
                .map(Vec::as_slice),
            Some(b"Native".as_slice())
        );

        native.cpu.gpr[3] = view_ptr;
        native.cpu.gpr[4] = bounds_ptr;
        native.cpu.gpr[5] = (20u32 << 16) | 100;
        native.cpu.gpr[6] = 0;
        native.cpu.gpr[7] = PPC_MAIN_GWORLD;
        native.cpu.gpr[8] = 0;
        native.cpu.gpr[9] = 0;
        native.cpu.gpr[10] = 0;
        run_test_import(&mut native, PpcImportDispatcherTarget::LNew);
        let second_list = native.cpu.gpr[3];
        assert_ne!(first_list, second_list);
        assert_eq!(classic.list_states.len(), 2);
        assert_eq!(
            native
                .list_manager
                .get(&second_list)
                .map(|record| record.cell_size),
            Some((20, 100))
        );

        native.cpu.gpr[3] = first_list;
        run_test_import(&mut native, PpcImportDispatcherTarget::LDispose);
        assert!(!classic.list_states.contains_key(&first_list));
        assert!(classic.list_states.contains_key(&second_list));
    }

    #[test]
    fn cloned_native_adapter_detaches_list_manager_state() {
        let mut original = load_pef_application(&synthetic_pef_with_import(b"TestImport")).unwrap();
        original.list_manager.insert(
            0x0032_1000,
            PpcListRecord {
                handle: 0x0032_1000,
                cells_handle: 0x0032_2000,
                view_rect: (0, 0, 40, 100),
                data_bounds: (0, 0, 2, 1),
                cell_size: (20, 100),
                visible: (0, 0, 2, 1),
                port: PPC_MAIN_GWORLD,
                draw_enabled: true,
                cells: [((0, 0), b"Original".to_vec())].into(),
                selected: [(0, 0)].into(),
                last_click: (0, 0),
                last_click_tick: 10,
            },
        );
        let mut detached = original.clone();
        let detached_record = detached.list_manager.get_mut(&0x0032_1000).unwrap();
        detached_record.cells.insert((0, 0), b"Detached".to_vec());
        detached_record.selected.clear();
        detached.list_manager.insert(
            0x0032_3000,
            PpcListRecord {
                handle: 0x0032_3000,
                cells_handle: 0x0032_4000,
                view_rect: (0, 0, 20, 100),
                data_bounds: (0, 0, 1, 1),
                cell_size: (20, 100),
                visible: (0, 0, 1, 1),
                port: PPC_MAIN_GWORLD,
                draw_enabled: false,
                cells: Default::default(),
                selected: Default::default(),
                last_click: (-1, -1),
                last_click_tick: 0,
            },
        );

        assert_eq!(
            original.list_manager[&0x0032_1000].cells[&(0, 0)],
            b"Original"
        );
        assert!(original.list_manager[&0x0032_1000]
            .selected
            .contains(&(0, 0)));
        assert!(!original.list_manager.contains_key(&0x0032_3000));
    }

    #[test]
    fn native_menu_manager_mutates_items_dimensions_and_the_current_menu_list() {
        let pef = synthetic_pef_with_import(b"NewMenu");
        let mut loaded = load_pef_application(&pef).unwrap();
        let mut free_handle_blocks = loaded.free_handle_blocks();
        let scratch = PPC_DATA_BASE + 0x1000;
        let title = scratch;
        let definitions = scratch + 0x40;
        let replacement = scratch + 0x80;
        loaded.memory.add_region(scratch, vec![0; 0x100]);
        assert!(ppc_write_pstring_bytes(&mut loaded.memory, title, b"Game"));
        assert!(ppc_write_pstring_bytes(
            &mut loaded.memory,
            definitions,
            b"Start/S;Disabled(;About/A",
        ));
        assert!(ppc_write_pstring_bytes(
            &mut loaded.memory,
            replacement,
            b"New Game"
        ));

        let menu = ppc_new_menu(
            &mut loaded.memory,
            test_heap_cursor!(loaded),
            test_heap_limit!(loaded),
            test_handles!(loaded),
            &mut free_handle_blocks,
            128,
            title,
        );
        assert_ne!(menu, 0);
        assert_eq!(
            ppc_insert_menu_items(
                &mut loaded.memory,
                test_heap_cursor!(loaded),
                test_heap_limit!(loaded),
                test_handles!(loaded),
                menu,
                definitions,
                i16::MAX,
            ),
            PPC_NO_ERR
        );
        assert_eq!(ppc_count_menu_items(&mut loaded.memory, menu), 3);
        assert!(ppc_menu_item_enabled(&mut loaded.memory, menu, 1));
        assert!(!ppc_menu_item_enabled(&mut loaded.memory, menu, 2));

        let mut cpu = PpcCpu::new();
        cpu.gpr[3] = menu;
        cpu.gpr[4] = 1;
        cpu.gpr[5] = replacement;
        assert_eq!(
            ppc_set_menu_item_text(
                &cpu,
                &mut loaded.memory,
                test_heap_cursor!(loaded),
                test_heap_limit!(loaded),
                test_handles!(loaded),
            ),
            PPC_NO_ERR
        );
        assert_eq!(
            ppc_menu_item(&mut loaded.memory, menu, 1).and_then(|(address, length)| {
                ppc_memory_read_bytes(&mut loaded.memory, address + 1, u32::from(length))
            }),
            Some(b"New Game".to_vec())
        );
        assert_eq!(
            ppc_delete_menu_item(
                &mut loaded.memory,
                test_heap_cursor!(loaded),
                test_heap_limit!(loaded),
                test_handles!(loaded),
                menu,
                2,
            ),
            PPC_NO_ERR
        );
        ppc_calc_menu_size(&mut loaded.memory, menu);
        let menu_ptr = loaded.memory.read_u32_be(menu).unwrap();
        assert_eq!(ppc_count_menu_items(&mut loaded.memory, menu), 2);
        assert!(loaded.memory.read_u16_be(menu_ptr + 2).unwrap() >= 32);
        assert_eq!(loaded.memory.read_u16_be(menu_ptr + 4), Some(32));

        assert_eq!(
            ppc_insert_menu(
                &mut loaded.memory,
                test_heap_cursor!(loaded),
                test_heap_limit!(loaded),
                test_handles!(loaded),
                &mut free_handle_blocks,
                menu,
                0,
            ),
            PPC_NO_ERR
        );
        let menu_list = ppc_current_menu_list(&mut loaded.memory);
        assert_eq!(
            ppc_get_menu_handle(&mut loaded.memory, menu_list, 128,),
            menu
        );
        assert_eq!(
            ppc_delete_menu(
                &mut loaded.memory,
                test_heap_cursor!(loaded),
                test_heap_limit!(loaded),
                test_handles!(loaded),
                menu_list,
                128,
            ),
            PPC_NO_ERR
        );
        assert_eq!(ppc_get_menu_handle(&mut loaded.memory, menu_list, 128,), 0);
    }

    #[test]
    fn get_new_dialog_opens_its_first_edit_text_item_with_a_borrowed_text_handle() {
        let pef = synthetic_pef_with_import(b"GetNewDialog");
        let mut loaded = load_pef_application(&pef).unwrap();
        let mut dlog = vec![0; 22];
        dlog[4..6].copy_from_slice(&100i16.to_be_bytes());
        dlog[6..8].copy_from_slice(&260i16.to_be_bytes());
        dlog[10] = 1;
        dlog[18..20].copy_from_slice(&128i16.to_be_bytes());
        let mut ditl = vec![0; 22];
        ditl[6..8].copy_from_slice(&12i16.to_be_bytes());
        ditl[8..10].copy_from_slice(&20i16.to_be_bytes());
        ditl[10..12].copy_from_slice(&32i16.to_be_bytes());
        ditl[12..14].copy_from_slice(&220i16.to_be_bytes());
        ditl[14] = PPC_DIALOG_ITEM_EDIT_TEXT;
        ditl[15] = 5;
        ditl[16..21].copy_from_slice(b"Pilot");
        for (res_type, data) in [(*b"DLOG", dlog), (*b"DITL", ditl)] {
            let current_resource_refnum = *loaded.process_file_system.current_resource_file;
            loaded
                .process_file_system
                .vfs_resources
                .push(PpcVfsResourceRecord {
                ref_num: current_resource_refnum,
                path: String::new(),
                res_type: u32::from_be_bytes(res_type),
                res_id: 128,
                name: Vec::new(),
                data,
                raw_data: None,
                raw_attrs: None,
                attrs: 0,
                handle: 0,
            });
        }
        loaded.cpu.gpr[3] = 128;
        let probe = loaded.run_with_hle_imports(128);
        assert_eq!(probe.unsupported_import_index, None);
        let dialog = loaded.cpu.gpr[3];
        let items_handle = loaded
            .memory
            .read_u32_be(dialog + PPC_DIALOG_ITEMS_OFFSET)
            .unwrap();
        let items_ptr = loaded.memory.read_u32_be(items_handle).unwrap();
        let item_text_handle = loaded.memory.read_u32_be(items_ptr + 2).unwrap();
        let te_handle = loaded
            .memory
            .read_u32_be(dialog + PPC_DIALOG_TEXT_HANDLE_OFFSET)
            .unwrap();
        let te_ptr = loaded.memory.read_u32_be(te_handle).unwrap();
        assert_ne!(te_handle, 0);
        assert!(loaded
            .event_queue()
            .iter()
            .any(|event| event.what == 6 && event.message == dialog));
        assert_eq!(
            loaded.memory.read_u32_be(te_ptr + PPC_TE_HTEXT_OFFSET),
            Some(item_text_handle)
        );
        assert_eq!(
            ppc_te_text_bytes(&mut loaded.memory, &test_handle_records!(loaded), te_handle),
            Some(b"Pilot".to_vec())
        );
        assert_eq!(
            loaded
                .memory
                .read_u16_be(dialog + PPC_DIALOG_EDIT_FIELD_OFFSET),
            Some(0)
        );
        assert_eq!(
            loaded
                .memory
                .read_u16_be(dialog + PPC_DIALOG_EDIT_OPEN_OFFSET),
            Some(1)
        );
        assert_eq!(
            loaded.memory.read_u16_be(te_ptr + PPC_TE_SEL_START_OFFSET),
            Some(0)
        );
        assert_eq!(
            loaded.memory.read_u16_be(te_ptr + PPC_TE_SEL_END_OFFSET),
            Some(5)
        );

        let item_hit_ptr = PPC_DATA_BASE + 0x1000;
        loaded.memory.add_region(item_hit_ptr, vec![0; 2]);
        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::ModalDialog;
        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.cpu.gpr[4] = item_hit_ptr;
        *loaded.current_gworld = dialog;
        loaded.set_event_queue([PpcQueuedEvent {
            what: 3,
            message: (2 << 8) | u32::from(b'D'),
            where_v: 20,
            where_h: 30,
            modifiers: 0,
        }]);

        let probe = loaded.run_with_hle_imports(64);

        assert!(matches!(probe.result, PpcRunResult::CycleLimit { .. }));
        assert_eq!(
            ppc_te_text_bytes(&mut loaded.memory, &test_handle_records!(loaded), te_handle),
            Some(b"D".to_vec())
        );
        assert_eq!(loaded.memory.read_u16_be(item_hit_ptr), Some(0));

        loaded.set_event_queue([PpcQueuedEvent {
            what: 3,
            message: (u32::from(PPC_KEY_RETURN) << 8) | 0x0d,
            where_v: 20,
            where_h: 30,
            modifiers: 0,
        }]);
        let probe = loaded.run_with_hle_imports(64);

        assert!(matches!(
            probe.result,
            PpcRunResult::Halted {
                pc: PPC_HALT_PC,
                ..
            }
        ));
        assert_eq!(loaded.memory.read_u16_be(item_hit_ptr), Some(1));
    }

    #[test]
    fn pbh_get_v_info_enumerates_and_selects_mounted_volumes() {
        let pef = synthetic_pef_with_import(b"PBGetVInfoSync");
        let mut loaded = load_pef_application(&pef).unwrap();
        loaded.seed_vfs_volumes(vec![PpcVfsVolumeRecord {
            ref_num: -2,
            name: "Gridz™ CD".to_string(),
            root_dir_id: 42,
            attributes: 0x8080,
            file_count: 38,
            allocation_block_count: 400,
            allocation_block_size: 2048,
            clump_size: 4096,
            free_blocks: 12,
            bitmap_start: 3,
            allocation_pointer: 4,
            allocation_start: 5,
            next_catalog_id: 81,
            created_date: 0x1234_5678,
            modified_date: 0x2345_6789,
        }]);
        let pb = PPC_DATA_BASE + 0x1000;
        let name_ptr = pb + 0x100;
        loaded.memory.add_region(pb, vec![0; 0x200]);
        loaded.memory.write_u32_be(pb + 18, name_ptr).unwrap();
        loaded.memory.write_u16_be(pb + 28, 2).unwrap();
        loaded.cpu.gpr[3] = pb;

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.unsupported_import_index, None);
        assert_eq!(loaded.cpu.gpr[3], 0);
        assert_eq!(loaded.memory.read_u16_be(pb + 22), Some((-2i16) as u16));
        assert_eq!(loaded.memory.read_u16_be(pb + 38), Some(0x8080));
        assert_eq!(loaded.memory.read_u16_be(pb + 40), Some(38));
        assert_eq!(loaded.memory.read_u32_be(pb + 48), Some(2048));
        assert_eq!(
            ppc_read_pstring_bytes(&mut loaded.memory, name_ptr),
            Some(encode_mac_roman_lossy("Gridz™ CD"))
        );

        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.cpu.gpr[3] = pb;
        loaded.memory.write_u16_be(pb + 28, 3).unwrap();
        let _ = loaded.run_with_hle_imports(64);
        assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_NSV_ERR));

        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.cpu.gpr[3] = pb;
        loaded.memory.write_u16_be(pb + 22, 0).unwrap();
        loaded.memory.write_u16_be(pb + 28, 0).unwrap();
        assert!(ppc_write_pstring_bytes(
            &mut loaded.memory,
            name_ptr,
            &encode_mac_roman_lossy("Gridz™ CD:ToolBot Power Supply"),
        ));
        let _ = loaded.run_with_hle_imports(64);
        assert_eq!(loaded.cpu.gpr[3], 0);
        assert_eq!(loaded.memory.read_u16_be(pb + 22), Some((-2i16) as u16));
    }

    #[test]
    fn pbh_get_v_info_keeps_relative_paths_on_the_default_volume() {
        let pef = synthetic_pef_with_import(b"PBHGetVInfoSync");
        let mut loaded = load_pef_application(&pef).unwrap();
        let pb = PPC_DATA_BASE + 0x1000;
        let name_ptr = pb + 0x100;
        loaded.memory.add_region(pb, vec![0; 0x200]);
        loaded.memory.write_u32_be(pb + 18, name_ptr).unwrap();
        loaded.memory.write_u16_be(pb + 22, 0).unwrap();
        loaded.memory.write_u16_be(pb + 28, (-1i16) as u16).unwrap();
        assert!(ppc_write_pstring_bytes(
            &mut loaded.memory,
            name_ptr,
            b":data:title.phd",
        ));
        loaded.cpu.gpr[3] = pb;

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.unsupported_import_index, None);
        assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_NO_ERR));
        assert_eq!(
            loaded.memory.read_u16_be(pb + 22),
            Some(PPC_BOOT_VOLUME_REF_NUM as u16)
        );
        assert_eq!(
            ppc_read_pstring_bytes(&mut loaded.memory, name_ptr).as_deref(),
            Some(crate::trap::TrapDispatcher::boot_volume_name().as_bytes())
        );
    }

    #[test]
    fn hle_import_runner_updates_control_titles_and_values() {
        let pef = synthetic_pef_with_import(b"SetControlTitle");
        let mut loaded = load_pef_application(&pef).unwrap();
        let title_ptr = PPC_DATA_BASE + 0x1000;
        loaded.memory.add_region(title_ptr, vec![0; 256]);
        write_ppc_pstring(&mut loaded.memory, title_ptr, b"Continue");
        let control_handle = ppc_alloc_handle_with_bytes(
            &mut loaded.memory,
            test_heap_cursor!(loaded),
            test_heap_limit!(loaded),
            test_handles!(loaded),
            &[0],
        );
        loaded.cpu.gpr[3] = control_handle;
        loaded.cpu.gpr[4] = title_ptr;

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.handled_import_count, 1);
        assert_eq!(probe.unsupported_import_index, None);
        assert_eq!(loaded.last_mem_error(), PPC_NO_ERR);
        let control = loaded.memory.read_u32_be(control_handle).unwrap();
        assert_eq!(
            ppc_read_pstring_bytes(&mut loaded.memory, control + PPC_CONTROL_TITLE_OFFSET),
            Some(b"Continue".to_vec())
        );
        loaded
            .memory
            .write_u16_be(control + PPC_CONTROL_MAX_OFFSET, 1)
            .unwrap();

        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::SetControlValue;
        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.cpu.gpr[3] = control_handle;
        loaded.cpu.gpr[4] = 1;
        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.handled_import_count, 1);
        assert_eq!(probe.unsupported_import_index, None);
        let control = loaded.memory.read_u32_be(control_handle).unwrap();
        assert_eq!(
            loaded
                .memory
                .read_u16_be(control + PPC_CONTROL_VALUE_OFFSET),
            Some(1)
        );
    }

