    #[test]
    fn hle_import_runner_handles_get_process_information() {
        let pef = synthetic_pef_with_import(b"GetProcessInformation");
        let mut loaded = load_pef_application(&pef).unwrap();
        loaded.vfs_directories.push(PpcVfsDirectory {
            dir_id: 100,
            path: "Gridz Demo ƒ".to_string(),
            parent_dir_id: PPC_ROOT_DIR_ID,
            finder_flags: 0,
            creator: PPC_DIRECTORY_CREATOR,
            file_type: PPC_DIRECTORY_FILE_TYPE,
            dirty: false,
        });
        loaded.vfs_directories.push(PpcVfsDirectory {
            dir_id: 101,
            path: "Source Folder".to_string(),
            parent_dir_id: PPC_ROOT_DIR_ID,
            finder_flags: 0,
            creator: PPC_DIRECTORY_CREATOR,
            file_type: PPC_DIRECTORY_FILE_TYPE,
            dirty: false,
        });
        loaded.vfs_files.push(PpcVfsFileRecord {
            path: "Source Folder/Installer".to_string(),
            data: (Vec::new()).into(),
            creator: u32::from_be_bytes(*b"SRC!"),
            file_type: u32::from_be_bytes(*b"APPL"),
            finder_flags: 0,
            dirty: false,
        });
        loaded.vfs_files.push(PpcVfsFileRecord {
            path: "Gridz Demo ƒ/Gridz™ Demo".to_string(),
            data: (Vec::new()).into(),
            creator: u32::from_be_bytes(*b"Grid"),
            file_type: u32::from_be_bytes(*b"APPL"),
            finder_flags: 0,
            dirty: false,
        });
        loaded.set_launched_app_path("Gridz Demo ƒ/Gridz™ Demo");
        let psn_ptr = PPC_DATA_BASE + 0x1000;
        let info_ptr = PPC_DATA_BASE + 0x1100;
        let name_ptr = PPC_DATA_BASE + 0x1200;
        let spec_ptr = PPC_DATA_BASE + 0x1300;
        loaded.memory.add_region(psn_ptr, vec![0; 8]);
        loaded.memory.add_region(info_ptr, vec![0; 60]);
        loaded.memory.add_region(name_ptr, vec![0xaa; 64]);
        loaded.memory.add_region(spec_ptr, vec![0xbb; 70]);
        loaded
            .memory
            .write_u32_be(psn_ptr, PPC_CURRENT_PROCESS_PSN_HIGH)
            .unwrap();
        loaded
            .memory
            .write_u32_be(psn_ptr + 4, PPC_CURRENT_PROCESS_PSN_LOW)
            .unwrap();
        loaded.memory.write_u16_be(info_ptr, 60).unwrap();
        loaded.memory.write_u32_be(info_ptr + 4, name_ptr).unwrap();
        loaded.memory.write_u32_be(info_ptr + 56, spec_ptr).unwrap();
        loaded.cpu.gpr[3] = psn_ptr;
        loaded.cpu.gpr[4] = info_ptr;
        let gridz_demo_name = [
            b'G', b'r', b'i', b'd', b'z', 0xAA, b' ', b'D', b'e', b'm', b'o',
        ];

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.handled_import_count, 1);
        assert_eq!(probe.unsupported_import_index, None);
        assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_NO_ERR));
        assert_eq!(
            loaded.memory.read_u32_be(info_ptr + 8),
            Some(PPC_CURRENT_PROCESS_PSN_HIGH)
        );
        assert_eq!(
            loaded.memory.read_u32_be(info_ptr + 12),
            Some(PPC_CURRENT_PROCESS_PSN_LOW)
        );
        assert_eq!(
            loaded.memory.read_u32_be(info_ptr + 16),
            Some(u32::from_be_bytes(*b"APPL"))
        );
        assert_eq!(
            loaded.memory.read_u32_be(info_ptr + 20),
            Some(u32::from_be_bytes(*b"Grid"))
        );
        assert_eq!(
            ppc_read_pstring_bytes(&mut loaded.memory, name_ptr).as_deref(),
            Some(&gridz_demo_name[..])
        );
        assert_eq!(
            loaded.memory.read_u16_be(spec_ptr),
            Some(PPC_BOOT_VOLUME_REF_NUM as u16)
        );
        assert_eq!(loaded.memory.read_u32_be(spec_ptr + 2), Some(100));
        assert_eq!(
            ppc_read_pstring_bytes(&mut loaded.memory, spec_ptr + 6).as_deref(),
            Some(&gridz_demo_name[..])
        );

        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.cpu.gpr[3] = psn_ptr;
        loaded.cpu.gpr[4] = info_ptr;
        loaded
            .memory
            .write_u32_be(psn_ptr + 4, PPC_CURRENT_PROCESS_PSN_LOW + 1)
            .unwrap();

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.handled_import_count, 1);
        assert_eq!(probe.unsupported_import_index, None);
        assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_PROC_NOT_FOUND_ERR));
    }

    #[test]
    fn hle_import_runner_handles_display_manager_gdevice_lookup() {
        let pef = synthetic_pef_with_import(b"DMGetGDeviceByDisplayID");
        let mut loaded = load_pef_application(&pef).unwrap();
        let gdevice_out_ptr = PPC_DATA_BASE + 0x1000;
        loaded.memory.add_region(gdevice_out_ptr, vec![0; 4]);
        loaded.cpu.gpr[3] = 1;
        loaded.cpu.gpr[4] = gdevice_out_ptr;
        loaded.cpu.gpr[5] = 1;

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.handled_import_count, 1);
        assert_eq!(probe.unsupported_import_index, None);
        assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_NO_ERR));
        assert_eq!(
            loaded.memory.read_u32_be(gdevice_out_ptr),
            Some(PPC_MAIN_GDEVICE)
        );

        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded
            .memory
            .write_u32_be(gdevice_out_ptr, 0xa5a5_5a5a)
            .unwrap();
        loaded.cpu.gpr[3] = PPC_DSP_DISPLAY_ID + 1;
        loaded.cpu.gpr[4] = gdevice_out_ptr;
        loaded.cpu.gpr[5] = 0;
        run_test_import(
            &mut loaded,
            PpcImportDispatcherTarget::DMGetGDeviceByDisplayID,
        );
        assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_PARAM_ERR));
        assert_eq!(
            loaded.memory.read_u32_be(gdevice_out_ptr),
            Some(0xa5a5_5a5a),
            "failed lookup must leave the output untouched"
        );

        loaded.cpu.gpr[3] = PPC_DSP_DISPLAY_ID + 1;
        loaded.cpu.gpr[4] = gdevice_out_ptr;
        loaded.cpu.gpr[5] = 1;
        run_test_import(
            &mut loaded,
            PpcImportDispatcherTarget::DMGetGDeviceByDisplayID,
        );
        assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_NO_ERR));
        assert_eq!(
            loaded.memory.read_u32_be(gdevice_out_ptr),
            Some(PPC_MAIN_GDEVICE),
            "failToMain must resolve an unknown display ID to the main device"
        );
    }

    #[test]
    fn display_manager_display_id_lookup_honors_fail_to_main() {
        let pef = synthetic_pef_with_import(b"DMGetDisplayIDByGDevice");
        let mut loaded = load_pef_application(&pef).unwrap();
        let display_id_out = PPC_DATA_BASE + 0x1000;
        loaded.memory.add_region(display_id_out, vec![0xa5; 4]);
        loaded.cpu.gpr[3] = 0x06ff_0000;
        loaded.cpu.gpr[4] = display_id_out;
        loaded.cpu.gpr[5] = 0;

        run_test_import(
            &mut loaded,
            PpcImportDispatcherTarget::DMGetDisplayIDByGDevice,
        );

        assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_PARAM_ERR));
        assert_eq!(
            loaded.memory.read_u32_be(display_id_out),
            Some(0xa5a5_a5a5),
            "failed lookup must leave the output untouched"
        );

        loaded.cpu.gpr[3] = 0x06ff_0000;
        loaded.cpu.gpr[4] = display_id_out;
        loaded.cpu.gpr[5] = 1;
        run_test_import(
            &mut loaded,
            PpcImportDispatcherTarget::DMGetDisplayIDByGDevice,
        );
        assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_NO_ERR));
        assert_eq!(
            loaded.memory.read_u32_be(display_id_out),
            Some(PPC_DSP_DISPLAY_ID),
            "failToMain must resolve an unknown GDevice to the main display"
        );
    }

