        assert_eq!(probe.draw_sprocket_trace.len(), 1);
        let trace = &probe.draw_sprocket_trace[0];
        assert_eq!(trace.action, "find_best_context");
        assert_eq!(trace.result, PPC_DSP_CONTEXT_NOT_FOUND_ERR);
        assert_eq!(trace.context, None);
