    #[test]
    fn display_manager_get_and_mode_list_follow_every_live_screen_depth() {
        for depth in [1, 2, 4, 8, 16] {
            let get_pef = synthetic_pef_with_import(b"DMGetDisplayMode");
            let mut loaded = load_pef_application_with_config(
                &get_pef,
                PpcLoadConfig {
                    screen_depth: depth,
                    ..PpcLoadConfig::default()
                },
            )
            .unwrap();
            let switch_info = PPC_DATA_BASE + 0x1000;
            loaded.memory.add_region(switch_info, vec![0xa5; 16]);
            loaded.cpu.gpr[3] = PPC_MAIN_GDEVICE;
            loaded.cpu.gpr[4] = switch_info;

            let probe = loaded.run_with_hle_imports(64);

            assert_eq!(probe.handled_import_count, 1, "depth {depth}");
            assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_NO_ERR));
            let depth_mode = loaded
                .memory
                .read_u32_be(PPC_MAIN_GDEVICE_RECORD + 42)
                .unwrap();
            assert_eq!(
                loaded.memory.read_u16_be(switch_info),
                Some(depth_mode as u16),
                "depth {depth}"
            );
            assert_eq!(
                loaded.memory.read_u32_be(switch_info + 2),
                Some(PPC_DM_CURRENT_DISPLAY_MODE_ID)
            );
            assert_eq!(
                loaded.memory.read_u32_be(switch_info + 8),
                loaded.memory.read_u32_be(PPC_MAIN_PIXMAP)
            );

            let list_pef = synthetic_pef_with_import(b"DMNewDisplayModeList");
            let mut loaded = load_pef_application_with_config(
                &list_pef,
                PpcLoadConfig {
                    screen_depth: depth,
                    ..PpcLoadConfig::default()
                },
            )
            .unwrap();
            let outputs = PPC_DATA_BASE + 0x1200;
            loaded.memory.add_region(outputs, vec![0; 8]);
            loaded.cpu.gpr[3] = PPC_DSP_DISPLAY_ID;
            loaded.cpu.gpr[4] = 0;
            loaded.cpu.gpr[5] = 0;
            loaded.cpu.gpr[6] = outputs;
            loaded.cpu.gpr[7] = outputs + 4;

            let probe = loaded.run_with_hle_imports(64);

            assert_eq!(probe.handled_import_count, 1, "depth {depth}");
            assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_NO_ERR));
            assert_eq!(loaded.memory.read_u32_be(outputs), Some(1));
            let list = loaded.memory.read_u32_be(outputs + 4).unwrap();
            assert_eq!(
                loaded.memory.read_u32_be(list),
                Some(PPC_DM_MODE_LIST_MAGIC)
            );
            let mode = ppc_dm_live_display_mode(&mut loaded.memory, PPC_MAIN_GDEVICE).unwrap();
            let listed_switch = list + PPC_DM_MODE_LIST_SWITCH_INFO_OFFSET;
            let resolution = list + PPC_DM_MODE_LIST_RESOLUTION_INFO_OFFSET;
            let timing = list + PPC_DM_MODE_LIST_TIMING_INFO_OFFSET;
            let vp_block = list + PPC_DM_MODE_LIST_VP_BLOCK_OFFSET;
            assert_eq!(
                loaded.memory.read_u16_be(listed_switch),
                Some(mode.depth_mode as u16)
            );
            assert_eq!(
                loaded.memory.read_u32_be(listed_switch + 2),
                Some(mode.display_mode_id)
            );
            assert_eq!(
                loaded.memory.read_u32_be(listed_switch + 8),
                Some(mode.base_addr)
            );
            assert_eq!(loaded.memory.read_u32_be(resolution + 8), Some(mode.width));
            assert_eq!(
                loaded.memory.read_u32_be(resolution + 12),
                Some(mode.height)
            );
            assert_eq!(
                loaded.memory.read_u32_be(resolution + 20),
                Some(mode.depth_mode)
            );
            assert_eq!(
                loaded.memory.read_u32_be(timing),
                Some(mode.display_mode_id)
            );
            assert_eq!(
                loaded.memory.read_u16_be(vp_block + 4),
                Some(mode.row_bytes)
            );
            assert_eq!(
                ppc_read_rect(&mut loaded.memory, vp_block + 6),
                Some(mode.bounds)
            );
            assert_eq!(loaded.memory.read_u16_be(vp_block + 14), Some(0));
            assert_eq!(loaded.memory.read_u16_be(vp_block + 16), Some(0));
            assert_eq!(loaded.memory.read_u32_be(vp_block + 18), Some(0));
            assert_eq!(loaded.memory.read_u32_be(vp_block + 22), Some(72 << 16));
            assert_eq!(loaded.memory.read_u32_be(vp_block + 26), Some(72 << 16));
            assert_eq!(
                loaded.memory.read_u16_be(vp_block + 30),
                Some(mode.pixel_type)
            );
            assert_eq!(
                loaded.memory.read_u16_be(vp_block + 32),
                Some(mode.pixel_size)
            );
            assert_eq!(
                loaded.memory.read_u16_be(vp_block + 34),
                Some(mode.component_count)
            );
            assert_eq!(
                loaded.memory.read_u16_be(vp_block + 36),
                Some(mode.component_size)
            );
        }
    }

    #[test]
    fn display_manager_check_accepts_only_the_live_timing_and_depth_mode() {
        let pef = synthetic_pef_with_import(b"DMCheckDisplayMode");
        let mut loaded = load_pef_application_with_config(
            &pef,
            PpcLoadConfig {
                screen_depth: 4,
                ..PpcLoadConfig::default()
            },
        )
        .unwrap();
        let outputs = PPC_DATA_BASE + 0x1000;
        loaded.memory.add_region(outputs, vec![0xa5; 8]);
        let depth_mode = loaded
            .memory
            .read_u32_be(PPC_MAIN_GDEVICE_RECORD + 42)
            .unwrap();
        loaded.cpu.gpr[3] = PPC_MAIN_GDEVICE;
        loaded.cpu.gpr[4] = PPC_DM_CURRENT_DISPLAY_MODE_ID;
        loaded.cpu.gpr[5] = depth_mode;
        loaded.cpu.gpr[6] = outputs;
        loaded.cpu.gpr[7] = 0;
        loaded.cpu.gpr[8] = outputs + 4;

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.handled_import_count, 1);
        assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_NO_ERR));
        assert_eq!(
            loaded.memory.read_u32_be(outputs),
            Some(PPC_DM_NO_SWITCH_CONFIRM_MASK)
        );
        assert_eq!(loaded.memory.read_u8(outputs + 4), Some(1));

        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.cpu.gpr[3] = PPC_MAIN_GDEVICE;
        loaded.cpu.gpr[4] = PPC_DM_CURRENT_DISPLAY_MODE_ID + 1;
        loaded.cpu.gpr[5] = depth_mode;
        loaded.cpu.gpr[6] = outputs;
        loaded.cpu.gpr[7] = 0;
        loaded.cpu.gpr[8] = outputs + 4;

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.handled_import_count, 1);
        assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_NO_ERR));
        assert_eq!(
            loaded.memory.read_u32_be(outputs),
            Some(PPC_DM_DEPTH_NOT_AVAILABLE_MASK)
        );
        assert_eq!(loaded.memory.read_u8(outputs + 4), Some(0));

        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.memory.write_u32_be(outputs, 0xa5a5_5a5a).unwrap();
        loaded.memory.write_u8(outputs + 4, 0xc3).unwrap();
        loaded.cpu.gpr[3] = PPC_MAIN_GDEVICE;
        loaded.cpu.gpr[4] = PPC_DM_CURRENT_DISPLAY_MODE_ID;
        loaded.cpu.gpr[5] = depth_mode;
        loaded.cpu.gpr[6] = outputs;
        loaded.cpu.gpr[7] = 1;
        loaded.cpu.gpr[8] = outputs + 4;

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.handled_import_count, 1);
        assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_PARAM_ERR));
        assert_eq!(loaded.memory.read_u32_be(outputs), Some(0xa5a5_5a5a));
        assert_eq!(loaded.memory.read_u8(outputs + 4), Some(0xc3));
    }

    #[test]
    fn display_manager_set_is_an_atomic_noop_outside_the_live_mode() {
        let pef = synthetic_pef_with_import(b"DMSetDisplayMode");
        let mut loaded = load_pef_application_with_config(
            &pef,
            PpcLoadConfig {
                screen_depth: 2,
                ..PpcLoadConfig::default()
            },
        )
        .unwrap();
        let depth_mode_ptr = PPC_DATA_BASE + 0x1000;
        loaded.memory.add_region(depth_mode_ptr, vec![0; 4]);
        let depth_mode = loaded
            .memory
            .read_u32_be(PPC_MAIN_GDEVICE_RECORD + 42)
            .unwrap();
        loaded
            .memory
            .write_u32_be(depth_mode_ptr, depth_mode)
            .unwrap();
        let gdevice_before = ppc_memory_read_bytes(
            &mut loaded.memory,
            PPC_MAIN_GDEVICE_RECORD,
            PPC_GDEVICE_SIZE,
        )
        .unwrap();
        let pixmap_before =
            ppc_memory_read_bytes(&mut loaded.memory, PPC_MAIN_PIXMAP, PPC_PIXMAP_SIZE).unwrap();
        let screen_row_bytes =
            u32::from(loaded.memory.read_u16_be(PPC_MAIN_PIXMAP + 4).unwrap() & 0x3fff);
        let screen_before =
            ppc_memory_read_bytes(&mut loaded.memory, PPC_MAIN_SCREEN_BASE, screen_row_bytes)
                .unwrap();
        loaded.cpu.gpr[3] = PPC_MAIN_GDEVICE;
        loaded.cpu.gpr[4] = PPC_DM_CURRENT_DISPLAY_MODE_ID;
        loaded.cpu.gpr[5] = depth_mode_ptr;
        loaded.cpu.gpr[6] = 0;
        loaded.cpu.gpr[7] = 0;

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.handled_import_count, 1);
        assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_NO_ERR));
        assert_eq!(loaded.memory.read_u32_be(depth_mode_ptr), Some(depth_mode));

        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.cpu.gpr[3] = PPC_MAIN_GDEVICE;
        loaded.cpu.gpr[4] = PPC_DM_CURRENT_DISPLAY_MODE_ID + 1;
        loaded.cpu.gpr[5] = depth_mode_ptr;
        loaded.cpu.gpr[6] = 0;
        loaded.cpu.gpr[7] = 0;

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.handled_import_count, 1);
        assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_DM_MODE_NOT_FOUND_ERR));
        assert_eq!(loaded.memory.read_u32_be(depth_mode_ptr), Some(depth_mode));
        assert_eq!(
            ppc_memory_read_bytes(
                &mut loaded.memory,
                PPC_MAIN_GDEVICE_RECORD,
                PPC_GDEVICE_SIZE,
            )
            .unwrap(),
            gdevice_before
        );
        assert_eq!(
            ppc_memory_read_bytes(&mut loaded.memory, PPC_MAIN_PIXMAP, PPC_PIXMAP_SIZE).unwrap(),
            pixmap_before
        );
        assert_eq!(
            ppc_memory_read_bytes(&mut loaded.memory, PPC_MAIN_SCREEN_BASE, screen_row_bytes,)
                .unwrap(),
            screen_before
        );

        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.memory.write_u32_be(depth_mode_ptr, 16).unwrap();
        loaded.cpu.gpr[3] = PPC_MAIN_GDEVICE;
        loaded.cpu.gpr[4] = PPC_DM_CURRENT_DISPLAY_MODE_ID;
        loaded.cpu.gpr[5] = depth_mode_ptr;
        loaded.cpu.gpr[6] = 0;
        loaded.cpu.gpr[7] = 0;

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.handled_import_count, 1);
        assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_DM_MODE_NOT_FOUND_ERR));
        assert_eq!(loaded.memory.read_u32_be(depth_mode_ptr), Some(16));
        assert_eq!(
            ppc_memory_read_bytes(
                &mut loaded.memory,
                PPC_MAIN_GDEVICE_RECORD,
                PPC_GDEVICE_SIZE,
            )
            .unwrap(),
            gdevice_before
        );
        assert_eq!(
            ppc_memory_read_bytes(&mut loaded.memory, PPC_MAIN_PIXMAP, PPC_PIXMAP_SIZE).unwrap(),
            pixmap_before
        );
        assert_eq!(
            ppc_memory_read_bytes(&mut loaded.memory, PPC_MAIN_SCREEN_BASE, screen_row_bytes,)
                .unwrap(),
            screen_before
        );

        loaded
            .memory
            .write_u32_be(depth_mode_ptr, depth_mode)
            .unwrap();
        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.cpu.gpr[3] = PPC_MAIN_GDEVICE;
        loaded.cpu.gpr[4] = PPC_DM_CURRENT_DISPLAY_MODE_ID;
        loaded.cpu.gpr[5] = depth_mode_ptr;
        loaded.cpu.gpr[6] = PPC_DATA_BASE + 0x2000;
        loaded.cpu.gpr[7] = 0;

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.handled_import_count, 1);
        assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_PARAM_ERR));
        assert_eq!(loaded.memory.read_u32_be(depth_mode_ptr), Some(depth_mode));
        assert_eq!(
            ppc_memory_read_bytes(
                &mut loaded.memory,
                PPC_MAIN_GDEVICE_RECORD,
                PPC_GDEVICE_SIZE,
            )
            .unwrap(),
            gdevice_before,
            "the scalar reserved parameter must not be dereferenced as VDSwitchInfo"
        );
        assert_eq!(
            ppc_memory_read_bytes(&mut loaded.memory, PPC_MAIN_PIXMAP, PPC_PIXMAP_SIZE).unwrap(),
            pixmap_before
        );
        assert_eq!(
            ppc_memory_read_bytes(&mut loaded.memory, PPC_MAIN_SCREEN_BASE, screen_row_bytes,)
                .unwrap(),
            screen_before
        );
    }

    pub(crate) fn synthetic_pef() -> Vec<u8> {
        synthetic_pef_with_import(b"TestImport")
    }

    fn synthetic_pef_with_initializer() -> Vec<u8> {
        let mut pef = synthetic_pef();
        // The synthetic loader section begins at $80. Reuse its main TVector
        // as a valid initializer TVector so loading exercises CFM's startup
        // fragment and InitBlock allocations without executing the code.
        write_i32(&mut pef, 0x80 + 8, 1);
        write_u32(&mut pef, 0x80 + 12, 0);
        pef
    }

    fn assert_ppc_bytes_equal(memory: &mut PpcSectionMem, start: u32, len: u32, expected: u8) {
        for offset in 0..len {
            assert_eq!(memory.read_u8(start + offset), Some(expected));
        }
    }

    #[test]
    fn stdclib_allocations_are_immediately_process_owned_and_cross_isa_visible() {
        let pef = synthetic_pef_with_library_import(b"StdCLib", b"malloc");
        let mut native = load_pef_application(&pef).unwrap();
        let mut context = ProcessContext::default();
        native.attach_process_context(&mut context);
        let detached = context.memory_manager_mut().detached_clone();
        native.set_last_mem_error(PPC_PARAM_ERR);

        native.cpu.gpr[3] = 8;
        run_test_import(&mut native, PpcImportDispatcherTarget::StdMalloc);
        let original = native.cpu.gpr[3];
        assert_ne!(original, 0);
        assert!(context
            .memory_manager_mut()
            .native_allocator_snapshot()
            .unwrap()
            .ptrs
            .iter()
            .any(|record| record.ptr == original && record.size == 8));
        assert!(!detached
            .native_allocator()
            .unwrap()
            .ptrs
            .iter()
            .any(|record| record.ptr == original));

        let shared = native.memory.shared_view();
        let mut classic_bus = MacMemoryBus::new(0x2000);
        classic_bus.attach_guest_address_space(shared);
        context.attach_classic_memory_bus(&mut classic_bus);
        classic_bus.write_bytes(original, b"payload!");
        assert_eq!(
            ppc_memory_read_bytes(&mut native.memory, original, 8),
            Some(b"payload!".to_vec())
        );

        native.cpu.gpr[3] = original;
        native.cpu.gpr[4] = u32::MAX;
        run_test_import(&mut native, PpcImportDispatcherTarget::StdRealloc);
        assert_eq!(native.cpu.gpr[3], 0);
        assert_eq!(classic_bus.read_bytes(original, 8), b"payload!");
        assert!(context
            .memory_manager_mut()
            .native_allocator_snapshot()
            .unwrap()
            .ptrs
            .iter()
            .any(|record| record.ptr == original));

        native.cpu.gpr[3] = original;
        native.cpu.gpr[4] = 24;
        run_test_import(&mut native, PpcImportDispatcherTarget::StdRealloc);
        let replacement = native.cpu.gpr[3];
        assert_ne!(replacement, 0);
        assert_ne!(replacement, original);
        assert_eq!(classic_bus.read_bytes(replacement, 8), b"payload!");
        let allocator = context
            .memory_manager_mut()
            .native_allocator_snapshot()
            .unwrap();
        assert!(allocator
            .ptrs
            .iter()
            .any(|record| record.ptr == replacement && record.size == 24));
        assert!(!allocator.ptrs.iter().any(|record| record.ptr == original));

        native.cpu.gpr[3] = 4;
        native.cpu.gpr[4] = 4;
        run_test_import(&mut native, PpcImportDispatcherTarget::StdCalloc);
        let zeroed = native.cpu.gpr[3];
        assert_ne!(zeroed, 0);
        assert_eq!(classic_bus.read_bytes(zeroed, 16), vec![0; 16]);
        native.memory.write_u8(zeroed, 0x5a).unwrap();
        assert_eq!(classic_bus.read_byte(zeroed), 0x5a);

        native.cpu.gpr[3] = replacement;
        run_test_import(&mut native, PpcImportDispatcherTarget::StdFree);
        assert!(!context
            .memory_manager_mut()
            .native_allocator_snapshot()
            .unwrap()
            .ptrs
            .iter()
            .any(|record| record.ptr == replacement));
        assert!(detached.native_allocator().unwrap().ptrs.is_empty());
        assert_eq!(native.last_mem_error(), PPC_PARAM_ERR);
    }

    #[test]
    fn stdio_records_advance_the_process_owned_heap_immediately() {
        let pef = synthetic_pef_with_library_import(b"StdCLib", b"fopen");
        let mut native = load_pef_application(&pef).unwrap();
        let mut context = ProcessContext::default();
        native.attach_process_context(&mut context);
        let detached = context.memory_manager_mut().detached_clone();
        let heap_before = context
            .memory_manager_mut()
            .native_heap_state()
            .unwrap()
            .heap_cursor;
        let path = PPC_DATA_BASE + 0x2000;
        let mode = path + 0x20;
        native.memory.add_region(path, vec![0; 0x100]);
        native.memory.write_bytes(path, b"test.bin\0").unwrap();
        native.memory.write_bytes(mode, b"rb\0").unwrap();
        native.vfs_files.push(PpcVfsFileRecord {
            path: "Volume/test.bin".to_string(),
            data: (b"payload".to_vec()).into(),
            creator: 0,
            file_type: 0,
            finder_flags: 0,
            dirty: false,
        });
        native.cpu.gpr[3] = path;
        native.cpu.gpr[4] = mode;

        run_test_import(&mut native, PpcImportDispatcherTarget::StdIoCompatibility);

        let stream = native.cpu.gpr[3];
        assert_ne!(stream, 0);
        let heap_after = context
            .memory_manager_mut()
            .native_heap_state()
            .unwrap()
            .heap_cursor;
        assert!(heap_after > heap_before);
        assert_eq!(native.heap_cursor(), heap_after);
        assert_eq!(
            detached.native_heap_state().unwrap().heap_cursor,
            heap_before
        );
    }

    #[test]
    fn stdclib_heap_and_string_helpers_cover_guest_abi_edges() {
        for (name, target) in [
            ("malloc", PpcImportDispatcherTarget::StdMalloc),
            ("free", PpcImportDispatcherTarget::StdFree),
            ("calloc", PpcImportDispatcherTarget::StdCalloc),
            ("realloc", PpcImportDispatcherTarget::StdRealloc),
            ("strncpy", PpcImportDispatcherTarget::StdStrncpy),
            ("strncat", PpcImportDispatcherTarget::StdStrncat),
            ("atoi", PpcImportDispatcherTarget::StdAtoi),
            ("getenv", PpcImportDispatcherTarget::StdGetenv),
        ] {
            assert_eq!(dispatcher_target_for_import("StdCLib", name), target);
        }

        let mut loaded = load_pef_application(&synthetic_pef_with_import(b"malloc")).unwrap();

        let source = PPC_DATA_BASE + 0x2000;
        let destination = PPC_DATA_BASE + 0x2100;
        loaded.memory.add_region(source, b"abc\0\0\0".to_vec());
        loaded.memory.add_region(destination, vec![0xaa; 16]);
        assert_eq!(
            ppc_std_strncpy(&mut loaded.memory, destination, source, 6),
            destination
        );
        assert_eq!(
            ppc_memory_read_bytes(&mut loaded.memory, destination, 6),
            Some(b"abc\0\0\0".to_vec())
        );
        loaded.memory.write_bytes(destination, &[0xaa; 6]).unwrap();
        assert_eq!(
            ppc_std_strncpy(&mut loaded.memory, destination, source, 2),
            destination
        );
        assert_eq!(
            ppc_memory_read_bytes(&mut loaded.memory, destination, 2),
            Some(b"ab".to_vec())
        );
        assert_eq!(
            ppc_std_strncpy(&mut loaded.memory, destination, source, 0),
            destination
        );
        loaded
            .memory
            .write_bytes(destination, b"xy\0\0\0\0")
            .unwrap();
        assert_eq!(
            ppc_std_strncat(&mut loaded.memory, destination, source, 2),
            destination
        );
        assert_eq!(
            ppc_memory_read_bytes(&mut loaded.memory, destination, 5),
            Some(b"xyab\0".to_vec())
        );
        assert_eq!(
            ppc_std_strncat(&mut loaded.memory, destination, source, 0),
            destination
        );

        let atoi_ptr = PPC_DATA_BASE + 0x2200;
        loaded.memory.add_region(atoi_ptr, vec![0; 32]);
        loaded.memory.write_bytes(atoi_ptr, b"  -123x\0").unwrap();
        assert_eq!(ppc_std_atoi(&mut loaded.memory, atoi_ptr), (-123i32) as u32);
        loaded
            .memory
            .write_bytes(atoi_ptr, b"2147483648\0")
            .unwrap();
        assert_eq!(ppc_std_atoi(&mut loaded.memory, atoi_ptr), i32::MAX as u32);
        loaded.memory.write_bytes(atoi_ptr, b"nope\0").unwrap();
        assert_eq!(ppc_std_atoi(&mut loaded.memory, atoi_ptr), 0);
        assert_eq!(
            PpcImportDispatcherTarget::StdGetenv,
            dispatcher_target_for_import("StdCLib", "getenv")
        );
    }

    #[test]
    fn stdclib_string_search_helpers_cover_guest_abi_edges() {
        for (name, target) in [
            ("memchr", PpcImportDispatcherTarget::StdMemchr),
            ("strchr", PpcImportDispatcherTarget::StdStrchr),
            ("strrchr", PpcImportDispatcherTarget::StdStrrchr),
            ("strspn", PpcImportDispatcherTarget::StdStrspn),
            ("strcspn", PpcImportDispatcherTarget::StdStrcspn),
            ("strpbrk", PpcImportDispatcherTarget::StdStrpbrk),
            ("strstr", PpcImportDispatcherTarget::StdStrstr),
        ] {
            assert_eq!(dispatcher_target_for_import("StdCLib", name), target);
        }

        let mut loaded =
            load_pef_application(&synthetic_pef_with_library_import(b"StdCLib", b"memchr"))
                .unwrap();
        let string = PPC_DATA_BASE + 0x2400;
        let set = string + 0x40;
        let reject = string + 0x50;
        let needle = string + 0x60;
        let empty = string + 0x80;
        loaded.memory.add_region(string, vec![0; 0x100]);
        loaded.memory.write_bytes(string, b"abc123abc\0").unwrap();
        loaded.memory.write_bytes(set, b"abc\0").unwrap();
        loaded.memory.write_bytes(reject, b"13\0").unwrap();
        loaded.memory.write_bytes(needle, b"123a\0").unwrap();

        assert_eq!(
            ppc_std_memchr(&mut loaded.memory, string, b'c', 3),
            string + 2
        );
        assert_eq!(ppc_std_memchr(&mut loaded.memory, string, b'c', 2), 0);
        assert_eq!(ppc_std_memchr(&mut loaded.memory, string, b'a', 0), 0);
        assert_eq!(
            ppc_std_strchr(&mut loaded.memory, string, b'a', false),
            string
        );
        assert_eq!(
            ppc_std_strchr(&mut loaded.memory, string, b'a', true),
            string + 6
        );
        assert_eq!(
            ppc_std_strchr(&mut loaded.memory, string, 0, false),
            string + 9
        );
        assert_eq!(
            ppc_std_strchr(&mut loaded.memory, string, 0, true),
            string + 9
        );
        assert_eq!(ppc_std_strchr(&mut loaded.memory, string, b'z', false), 0);
        assert_eq!(ppc_std_strspn(&mut loaded.memory, string, set, true), 3);
        assert_eq!(ppc_std_strspn(&mut loaded.memory, string, reject, false), 3);
        assert_eq!(ppc_std_strspn(&mut loaded.memory, string, empty, true), 0);
        assert_eq!(ppc_std_strspn(&mut loaded.memory, string, empty, false), 9);
        assert_eq!(
            ppc_std_strpbrk(&mut loaded.memory, string, reject),
            string + 3
        );
        assert_eq!(ppc_std_strpbrk(&mut loaded.memory, string, empty), 0);
        assert_eq!(
            ppc_std_strstr(&mut loaded.memory, string, needle),
            string + 3
        );
        assert_eq!(ppc_std_strstr(&mut loaded.memory, string, empty), string);
        loaded.memory.write_bytes(needle, b"missing\0").unwrap();
        assert_eq!(ppc_std_strstr(&mut loaded.memory, string, needle), 0);

        for (name, argument, count, expected) in [
            (b"memchr".as_slice(), 0x163, 9, string + 2),
            (b"strchr".as_slice(), u32::from(b'a'), 0, string),
            (b"strrchr".as_slice(), u32::from(b'a'), 0, string + 6),
            (b"strspn".as_slice(), set, 0, 3),
            (b"strcspn".as_slice(), reject, 0, 3),
            (b"strpbrk".as_slice(), reject, 0, string + 3),
            (b"strstr".as_slice(), needle, 0, string + 3),
        ] {
            let mut imported =
                load_pef_application(&synthetic_pef_with_library_import(b"StdCLib", name)).unwrap();
            imported.memory.add_region(string, vec![0; 0x100]);
            imported.memory.write_bytes(string, b"abc123abc\0").unwrap();
            imported.memory.write_bytes(set, b"abc\0").unwrap();
            imported.memory.write_bytes(reject, b"13\0").unwrap();
            imported.memory.write_bytes(needle, b"123a\0").unwrap();
            imported.cpu.gpr[3] = string;
            imported.cpu.gpr[4] = argument;
            imported.cpu.gpr[5] = count;
            imported.cpu.pc = imported.entry_pc;
            imported.cpu.lr = PPC_HALT_PC;

            let result = imported.run_with_hle_imports(64);

            assert_eq!(result.handled_import_count, 1, "{}", decode_mac_roman(name));
            assert_eq!(imported.cpu.gpr[3], expected, "{}", decode_mac_roman(name));
        }
    }

    #[test]
    fn stdclib_stdio_uses_host_metadata_and_preserves_the_guest_iob_layout() {
        let mut loaded = load_pef_application(&synthetic_pef_with_loader(
            synthetic_loader_with_symbol_class(b"StdCLib", b"_iob", 1, &[sm_index_reloc(0x30, 0)]),
        ))
        .unwrap();
        assert_eq!(loaded.imports[0].address, PPC_STDIO_IOB_ADDR);
        assert_eq!(loaded.process_file_system.stdio_streams.len(), 3);
        assert!(loaded
            .stdio_streams
            .contains_key(&(PPC_STDIO_IOB_ADDR + PPC_STDIO_FILE_SIZE)));
        assert!(loaded
            .stdio_streams
            .contains_key(&(PPC_STDIO_IOB_ADDR + 2 * PPC_STDIO_FILE_SIZE)));
        assert_eq!(
            ppc_memory_read_bytes(
                &mut loaded.memory,
                PPC_STDIO_IOB_ADDR,
                3 * PPC_STDIO_FILE_SIZE,
            ),
            Some(vec![0; (3 * PPC_STDIO_FILE_SIZE) as usize])
        );

        let mut cpu = PpcCpu::new();
        let mut files = Vec::new();
        let mut vfs_files: ProcessVfsFileRecords = vec![PpcVfsFileRecord {
            path: "Volume/test.bin".to_string(),
            data: (b"abcdef".to_vec()).into(),
            creator: 0,
            file_type: 0,
            finder_flags: 0,
            dirty: false,
        }]
        .into();
        let mut next_file_ref_num = PPC_FIRST_FILE_REF_NUM;
        let path = PPC_DATA_BASE + 0x2000;
        let mode = PPC_DATA_BASE + 0x2020;
        let destination = PPC_DATA_BASE + 0x2040;
        loaded.memory.add_region(path, vec![0; 0x100]);
        loaded.memory.write_bytes(path, b"test.bin\0").unwrap();
        loaded.memory.write_bytes(mode, b"rb\0").unwrap();

        cpu.gpr[3] = path;
        cpu.gpr[4] = mode;
        let fopen = compatibility_binding(
            "StdCLib",
            "fopen",
            PpcImportDispatcherTarget::StdIoCompatibility,
        );
        let PpcImportAction::Return(stream) = ppc_dispatch_stdio_compatibility(
            &fopen,
            &mut cpu,
            &mut loaded.memory,
            test_heap_cursor!(loaded),
            test_heap_limit!(loaded),
            &mut files,
            &mut vfs_files,
            &mut next_file_ref_num,
            &mut loaded.process_file_system.stdio_streams,
        ) else {
            panic!("fopen did not return a stream");
        };
        assert_ne!(stream, 0);

        cpu.gpr[3] = destination;
        cpu.gpr[4] = 2;
        cpu.gpr[5] = 2;
        cpu.gpr[6] = stream;
        let fread = compatibility_binding(
            "StdCLib",
            "fread",
            PpcImportDispatcherTarget::StdIoCompatibility,
        );
        assert_eq!(
            ppc_dispatch_stdio_compatibility(
                &fread,
                &mut cpu,
                &mut loaded.memory,
                test_heap_cursor!(loaded),
                test_heap_limit!(loaded),
                &mut files,
                &mut vfs_files,
                &mut next_file_ref_num,
                &mut loaded.process_file_system.stdio_streams,
            ),
            PpcImportAction::Return(2)
        );
        assert_eq!(
            ppc_memory_read_bytes(&mut loaded.memory, destination, 4),
            Some(b"abcd".to_vec())
        );

        let fwrite = compatibility_binding(
            "StdCLib",
            "fwrite",
            PpcImportDispatcherTarget::StdIoCompatibility,
        );
        loaded.memory.write_bytes(destination, b"XY").unwrap();
        cpu.gpr[3] = destination;
        cpu.gpr[4] = 1;
        cpu.gpr[5] = 2;
        cpu.gpr[6] = stream;
        assert_eq!(
            ppc_dispatch_stdio_compatibility(
                &fwrite,
                &mut cpu,
                &mut loaded.memory,
                test_heap_cursor!(loaded),
                test_heap_limit!(loaded),
                &mut files,
                &mut vfs_files,
                &mut next_file_ref_num,
                &mut loaded.process_file_system.stdio_streams,
            ),
            PpcImportAction::Return(0)
        );
        assert_eq!(vfs_files[0].data, b"abcdef");

        loaded.memory.write_bytes(mode, b"r+\0").unwrap();
        cpu.gpr[3] = path;
        cpu.gpr[4] = mode;
        let PpcImportAction::Return(read_write_stream) = ppc_dispatch_stdio_compatibility(
            &fopen,
            &mut cpu,
            &mut loaded.memory,
            test_heap_cursor!(loaded),
            test_heap_limit!(loaded),
            &mut files,
            &mut vfs_files,
            &mut next_file_ref_num,
            &mut loaded.process_file_system.stdio_streams,
        ) else {
            panic!("fopen did not return the read/write stream");
        };
        loaded.memory.write_bytes(destination, b"XY").unwrap();
        cpu.gpr[3] = destination;
        cpu.gpr[4] = 1;
        cpu.gpr[5] = 2;
        cpu.gpr[6] = read_write_stream;
        assert_eq!(
            ppc_dispatch_stdio_compatibility(
                &fwrite,
                &mut cpu,
                &mut loaded.memory,
                test_heap_cursor!(loaded),
                test_heap_limit!(loaded),
                &mut files,
                &mut vfs_files,
                &mut next_file_ref_num,
                &mut loaded.process_file_system.stdio_streams,
            ),
            PpcImportAction::Return(2)
        );
        assert_eq!(vfs_files[0].data, b"XYcdef");

        let format = PPC_DATA_BASE + 0x2300;
        loaded.memory.add_region(format, b"%20000d\0".to_vec());
        let fprintf = compatibility_binding(
            "StdCLib",
            "fprintf",
            PpcImportDispatcherTarget::StdIoCompatibility,
        );
        cpu.gpr[3] = read_write_stream;
        cpu.gpr[4] = format;
        cpu.gpr[5] = 0;
        assert_eq!(
            ppc_dispatch_stdio_compatibility(
                &fprintf,
                &mut cpu,
                &mut loaded.memory,
                test_heap_cursor!(loaded),
                test_heap_limit!(loaded),
                &mut files,
                &mut vfs_files,
                &mut next_file_ref_num,
                &mut loaded.process_file_system.stdio_streams,
            ),
            PpcImportAction::Return(u32::MAX)
        );
        assert_eq!(vfs_files[0].data, b"XYcdef");

        loaded.memory.write_bytes(mode, b"invalid\0").unwrap();
        cpu.gpr[3] = path;
        cpu.gpr[4] = mode;
        assert_eq!(
            ppc_dispatch_stdio_compatibility(
                &fopen,
                &mut cpu,
                &mut loaded.memory,
                test_heap_cursor!(loaded),
                test_heap_limit!(loaded),
                &mut files,
                &mut vfs_files,
                &mut next_file_ref_num,
                &mut loaded.process_file_system.stdio_streams,
            ),
            PpcImportAction::Return(0)
        );
        assert_eq!(vfs_files.len(), 1);
        assert_eq!(vfs_files[0].data, b"XYcdef");

        loaded.memory.write_bytes(path, b"missing.bin\0").unwrap();
        loaded.memory.write_bytes(mode, b"r+\0").unwrap();
        cpu.gpr[3] = path;
        cpu.gpr[4] = mode;
        assert_eq!(
            ppc_dispatch_stdio_compatibility(
                &fopen,
                &mut cpu,
                &mut loaded.memory,
                test_heap_cursor!(loaded),
                test_heap_limit!(loaded),
                &mut files,
                &mut vfs_files,
                &mut next_file_ref_num,
                &mut loaded.process_file_system.stdio_streams,
            ),
            PpcImportAction::Return(0)
        );
        assert_eq!(vfs_files.len(), 1);

        loaded.memory.write_bytes(mode, b"w\0").unwrap();
        loaded.memory.write_bytes(path, b"test.bin\0").unwrap();
        let saved_heap_cursor = loaded.heap_cursor();
        loaded.set_heap_cursor(test_heap_limit!(loaded).saturating_sub(8));
        cpu.gpr[3] = path;
        cpu.gpr[4] = mode;
        assert_eq!(
            ppc_dispatch_stdio_compatibility(
                &fopen,
                &mut cpu,
                &mut loaded.memory,
                test_heap_cursor!(loaded),
                test_heap_limit!(loaded),
                &mut files,
                &mut vfs_files,
                &mut next_file_ref_num,
                &mut loaded.process_file_system.stdio_streams,
            ),
            PpcImportAction::Return(0)
        );
        loaded.set_heap_cursor(saved_heap_cursor);
        assert_eq!(vfs_files[0].data, b"XYcdef");

        cpu.gpr[3] = destination;
        cpu.gpr[4] = 1;
        cpu.gpr[5] = 1;
        cpu.gpr[6] = PPC_STDIO_IOB_ADDR + PPC_STDIO_FILE_SIZE;
        loaded.memory.write_bytes(destination, b"X").unwrap();
        assert_eq!(
            ppc_dispatch_stdio_compatibility(
                &fwrite,
                &mut cpu,
                &mut loaded.memory,
                test_heap_cursor!(loaded),
                test_heap_limit!(loaded),
                &mut files,
                &mut vfs_files,
                &mut next_file_ref_num,
                &mut loaded.process_file_system.stdio_streams,
            ),
            PpcImportAction::Return(1)
        );
        cpu.gpr[3] = 0xdead_beef;
        assert_eq!(
            ppc_dispatch_stdio_compatibility(
                &fwrite,
                &mut cpu,
                &mut loaded.memory,
                test_heap_cursor!(loaded),
                test_heap_limit!(loaded),
                &mut files,
                &mut vfs_files,
                &mut next_file_ref_num,
                &mut loaded.process_file_system.stdio_streams,
            ),
            PpcImportAction::Return(0)
        );
        assert!(loaded
            .stdio_streams
            .get(&(PPC_STDIO_IOB_ADDR + PPC_STDIO_FILE_SIZE))
            .is_some_and(|record| record.error));

        cpu.gpr[3] = stream;
        let ftell = compatibility_binding(
            "StdCLib",
            "ftell",
            PpcImportDispatcherTarget::StdIoCompatibility,
        );
        assert_eq!(
            ppc_dispatch_stdio_compatibility(
                &ftell,
                &mut cpu,
                &mut loaded.memory,
                test_heap_cursor!(loaded),
                test_heap_limit!(loaded),
                &mut files,
                &mut vfs_files,
                &mut next_file_ref_num,
                &mut loaded.process_file_system.stdio_streams,
            ),
            PpcImportAction::Return(4)
        );

        let fclose = compatibility_binding(
            "StdCLib",
            "fclose",
            PpcImportDispatcherTarget::StdIoCompatibility,
        );
        for stream in [
            stream,
            read_write_stream,
            PPC_STDIO_IOB_ADDR + PPC_STDIO_FILE_SIZE,
            PPC_STDIO_IOB_ADDR + 2 * PPC_STDIO_FILE_SIZE,
        ] {
            cpu.gpr[3] = stream;
            assert_eq!(
                ppc_dispatch_stdio_compatibility(
                    &fclose,
                    &mut cpu,
                    &mut loaded.memory,
                    test_heap_cursor!(loaded),
                    test_heap_limit!(loaded),
                    &mut files,
                    &mut vfs_files,
                    &mut next_file_ref_num,
                    &mut loaded.process_file_system.stdio_streams,
                ),
                PpcImportAction::Return(0)
            );
        }
    }

    #[test]
    fn stdclib_ctype_classification_and_conversion_conforms_to_universal_interfaces() {
        // Universal Interfaces 3.4 ctype.h routes.
        let expected_targets = [
            ("isalnum", PpcImportDispatcherTarget::StdIsalnum),
            ("isalpha", PpcImportDispatcherTarget::StdIsalpha),
            ("isascii", PpcImportDispatcherTarget::StdIsascii),
            ("iscntrl", PpcImportDispatcherTarget::StdIscntrl),
            ("isdigit", PpcImportDispatcherTarget::StdIsdigit),
            ("isgraph", PpcImportDispatcherTarget::StdIsgraph),
            ("islower", PpcImportDispatcherTarget::StdIslower),
            ("isprint", PpcImportDispatcherTarget::StdIsprint),
            ("ispunct", PpcImportDispatcherTarget::StdIspunct),
            ("isspace", PpcImportDispatcherTarget::StdIsspace),
            ("isupper", PpcImportDispatcherTarget::StdIsupper),
            ("isxdigit", PpcImportDispatcherTarget::StdIsxdigit),
            ("toascii", PpcImportDispatcherTarget::StdToascii),
        ];

        for (name, target) in &expected_targets {
            assert_eq!(
                dispatcher_target_for_import("StdCLib", name),
                *target,
                "Import StdCLib::{name} should map to expected dispatcher target"
            );
        }

        // Verify character classification flags across the complete byte domain.
        for byte in 0u8..=255 {
            let entry = ppc_ctype_entry(byte);
            let is_upp = (b'A'..=b'Z').contains(&byte);
            let is_low = (b'a'..=b'z').contains(&byte);
            let is_dig = (b'0'..=b'9').contains(&byte);
            let is_wsp = matches!(byte, b' ' | b'\t' | b'\n' | 0x0B | 0x0C | b'\r');
            let is_pun = matches!(byte, 33..=47 | 58..=64 | 91..=96 | 123..=126);
            let is_ctl = matches!(byte, 0..=31 | 127);
            let is_hex = is_dig || (b'a'..=b'f').contains(&byte) || (b'A'..=b'F').contains(&byte);
            let is_bla = byte == b' ';

            assert_eq!(
                (entry & PPC_CTYPE_UPP) != 0,
                is_upp,
                "byte 0x{byte:02x} UPP flag"
            );
            assert_eq!(
                (entry & PPC_CTYPE_LOW) != 0,
                is_low,
                "byte 0x{byte:02x} LOW flag"
            );
            assert_eq!(
                (entry & PPC_CTYPE_DIG) != 0,
                is_dig,
                "byte 0x{byte:02x} DIG flag"
            );
            assert_eq!(
                (entry & PPC_CTYPE_WSP) != 0,
                is_wsp,
                "byte 0x{byte:02x} WSP flag"
            );
            assert_eq!(
                (entry & PPC_CTYPE_PUN) != 0,
                is_pun,
                "byte 0x{byte:02x} PUN flag"
            );
            assert_eq!(
                (entry & PPC_CTYPE_CTL) != 0,
                is_ctl,
                "byte 0x{byte:02x} CTL flag"
            );
            assert_eq!(
                (entry & PPC_CTYPE_HEX) != 0,
                is_hex,
                "byte 0x{byte:02x} HEX flag"
            );
            assert_eq!(
                (entry & PPC_CTYPE_BLA) != 0,
                is_bla,
                "byte 0x{byte:02x} BLA flag"
            );

            if byte >= 128 {
                assert_eq!(entry, 0, "non-ASCII byte 0x{byte:02x} must be 0");
            }
        }

        // Execute every route through a synthetic PEF import.
        for (name, target) in &expected_targets {
            let mut loaded = load_pef_application(&synthetic_pef_with_library_import(
                b"StdCLib",
                name.as_bytes(),
            ))
            .unwrap();

            assert_eq!(loaded.imports[0].dispatcher_target, *target);
            assert_eq!(
                loaded.memory.read_u32_be(PPC_IMPORT_CTYPE_POINTER),
                Some(PPC_IMPORT_CTYPE_TABLE)
            );
            for byte in 0u16..=255 {
                assert_eq!(
                    loaded
                        .memory
                        .read_u8(PPC_IMPORT_CTYPE_TABLE + u32::from(byte)),
                    Some(ppc_ctype_entry(byte as u8))
                );
            }

            let test_inputs: &[(u32, u32)] = match target {
                PpcImportDispatcherTarget::StdIsalnum => &[
                    (u32::from(b'a'), u32::from(PPC_CTYPE_LOW)),
                    (u32::from(b'Z'), u32::from(PPC_CTYPE_UPP)),
                    (u32::from(b'5'), u32::from(PPC_CTYPE_DIG)),
                    (u32::from(b'!'), 0),
                    (u32::from(b' '), 0),
                    (0, 0),
                    (0x80, 0),
                    (0xFF, 0),
                ],
                PpcImportDispatcherTarget::StdIsalpha => &[
                    (u32::from(b'a'), u32::from(PPC_CTYPE_LOW)),
                    (u32::from(b'Z'), u32::from(PPC_CTYPE_UPP)),
                    (u32::from(b'5'), 0),
                    (u32::from(b'?'), 0),
                    (0, 0),
                ],
                PpcImportDispatcherTarget::StdIsascii => &[
                    (0, 1),
                    (0x41, 1),
                    (0x7F, 1),
                    (0x80, 0),
                    (0xFF, 0),
                    (0x100, 0),
                    (0x1234_5678, 0),
                ],
                PpcImportDispatcherTarget::StdIscntrl => &[
                    (0, u32::from(PPC_CTYPE_CTL)),
                    (0x1F, u32::from(PPC_CTYPE_CTL)),
                    (0x7F, u32::from(PPC_CTYPE_CTL)),
                    (u32::from(b' '), 0),
                    (u32::from(b'A'), 0),
                ],
                PpcImportDispatcherTarget::StdIsdigit => &[
                    (u32::from(b'0'), u32::from(PPC_CTYPE_DIG)),
                    (u32::from(b'9'), u32::from(PPC_CTYPE_DIG)),
                    (u32::from(b'/'), 0),
                    (u32::from(b':'), 0),
                    (u32::from(b'a'), 0),
                ],
                PpcImportDispatcherTarget::StdIsgraph => &[
                    (u32::from(b'!'), u32::from(PPC_CTYPE_PUN)),
                    (u32::from(b'~'), u32::from(PPC_CTYPE_PUN)),
                    (u32::from(b'a'), u32::from(PPC_CTYPE_LOW)),
                    (u32::from(b'A'), u32::from(PPC_CTYPE_UPP)),
                    (u32::from(b'0'), u32::from(PPC_CTYPE_DIG)),
                    (u32::from(b' '), 0),
                    (0x1F, 0),
                    (0x7F, 0),
                    (0x80, 0),
                ],
                PpcImportDispatcherTarget::StdIslower => &[
                    (u32::from(b'a'), u32::from(PPC_CTYPE_LOW)),
                    (u32::from(b'z'), u32::from(PPC_CTYPE_LOW)),
                    (u32::from(b'A'), 0),
                    (u32::from(b'0'), 0),
                    (u32::from(b' '), 0),
                ],
                PpcImportDispatcherTarget::StdIsprint => &[
                    (u32::from(b' '), u32::from(PPC_CTYPE_BLA)),
                    (u32::from(b'!'), u32::from(PPC_CTYPE_PUN)),
                    (u32::from(b'~'), u32::from(PPC_CTYPE_PUN)),
                    (u32::from(b'a'), u32::from(PPC_CTYPE_LOW)),
                    (0x1F, 0),
                    (0x7F, 0),
                    (0x80, 0),
                ],
                PpcImportDispatcherTarget::StdIspunct => &[
                    (u32::from(b'!'), u32::from(PPC_CTYPE_PUN)),
                    (u32::from(b'/'), u32::from(PPC_CTYPE_PUN)),
                    (u32::from(b':'), u32::from(PPC_CTYPE_PUN)),
                    (u32::from(b'@'), u32::from(PPC_CTYPE_PUN)),
                    (u32::from(b'['), u32::from(PPC_CTYPE_PUN)),
                    (u32::from(b'`'), u32::from(PPC_CTYPE_PUN)),
                    (u32::from(b'{'), u32::from(PPC_CTYPE_PUN)),
                    (u32::from(b'~'), u32::from(PPC_CTYPE_PUN)),
                    (u32::from(b'a'), 0),
                    (u32::from(b'0'), 0),
                    (u32::from(b' '), 0),
                ],
                PpcImportDispatcherTarget::StdIsspace => &[
                    (u32::from(b' '), u32::from(PPC_CTYPE_WSP)),
                    (u32::from(b'\t'), u32::from(PPC_CTYPE_WSP)),
                    (u32::from(b'\n'), u32::from(PPC_CTYPE_WSP)),
                    (0x0B, u32::from(PPC_CTYPE_WSP)),
                    (0x0C, u32::from(PPC_CTYPE_WSP)),
                    (u32::from(b'\r'), u32::from(PPC_CTYPE_WSP)),
                    (u32::from(b'a'), 0),
                    (0, 0),
                ],
                PpcImportDispatcherTarget::StdIsupper => &[
                    (u32::from(b'A'), u32::from(PPC_CTYPE_UPP)),
                    (u32::from(b'Z'), u32::from(PPC_CTYPE_UPP)),
                    (u32::from(b'a'), 0),
                    (u32::from(b'0'), 0),
                    (u32::from(b' '), 0),
                ],
                PpcImportDispatcherTarget::StdIsxdigit => &[
                    (u32::from(b'0'), u32::from(PPC_CTYPE_HEX)),
                    (u32::from(b'9'), u32::from(PPC_CTYPE_HEX)),
                    (u32::from(b'a'), u32::from(PPC_CTYPE_HEX)),
                    (u32::from(b'f'), u32::from(PPC_CTYPE_HEX)),
                    (u32::from(b'A'), u32::from(PPC_CTYPE_HEX)),
                    (u32::from(b'F'), u32::from(PPC_CTYPE_HEX)),
                    (u32::from(b'g'), 0),
                    (u32::from(b'G'), 0),
                    (u32::from(b' '), 0),
                ],
                PpcImportDispatcherTarget::StdToascii => &[
                    (0x41, 0x41),
                    (0xC1, 0x41),
                    (0x1234_5678, 0x78),
                    (0xFF, 0x7F),
                    (u32::MAX, 0x7F),
                    (0, 0),
                ],
                _ => unreachable!(),
            };

            for &(input, expected) in test_inputs {
                loaded.cpu.gpr[3] = input;
                run_test_import(&mut loaded, target.clone());
                assert_eq!(
                    loaded.cpu.gpr[3], expected,
                    "{name}(0x{input:02x}) expected 0x{expected:x}, got 0x{:x}",
                    loaded.cpu.gpr[3]
                );
            }
            if !matches!(target, PpcImportDispatcherTarget::StdToascii) {
                loaded.cpu.gpr[3] = u32::MAX;
                run_test_import(&mut loaded, target.clone());
                assert_eq!(loaded.cpu.gpr[3], 0, "{name}(EOF)");
            }
        }
    }

    fn synthetic_pef_with_import(symbol_name: &[u8]) -> Vec<u8> {
        synthetic_pef_with_library_import(b"InterfaceLib", symbol_name)
    }

    fn synthetic_pef_with_import_class(symbol_name: &[u8], symbol_class: u8) -> Vec<u8> {
        synthetic_pef_with_loader(synthetic_loader_with_symbol_class(
            b"InterfaceLib",
            symbol_name,
            symbol_class,
            &[sm_index_reloc(0x30, 0)],
        ))
    }

    fn write_test_dsp_context_attributes(
        memory: &mut PpcSectionMem,
        attributes: u32,
        context_attributes: PpcDspContextAttributes,
    ) {
        memory
            .write_u32_be(attributes, context_attributes.frequency)
            .unwrap();
        memory
            .write_u32_be(attributes + 4, context_attributes.width)
            .unwrap();
        memory
            .write_u32_be(attributes + 8, context_attributes.height)
            .unwrap();
        memory
            .write_u32_be(attributes + 28, context_attributes.context_options)
            .unwrap();
        memory
            .write_u32_be(
                attributes + 32,
                context_attributes.back_buffer_best_depth_mask,
            )
            .unwrap();
        memory
            .write_u32_be(attributes + 36, context_attributes.display_best_depth_mask)
            .unwrap();
        memory
            .write_u32_be(attributes + 40, context_attributes.back_buffer_depth)
            .unwrap();
        memory
            .write_u32_be(attributes + 44, context_attributes.display_depth)
            .unwrap();
        memory
            .write_u32_be(attributes + 48, context_attributes.page_count)
            .unwrap();
    }

    fn synthetic_pef_with_library_import(library_name: &[u8], symbol_name: &[u8]) -> Vec<u8> {
        synthetic_pef_with_loader(synthetic_loader(library_name, symbol_name))
    }

    fn synthetic_pef_with_reloc_chunks(
        library_name: &[u8],
        symbol_name: &[u8],
        chunks: &[u16],
    ) -> Vec<u8> {
        synthetic_pef_with_loader(synthetic_loader_with_chunks(
            library_name,
            symbol_name,
            chunks,
        ))
    }

    fn synthetic_pef_with_loader(loader: Vec<u8>) -> Vec<u8> {
        synthetic_pef_with_loader_and_data(loader, &[0; 8])
    }

    fn synthetic_pef_with_loader_and_data(loader: Vec<u8>, data: &[u8]) -> Vec<u8> {
        let code = synthetic_code();
        let loader_offset = 0x80usize;
        let code_offset = align_test_offset((loader_offset + loader.len()).max(0x100), 0x10);
        let data_offset = code_offset + code.len();
        let total_len = data_offset + data.len();
        let mut bytes = vec![0u8; total_len.max(loader_offset + loader.len())];

        bytes[0..4].copy_from_slice(b"Joy!");
        bytes[4..8].copy_from_slice(b"peff");
        bytes[8..12].copy_from_slice(b"pwpc");
        write_u32(&mut bytes, 12, 1);
        write_u16(&mut bytes, 32, 3);
        write_u16(&mut bytes, 34, 2);

        write_section(
            &mut bytes,
            0,
            SectionSpec {
                total_size: code.len() as u32,
                unpacked_size: code.len() as u32,
                packed_size: code.len() as u32,
                container_offset: code_offset as u32,
                section_kind: SECTION_KIND_CODE,
            },
        );
        write_section(
            &mut bytes,
            1,
            SectionSpec {
                total_size: data.len() as u32,
                unpacked_size: data.len() as u32,
                packed_size: data.len() as u32,
                container_offset: data_offset as u32,
                section_kind: SECTION_KIND_UNPACKED_DATA,
            },
        );
        write_section(
            &mut bytes,
            2,
            SectionSpec {
                total_size: 0,
                unpacked_size: 0,
                packed_size: loader.len() as u32,
                container_offset: loader_offset as u32,
                section_kind: super::super::pef::SECTION_KIND_LOADER,
            },
        );

        bytes[loader_offset..loader_offset + loader.len()].copy_from_slice(&loader);
        bytes[code_offset..code_offset + code.len()].copy_from_slice(&code);
        bytes[data_offset..data_offset + data.len()].copy_from_slice(&data);
        bytes
    }

    fn align_test_offset(value: usize, align: usize) -> usize {
        (value + align - 1) & !(align - 1)
    }

    fn synthetic_code() -> Vec<u8> {
        let mut code = Vec::new();
        let hi = (PPC_IMPORT_TRAP_BASE >> 16) as u16;
        let lo = (PPC_IMPORT_TRAP_BASE & 0xffff) as u16;
        for word in [
            d_form_u(15, 12, 0, hi),       // lis r12, trap@ha
            d_form_u(24, 12, 12, lo),      // ori r12, r12, trap@l
            xfx_form(31, 12, 9, 467),      // mtctr r12
            xl_form(19, 20, 0, 528, true), // bctrl
            d_form_u(14, 0, 0, 0),         // li r0, 0
            xfx_form(31, 0, 8, 467),       // mtlr r0
            BLR,
        ] {
            code.extend_from_slice(&word.to_be_bytes());
        }
        code
    }

    fn synthetic_loader(library_name: &[u8], symbol_name: &[u8]) -> Vec<u8> {
        let chunks = [run_reloc(0x23, 1)];
        synthetic_loader_with_chunks(library_name, symbol_name, &chunks)
    }

    fn synthetic_loader_with_chunks(
        library_name: &[u8],
        symbol_name: &[u8],
        chunks: &[u16],
    ) -> Vec<u8> {
        synthetic_loader_with_symbol_class(library_name, symbol_name, 0x02, chunks)
    }

    fn synthetic_loader_with_symbol_class(
        library_name: &[u8],
        symbol_name: &[u8],
        symbol_class: u8,
        chunks: &[u16],
    ) -> Vec<u8> {
        let mut strings = Vec::new();
        let library_name = push_c_string(&mut strings, library_name);
        let symbol_name = push_c_string(&mut strings, symbol_name);
        let reloc_header_offset = 56 + 24 + 4;
        let reloc_instr_offset = reloc_header_offset + 12;
        let strings_offset = reloc_instr_offset + chunks.len() * 2;
        let mut bytes = vec![0u8; strings_offset + strings.len()];

        write_i32(&mut bytes, 0, 1);
        write_u32(&mut bytes, 4, 0);
        write_i32(&mut bytes, 8, -1);
        write_i32(&mut bytes, 16, -1);
        write_u32(&mut bytes, 24, 1);
        write_u32(&mut bytes, 28, 1);
        write_u32(&mut bytes, 32, 1);
        write_u32(&mut bytes, 36, reloc_instr_offset as u32);
        write_u32(&mut bytes, 40, strings_offset as u32);

        write_u32(&mut bytes, 56, library_name);
        write_u32(&mut bytes, 56 + 12, 1);
        write_symbol(&mut bytes, 56 + 24, symbol_class, symbol_name);

        write_u16(&mut bytes, reloc_header_offset, 1);
        write_u32(&mut bytes, reloc_header_offset + 4, chunks.len() as u32);
        write_u32(&mut bytes, reloc_header_offset + 8, 0);
        for (index, chunk) in chunks.iter().enumerate() {
            write_u16(&mut bytes, reloc_instr_offset + index * 2, *chunk);
        }

        bytes[strings_offset..].copy_from_slice(&strings);
        bytes
    }

    fn synthetic_pef_with_exports() -> Vec<u8> {
        let names = [b"tvector".as_slice(), b"absolute", b"reexport"];
        let mut strings = Vec::new();
        let mut name_offsets = Vec::new();
        for name in names {
            name_offsets.push(strings.len() as u32);
            strings.extend_from_slice(name);
            strings.push(0);
        }

        let strings_offset = 56usize;
        let export_hash_offset = strings_offset + strings.len();
        let key_table_offset = export_hash_offset + 4;
        let symbol_table_offset = key_table_offset + names.len() * 4;
        let loader_len = symbol_table_offset + names.len() * 10;
        let mut loader = vec![0; loader_len];
        write_i32(&mut loader, 0, -1);
        write_i32(&mut loader, 8, -1);
        write_i32(&mut loader, 16, -1);
        write_u32(&mut loader, 40, strings_offset as u32);
        write_u32(&mut loader, 44, export_hash_offset as u32);
        write_u32(&mut loader, 48, 0);
        write_u32(&mut loader, 52, names.len() as u32);
        loader[strings_offset..export_hash_offset].copy_from_slice(&strings);

        // All three entries occupy one valid hash chain. The resolver uses
        // the flattened export table, but the parser still validates chains.
        write_u32(&mut loader, export_hash_offset, 3 << 18);
        for (index, name) in names.iter().enumerate() {
            write_u32(
                &mut loader,
                key_table_offset + index * 4,
                (name.len() as u32) << 16,
            );
        }
        let records = [
            (2u8, name_offsets[0], 0u32, 1i16),
            (1u8, name_offsets[1], 0x1234_5678, -2i16),
            (2u8, name_offsets[2], 0u32, -3i16),
        ];
        for (index, (class, name_offset, value, section_index)) in records.into_iter().enumerate() {
            let base = symbol_table_offset + index * 10;
            write_u32(&mut loader, base, (u32::from(class) << 24) | name_offset);
            write_u32(&mut loader, base + 4, value);
            write_u16(&mut loader, base + 8, section_index as u16);
        }
        synthetic_pef_with_loader_and_data(loader, &[0; 8])
    }

    fn write_ppc_pstring(memory: &mut PpcSectionMem, addr: u32, bytes: &[u8]) {
        assert!(bytes.len() <= 255);
        memory.write_u8(addr, bytes.len() as u8).unwrap();
        for (offset, byte) in bytes.iter().enumerate() {
            memory.write_u8(addr + 1 + offset as u32, *byte).unwrap();
        }
    }

    fn compressed_resource_bytes(decompressed_len: u32, body: &[u8]) -> Vec<u8> {
        let mut out = Vec::new();
        out.extend_from_slice(b"\xA8\x9Fer");
        out.extend_from_slice(&0x12u16.to_be_bytes());
        out.extend_from_slice(&0x0801u16.to_be_bytes());
        out.extend_from_slice(&decompressed_len.to_be_bytes());
        out.extend_from_slice(&[0x80, 0x03]);
        out.extend_from_slice(&0i16.to_be_bytes());
        out.extend_from_slice(&0u16.to_be_bytes());
        out.extend_from_slice(body);
        out
    }

    fn noncanonical_single_resource_fork_bytes(
        res_type: [u8; 4],
        res_id: i16,
        data: &[u8],
        attrs: u8,
        map_attrs: u16,
    ) -> Vec<u8> {
        let data_offset = 16u32;
        let data_length = (4 + data.len()) as u32;
        let map_offset = data_offset + data_length;
        let type_list_offset = 30u16;
        let ref_list_offset = 10u16;
        let name_list_offset = 40u16;
        let map_length = 52u32;

        let mut bytes = vec![0u8; (map_offset + map_length) as usize];
        let mut header = [0u8; 16];
        header[0..4].copy_from_slice(&data_offset.to_be_bytes());
        header[4..8].copy_from_slice(&map_offset.to_be_bytes());
        header[8..12].copy_from_slice(&data_length.to_be_bytes());
        header[12..16].copy_from_slice(&map_length.to_be_bytes());
        bytes[0..16].copy_from_slice(&header);

        let data_start = data_offset as usize;
        bytes[data_start..data_start + 4].copy_from_slice(&(data.len() as u32).to_be_bytes());
        bytes[data_start + 4..data_start + 4 + data.len()].copy_from_slice(data);

        let map_start = map_offset as usize;
        bytes[map_start..map_start + 16].copy_from_slice(&header);
        bytes[map_start + 22..map_start + 24].copy_from_slice(&map_attrs.to_be_bytes());
        bytes[map_start + 24..map_start + 26].copy_from_slice(&type_list_offset.to_be_bytes());
        bytes[map_start + 26..map_start + 28].copy_from_slice(&name_list_offset.to_be_bytes());

        let type_list_start = map_start + type_list_offset as usize;
        bytes[type_list_start..type_list_start + 2].copy_from_slice(&0u16.to_be_bytes());
        bytes[type_list_start + 2..type_list_start + 6].copy_from_slice(&res_type);
        bytes[type_list_start + 6..type_list_start + 8].copy_from_slice(&0u16.to_be_bytes());
        bytes[type_list_start + 8..type_list_start + 10]
            .copy_from_slice(&ref_list_offset.to_be_bytes());

        let ref_list_start = type_list_start + ref_list_offset as usize;
        bytes[ref_list_start..ref_list_start + 2].copy_from_slice(&(res_id as u16).to_be_bytes());
        bytes[ref_list_start + 2..ref_list_start + 4].copy_from_slice(&0xffffu16.to_be_bytes());
        bytes[ref_list_start + 4] = attrs;
        bytes[ref_list_start + 5..ref_list_start + 8].copy_from_slice(&0u32.to_be_bytes()[1..4]);
        bytes
    }

