    fn test_v1_one_bit_packbits_pict() -> Vec<u8> {
        fn push_u16(bytes: &mut Vec<u8>, value: u16) {
            bytes.extend_from_slice(&value.to_be_bytes());
        }

        let mut bytes = Vec::new();
        push_u16(&mut bytes, 0); // patched picSize
        for value in [0i16, 0, 1, 8] {
            push_u16(&mut bytes, value as u16);
        }
        bytes.push(0x11); // versionOp
        bytes.push(0x01); // version 1
        bytes.push(0x98); // PackBitsRect
        push_u16(&mut bytes, 1); // rowBytes < 8: unpacked bitmap data
        for value in [0i16, 0, 1, 8] {
            push_u16(&mut bytes, value as u16);
        }
        for _ in 0..2 {
            for value in [0i16, 0, 1, 8] {
                push_u16(&mut bytes, value as u16);
            }
        }
        push_u16(&mut bytes, 0); // srcCopy
        bytes.push(0b1010_0000);
        bytes.push(0xff); // EndOfPicture
        let size = u16::try_from(bytes.len()).unwrap();
        bytes[0..2].copy_from_slice(&size.to_be_bytes());
        bytes
    }

    fn test_one_bit_cicon() -> Vec<u8> {
        let mut data = vec![0u8; 101];
        data[4..6].copy_from_slice(&0x8001u16.to_be_bytes());
        data[10..12].copy_from_slice(&1u16.to_be_bytes());
        data[12..14].copy_from_slice(&8u16.to_be_bytes());
        data[32..34].copy_from_slice(&1u16.to_be_bytes());
        data[34..36].copy_from_slice(&1u16.to_be_bytes());
        data[36..38].copy_from_slice(&1u16.to_be_bytes());

        data[54..56].copy_from_slice(&1u16.to_be_bytes());
        data[60..62].copy_from_slice(&1u16.to_be_bytes());
        data[62..64].copy_from_slice(&8u16.to_be_bytes());
        data[68..70].copy_from_slice(&1u16.to_be_bytes());
        data[74..76].copy_from_slice(&1u16.to_be_bytes());
        data[76..78].copy_from_slice(&8u16.to_be_bytes());

        data[82] = 0xf0; // first four pixels are opaque
        data[83] = 0x00; // monochrome fallback
        data[90..92].copy_from_slice(&0u16.to_be_bytes()); // one ColorSpec
        data[92..94].copy_from_slice(&0u16.to_be_bytes()); // pixel value 0
        data[94..96].copy_from_slice(&0xffffu16.to_be_bytes()); // red
        data[96..98].copy_from_slice(&0u16.to_be_bytes());
        data[98..100].copy_from_slice(&0u16.to_be_bytes());
        data[100] = 0x00; // eight one-bit red pixels
        data
    }

    fn test_stack_proc_info(result_size: u32, parameter_sizes: &[u32]) -> u32 {
        let mut proc_info =
            PPC_PROCINFO_PASCAL_STACK_BASED | (result_size << PPC_PROCINFO_RESULT_SIZE_PHASE);
        for (index, size) in parameter_sizes.iter().copied().enumerate() {
            proc_info |= size
                << (PPC_PROCINFO_STACK_PARAMETER_PHASE
                    + u32::try_from(index).unwrap() * PPC_PROCINFO_STACK_PARAMETER_WIDTH);
        }
        proc_info
    }

    fn test_register_proc_info(result_size: u32, parameters: &[(u32, u32)]) -> u32 {
        let mut proc_info =
            PPC_PROCINFO_REGISTER_BASED | (result_size << PPC_PROCINFO_RESULT_SIZE_PHASE);
        for (index, (which_register, size)) in parameters.iter().copied().enumerate() {
            let field = size | (which_register << PPC_PROCINFO_REGISTER_PARAMETER_WHICH_SHIFT);
            proc_info |= field
                << (PPC_PROCINFO_REGISTER_PARAMETER_PHASE
                    + u32::try_from(index).unwrap() * PPC_PROCINFO_REGISTER_PARAMETER_WIDTH);
        }
        proc_info
    }

    fn test_register_proc_info_with_result_location(
        result_size: u32,
        result_location: u32,
        parameters: &[(u32, u32)],
    ) -> u32 {
        test_register_proc_info(result_size, parameters)
            | (result_location << PPC_PROCINFO_REGISTER_RESULT_LOCATION_PHASE)
    }

    fn test_dispatched_stack_proc_info(
        calling_convention: u32,
        result_size: u32,
        selector_size: u32,
        parameter_sizes: &[u32],
    ) -> u32 {
        let mut proc_info = calling_convention
            | (result_size << PPC_PROCINFO_RESULT_SIZE_PHASE)
            | (selector_size << PPC_PROCINFO_DISPATCHED_SELECTOR_SIZE_PHASE);
        for (index, size) in parameter_sizes.iter().copied().enumerate() {
            proc_info |= size
                << (PPC_PROCINFO_DISPATCHED_PARAMETER_PHASE
                    + u32::try_from(index).unwrap() * PPC_PROCINFO_STACK_PARAMETER_WIDTH);
        }
        proc_info
    }

    fn install_test_powerpc_callback(
        loaded: &mut PpcLoadedApp,
        descriptor: u32,
        tvector: u32,
        callback_entry: u32,
        callback_rtoc: u32,
        proc_info: u32,
        callback_words: &[u32],
    ) {
        let mut callback = Vec::new();
        for word in callback_words {
            callback.extend_from_slice(&word.to_be_bytes());
        }
        loaded.memory.add_region(callback_entry, callback);
        loaded.memory.add_region(callback_rtoc, vec![0; 0x100]);
        loaded.memory.add_region(descriptor, vec![0; 0x100]);
        loaded
            .memory
            .write_u16_be(descriptor, PPC_MIXED_MODE_TRAP)
            .unwrap();
        loaded
            .memory
            .write_u8(descriptor + 2, PPC_ROUTINE_DESCRIPTOR_VERSION)
            .unwrap();
        loaded.memory.write_u16_be(descriptor + 10, 0).unwrap();
        assert!(ppc_write_routine_record(
            &mut loaded.memory,
            descriptor + PPC_ROUTINE_DESCRIPTOR_HEADER_SIZE,
            proc_info,
            PPC_ROUTINE_RECORD_POWERPC_ISA,
            PPC_ROUTINE_FLAG_USE_NATIVE_ISA,
            tvector,
        ));
        loaded.memory.write_u32_be(tvector, callback_entry).unwrap();
        loaded
            .memory
            .write_u32_be(tvector + 4, callback_rtoc)
            .unwrap();
    }

    fn install_test_m68k_callback(
        loaded: &mut PpcLoadedApp,
        descriptor: u32,
        callback_entry: u32,
        proc_info: u32,
        routine_flags: u16,
        callback_words: &[u16],
    ) {
        let mut callback = Vec::new();
        for word in callback_words {
            callback.extend_from_slice(&word.to_be_bytes());
        }
        loaded.set_heap_cursor(
            loaded
                .heap_cursor()
                .max(descriptor + 0x100)
                .max(callback_entry + u32::try_from(callback.len()).unwrap()),
        );
        loaded.memory.add_region(callback_entry, callback);
        loaded.memory.add_region(descriptor, vec![0; 0x100]);
        loaded
            .memory
            .write_u16_be(descriptor, PPC_MIXED_MODE_TRAP)
            .unwrap();
        loaded
            .memory
            .write_u8(descriptor + 2, PPC_ROUTINE_DESCRIPTOR_VERSION)
            .unwrap();
        loaded.memory.write_u16_be(descriptor + 10, 0).unwrap();
        assert!(ppc_write_routine_record(
            &mut loaded.memory,
            descriptor + PPC_ROUTINE_DESCRIPTOR_HEADER_SIZE,
            proc_info,
            PPC_ROUTINE_RECORD_M68K_ISA,
            routine_flags,
            callback_entry,
        ));
    }

    fn compatibility_binding(
        library_name: &str,
        symbol_name: &str,
        dispatcher_target: PpcImportDispatcherTarget,
    ) -> PpcImportBinding {
        PpcImportBinding {
            library_index: 0,
            symbol_index: 0,
            library_name: library_name.to_string(),
            symbol_name: symbol_name.to_string(),
            class: 0,
            weak: false,
            address: 0,
            tvector_address: None,
            trap_pc: 0,
            dispatcher_target,
        }
    }

    #[test]
    fn native_ppc_apple_event_descriptors_own_and_dispose_guest_data() {
        let mut memory = PpcSectionMem::new();
        memory.add_region(0x1000, b"payload".to_vec());
        memory.add_region(0x1100, vec![0xaa; 8]);
        let mut cpu = PpcCpu::new();
        cpu.gpr[3] = u32::from_be_bytes(*b"TEXT");
        cpu.gpr[4] = 0x1000;
        cpu.gpr[5] = 7;
        cpu.gpr[6] = 0x1100;
        let mut heap_cursor = 0x3000;
        let mut last_mem_error = PPC_NO_ERR;
        let mut memory_manager = ProcessMemoryManager::default();
        memory_manager.publish_native_allocator(
            ProcessNativeHeapState {
                heap_base: heap_cursor,
                heap_cursor,
                heap_limit: 0x5000,
                last_mem_error,
                heap_maximized: false,
                master_pointer_blocks_requested: 0,
            },
            &[],
            &[],
            &[],
        );
        let mut handles = Vec::new();
        let create = compatibility_binding(
            "InterfaceLib",
            "AECreateDesc",
            PpcImportDispatcherTarget::AppleEventCompatibility,
        );
        assert_eq!(
            ppc_dispatch_apple_event_compatibility(
                &create,
                &mut cpu,
                &mut memory_manager,
                &mut memory,
                &mut heap_cursor,
                0x5000,
                &mut last_mem_error,
                &mut handles,
            ),
            PpcImportAction::Return(0)
        );
        let data_handle = memory.read_u32_be(0x1104).unwrap();
        assert_eq!(
            memory.read_u32_be(0x1100),
            Some(u32::from_be_bytes(*b"TEXT"))
        );
        assert_eq!(
            ppc_handle_bytes(&mut memory, &handles, data_handle),
            Some(b"payload".to_vec())
        );

        cpu.gpr[3] = 0x1100;
        let dispose = compatibility_binding(
            "InterfaceLib",
            "AEDisposeDesc",
            PpcImportDispatcherTarget::AppleEventCompatibility,
        );
        assert_eq!(
            ppc_dispatch_apple_event_compatibility(
                &dispose,
                &mut cpu,
                &mut memory_manager,
                &mut memory,
                &mut heap_cursor,
                0x5000,
                &mut last_mem_error,
                &mut handles,
            ),
            PpcImportAction::Return(0)
        );
        assert_eq!(memory.read_u32_be(0x1100), Some(0));
        assert_eq!(memory.read_u32_be(0x1104), Some(0));
        assert!(handles.is_empty());
    }

    #[test]
    fn apple_event_descriptor_handles_are_immediately_process_owned_and_cross_isa_visible() {
        let pef = synthetic_pef_with_library_import(b"InterfaceLib", b"AECreateDesc");
        let mut native = load_pef_application(&pef).unwrap();
        let mut context = ProcessContext::default();
        native.attach_process_context(&mut context);
        let detached = context.memory_manager_mut().detached_clone();
        let scratch = PPC_DATA_BASE + 0x2000;
        let source = scratch;
        let descriptor = scratch + 0x20;
        native.memory.add_region(scratch, vec![0; 0x40]);
        native.memory.write_bytes(source, b"payload").unwrap();
        native.cpu.gpr[3] = u32::from_be_bytes(*b"TEXT");
        native.cpu.gpr[4] = source;
        native.cpu.gpr[5] = 7;
        native.cpu.gpr[6] = descriptor;

        run_test_import(
            &mut native,
            PpcImportDispatcherTarget::AppleEventCompatibility,
        );

        assert_eq!(native.cpu.gpr[3] as u16 as i16, PPC_NO_ERR);
        let handle = native.memory.read_u32_be(descriptor + 4).unwrap();
        let allocation = context
            .memory_manager_mut()
            .native_allocation(handle)
            .unwrap();
        assert_eq!(allocation.size, 7);
        assert_eq!(
            context.memory_manager_mut().recover_handle(allocation.ptr),
            Some(handle)
        );
        assert_eq!(detached.native_allocation(handle), None);

        let shared = native.memory.shared_view();
        let mut classic_bus = MacMemoryBus::new(0x2000);
        classic_bus.attach_guest_address_space(shared);
        context.attach_classic_memory_bus(&mut classic_bus);
        assert_eq!(classic_bus.read_bytes(allocation.ptr, 7), b"payload");
        classic_bus.write_byte(allocation.ptr, b'P');
        assert_eq!(native.memory.read_u8(allocation.ptr), Some(b'P'));
        native.memory.write_u8(allocation.ptr + 6, b'!').unwrap();
        assert_eq!(classic_bus.read_byte(allocation.ptr + 6), b'!');

        native.imports[0].symbol_name = "AEDisposeDesc".to_string();
        native.cpu.gpr[3] = descriptor;
        run_test_import(
            &mut native,
            PpcImportDispatcherTarget::AppleEventCompatibility,
        );

        assert_eq!(native.cpu.gpr[3] as u16 as i16, PPC_NO_ERR);
        assert_eq!(native.memory.read_u32_be(descriptor), Some(0));
        assert_eq!(native.memory.read_u32_be(descriptor + 4), Some(0));
        assert_eq!(native.memory.read_u32_be(handle), Some(0));
        let manager = context.memory_manager_mut();
        assert_eq!(manager.native_allocation(handle), None);
        assert_eq!(manager.recover_handle(allocation.ptr), None);
        assert!(manager
            .native_allocator_snapshot()
            .unwrap()
            .free_handle_blocks
            .iter()
            .any(|record| record.handle == handle));
        assert_eq!(detached.native_allocation(handle), None);
    }

    #[test]
    fn apple_event_descriptor_allocation_failure_is_atomic() {
        let pef = synthetic_pef_with_library_import(b"InterfaceLib", b"AECreateDesc");
        let mut native = load_pef_application(&pef).unwrap();
        native.set_heap_cursor(native.heap_limit().saturating_sub(8));
        let mut context = ProcessContext::default();
        native.attach_process_context(&mut context);
        let scratch = PPC_DATA_BASE + 0x2200;
        let descriptor = scratch + 0x20;
        native.memory.add_region(scratch, vec![0xaa; 0x40]);
        native.memory.write_bytes(scratch, b"payload").unwrap();
        let (before_allocator, before_handles) = {
            let manager = context.memory_manager_mut();
            (
                manager.native_allocator_snapshot().unwrap(),
                manager.native_handle_records().to_vec(),
            )
        };
        native.cpu.gpr[3] = u32::from_be_bytes(*b"TEXT");
        native.cpu.gpr[4] = scratch;
        native.cpu.gpr[5] = 7;
        native.cpu.gpr[6] = descriptor;

        run_test_import(
            &mut native,
            PpcImportDispatcherTarget::AppleEventCompatibility,
        );

        assert_eq!(native.cpu.gpr[3] as u16 as i16, PPC_MEM_FULL_ERR);
        assert_eq!(native.memory.read_u32_be(descriptor), Some(0xaaaa_aaaa));
        assert_eq!(native.memory.read_u32_be(descriptor + 4), Some(0xaaaa_aaaa));
        let manager = context.memory_manager_mut();
        let after_allocator = manager.native_allocator_snapshot().unwrap();
        assert_eq!(
            after_allocator.heap.heap_cursor,
            before_allocator.heap.heap_cursor
        );
        assert_eq!(
            after_allocator.heap.heap_limit,
            before_allocator.heap.heap_limit
        );
        assert_eq!(after_allocator.ptrs, before_allocator.ptrs);
        assert_eq!(
            after_allocator.free_ptr_blocks,
            before_allocator.free_ptr_blocks
        );
        assert_eq!(
            after_allocator.free_handle_blocks,
            before_allocator.free_handle_blocks
        );
        assert_eq!(manager.native_handle_records(), before_handles);
    }

